	var NODE_ELEMENT = 1;
	var NODE_ATTRIBUTE = 2;
	var NODE_TEXT = 3;
	var NODE_CDATA_SECTION = 4;
	var NODE_ENTITY_REFERENCE = 5;
	var NODE_ENTITY = 6;
	var NODE_PROCESSING_INSTRUCTION = 7;
	var NODE_COMMENT = 8;
	var NODE_DOCUMENT = 9;
	var NODE_DOCUMENT_TYPE = 10;
	var NODE_DOCUMENT_FRAGMENT = 11;
	var NODE_NOTATION = 12;
	
