					var oXmlDoc = new XMLDoc();
					
					// Replace unsupported in Msxml2.DOMDocument.3.0 namespace.
					if (3 == XMLDoc._version) {
						sXmlText = sXmlText.replace(/(?:urn\:uuid\:c2f41010\-65b3\-11d1\-a29f\-00aa00c14882\/)/g, 'cutted');
					}
					
