/*
* Utilities container.
* @struct {static} ITHit.WebDAV.Client.WebDavUtil
*/
ITHit.oNS.WebDavUtil = {}

/*
* Check for non null value.
* @function {static} ITHit.WebDAV.Client.WebDavUtil.VerifyArgumentNotNull
*
* @throws ITHit.Exceptions.ArgumentNullException Argument is null.
*/
ITHit.oNS.WebDavUtil.VerifyArgumentNotNull = function(oArgument, sArgumentName) {
	
	if (null === oArgument) {
		throw new ITHit.Exceptions.ArgumentNullException(sArgumentName);
	}
}

/*
* Check for non empty and non null value.
* @function {static} ITHit.WebDAV.Client.WebDavUtil.VerifyArgumentNotNullOrEmpty
*
* @throws ITHit.Exceptions.ArgumentNullException Argument is null or empty.
*/
ITHit.oNS.WebDavUtil.VerifyArgumentNotNullOrEmpty = function(oArgument, sArgumentName) {
	
	if ( (null === oArgument) || ('' === oArgument) ) {
		throw new ITHit.Exceptions.ArgumentNullException(sArgumentName);
	}
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

/**
 * WebDAV property name.
 * @class ITHit.WebDAV.Client.PropertyName
 */
/**
* Initializes new instance of PropertyName.
* @constructor PropertyName
*
* @param {String} sName Name of the property.
* @param {String} sNnamespaceUri Namespace of the property.
*/
ITHit.oNS.PropertyName = function(sName, sNamespaceUri) {
	
	// Check passed arguments type
	ITHit.WebDAV.Client.WebDavUtil.VerifyArgumentNotNullOrEmpty(sName, "sName");
	
	// Name of the property.
	this.Name         = sName;
	
	// Namespace of the property.
	this.NamespaceUri = sNamespaceUri;
}

/**
* Returns string representation of current property name.
* @function {String} ITHit.WebDAV.Client.PropertyName.toString
*
* @returns String representation of current property name.
*/
ITHit.oNS.PropertyName.prototype.toString = function() {
	return this.NamespaceUri + ':' + this.Name;
}

/**
* Checks whether objects are equal.
* @function {Boolean} ITHit.WebDAV.Client.PropertyName.Equals
*
* @param {ITHit.WebDAV.Client.PropertyName} oObj An object to compare with the PropertyName object.
* 
* @returns true if the PropertyName and oObj are both PropertyName objects, and every component of the PropertyName object matches
*             the corresponding component of oObj; otherwise, false.
*/
ITHit.oNS.PropertyName.prototype.Equals = function(oObj) {

	if (this == oObj) {
		return true;
	}
	
	if ( !oObj instanceof ITHit.WebDAV.Client.PropertyName ) {
		return false;
	}
	
	return (this.Name === oObj.Name) && (this.NamespaceUri === oObj.NamespaceUri);
}

/*
* Check whether property is standard.
* @function {Boolean} ITHit.WebDAV.Client.PropertyName.IsStandardProperty
* 
* @returns Whether property is standard.
*/
ITHit.oNS.PropertyName.prototype.IsStandardProperty = function () {
	
	// Declare references for namespaces.
	var oNsCl = ITHit.WebDAV.Client;
	var oNsPropName = oNsCl.PropertyName;
	var oNsDavConst = oNsCl.DavConstants;
	
	// Declare standard properties.
	if (!oNsPropName.StandardNames) {
		oNsPropName.StandardNames = [
			oNsDavConst.ResourceType,
			oNsDavConst.DisplayName,
			oNsDavConst.CreationDate,
			oNsDavConst.GetLastModified,
			oNsDavConst.GetContentLength,
			oNsDavConst.GetContentType,
			oNsDavConst.GetETag,
			oNsDavConst.IsCollection,
			oNsDavConst.IsFolder,
			oNsDavConst.IsHidden,
			oNsDavConst.SupportedLock,
			oNsDavConst.LockDiscovery,
			oNsDavConst.GetContentLanguage,
			oNsDavConst.Source,
			oNsDavConst.QuotaAvailableBytes,
			oNsDavConst.QuotaUsedBytes,
			new oNsPropName("Win32FileAttributes", 'urn:schemas-microsoft-com:')
		];
	}
	
	// Search whether property is standard.
	for (var i = 0; i < oNsPropName.StandardNames.length; i++) {
		if (this.Equals(oNsPropName.StandardNames[i])) {
			return true;
		}
	}
	
	return false;
}

/*
 * Check exists "DAV:" namespace
 * @function {Boolean} ITHit.WebDAV.Client.PropertyName.HasDavNamespace
 *
 * @returns Whether property is standard.
 */
ITHit.oNS.PropertyName.prototype.HasDavNamespace = function () {

	// Declare references for namespaces.
	var oNsCl = ITHit.WebDAV.Client;

	return this.NamespaceUri === oNsCl.DavConstants.NamespaceUri;
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

