/**
 * The method could not be performed on the resource because the server is unable to store the
 *  representation needed to successfully complete the request.
 * @property {static ITHit.WebDAV.Client.HttpStatus} ITHit.WebDAV.Client.HttpStatus.InsufficientStorage
 */
ITHit.oNS.HttpStatus.InsufficientStorage = new ITHit.oNS.HttpStatus(507, 'Insufficient Storage');

/*
 * Parses HttpStatus structure from string containing status information.
 * @function {static ITHit.WebDAV.Client.HttpStatus} ITHit.WebDAV.Client.HttpStatus.Parse
 * 
 * @param {String} sStatus String containing status information.
 * 
 * @returns HttpStatus structure that describes current status.
 */
ITHit.oNS.HttpStatus.Parse = function(sStatus) {
	
	var aParts  = sStatus.split(' ');
	var iStatus = parseInt(aParts[1]);
	
	aParts.splice(0, 2);
	
	return new ITHit.WebDAV.Client.HttpStatus(iStatus, aParts.join(' '));
}

/**
 * Indicates whether the current HttpStatus structure is equal to
 *  another HttpStatus structure.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.Equals
 * 
 * @param {ITHit.WebDAV.Client.HttpStatus} oHttpStatus HttpStatus object to compare.
 * 
 * @returns true if the current object is equal to the other parameter; otherwise, false.
 */
ITHit.oNS.HttpStatus.prototype.Equals = function(oHttpStatus) {
	
	if ( !oHttpStatus || !(oHttpStatus instanceof ITHit.WebDAV.Client.HttpStatus) ) {
		return false;
	}
	
	return this.Code == oHttpStatus.Code;
}

/**
 * Returns true if status is successful for Create operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsCreateOk
 * 
 * @returns Returns true if status is successful for Create operation.
 */
ITHit.oNS.HttpStatus.prototype.IsCreateOk = function() {
	return this.Equals(ITHit.WebDAV.Client.HttpStatus.Created);
}

/**
 * Returns true if status is successful for Delete operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsDeleteOk
 * 
 * @returns Returns true if status is successful for Delete operation.
 */
ITHit.oNS.HttpStatus.prototype.IsDeleteOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.OK) || this.Equals(oNsHttpStat.NoContent);
}

/**
 * Returns true if status is successful.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsOk
 * 
 * @returns Returns true if status is successful.
 */
ITHit.oNS.HttpStatus.prototype.IsOk = function() {
	return this.Equals(ITHit.WebDAV.Client.HttpStatus.OK);
}

/**
 * Returns true if status is successful for Copy or Move operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsCopyMoveOk
 * 
 * @returns Returns true if status is successful for Copy or Move operation.
 */
ITHit.oNS.HttpStatus.prototype.IsCopyMoveOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.NoContent) || this.Equals(oNsHttpStat.Created);
}

/**
 * Returns true if status is successful for Get operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsGetOk
 * 
 * @returns Returns true if status is successful for Get operation.
 */
ITHit.oNS.HttpStatus.prototype.IsGetOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.OK) || this.Equals(oNsHttpStat.PartialContent);
}

/**
 * Returns true if status is successful for Put operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsPutOk
 * 
 * @returns Returns true if status is successful for Put operation.
 */
ITHit.oNS.HttpStatus.prototype.IsPutOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.OK) || this.Equals(oNsHttpStat.Created) || this.Equals(oNsHttpStat.NoContent);
}

/**
 * Returns true if status is successful for Unlock operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsUnlockOk
 * 
 * @returns Returns true if status is successful for Unlock operation.
 */
ITHit.oNS.HttpStatus.prototype.IsUnlockOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.OK) || this.Equals(oNsHttpStat.NoContent);
}

/**
 * Returns true if status is successful for Head operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsHeadOk
 * 
 * @returns Returns true if status is successful for Head operation.
 */
ITHit.oNS.HttpStatus.prototype.IsHeadOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.OK) || this.Equals(oNsHttpStat.NotFound);
}


/**
 * Returns true if status is successful for Proppatch operation.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsUpdateOk
 * 
 * @returns Returns true if status is successful for Proppatch operation.
 */
ITHit.oNS.HttpStatus.prototype.IsUpdateOk = function() {
	var oNsHttpStat = ITHit.WebDAV.Client.HttpStatus;
	return this.Equals(oNsHttpStat.OK) || this.Equals(oNsHttpStat.None);
}

/**
 * Returns true if status is successful.
 * @function {Boolean} ITHit.WebDAV.Client.HttpStatus.IsSuccess
 * 
 * @returns Returns true if status is successful.
 */
ITHit.oNS.HttpStatus.prototype.IsSuccess = function() {
	return (parseInt(this.Code / 100) == 2);
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

/**
 * Represents custom property exposed by WebDAV hierarchy items.
 * @class ITHit.WebDAV.Client.Property
 */
/**
 * Initializes new string valued property.
 * @constructor Property
 * 
 * @paramset Syntax 1
 * @param {ITHit.WebDAV.Client.PropertyName} mOne Property name.
 * @param {String} mTwo Property value.
 * @paramset Syntax 2
 * @param {String} mOne Name of the property.
 * @param {String} mTwo Property value.
 * @param {String} mThree Namespace of the property.
 */
/*
 * @paramset Syntax 1
 * @param {ITHit.XMLDoc} mOne Property XML DOM Element.
 */
ITHit.oNS.Property = function(mOne, mTwo, mThree) {
	
	/**
	 * Property Name.
	 * @property {String} ITHit.WebDAV.Client.Property.Name
	 */
	this.Name;
	
	// Property value.
	this.Value;
	
	var oNsCl = ITHit.WebDAV.Client;
	
	switch (arguments.length) {
		
		case 1:
			// Declare variable.
			var oElement = mOne;
			
			// Check variable.
			oNsCl.WebDavUtil.VerifyArgumentNotNull(oElement, 'oElement');
			
			this.Name    = new oNsCl.PropertyName(oElement.localName(), oElement.namespaceURI());
			this.Value   = oElement;
			
			break;
			
		case 2:
			// Declare variables.
			var oName        = mOne,
			    sStringValue = mTwo;
			
			// Check variables.
			oNsCl.WebDavUtil.VerifyArgumentNotNull(oName, 'oName');
			oNsCl.WebDavUtil.VerifyArgumentNotNull(sStringValue, 'sStringValue');
			
			this.Name   = oName;
			
			// Create element.
			var oXmlDoc = new ITHit.XMLDoc(),
			    oElem   = oXmlDoc.createElementNS(oName.NamespaceUri, oName.Name);
			oElem.appendChild(oXmlDoc.createTextNode(sStringValue));
			this.Value  = oElem;
			
			break;
			
		case 3:
			// Declare variables.
			var sName      = mOne,
			    sValue     = mTwo,
			    sNameSpace = mThree;
			
			// Check variables.
			oNsCl.WebDavUtil.VerifyArgumentNotNullOrEmpty(sName, "sName");
			oNsCl.WebDavUtil.VerifyArgumentNotNull(sValue, "sValue");
			oNsCl.WebDavUtil.VerifyArgumentNotNullOrEmpty(sNameSpace, "sNameSpace");
			
			this.Name   = new oNsCl.PropertyName(sName, sNameSpace);
			
			// Create element.
			var oXmlDoc = new ITHit.XMLDoc(),
			    oElem   = oXmlDoc.createElementNS(sNameSpace, sName);
			oElem.appendChild(oXmlDoc.createTextNode(sValue));
			this.Value  = oElem;
			
			break;
			
		default:
			throw ITHit.Exception(ITHit.Phrases.Exceptions.WrongCountPropertyInputParameters.Paste(arguments.length));
	}
}

/**
 * String value of the custom property.
 * @function {String} ITHit.WebDAV.Client.Property.StringValue
 * 
 * @returns String value of the custom property.
 */
ITHit.oNS.Property.prototype.StringValue = function() {
	return this.Value.firstChild().nodeValue();
}

/**
 * Returns string representation of current property.
 * @function {String} ITHit.WebDAV.Client.Property.toString
 * 
 * @returns String representation of PropertyName.
 */
ITHit.oNS.Property.prototype.toString = function() {
	return this.Name.toString();
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.Propstat = function(oElement) {
	
	// Declare class variables.
	this.PropertiesByNames   = {};
	this.Properties          = [];
	this.ResponseDescription = '';
	this.Status              = '';
	
	// Declare variables.
	var oNsCl = ITHit.WebDAV.Client;
	var oNode;
	
	// Create namespace resolver.
	var oResolver = new ITHit.XPath.resolver();
	oResolver.add('d', oNsCl.DavConstants.NamespaceUri);
	
	// Get response description.
	if ( oNode = ITHit.XPath.selectSingleNode('d:responsedescription', oElement, oResolver) ) {
		this.ResponseDescription = oNode.firstChild().nodeValue();
	}
	
	// Get status.
	oNode = ITHit.XPath.selectSingleNode('d:status', oElement, oResolver);
	this.Status = oNsCl.HttpStatus.Parse(oNode.firstChild().nodeValue());
	
	// Get properties.
	var oRes = ITHit.XPath.evaluate('d:prop/*', oElement, oResolver);
	while ( oNode = oRes.iterateNext() ) {
		
		var oProperty = new oNsCl.Property(oNode.cloneNode());
		var sPropName = oProperty.Name;
		
		if ('undefined' == typeof this.PropertiesByNames[sPropName]) {
			this.PropertiesByNames[sPropName] = oProperty;
		} else {
			var aChildNodes = oNode.childNodes();
			
			for ( var i = 0; i < aChildNodes.length; i++ ) {
				this.PropertiesByNames[sPropName].Value.appendChild(aChildNodes[i]);
			}
		}
		this.Properties.push(oProperty);
	}
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.Response = function(oResponseItem, sOriginalUri) {
	
	// Declare class properties.
	this.Href      = '';
	this.ResponseDescription = '';
	this.Status    = '';
	this.Propstats = [];
	
	// Get references for namespaces.
	var oNsCl      = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;
	
	// Declare variables.
	var oNode;
	
	// Create namespace resolver.
	var oResolver = new ITHit.XPath.resolver();
	oResolver.add('d', oNsCl.DavConstants.NamespaceUri);
	
	// Get response href.
	this.Href = ITHit.XPath.selectSingleNode('d:href', oResponseItem, oResolver).firstChild().nodeValue();
	
	// Get description if specified.
	if ( oNode = ITHit.XPath.selectSingleNode('d:responsedescription', oResponseItem, oResolver) ) {
		this.ResponseDescription = oNode.firstChild().nodeValue();
	}
	
	// Get response status if specified.
	if ( oNode = ITHit.XPath.selectSingleNode('d:status', oResponseItem, oResolver) ) {
		this.Status = oNsCl.HttpStatus.Parse(oNode.firstChild().nodeValue());
	}
	
	// Get propstat.
	var oRes = ITHit.XPath.evaluate('d:propstat', oResponseItem, oResolver);
	while ( oNode = oRes.iterateNext() ) {
		this.Propstats.push(new oNsMethods.Propstat(oNode.cloneNode()));
	}
	
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.MultiResponse = function(oXmlDoc, sOriginalUri) {
	
	// Declare properties.
	this.ResponseDescription = '';
	this.Responses = [];
	
	// Get references for namespaces.
	var oNsCl = ITHit.WebDAV.Client;
	var oNsResponse = oNsCl.Methods.Response;
	
	// Create namespace resolver.
	var oResolver = new ITHit.XPath.resolver();
	oResolver.add('d', oNsCl.DavConstants.NamespaceUri);
	
	// Select nodes.
	var oRes = ITHit.XPath.evaluate('/d:multistatus/d:response', oXmlDoc, oResolver);
	
	// Loop through selected nodes.
	var oNode;
	while( (oNode = oRes.iterateNext())) {
		this.Responses.push(new oNsResponse(oNode.cloneNode(), sOriginalUri));
	}
	
	// Get response description if specified.
	ITHit.XPath.evaluate('/d:multistatus/d:responsedescription', oXmlDoc, oResolver, oRes);
	
	if ( (oNode = oRes.iterateNext()) ) {
		this.ResponseDescription = oNode.firstChild().nodeValue();
	}
};
ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

/**
 * @function ITHit.WebDAV.Client.AsyncResult
 * @param {object} oResult
 * @param {boolean} bSuccess
 * @param {object} oError
 */
ITHit.oNS.AsyncResult = function(oResult, bSuccess, oError) {
		
	/**
	 * Result value. Can be any type, each method may put there appropriate object which before was returned directly
	 * @var {object}
	 */
	this.Result = oResult;
	
    /**
	 * Flag of either async request result was successfully or not
	 * @var {boolean}
	 */
	this.IsSuccess = bSuccess;

	/**
	 * Error (Exception) object. Exception which was thrown in case of Sync method call
	 * @var {object}
	 */
	this.Error = oError;

};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

/*
 * Method to perform Propfind request to a server.
 * @class ITHit.WebDAV.Client.Methods.Propfind
 * @extends ITHit.WebDAV.Client.Methods.HttpMethod
 */
/*
 * Create new instance of Propfind class.
 * @constructor Propfind
 * 
 * @param {ITHit.WebDAV.Client.WebDavResponse} oResponse Response object.
 */
ITHit.oNS.Propfind = function(oResponse) {
	
	// Inheritance definition.
	ITHit.WebDAV.Client.Methods.Propfind.baseConstructor.call(this);
	
	// Response
	this.Response = oResponse;
};

// Extend class.
ITHit.Extend(ITHit.oNS.Propfind, ITHit.oNS.HttpMethod);

// Propfind modes.
ITHit.oNS.Propfind.PropfindMode = {
	SelectedProperties: 'SelectedProperties',
	PropertyNames:      'PropertyNames'
}

ITHit.oNS.Propfind.Go = function(oSession, sUri, iMode, aProperties, oDepth, sHost, fCallback) {

    // Get references for namespaces.
    var oNsCl = ITHit.WebDAV.Client;
    var oNsPropfind = oNsCl.Methods.Propfind;
	
	// Create request object.
	var oRequest = oNsPropfind.createRequest(oSession, sUri, iMode, aProperties, oDepth, sHost);

    var self = this;
    var fOnResponse = typeof fCallback === 'function'
        ? function(oResult) { self._GoCallback(oSession, sUri, oResult, fCallback) }
        : null;
	
	// Make request.
	var oResponse = oRequest.GetResponse(fOnResponse);

	if (typeof fCallback !== 'function') {
	    var oResult = new oNsCl.AsyncResult(oResponse, oResponse != null, null);
        return this._GoCallback(oSession, sUri, oResult, fCallback);
    } else {
		return oRequest;
	}
}

ITHit.oNS.Propfind._GoCallback = function (oSession, sUri, oResult, fCallback) {
    // Get references for namespaces.
    var oNsCl = ITHit.WebDAV.Client;

    var oResponse = oResult;
    var bSuccess = true;
    var oError = null;

    if (oResult instanceof ITHit.WebDAV.Client.AsyncResult) {
        oResponse = oResult.Result;
        bSuccess = oResult.IsSuccess;
        oError = oResult.Error;
    }

    var oPropfind = null;
    if (bSuccess) {
        // Receive data.
        var oResponseData = oResponse.GetResponseStream();

        // Finish logger session.
        ITHit.Logger.FinishRequest();

        var oMultiResponse = new oNsCl.Methods.MultiResponse(oResponseData, sUri);


        var oNsPropfind = oNsCl.Methods.Propfind;
        oPropfind = new oNsPropfind(oMultiResponse);
    }
    // Return response.
    if (typeof fCallback === 'function') {
        var oPropfindResult = new oNsCl.AsyncResult(oPropfind, bSuccess, oError);
        fCallback.call(this, oPropfindResult);
    } else {
        return oPropfind;
    }
}

ITHit.oNS.Propfind.createRequest = function(oSession, sUri, iMode, aProperties, oDepth, sHost) {
	
	// Create request object.
	var oRequest = oSession.CreateRequest(sHost, sUri);
	
	// Set method.
	oRequest.Method('PROPFIND');
	
	// Add headers.
	oRequest.Headers.Add('Depth', oDepth.Value);
	oRequest.Headers.Add('Content-Type', 'text/xml; charset="utf-8"');
	
	// Set new session for logger.
	oRequest.LogRequestInfo();
	
	// Get references for namespaces.
	var oNsCl      = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;
	
	// Create XML document.
	var oWriter = new ITHit.XMLDoc();
	
	// Create root element.
	var propfind = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'propfind');
	
	// Switch property mode.
	switch(iMode) {
		
		// Namespace mode.
		case oNsMethods.Propfind.PropfindMode.SelectedProperties:
			
			// All properties.
			if (!aProperties || !aProperties.length) {
				var propEl = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'allprop');
				
			// Selected properties.
			} else {
				var propEl = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'prop');
				for (var i = 0; i < aProperties.length; i++) {
					var prop = oWriter.createElementNS(aProperties[i].NamespaceUri, aProperties[i].Name);
					propEl.appendChild(prop);
				}
			}
			break;
		
		// Property mode.
		case oNsMethods.Propfind.PropfindMode.PropertyNames:
			var propEl = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'propname');
			break;
	}
	
	// Append created child nodes.
	propfind.appendChild(propEl);
	oWriter.appendChild(propfind);
	
	// Assign created document as body for request.
	oRequest.Body(oWriter);
	
	return oRequest;
};

