/**
 * Represents information about errors occurred in different elements.
 * @interface ITHit.WebDAV.Client.IMultistatus
 */
/**
 * Gets the generic description, if available.
 * @variable {String} Description
 */
/**
 * Array of the errors returned by server.
 * @variable {ITHit.WebDAV.Client.IMultistatusResponse[]} Responses
 */
ITHit.oNS.IMultistatus = function() {};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

/**
 * Represents error occurred in one element.
 * @interface ITHit.WebDAV.Client.IMultistatusResponse
 */
/**
 * Description of error, if available.
 * @variable {String} Href
 */
/**
 * Description of error, if available.
 * @variable {String} Description
 */
/**
 * HTTP Status of the operation.
 * @variable {ITHit.WebDAV.Client.HttpStatus} Status
 */
ITHit.oNS.IMultistatusResponse = function() {};

ITHit.oNSClient = ITHit.Declare('ITHit.WebDAV.Client');
ITHit.oNS       = ITHit.Declare('Exceptions.Info', ITHit.oNSClient);

/*
 * Represents error occurred in one element. 
 * @class ITHit.WebDAV.Client.Exceptions.Info.MultistatusResponse
 * @extends ITHit.WebDAV.Client.IMultistatusResponse
 */
ITHit.oNS.MultistatusResponse = function(oResponse) {
	
	// Define object properties.
	/*
	 * Url of the item.
	 * @property {ITHit.WebDAV.Client.IMultistatusResponse.Href} ITHit.WebDAV.Client.Exceptions.Info.MultistatusResponse.Href
	 */
	this.Href = oResponse.Href;
	
	/*
	 * Description of error, if available. 
	 * @property {ITHit.WebDAV.Client.IMultistatusResponse.Description} ITHit.WebDAV.Client.Exceptions.Info.MultistatusResponse.Description
	 */
	this.Description = oResponse.ResponseDescription;
	
	/*
	 * HTTP Status of the operation.
	 * @property {ITHit.WebDAV.Client.IMultistatusResponse.Status} ITHit.WebDAV.Client.Exceptions.Info.MultistatusResponse.Status
	 */
	this.Status = oResponse.Status;
	
	// Declare namespace variable.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Loop through response propstats, look for first not OK status.
	for ( var i = 0; i < oResponse.Propstats.length; i++ ) {
		if (oResponse.Propstats[i] != oNsCl.HttpStatus.OK) {
			this.Status = oResponse.Propstats[i];
			break;
		}
	}
};

// Inheritance definition.
ITHit.Extend(ITHit.oNS.MultistatusResponse, ITHit.oNSClient.IMultistatusResponse);

ITHit.oNSClient = ITHit.Declare('ITHit.WebDAV.Client');
ITHit.oNS       = ITHit.Declare('Exceptions.Info', ITHit.oNSClient);

/*
 * Represents information about errors occurred in different elements.
 * @class ITHit.WebDAV.Client.Exceptions.Info.Multistatus
 * @extends ITHit.WebDAV.Client.IMultistatus
 */
ITHit.oNS.Multistatus = function(oMultiResponse) {
	
	// Get reference for namespace.
	var oNsInfo = ITHit.WebDAV.Client.Exceptions.Info;
	
	// Call base constructor.
	oNsInfo.Multistatus.baseConstructor.call(this);
	
	/*
	 * Gets the generic description, if available. 11
	 * @property {ITHit.WebDAV.Client.IMultistatus.Description} ITHit.WebDAV.Client.Exceptions.Info.Multistatus.Description
	 */
	this.Description = '';
	
	/*
	 * Array of the errors returned by server.
	 * @property {ITHit.WebDAV.Client.IMultistatusResponse[]} ITHit.WebDAV.Client.Exceptions.Info.Multistatus.Responses
	 */
	this.Responses = [];
	
	
	// Whether multistatus response object passed.
	if (oMultiResponse) {
		
		this.Description = oMultiResponse.ResponseDescription;
		
		// Loop through all received responses and add it to class' property.
		for ( var i = 0; i < oMultiResponse.Responses.length; i++ ) {
			this.Responses.push(new oNsInfo.MultistatusResponse(oMultiResponse.Responses[i]));
		}
	}
};

// Inheritance definition.
ITHit.Extend(ITHit.oNS.Multistatus, ITHit.oNSClient.IMultistatus);


