/*
 * Provides means for finding which properties failed to update. 
 * @class ITHit.WebDAV.Client.Exceptions.Info.PropertyMultistatus
 * @extends ITHit.WebDAV.Client.IMultistatus
 */
/*
 * Create new instance of PropertyMultistatus class.
 * @constructor PropertyMultistatus
 * 
 * @param {optional ITHit.WebDAV.Client.Exceptions.Info.MultiResponse} MultiResponse object.
 */
ITHit.oNS.PropertyMultistatus = function(oMultiResponse) {
	
	/*
	 Gets the generic description, if available. 11
	 * @property {ITHit.WebDAV.Client.IMultistatus.Description} ITHit.WebDAV.Client.Exceptions.Info.PropertyMultistatus.Description
	 */
	this.Description = '';
	
	/*
	 * Array of the errors returned by server.
	 * @property {ITHit.WebDAV.Client.IMultistatusResponse[]} ITHit.WebDAV.Client.Exceptions.Info.PropertyMultistatus.Responses
	 */
	this.Responses = [];
	
	if (oMultiResponse) {
		this.Description = oMultiResponse.ResponseDescription;
	
		var oNsMultistatPropResp = ITHit.WebDAV.Client.Exceptions.Info.PropertyMultistatusResponse;
		
		for ( var i = 0; i < oMultiResponse.Responses.length; i++ ) {
			var oResponse = oMultiResponse.Responses[i];
			for ( var j = 0; j < oResponse.Propstats.length; j++ ) {
				var oPropstat = oResponse.Propstats[j];
				for ( var k = 0; k < oPropstat.Properties.length; k++ ) {
					this.Responses.push(new oNsMultistatPropResp(oResponse.Href, oPropstat.ResponseDescription, oPropstat.Status, oPropstat.Properties[k].Name));
				}
			}
		}
	}
};

// Inheritance definition.
ITHit.Extend(ITHit.oNS.PropertyMultistatus, ITHit.oNSClient.IMultistatus);

