/*
 * Contains information about server's simple response with no XML content.
 * @class ITHit.WebDAV.Client.Methods.SingleResponse
 */
/*
 * Create new instance of SingleResponse class.
 * @constructor SingleResponse
 * 
 * @param {ITHit.WebDAV.Client.WebDavResponse} oResponse Response object.
 */
ITHit.oNS.SingleResponse = function(oResponse) {
	
	this.Status              = oResponse.Status;
	this.ResponseDescription = oResponse.Status.Description;
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

/*
 * Factory class for different inheritors.
 * @namespace ITHit.WebDAV.Client.Methods.ResponseFactory
 */
ITHit.oNS.ResponseFactory = {}

/*
 * Returns suitable object of IResponse's inheritor: SingleResponse or MultiResponse.
 * @function {static Object} ITHit.WebDAV.Client.Methods.ResponseFactory.GetResponse
 * 
 * @param {ITHit.WebDAV.Client.WebDavResponse} oResponse Response object.
 * @param {String} sOriginalUri Request URI.
 * 
 * @returns SingleResponse or MultiResponse object corresponding to request.
 */
ITHit.oNS.ResponseFactory.GetResponse = function(oResponse, sOriginalUri) {
	
	// Get reference for namespace.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Get response body.
	var oResponseData = oResponse.GetResponseStream(oResponse);
	
	// Check whether there is single or multi-response.
	if ( !oResponseData || !oResponse.Status.Equals(oNsCl.HttpStatus.MultiStatus) ) {
		
		// Single response.
		return new oNsCl.Methods.SingleResponse(oResponse);
	} else {
		
		// Multi-response.
		return new oNsCl.Methods.MultiResponse(oResponseData, sOriginalUri);
	}
};

