/*
 * Method to perform Copy or Move request to a server.
 * @class ITHit.WebDAV.Client.Methods.CopyMove
 * @extends ITHit.WebDAV.Client.Methods.HttpMethod
 */
/*
 * Create new instance of CopyMove class.
 * @constructor CopyMove
 * 
 * @param {ITHit.WebDAV.Client.WebDavResponse} oResponse Response object.
 */
ITHit.oNS.CopyMove = function(oResponse) {
	
	// Inheritance definition.
	ITHit.WebDAV.Client.Methods.CopyMove.baseConstructor.call(this);
	
	this.Response = oResponse;
}

// Extend class.
ITHit.Extend(ITHit.oNS.CopyMove, ITHit.oNS.HttpMethod);

/*
 * Modes for CopyMove methods.
 */
ITHit.oNS.CopyMove.Mode = {
	Copy: 'Copy',
	Move: 'Move'
}

ITHit.oNS.CopyMove.Go = function(oSession, sMode, sSource, sDestination, bIsCollection, bDeep, bOverwrite, aLockTokens, sHost) {
	// Create request.
	var oRequest = this.createRequest(oSession, sMode, sSource, sDestination, bIsCollection, bDeep, bOverwrite, aLockTokens, sHost);
	var oResponse = oRequest.GetResponse();
	return this._ProcessResponse(oResponse, sSource);
}

ITHit.oNS.CopyMove.GoAsync = function(oSession, sMode, sSource, sDestination, bIsCollection, bDeep, bOverwrite, aLockTokens, sHost, fCallback) {
	// Create request.
	var oRequest = this.createRequest(oSession, sMode, sSource, sDestination, bIsCollection, bDeep, bOverwrite, aLockTokens, sHost);

	var that = this;
	oRequest.GetResponse(function(oAsyncResult) {
		if (!oAsyncResult.IsSuccess) {
			fCallback(new ITHit.WebDAV.Client.AsyncResult(null, false, oAsyncResult.Error));
			return;
		}

		var oResult = that._ProcessResponse(oAsyncResult.Result, sSource);
		fCallback(new ITHit.WebDAV.Client.AsyncResult(oResult, true, null));
	});

	return oRequest;
}

ITHit.oNS.CopyMove._ProcessResponse = function(oResponse, sSource) {
	// Get appropriate response object.
	var oResp = ITHit.WebDAV.Client.Methods.ResponseFactory.GetResponse(oResponse, sSource);

	// Return result.
	return new ITHit.WebDAV.Client.Methods.CopyMove(oResp);

}

ITHit.oNS.CopyMove.createRequest = function(oSession, sMode, sSource, sDestination, bIsCollection, bDeep, bOverwrite, aLockTokens, sHost) {
	
	// Get references for namespaces.
	var oNsCl      = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;
	
	// Create request.
	var oRequest = oSession.CreateRequest(sHost, sSource, aLockTokens);

	// TODO: Remove after when encoding special characters on server will be fixed.
	sDestination = ITHit.WebDAV.Client.Encoder.EncodeURI(sDestination).replace(/#/g, '%23').replace(/'/g, '%27');

	if (/^\//.test(sDestination)) {
		sDestination = sHost + sDestination.substr(1);
	}
	
	// Add headers
	oRequest.Method((sMode == oNsMethods.CopyMove.Mode.Copy) ? 'COPY' : 'MOVE');
	oRequest.Headers.Add('Content-Type', 'text/xml; charset="utf-8"');
	oRequest.Headers.Add('Destination', ITHit.DecodeHost(sDestination));
	oRequest.Headers.Add('Overwrite', bOverwrite ? "T" : "F");
	
	// Set depth property if specified by input parameters.
	if ( bIsCollection && (sMode == oNsMethods.CopyMove.Mode.Copy) ) {
		// Built-in IIS 8.0 WebDAV does not support Depth: Infinity
		if (!bDeep) {
			oRequest.Headers.Add("Depth", oNsCl.Depth.Zero.Value);
		}
	}
	
	// Create XML DOM document.
	var oWriter = new ITHit.XMLDoc();
	
	// Create XML document.
	var propBehav = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'propertybehavior');
	var keepAlive = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'keepalive')
	keepAlive.appendChild(oWriter.createTextNode('*'));
	propBehav.appendChild(keepAlive);
	oWriter.appendChild(propBehav);
	
	// Add XML document as request body.
	oRequest.Body(oWriter);
	
	// Return request object.
	return oRequest;
};


