ITHit.oNS.Delete = function(oResponse) {
	
	// Inheritance definition.
	ITHit.WebDAV.Client.Methods.Delete.baseConstructor.call(this);
	
	this.Response = oResponse;
}

// Extend class.
ITHit.Extend(ITHit.oNS.Delete, ITHit.oNS.HttpMethod);

ITHit.oNS.Delete.Go = function (oSession, sHref, oLockTokens, sHost) {
	// Create request.
	var oRequest = this.createRequest(oSession, sHref, oLockTokens, sHost);
	var oResponse = oRequest.GetResponse();

    return this._ProcessResponse(oResponse)
}

ITHit.oNS.Delete.GoAsync = function(oSession, sHref, oLockTokens, sHost, fCallback) {
	// Create request.
    var oRequest = this.createRequest(oSession, sHref, oLockTokens, sHost);

	var that = this;
    oRequest.GetResponse(function(oAsyncResult) {
		if (!oAsyncResult.IsSuccess) {
			fCallback(new ITHit.WebDAV.Client.AsyncResult(null, false, oAsyncResult.Error));
			return;
		}

		var oResult = that._ProcessResponse(oAsyncResult.Result);
		fCallback(new ITHit.WebDAV.Client.AsyncResult(oResult, true, null));
	});

    return oRequest;
}

ITHit.oNS.Delete._ProcessResponse = function (oResponse, sHref) {
	// Get appropriate response object.
	var oResp = ITHit.WebDAV.Client.Methods.ResponseFactory.GetResponse(oResponse, sHref);

	// Finnish logging.
	ITHit.Logger.FinishRequest();

	// Return result object.
	return new ITHit.WebDAV.Client.Methods.Delete(oResp);
}

ITHit.oNS.Delete.createRequest = function(oSession, sHref, oLockTokens, sHost) {
	
	// Create request.
	var oRequest = oSession.CreateRequest(sHost, sHref, oLockTokens);
	
	// Set method.
	oRequest.Method('DELETE');
	
	// Return request object.
	return oRequest;
};

