// Extend class.
ITHit.Extend(ITHit.oNS.Proppatch, ITHit.oNS.HttpMethod);

ITHit.oNS.Proppatch.Go = function(oSession, sHref, aPropsToAddOrUpdate, aPropsToDelete, sLockToken, sHost) {

	// Get refeneces for namespaces. 
	var oNsCl          = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;

	// Create request.
	var oRequest = oNsMethods.Proppatch.createRequest(
		oSession,
		sHref,
		aPropsToAddOrUpdate,
		aPropsToDelete,
		sLockToken,
		sHost
	);

	// Get response.
	var oResult = oRequest.GetResponse();

	// Finish request.
	ITHit.Logger.FinishRequest();

	// Return response object.
	return this._ProcessResponse(oResult);
}

ITHit.oNS.Proppatch.GoAsync = function(oSession, sHref, aPropsToAddOrUpdate, aPropsToDelete, sLockToken, sHost, fCallback) {
	// Get refeneces for namespaces.
	var oNsCl          = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;

	// Create request.
	var oRequest = oNsMethods.Proppatch.createRequest(
		oSession,
		sHref,
		aPropsToAddOrUpdate,
		aPropsToDelete,
		sLockToken,
		sHost
	);

	// Get response.
	var that = this;
	oRequest.GetResponse(function(oAsyncResult) {
		// Finish request.
		ITHit.Logger.FinishRequest();

		if (!oAsyncResult.IsSuccess) {
			fCallback(new ITHit.WebDAV.Client.AsyncResult(null, false, oAsyncResult.Error));
			return;
		}

		var oResult = that._ProcessResponse(oAsyncResult.Result, sHref);
		fCallback(new ITHit.WebDAV.Client.AsyncResult(oResult, true, null));
	});

}

ITHit.oNS.Proppatch._ProcessResponse = function(oResponse, sHref) {
	var oNsCl          = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;

	// Get response data.
	var oResponseData = oResponse.GetResponseStream();

	// Return response object.
	return new oNsMethods.Proppatch(new oNsMethods.MultiResponse(oResponseData, sHref));
}

ITHit.oNS.Proppatch.ItemExists = function(aArr) {
	
	if (aArr && aArr.length) {
		for (var i = 0; i < aArr.length; i++) {
			if (aArr[i]) {
				return true;
			}
		}
	}
	
	return false;
}

ITHit.oNS.Proppatch.createRequest = function(oSession, sHref, aPropsToAddOrUpdate, aPropsToDelete, sLockToken, sHost) {
	
	// Assign default value if needed.
	sLockToken = sLockToken || null;
	
	// Get references for namespaces.
	var oNsCl      = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;
	
	// Create request.
	var oRequest = oSession.CreateRequest(sHost, sHref, sLockToken);
	oRequest.Method('PROPPATCH');
	oRequest.Headers.Add('Content-Type', 'text/xml; charset="utf-8"');
	
	// Create XML DOM document.
	var oWriter = new ITHit.XMLDoc();
	
	// Create XML request.
	var propUpd = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'propertyupdate');
	
	// Check whether properties to add or update are specified.
	if (oNsMethods.Proppatch.ItemExists(aPropsToAddOrUpdate)) {
		var set = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'set');

		for (var i = 0; i < aPropsToAddOrUpdate.length; i++) {
			if (aPropsToAddOrUpdate[i]) {
				var prop = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'prop');
				prop.appendChild(aPropsToAddOrUpdate[i].Value);
				set.appendChild(prop);
			}
		}
		propUpd.appendChild(set);
	}
	
	// Check whether properties to delete are specified.
	if (oNsMethods.Proppatch.ItemExists(aPropsToDelete)) {
		var remove = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'remove');
		var prop = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'prop');
		for (var i = 0; i < aPropsToDelete.length; i++) {
			if (aPropsToDelete[i]) {
				var elem = oWriter.createElementNS(aPropsToDelete[i].NamespaceUri, aPropsToDelete[i].Name);
				prop.appendChild(elem);
			}
		}
		remove.appendChild(prop);
		propUpd.appendChild(remove);
	}
	
	oWriter.appendChild(propUpd);
	oRequest.Body(oWriter);
	
	return oRequest;
};



