/*
 * Parses activeLocks from lockNode.
 * @function {static ITHit.WebDAV.Client.LockInfo} ITHit.WebDAV.Client.LockInfo.ParseLockInfo
 * 
 * @param {ITHit.XMLDoc} oElement Node containing XML Element with activeLock node.
 * @param {String} sHref Request's URI.
 *  
 * @returns Information about active locks.
 */
ITHit.oNS.LockInfo.ParseLockInfo = function(oElement, sHref) {
	
	// Get reference for namespace.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Declare resolver for namespace.
	var oResolver = new ITHit.XPath.resolver();
	oResolver.add('d', oNsCl.DavConstants.NamespaceUri);
	
	// Declare node variable.
	var oNode;
	
	// Get lock scope.
	if (!(oNode = ITHit.XPath.selectSingleNode('d:lockscope', oElement, oResolver))) {
		throw new oNsCl.Exceptions.WebDavException(ITHit.Phrases.Exceptions.ActiveLockDoesntContainLockscope);
	}
	
	
	var oLockScope = oNode.firstChild().localName();
	
	// Get depth.
	if ( !(oNode = ITHit.XPath.selectSingleNode('d:depth', oElement, oResolver)) ) {
		throw new oNsCl.Exceptions.WebDavException(ITHit.Phrases.Exceptions.ActiveLockDoesntContainDepth);
	}
	
	var oDepthValue = oNsCl.Depth.Parse(oNode.firstChild().nodeValue());
	var bDeep = (oDepthValue == oNsCl.Depth.Infinity);
	
	// Get owner.
	var sOwner = null;
	if ( oNode = ITHit.XPath.selectSingleNode('d:owner', oElement, oResolver) ) {
		sOwner = oNode.firstChild().nodeValue();
	}
	
	// Get timeout.
	var iTimeOut = -1;
	if ( oNode = ITHit.XPath.selectSingleNode('d:timeout', oElement, oResolver) ) {
		var sTimeOut = oNode.firstChild().nodeValue();
		
		if ('infinite' != sTimeOut.toLowerCase()) {
			if (-1 != sTimeOut.toLowerCase().indexOf('second-')) {
				sTimeOut = sTimeOut.substr(7);
			}
			var iTimeOut = parseInt(sTimeOut);
		}
	}
	
	// Get lock token.
	
	var oLockToken = null;
	if ( oNode = ITHit.XPath.selectSingleNode('d:locktoken', oElement, oResolver) ) {
		var sLockTokenText = ITHit.XPath.selectSingleNode('d:href', oNode, oResolver).firstChild().nodeValue();
		sLockTokenText = sLockTokenText.replace(oNsCl.DavConstants.OpaqueLockToken, '');
		oLockToken = new oNsCl.LockUriTokenPair(sHref, sLockTokenText);
	}
	
	return new oNsCl.LockInfo(oLockScope, bDeep, sOwner, iTimeOut, oLockToken);
}

/*
 * Parses activeLocks from lockNode.
 * @function {static Array} ITHit.WebDAV.Client.LockInfo.ParseLockDiscovery
 * 
 * @param {ITHit.XMLDoc} oElement Node containing XML Element with activeLock node.
 * @param {String} sHref Request's URI
 * 
 * @returns Information about active locks.
 */
ITHit.oNS.LockInfo.ParseLockDiscovery = function(oElement, sHref) {
	
	// Get reference for namespace.
	var oNsCl   = ITHit.WebDAV.Client;
	
	// Declare variable list of locks.
	var aLocks = [];
	
	// Get a list of active lockes nodes.
	var aSearchedLocks = oElement.getElementsByTagNameNS(oNsCl.DavConstants.NamespaceUri, 'activelock');
	
	for (var i = 0; i < aSearchedLocks.length; i++) {
		aLocks.push(oNsCl.LockInfo.ParseLockInfo(aSearchedLocks[i], sHref));
	}
	
	return aLocks;
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.LockResponse = function(oResponse, sHref) {
	
	// Declare class properties.
	this.ResponseDescriptiono = oResponse.Status.Description;
	this.Status = oResponse.Status;
	this.LockInfo;
	
	// Get reference for namespace.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Get response data as string.
	var oXmlDoc = oResponse.GetResponseStream();
	
	// Create namespace resolver.
	var oResolver = new ITHit.XPath.resolver();
	oResolver.add('d', oNsCl.DavConstants.NamespaceUri);
	
	// Select property element.
	var oProp = new oNsCl.Property(ITHit.XPath.selectSingleNode('/d:prop', oXmlDoc, oResolver));
	
	try {
		
		// Parse property element.
		var oInfos = new oNsCl.LockInfo.ParseLockDiscovery(oProp.Value, sHref);
		
		// Check length of selected elements.
		if (1 != oInfos.length) {
			throw new oNsCl.Exceptions.WebDavException(ITHit.Phrases.UnableToParseLockInfoResponse);
		}
		
		// Select property element.
		this.LockInfo = oInfos[0];
		
	// Exception had happened.
	} catch(e) {
		throw new oNsCl.Exceptions.PropertyException(
				ITHit.Phrases.Exceptions.ParsingPropertiesException,
				sHref,
				oProp.Name,
				null,
				oNsCl.HttpStatus.OK,
				e
			);
	}
};


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.Lock = function(oResponse) {
	
	// Inheritance definition.
	ITHit.WebDAV.Client.Methods.Lock.baseConstructor.call(this);
	
	this.Response = oResponse;
}

// Extend class.
ITHit.Extend(ITHit.oNS.Lock, ITHit.oNS.HttpMethod);

ITHit.oNS.Lock.Go = function(oSession, sHref, iTimeout, sLockTokenOrScope, sHost, bDeep, sOwner) {
	
	// Get references for namespaces.
	var oNsCl = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;
	
	// Create request.
	switch (arguments.length) {
		case 7:
			var oRequest = oNsMethods.Lock.createRequest(oSession, sHref, iTimeout, sLockTokenOrScope, sHost, bDeep, sOwner);
			break;
			
		case 5:
			var oRequest = oNsMethods.Lock.createRequest(oSession, sHref, iTimeout, sLockTokenOrScope, sHost);
			break;
			
		default:
				throw new ITHit.Exception(ITHit.Phrases.Exceptions.LockWrongCountParametersPassed.Paste('Go', arguments.length));
	}
	
	// Get response.
	var oResponse = oRequest.GetResponse();
	
	// Get lock response object.
	var oLockResponse = new oNsMethods.LockResponse(oResponse, sHref);
	
	ITHit.Logger.FinishRequest();
	
	return new oNsMethods.Lock(oLockResponse);
}

ITHit.oNS.Lock.createRequest = function(oSession, sHref, iTimeout, sLockTokenOrScope, sHost, bDeep, sOwner) {
	
	// Get references for namespaces.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Switch count of passed variabled (5 or 7).
	switch (arguments.length) {
			
		case 7:
			
			// Passed lock scope.
			var sLockScope = sLockTokenOrScope;
			
			// Create request.
			var oRequest = oSession.CreateRequest(sHost, sHref);
			oRequest.Method('LOCK');
			
			// Add headers.
			oRequest.Headers.Add('Timeout',
					(-1 == iTimeout)
						? 'Infinite'
						: 'Second-'+ parseInt(iTimeout)
				);
			oRequest.Headers.Add('Depth', bDeep ? oNsCl.Depth.Infinity.Value : oNsCl.Depth.Zero.Value);
			oRequest.Headers.Add('Content-Type', 'text/xml; charset="utf-8"');
			
			// Create XML DOM document object.
			var oWriter = new ITHit.XMLDoc();
			
			// Get namespace for XML elements.
			var sNamespaceUri = oNsCl.DavConstants.NamespaceUri;
			
			// Create root element.
			var lockInfo = oWriter.createElementNS(sNamespaceUri, 'lockinfo');
			
			// Create elements.
			var lockScope = oWriter.createElementNS(sNamespaceUri, 'lockscope');
			var lockScopeData = oWriter.createElementNS(sNamespaceUri, sLockScope.toLowerCase());
			lockScope.appendChild(lockScopeData);
			
			var lockType = oWriter.createElementNS(sNamespaceUri, 'locktype');
			var write = oWriter.createElementNS(sNamespaceUri, 'write');
			lockType.appendChild(write);
			
			var owner = oWriter.createElementNS(sNamespaceUri, 'owner');
			owner.appendChild(oWriter.createTextNode(sOwner));
			
			lockInfo.appendChild(lockScope);
			lockInfo.appendChild(lockType);
			lockInfo.appendChild(owner);
			
			oWriter.appendChild(lockInfo);
			
			// Add XML document as request body.
			oRequest.Body(oWriter);
			
			break;
		
		case 5:
			
			// Passed lock token.
			var sLockToken = sLockTokenOrScope;
			
			// Create request.
			var oRequest = oSession.CreateRequest(sHost, sHref, sLockToken);
			oRequest.Method('LOCK');
			
			// Add header.
			oRequest.Headers.Add('Timeout',
					(-1 == iTimeout)
						? 'Infinite'
						: 'Second-'+ parseInt(iTimeout)
				);
			
			oRequest.Body('');
			
			break;
			
		default:
			throw new ITHit.Exception(ITHit.Phrases.Exceptions.LockWrongCountParametersPassed.Paste('createRequest', arguments.length));
		
	}
	
	return oRequest;
};


