// Extend class.
ITHit.Extend(ITHit.oNS.Unlock, ITHit.oNS.HttpMethod);

ITHit.oNS.Unlock.Go = function(oSession, sHref, sLockToken, sHost) {
	
	// Get references for namespaces.
	var oNsCl     = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;
	
	// Create request.
	var oRequest = oNsMethods.Unlock.createRequest(oSession, sHref, sLockToken, sHost);
	
	// Get response.
	var oResponse = oRequest.GetResponse();
	
	// Parse response response.
	var oUnlock = new oNsMethods.Unlock(new oNsMethods.SingleResponse(oResponse));
	
	ITHit.Logger.FinishRequest();
	
	// Return response object.
	return oUnlock;
}

ITHit.oNS.Unlock.createRequest = function(oSession, sHref, sLockToken, sHost) {
	
	// Create request.
	var oRequest = oSession.CreateRequest(sHost, sHref);
	oRequest.Method('UNLOCK');
	
	// Add header.
	oRequest.Headers.Add('Lock-Token', '<'+ ITHit.WebDAV.Client.DavConstants.OpaqueLockToken + sLockToken+ '>');
	
	return oRequest;
};

