ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');


/**
 * Information about file upload progress.
 * @class {static Object} ITHit.WebDAV.Client.UploadProgressInfo
 */
/*
 * Information about file upload progress.
 * @function {Object} ITHit.WebDAV.Client.UploadProgressInfo
 * 
 * @param {String}  sHref                 Item's path.
 * @param {Integer} iBytesUploaded        Uploaded bytes.
 * @param {Integer} iContentLength        Total file size.
 * @param {optional Date} oLastChunkSaved Last chunk save date.
 */
ITHit.oNS.UploadProgressInfo = function(sHref, iBytesUploaded, iContentLength, oLastChunkSaved) {
	
	if (!ITHit.Utils.IsString(sHref) || !sHref) {
		throw new ITHit.Exceptions.ArgumentException(ITHit.Phrases.Exceptions.WrongHref.Paste(), sHref);
	}
	
	if (!ITHit.Utils.IsInteger(iBytesUploaded)) {
		throw new ITHit.Exceptions.ArgumentException(ITHit.Phrases.Exceptions.WrongUploadedBytesType, iBytesUploaded);
	}
	
	if (!ITHit.Utils.IsInteger(iContentLength)) {
		throw new ITHit.Exceptions.ArgumentException(ITHit.Phrases.Exceptions.WrongContentLengthType, iContentLength);
	}
	
	if (iBytesUploaded > iContentLength) {
		throw new ITHit.Exceptions.ExpressionException(ITHit.Phrases.Exceptions.BytesUploadedIsMoreThanTotalFileContentLength);
	}
	
	/**
	 * Item path on the server.
	 * @property {String} ITHit.WebDAV.Client.UploadProgressInfo.Href
	 */
	this.Href               = sHref;
	
	/**
	 * Amount of bytes successfully uploaded to server.
	 * @property {Integer} ITHit.WebDAV.Client.UploadProgressInfo.BytesUploaded
	 */
	this.BytesUploaded      = iBytesUploaded;
	
	/**
	 * Total file size.
	 * @property {Integer} ITHit.WebDAV.Client.UploadProgressInfo.TotalContentLength
	 */
	this.TotalContentLength = iContentLength;
	
	/**
	 * The date and time when the last chunk of file was saved on server side.
	 * @property {Date} ITHit.WebDAV.Client.UploadProgressInfo.LastChunkSaved
	 */
	this.LastChunkSaved     = oLastChunkSaved;
}

ITHit.oNS.UploadProgressInfo.GetUploadProgress = function(oMultiResponse) {
	
	var oNsCl          = ITHit.WebDAV.Client
	var oNsUplProgress = oNsCl.UploadProgressInfo;
	var aUploadInfo    = [];
	
	if (!oNsUplProgress.PropNames) {
		oNsUplProgress.PropNames = [
			new oNsCl.PropertyName('bytes-uploaded', 'ithit'),
			new oNsCl.PropertyName('last-chunk-saved', 'ithit'),
			new oNsCl.PropertyName('total-content-length', 'ithit')
		];
	}
	
	for (var i = 0, oResponse; oResponse = oMultiResponse.Responses[i]; i++) {
		for (var j = 0, oPropstat; oPropstat = oResponse.Propstats[j]; j++) {
			
			var oFoundedProps = [];
	
			for (var k = 0, oProp; oProp = oPropstat.Properties[k]; k++) {
				
				// Bytes uploaded.
				if (oProp.Name.Equals(oNsUplProgress.PropNames[0])) {
					oFoundedProps[0] = oProp.Value;
				}
				// Last chunk saved.
				else if (oProp.Name.Equals(oNsUplProgress.PropNames[1])) {
					oFoundedProps[1] = oProp.Value;
				}
				// Percent uploaded.
				else if (oProp.Name.Equals(oNsUplProgress.PropNames[2])) {
					oFoundedProps[2] = oProp.Value;
				}
			}
			
			if (!oFoundedProps[0] || !oFoundedProps[1] || !oFoundedProps[2]) {
				throw new ITHit.Exception(ITHit.Phrases.Exceptions.NotAllPropertiesReceivedForUploadProgress.Paste(oResponse.Href));
			}
			
			aUploadInfo.push(new oNsUplProgress(oResponse.Href, parseInt(oFoundedProps[0].firstChild().nodeValue()), parseInt(oFoundedProps[2].firstChild().nodeValue()), oNsCl.HierarchyItem.GetDate(oFoundedProps[1].firstChild().nodeValue())));
		}
	}
	
	return aUploadInfo;
};


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.Report = function(oResponse, reportType) {

    // Get reference for namespace.
    var oNsCl = ITHit.WebDAV.Client;
    var oNsMethods = oNsCl.Methods;

    // Inheritance definition.
    oNsCl.Methods.Report.baseConstructor.call(this);

    // Response
    this.Response = oResponse;

    switch (reportType) {
        case oNsMethods.Report.ReportType.UploadProgress:
            return oNsCl.UploadProgressInfo.GetUploadProgress(oResponse);
    }
}

// Extend class.
ITHit.Extend(ITHit.oNS.Report, ITHit.oNS.HttpMethod);

ITHit.oNS.Report.ReportType = {

    /**
     * Report return upload progress info (default)
     * @property {static read String} ITHit.oNS.Report.ReportType.UploadProgress
     */
    UploadProgress: 'UploadProgress',

    /**
     * Report return versions tree
     * @property {static read String} ITHit.oNS.Report.ReportType.VersionsTree
     */
    VersionsTree: 'VersionsTree'
}

ITHit.oNS.Report.Go = function (oSession, sHref, sHost, reportType, aProperties) {
    return ITHit.WebDAV.Client.Methods.Report.GoAsync(oSession, sHref, sHost, reportType, aProperties);
}

ITHit.oNS.Report.GoAsync = function (oSession, sHref, sHost, reportType, aProperties, fCallback) {

    // Get references for namespaces.
    var oNsCl      = ITHit.WebDAV.Client;
    var oNsMethods = oNsCl.Methods;

    // by default
    if (!reportType) {
        reportType = oNsMethods.Report.ReportType.UploadProgress;
    }

    // Create request.
    var oRequest = oNsMethods.Report.createRequest(oSession, sHref, sHost, reportType, aProperties);


    var self = this;
    var fOnResponse = typeof fCallback === 'function'
        ? function (oResult) { self._GoCallback(oSession, sHref, oResult, reportType, fCallback) }
        : null;

    // Make request.
    var oResponse = oRequest.GetResponse(fOnResponse);

    if (typeof fCallback !== 'function') {
        var oResult = new oNsCl.AsyncResult(oResponse, oResponse != null, null);
        return this._GoCallback(oSession, sHref, oResult, reportType, fCallback);
    } else {
		return oRequest;
	}
}

ITHit.oNS.Report._GoCallback = function (oSession, sHref, oResult, reportType, fCallback) {

    // Get references for namespaces.
    var oNsCl = ITHit.WebDAV.Client;
    var oNsMethods = oNsCl.Methods;

    var oResponse = oResult;
    var bSuccess = true;
    var oError = null;

    if (oResult instanceof ITHit.WebDAV.Client.AsyncResult) {
        oResponse = oResult.Result;
        bSuccess = oResult.IsSuccess;
        oError = oResult.Error;
    }

    var oReport = null;
    if (bSuccess) {
        // Receive data.
        var oResponseData = oResponse.GetResponseStream();

        // Finish logger session.
        ITHit.Logger.FinishRequest();

        oReport = new oNsMethods.Report(new oNsMethods.MultiResponse(oResponseData, sHref), reportType);
    }

    // Return response.
    if (typeof fCallback === 'function') {
        var oReportResult = new oNsCl.AsyncResult(oReport, bSuccess, oError);
        fCallback.call(this, oReportResult);
    } else {
        return oReport;
    }
}

ITHit.oNS.Report.createRequest = function(oSession, sHref, sHost, reportType, aProperties) {

    // Create request.
    var oNsCl      = ITHit.WebDAV.Client;
    var oNsMethods = oNsCl.Methods;
    var oRequest = oSession.CreateRequest(sHost, sHref);

    oRequest.Method('REPORT');
    oRequest.Headers.Add('Content-Type', 'text/xml; charset="utf-8"');

    // Create XML DOM document.
    var oWriter = new ITHit.XMLDoc();

    switch (reportType) {
        case oNsMethods.Report.ReportType.UploadProgress:
            var oElem = oWriter.createElementNS('ithit', 'upload-progress');
            oWriter.appendChild(oElem);
            break;

        case oNsMethods.Report.ReportType.VersionsTree:
            // Create root element.
            var oVersionTreeElement = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'version-tree');

            // All properties.
            if (!aProperties || !aProperties.length) {
                var propEl = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'allprop');

                // Selected properties.
            } else {
                var propEl = oWriter.createElementNS(oNsCl.DavConstants.NamespaceUri, 'prop');
                for (var i = 0; i < aProperties.length; i++) {
                    var prop = oWriter.createElementNS(aProperties[i].NamespaceUri, aProperties[i].Name);
                    propEl.appendChild(prop);
                }
            }

            // Append created child nodes.
            oVersionTreeElement.appendChild(propEl);
            oWriter.appendChild(oVersionTreeElement);
            break;
    }

    oRequest.Body(oWriter);

    // Return request object.
    return oRequest;
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.Methods');

ITHit.oNS.VersionUpdate = function(oResponse) {

    // Inheritance definition.
    ITHit.WebDAV.Client.Methods.VersionUpdate.baseConstructor.call(this);

    // Response
    this.Response = oResponse;
}

// Extend class.
ITHit.Extend(ITHit.oNS.VersionUpdate, ITHit.oNS.HttpMethod);

ITHit.oNS.VersionUpdate.Go = function(oSession, sHref, sHost, sToVersionHref) {

	// Get references for namespaces.
	var oNsCl      = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;

	// Create request.
	var oRequest = oNsMethods.VersionUpdate.createRequest(oSession, sHref, sHost, sToVersionHref);

	// Make request.
	var oResponse = oRequest.GetResponse();

	return this._ProcessResponse(oResponse, sHref);
}

ITHit.oNS.VersionUpdate.GoAsync = function(oSession, sHref, sHost, sToVersionHref, fCallback) {

	// Get references for namespaces.
	var oNsCl      = ITHit.WebDAV.Client;
	var oNsMethods = oNsCl.Methods;

	// Create request.
	var oRequest = oNsMethods.VersionUpdate.createRequest(oSession, sHref, sHost, sToVersionHref);

	// Make request.
	var that = this;
	oRequest.GetResponse(function(oAsyncResult) {
		if (!oAsyncResult.IsSuccess) {
			fCallback(new ITHit.WebDAV.Client.AsyncResult(null, false, oAsyncResult.Error));
			return;
		}

		var oResult = that._ProcessResponse(oAsyncResult.Result, sHref);
		fCallback(new ITHit.WebDAV.Client.AsyncResult(oResult, true, null));
	});

	return oRequest;
}

ITHit.oNS.VersionUpdate._ProcessResponse = function(oResponse, sHref) {
	// Get references for namespaces.
	var oNsMethods = ITHit.WebDAV.Client.Methods;

	// Receive data.
	var oResponseData = oResponse.GetResponseStream();
	return new oNsMethods.VersionUpdate(new oNsMethods.MultiResponse(oResponseData, sHref));
};

ITHit.oNS.VersionUpdate.createRequest = function(oSession, sHref, sHost, sToVersionHref) {

    // Create request.
    var oNsCl      = ITHit.WebDAV.Client;
    var oRequest = oSession.CreateRequest(sHost, sHref);

    oRequest.Method('UPDATE');
    oRequest.Headers.Add('Content-Type', 'text/xml; charset="utf-8"');

    // Create XML DOM document.
    var oWriter = new ITHit.XMLDoc();

    // Get namespace for XML elements.
    var sNamespaceUri = oNsCl.DavConstants.NamespaceUri;

    // Create elements.
    var oUpdateElement = oWriter.createElementNS(sNamespaceUri, 'update');
    var oVersionElement = oWriter.createElementNS(sNamespaceUri, 'version');
    var oHrefElement = oWriter.createElementNS(sNamespaceUri, 'href');

    // Set value
    oHrefElement.appendChild(oWriter.createTextNode(sToVersionHref));

    // Append created child nodes.
    oVersionElement.appendChild(oHrefElement);
    oUpdateElement.appendChild(oVersionElement);
    oWriter.appendChild(oUpdateElement);

    oRequest.Body(oWriter);

    // Return request object.
    return oRequest;
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

/**
 * Represents one WebDAV item (resource, folder or lock-null). 
 * @interface ITHit.WebDAV.Client.HierarchyItem
 */
/*
 * Create new instance of HierarchyItem class which represents one WebDAV item (resource, folder or lock-null).
 * @constructor HierarchyItem
 *
 * @param {ITHit.WebDAV.Client.WebDavSession} oSession Current WebDAV session
 * @param {String} sHref This item path on the server. 
 * @param {Object} oGetLastModified Most recent modification date.
 * @param {String} sDisplayName User friendly item name.
 * @param {Object} oCreationDate The date item was created.
 * @param {String} sResourceType Type of this item, see ResourceType.
 */
ITHit.oNS.HierarchyItem = function(oSession, sHref, oLastModified, sDisplayName, oCreationDate, sResourceType, aSupportedLocks, aActiveLocks, sHost, iAvailableBytes, iUsedBytes, aCheckedIn, aCheckedOut, oProperties) {
	
	// Current WebDAV session.
	this.Session = oSession;
	
	/**
	 * This item path on the server.
	 * @property {String} ITHit.WebDAV.Client.HierarchyItem.Href
	 */
	this.Href = sHref;
	
	/**
	 * Most recent modification date.
	 * @property {Date} ITHit.WebDAV.Client.HierarchyItem.LastModified
	 */
	this.LastModified = oLastModified;
	
	/**
	 * User friendly item name.
	 * @property {String} ITHit.WebDAV.Client.HierarchyItem.DisplayName
	 */
	this.DisplayName = sDisplayName;
	
	/**
	 * The date item was created.
	 * @property {Date} ITHit.WebDAV.Client.HierarchyItem.CreationDate
	 */
	this.CreationDate = oCreationDate;
	
	// Whether item was moved or deleted.
	// this.DeletedMoved = false;
	
	/**
	 * Type of the item (Resource or Folder).
	 * @property {String} ITHit.WebDAV.Client.HierarchyItem.ResourceType
	 * @see ITHit.WebDAV.Client.ResourceType
	 */
	this.ResourceType = sResourceType;
	
	/**
	 * Retrieves information about supported locks.
	 * @property {Array} ITHit.WebDAV.Client.HierarchyItem.SupportedLocks
	 * @see ITHit.WebDAV.Client.LockScope
	 */
	this.SupportedLocks = aSupportedLocks;
	
	/**
	 * Retrieves lock information about this item.
	 * @property {Array} ITHit.WebDAV.Client.HierarchyItem.ActiveLocks
	 */
	this.ActiveLocks = aActiveLocks;
	
	/*
	 * Server host.
	 * @property {String} ITHit.WebDAV.Client.HierarchyItem.Host
	 */
	this.Host = sHost;
	
	/*
	 * Available bytes.
	 * @property {String} ITHit.WebDAV.Client.HierarchyItem.AvailableBytes
	 */
	this.AvailableBytes = iAvailableBytes;
	
	/*
	 * Used bytes.
	 * @property {String} ITHit.WebDAV.Client.HierarchyItem.UsedBytes
	 */
	this.UsedBytes = iUsedBytes;

	/*
	 * Checked-in files list
	 * @property {Array} ITHit.WebDAV.Client.HierarchyItem.CheckedIn
	 */
	this.CheckedIn = aCheckedIn;

	/*
	 * Checked-in files list
	 * @property {Array} ITHit.WebDAV.Client.HierarchyItem.CheckedOut
	 */
	this.CheckedOut = aCheckedOut;

	/*
	 * Server version (engine header)
	 * @property {Array} ITHit.WebDAV.Client.HierarchyItem.ServerVersion
	 */
	this.ServerVersion = oSession.sServerEngine;

	/*
	 * Additional properties by user requested
	 * @property {object} Key-value list
	 */
	this.Properties = oProperties;
}

/**
 * Check to property exists
 * @function ITHit.WebDAV.Client.HierarchyItem.HasProperty
 *
 * @param {ITHit.WebDAV.Client.PropertyName} oPropName Property name.
 * @returns {Boolean}
 */
ITHit.oNS.HierarchyItem.prototype.HasProperty = function(oPropName) {
	var sKey = oPropName.toString();
	return this.Properties.hasOwnProperty(sKey);
}

/**
 * Get additional property
 * @function ITHit.WebDAV.Client.HierarchyItem.GetProperty
 *
 * @param {ITHit.WebDAV.Client.PropertyName} oPropName Property name.
 * @returns {*}
 */
ITHit.oNS.HierarchyItem.prototype.GetProperty = function(oPropName) {
    var sKey = oPropName.toString();
    if (!this.Properties.hasOwnProperty(sKey)) {
        throw new ITHit.WebDAV.Client.Exceptions.PropertyNotFoundException('Not found property `' + sKey + '` in resource `' + this.Href + '`.');
    }
    return this.Properties[sKey];
}

/**
* Refresh items's info.
* @function ITHit.WebDAV.Client.HierarchyItem.Refresh
* 
* @throws ITHit.WebDAV.Client.Exceptions.UnauthorizedException &nbsp;Incorrect credentials provided or insufficient permissions to access the requested item.
* @throws ITHit.WebDAV.Client.Exceptions.NotFoundException &nbsp;The requested folder doesn't exist on the server.
* @throws ITHit.WebDAV.Client.Exceptions.ForbiddenException &nbsp;The server refused to fulfill the request.
* @throws ITHit.WebDAV.Client.Exceptions.WebDavException &nbsp;Unexpected error occurred.
*/
ITHit.oNS.HierarchyItem.prototype.Refresh = function() {
	
	var item = this.Session.OpenItem(this.Href);
	
	this.LastModified   = item.LastModified;
	this.CreationDate   = item.CreationDate;
	this.SupportedLocks = item.SupportedLocks;
	this.ActiveLocks    = item.ActiveLocks;
}

/**
 * Copies this item to destination folder.
 * @function ITHit.WebDAV.Client.HierarchyItem.CopyTo
 *
 * @param {ITHit.WebDAV.Client.Folder} oDestinationFolder Folder to move to.
 * @param {String} sDestinationName Name to assign to copied item.
 * @param {Boolean} bDeep Indicates whether children of this item should be copied.
 * @param {Boolean} bOverwrite Whether existing destination item shall be overwritten.
 * @param {optional ITHit.WebDAV.Client.LockUriTokenPair[]} mLockTokens Lock tokens for destination folder.
 *
 * @throws ITHit.WebDAV.Client.Exceptions.ForbiddenException &nbsp;The source and destination URIs are the same.
 * @throws ITHit.WebDAV.Client.Exceptions.LockedException &nbsp;The destination folder or items to be overwritten were locked.
 * @throws ITHit.WebDAV.Client.Exceptions.PreconditionFailedException &nbsp;The destination item exists and overwrite was false.
 * @throws ITHit.WebDAV.Client.Exceptions.NotFoundException &nbsp;This item doesn't exist on the server.
 * @throws ITHit.WebDAV.Client.Exceptions.WebDavHttpException &nbsp;Server returned unknown error for specific resource.
 * @throws ITHit.WebDAV.Client.Exceptions.WebDavException &nbsp;Unexpected error occurred.
 */
ITHit.oNS.HierarchyItem.prototype.CopyTo = function(oDestinationFolder, sDestinationName, bDeep, bOverwrite, oLockTokens) {
	oLockTokens = oLockTokens || null;

	// Start logging.
	ITHit.Logger.StartLogging();

	var oResult = this._CopyToGoRequest(oDestinationFolder, sDestinationName, bDeep, bOverwrite, oLockTokens);

	// Finish logging.
	ITHit.Logger.FinishLogging();

	var oError = this._CopyToProcessResponseException(oResult);
	if (oError) {
		throw oError;
	}
}

/**
 * Async alias for CopyTo
 * @function ITHit.WebDAV.Client.HierarchyItem.CopyToAsync
 */
ITHit.oNS.HierarchyItem.prototype.CopyToAsync = function(oDestinationFolder, sDestinationName, bDeep, bOverwrite, oLockTokens, fCallback) {
	oLockTokens = oLockTokens || null;

	// Start logging.
	ITHit.Logger.StartLogging();

	var that = this;
	return this._CopyToGoRequest(oDestinationFolder, sDestinationName, bDeep, bOverwrite, oLockTokens, function(oAsyncResult) {
		// Finish logging.
		ITHit.Logger.FinishLogging();

		if (!oAsyncResult.IsSuccess) {
			fCallback(new ITHit.WebDAV.Client.AsyncResult(null, false, oAsyncResult.Error));
			return;
		}

		var oError = that._CopyToProcessResponseException(oAsyncResult.Result);
		fCallback(new ITHit.WebDAV.Client.AsyncResult(null, oError === null, oError));
	});
}

ITHit.oNS.HierarchyItem.prototype._CopyToGoRequest = function(oDestinationFolder, sDestinationName, bDeep, bOverwrite, oLockTokens, fCallback) {
	fCallback = fCallback || null;

	var sMethod = fCallback ? 'GoAsync' : 'Go';
	return ITHit.WebDAV.Client.Methods.CopyMove[sMethod](
		this.Session,
		ITHit.WebDAV.Client.Methods.CopyMove.Mode.Copy,
		this.Href,
		ITHit.WebDAV.Client.HierarchyItem.AppendToUri(oDestinationFolder.Href, sDestinationName),
		(this.ResourceType == ITHit.WebDAV.Client.ResourceType.Folder),
		bDeep,
		bOverwrite,
		oLockTokens,
		this.Host,
		fCallback
	);
}

ITHit.oNS.HierarchyItem.prototype._CopyToProcessResponseException = function(oResponse) {
	var oNsCl    = ITHit.WebDAV.Client;
	var oNsExcpt = oNsCl.Exceptions;
	var oError = null;

	if (oResponse instanceof oNsCl.Methods.MultiResponse) {
		var aResponses = oResponse.Responses;
		for (var i = 0, l = aResponses.length; i < l; i++) {
			if (!aResponses[i].Status.IsCopyMoveOk()) {
				oError = new oNsExcpt.WebDavHttpException(
					ITHit.Phrases.FailedToCopy,
					this.Href,
					new oNsExcpt.Info.Multistatus(oResponse),
					oNsCl.HttpStatus.MultiStatus,
					null
				);
				break;
			}
		}
	} else if (oResponse instanceof oNsCl.Methods.SingleResponse) {
		var oResponseStatus = oResponse.Status;
		if (!oResponseStatus.IsCopyMoveOk()) {
			oError = new oNsExcpt.WebDavHttpException(
				ITHit.Phrases.FailedToCopyWithStatus.Paste(oResponseStatus.Code, oResponseStatus.Description),
				this.Href,
				null,
				oResponseStatus,
				null
			);
		}
	}

	return oError;
}

/*
 * Get item's full path.
 * @function {Static String} ITHit.WebDAV.Client.HierarchyItem.AppendToUri
 * 
 * @param {String} sUri Base URI.
 * @param {String} sDestinationName Item name.
 * 
 * @returns Item full path.
 */
ITHit.oNS.HierarchyItem.AppendToUri = function(sUri, sDestinationName) {
	return ITHit.WebDAV.Client.HierarchyItem.GetAbsoluteUriPath(sUri) + ITHit.WebDAV.Client.Encoder.EncodeURI(sDestinationName);
}

/**
 * Deletes this item.
 * @function ITHit.WebDAV.Client.HierarchyItem.Delete
 *
 * @param {ITHit.WebDAV.Client.LockUriTokenPair} oLockTokens Lock tokens for this item or any locked child item.
 *
 * @throws ITHit.WebDAV.Client.Exceptions.LockedException &nbsp;This folder or any child item is locked and no or invalid lock token was specified.
 * @throws ITHit.WebDAV.Client.Exceptions.ForbiddenException &nbsp;User has not enough rights to perform this operation.
 * @throws ITHit.WebDAV.Client.Exceptions.MethodNotAllowedException &nbsp;Trying to delete lock-null item. Lock-null items must be deleted using Unlock method.
 * @throws ITHit.WebDAV.Client.Exceptions.WebDavHttpException &nbsp;Server returned unknown error.
 * @throws ITHit.WebDAV.Client.Exceptions.WebDavException &nbsp;Unexpected error occurred.
 */
ITHit.oNS.HierarchyItem.prototype.Delete = function(oLockTokens) {
	oLockTokens = oLockTokens || null;

	// Delete item.
	var oResult = ITHit.WebDAV.Client.Methods.Delete.Go(this.Session, this.Href, oLockTokens, this.Host);

	var oError = this._DeleteProcessResponseException(oResult.Response);
	if (oError) {
		throw oError;
	}
}

/**
 * Async alias for Delete
 * @function ITHit.WebDAV.Client.HierarchyItem.DeleteAsync
 */
ITHit.oNS.HierarchyItem.prototype.DeleteAsync = function(oLockTokens, fCallback) {
	oLockTokens = oLockTokens || null;

	// Delete item.
	var that = this;
	return ITHit.WebDAV.Client.Methods.Delete.GoAsync(this.Session, this.Href, oLockTokens, this.Host, function(oAsyncResult) {
		if (!oAsyncResult.IsSuccess) {
			fCallback(new ITHit.WebDAV.Client.AsyncResult(null, false, oAsyncResult.Error));
			return;
		}

		var oError = that._DeleteProcessResponseException(oAsyncResult.Result);
		fCallback(new ITHit.WebDAV.Client.AsyncResult(null, oError === null, oError));
	});
}

ITHit.oNS.HierarchyItem.prototype._DeleteProcessResponseException = function(oResponse) {
	var oError = null;

	// Whether response is instance of MultiResponse class.
	if (oResponse instanceof ITHit.WebDAV.Client.Methods.MultiResponse) {
		// Throw Exception.
		oError = new ITHit.WebDAV.Client.Exceptions.WebDavHttpException(
			ITHit.Phrases.FailedToDelete,
			this.Href,
			new ITHit.WebDAV.Client.Exceptions.Info.Multistatus(oResponse),
			ITHit.WebDAV.Client.HttpStatus.MultiStatus,
			null
		);
	}

	// Whether response is instance of SingleResponse class.
	if (oResponse instanceof ITHit.WebDAV.Client.Methods.SingleResponse) {
		// Check status.
		if (oResponse.Status.IsSuccess()) {
			// Deleted successfully.
			// this.DeletedMoved = true;
		} else {
			// Throw exception.
			var sMessage = ITHit.Phrases.DeleteFailedWithStatus.Paste(oResponse.Status.Code, oResponse.Status.Description);
			oError = new ITHit.WebDAV.Client.Exceptions.WebDavHttpException(sMessage, this.Href, null, oResponse.Status, null);
		}
	}

	ITHit.Logger.FinishLogging();

	return oError;
}

/*
* Retrieves lock information about this item.
* @function {Array} ITHit.WebDAV.Client.HierarchyItem.GetActiveLocks
* 
* @returns List of LockInfo objects.
* 
* @throws ITHit.WebDAV.Client.Exceptions.NotFoundException &nbsp;This item doesn't exist on the server.
* @throws ITHit.WebDAV.Client.Exceptions.WebDavException &nbsp;Unexpected error occurred.
*/
ITHit.oNS.HierarchyItem.GetActiveLocks = function(oResp, sHref){
	
	// Get reference for namespace.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Get lock name.
	var oLockDiscovery = oNsCl.DavConstants.LockDiscovery;
	

	for (var i = 0; i < oResp.Propstats.length; i++) {
		var oPropstat = oResp.Propstats[i];
		
		if (!oPropstat.Status.IsOk()) {
			break;
		}
		
		if ('undefined' != typeof oPropstat.PropertiesByNames[oLockDiscovery]) {
			var oProp = oPropstat.PropertiesByNames[oLockDiscovery];
			
			try {
				// Return active locks.
				return oNsCl.LockInfo.ParseLockDiscovery(oProp.Value, sHref);
			} catch (e) {
				break;
			}
			
		} else {
			break;
		}
	}
	
	return [];
}

