	// Refresh lock.
	var oLockMethod = oNsMethods.Lock.Go(
			this.Session,
			this.Href,
			iTimeout,
			sLockToken,
			this.Host
		);
	
	// Get response.
	var oLockResponse = oLockMethod.Response;
	
