ITHit.oNS.InsufficientStorage = function(sMessage, sHref, oMultistatus, oError, oInnerException) {
	
	var sExceptionClass = 'InsufficientStorageException',
	    oNsCl = ITHit.WebDAV.Client;
	
	if (1 == oError.Properties.length) {
		var oPropName = oError.Properties[0].Name;
		
		if (oPropName.Equals(oNsCl.DavConstants.QuotaNotExceeded)) {
			sExceptionClass = 'QuotaNotExceededException';
		} else if (oPropName.Equals(oNsCl.DavConstants.SufficientDiskSpace)) {
			sExceptionClass = 'SufficientDiskSpaceException';
		}
	}
	
	return new oNsCl.Exceptions[sExceptionClass]((oError.Description || sMessage), sHref, oMultistatus, oInnerException, oError);
};


