/*
 * XMLHttpRequest request object.
 * @class ITHit.WebDAV.Client.WebDavRequest
 */
ITHit.oNS.WebDavRequest = {};
(function() {
	
	
	/*
	 * Request header collection.
	 */
	var Headers = function(oHeaders) {
		this.Headers = oHeaders;
	};
	
	/*
	 * Save header for request.
	 * @function ITHit.WebDAV.Client.WebDavRequest.Add
	 * 
	 * @param {String} sHeader Header's name.
	 * @param {String} sValue Header's value.
	 */
	Headers.prototype.Add = function(sHeader, sValue) {
		this.Headers[sHeader] = sValue;
	}
	
	/*
	 * Get headers dictionary as reference.
	 * @function {Object} ITHit.WebDAV.Client.WebDavRequest.GetAll
	 * 
	 * @returns Headers list.
	 */
	Headers.prototype.GetAll = function() {
		return this.Headers;
	}
	
	
	/*
	 * Create instance of WebDavRequest class.
	 * @constructor {private} WebDavRequest
	 * 
	 * @param {String} sUri URI
	 */
	var WebDavRequest = function(sUri, sUser, sPass) {
		
		ITHit.Logger.StartRequest();
		
		this._Href     = sUri;
		this._Method   = 'GET';
		this._Headers  = {};
		this._Body     = '';
		this._User     = sUser;
		this._Password = sPass;

		this.Headers   = new Headers(this._Headers);
		this.PreventCaching = null;
		this.OnProgress = null; // Custom handler for get progress event
		this._XMLRequest = null;

		this._ClassId  = 'ITHit.WebDAV.Client.WebDavSession.WebDavRequest_'+ WebDavRequest._Counter++;
	}
	
	WebDavRequest._Counter = 0;
	
	/*
	 * Create request.
	 * @function {static ITHit.WebDAV.Client.WebDavRequest} ITHit.WebDAV.Client.WebDavRequest.Create
	 * 
	 * @paramset Syntax 1
	 * @param {String} sUri Page URI.
	 * @param {String} mLockTokens Lock token for item.
	 * @paramset Syntax 2
	 * @param {String} sUri Page URI.
	 * @param {Array} mLockTokens Lock tokens for item.
	 * 
	 * @returns Request object.
	 */
	ITHit.oNS.WebDavRequest.Create = function(sUri, mLockTokens, sUser, sPass, sHost) {
		
		// Whether host is not set than add it.
		if (/^\//.test(sUri)) {
			sUri = sHost + sUri.substr(1);
		}
		
		// Create WebDavRequest object for specified URI.
		var oRequest = new WebDavRequest(sUri, sUser, sPass);
		
		// Get reference for namespace.
		var oNsCl = ITHit.WebDAV.Client;
		
		// If mLockTokens is string.
		if ('string' == typeof mLockTokens) {
			if (mLockTokens) {
				
				// Add If header.
				oRequest.Headers.Add('If', '(<'+ oNsCl.DavConstants.OpaqueLockToken + mLockTokens +'>)');
			}
			
		// Else if mLockTokens is an array type.
		} else if ( (mLockTokens instanceof Array) && mLockTokens.length) {
			
			var sLockTokensHeader = '';
			var bFirst = true;
			
			for (var i = 0; i < mLockTokens.length; i++) {
				
				// Check whether LockToken element is not null.
				oNsCl.WebDavUtil.VerifyArgumentNotNull(mLockTokens[i], "lockToken");
				
				// Append LockToken to header collection.
				sLockTokensHeader += (bFirst ? '' : ' ') + '(<'+ oNsCl.DavConstants.OpaqueLockToken + mLockTokens[i].LockToken +'>)';
				
				bFirst = false;
			}
			
			// Add If header.
			oRequest.Headers.Add("If", sLockTokensHeader);
		}
		
		return oRequest;
	}
	
	/*
	 * Get or set method for request
	 * @function {String} ITHit.WebDAV.Client.WebDavRequest.Method
	 * 
	 * @param {String} sValue Method's value.
	 * 
	 * @returns Method's value.
	 */
	WebDavRequest.prototype.Method = function(sValue) {
		if (undefined !== sValue) {
			this._Method = sValue;
		}
		
		return this._Method;
	}
	
	WebDavRequest.prototype.Body = function(mBody) {
		if (undefined !== mBody) {
			this._Body = mBody;
		}
		
		return this._Body;
	}

	WebDavRequest.prototype.Abort = function() {
		if (this._XMLRequest !== null) {
			this._XMLRequest.Abort();
		}
	}
	
	/*
	 * Make XMLHttpRequest and get response.
	 * @function {ITHit.WebDAV.Client.WebDavResponse} ITHit.WebDAV.Client.WebDavRequest.GetResponse
	 * @param {Function} fCallback Callback for asynchronous requests. If set null/undefined, then request will be send as synchronous.
	 * 
	 * @returns Response object.
	 */
	WebDavRequest.prototype.GetResponse = function(fCallback) {
		
        // Send async request
        var bAsync = typeof fCallback === 'function';

        var sHref = this._Href;

        // Add nocache attribute for force disabled cache
        if ((ITHit.Config.PreventCaching && this.PreventCaching === null) || this.PreventCaching === true ) {
            var sAndSymbol = sHref.indexOf('?') !== -1 ? '&' : '?';
            var sNoCacheParam = sAndSymbol + 'nocache=' + new Date().getTime();

            if (sHref.indexOf('#') !== -1) {
                sHref.replace(/#/g, sNoCacheParam + '#');
			} else {
                sHref += sNoCacheParam;
			}
        }

        // Fix for XMLHttpRequest.
        // TODO: Remove fix when encoding special characters on server will be fixed.
        sHref = sHref.replace(/#/g, '%23');

		var oRequestData = new ITHit.HttpRequest(
            sHref,
			this._Method,
			this._Headers,
			String(this._Body)
		);
		
		var oResponseData = ITHit.Events.DispatchEvent(this, 'OnBeforeRequestSend', oRequestData);
		
		if (!oResponseData || !(oResponseData instanceof ITHit.HttpResponse)) {
			
			// Set default user and password if specified.
			oRequestData.User     = (null === oRequestData.User) ? this._User : oRequestData.User;
			oRequestData.Password = (null === oRequestData.Password) ? this._Password : oRequestData.Password;
			
			// Log request method and URI.
			ITHit.Logger.WriteMessage(oRequestData.Method + ' ' + oRequestData.Href);

			// Get headers.
			var oHeaders = oRequestData.Headers;
			
			// Log and set request headers.
			for (var sHeader in oHeaders) {
				ITHit.Logger.WriteMessage(sHeader + ': ' + oHeaders[sHeader]);
			}
			
			oRequestData.Body = String(oRequestData.Body) || '';
			
			// Log request body if method is not PUT and body is not empty.
			if (('PUT' != oRequestData.Method.toUpperCase()) && oRequestData.Body) {
				ITHit.Logger.WriteMessage(oRequestData.Body);
			}
			
			// Send request.
			this._XMLRequest = new ITHit.XMLRequest(oRequestData, bAsync);
		}

        if (bAsync) {
            if (this._XMLRequest !== null) {
                // Call callback after receiving the response
                var self = this;
				this._XMLRequest.OnData = function (oResponseData) {
                    var oWebDavResponse = null;
                    var bSuccess = true;
                    var oError = null;
                    try {
                        oWebDavResponse = self._onGetResponse(oRequestData, oResponseData);
                        bSuccess = true;
                    }
                    catch (e) {
                        oError = e;
                        bSuccess = false;
                    }

                    var oAsyncResult = new ITHit.WebDAV.Client.AsyncResult(oWebDavResponse, bSuccess, oError);
                    fCallback.call(this, oAsyncResult);
                };
				this._XMLRequest.OnError = function (oException) {
					var oWebDavHttpException = new ITHit.WebDAV.Client.Exceptions.WebDavHttpException(oException.message, sHref, null, null, oException);
					var oAsyncResult = new ITHit.WebDAV.Client.AsyncResult(null, false, oWebDavHttpException);
					fCallback.call(this, oAsyncResult);
				};
				this._XMLRequest.OnProgress = function (oEvent) {
					if (typeof self.OnProgress === 'function') {
						self.OnProgress(oEvent);
					}
				};

				this._XMLRequest.Send();
            } else {
                // Only call callback
                var oWebDavResponse = this._onGetResponse(oRequestData, oResponseData);
                fCallback.call(this, oWebDavResponse);
            }
        } else {
            if (this._XMLRequest !== null) {
				this._XMLRequest.Send();
                oResponseData = this._XMLRequest.GetResponse();
            }

            // Send response synchronous
            var oWebDavResponse = this._onGetResponse(oRequestData, oResponseData);
            return oWebDavResponse;
        }
	}

    WebDavRequest.prototype._onGetResponse = function(oRequestData, oResponseData) {
        // Get references to namespaces.
        var oNsCl     = ITHit.WebDAV.Client;

        ITHit.Events.DispatchEvent(this, 'OnResponse', oResponseData);

        var oStatus = new oNsCl.HttpStatus(oResponseData.Status, oResponseData.StatusDescription);

		// If status is 278 treat this as a redirect, 302 redirect is processed automatically, no way to display login page
	    // http://stackoverflow.com/questions/199099/how-to-manage-a-redirect-request-after-a-jquery-ajax-call
		if (oResponseData.Status == oNsCl.HttpStatus.Redirect.Code) {
		    window.location.replace(oResponseData.Headers['Location']);
		}

        // If status is not success then raise exception.
        if (!oStatus.IsSuccess()) {
            throw WebDavRequest.ProcessWebException(oResponseData);
        }

        // Return response.
        return new oNsCl.WebDavResponse(oResponseData, oRequestData.Method);
    }
	
	WebDavRequest.ProcessWebException = function(oResponseData) {
		
		// Get references for namespaces.
		var oNsCl         = ITHit.WebDAV.Client,
		    oNsHttpStatus = oNsCl.HttpStatus,
		    oNsExcept     = oNsCl.Exceptions,
		    oResponse     = null,
		    sResponseData = '';
		
		if (oResponseData.BodyXml && oResponseData.BodyXml.childNodes.length) {
			oResponse     = new ITHit.XMLDoc(oResponseData.BodyXml);
			sResponseData = String(oResponse);
		}
		
		// Log error message.
		ITHit.Logger.WriteMessage('\n'+ oResponseData.Status +' '+ oResponseData.StatusDescription);
		var aHeaders = [];
		for (var sHeader in oResponseData.Headers) {
			aHeaders.push(sHeader +':'+ oResponseData.Headers[sHeader]);
		}
		ITHit.Logger.WriteMessage(aHeaders.join('\n'));
		ITHit.Logger.WriteMessage(sResponseData ? sResponseData : oResponseData.BodyText);
		
		// Try parse multistatus response.
		var oInfo         = null,
		    oErrorInfo    = null;
		
		if (oResponse) {
			var oErrorResponse = new oNsCl.Methods.ErrorResponse(oResponse, oResponseData.Href);
			oErrorInfo         = new oNsExcept.Info.Error(oErrorResponse);
			
			var oMultiResponse = new oNsCl.Methods.MultiResponse(oResponse, oResponseData.Href);
			oInfo              = new oNsExcept.Info.Multistatus(oMultiResponse);
		} else {
			oErrorInfo         = new oNsExcept.Info.Error();
			oErrorInfo.BodyText = oResponseData.BodyText;
		}
		
		// Throw apropriate exception
		var oException = null,
		    oExceptionToThrow;

		switch (oResponseData.Status) {

			case oNsHttpStatus.Unauthorized.Code:
				oExceptionToThrow = new oNsExcept.UnauthorizedException(ITHit.Phrases.Exceptions.Unauthorized, oResponseData.Href, oException);
				break;

			case oNsHttpStatus.Conflict.Code:
				oExceptionToThrow = new oNsExcept.ConflictException(ITHit.Phrases.Exceptions.Conflict, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.Locked.Code:
				oExceptionToThrow = new oNsExcept.LockedException(ITHit.Phrases.Exceptions.Locked, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.BadRequest.Code:
				oExceptionToThrow = new oNsExcept.BadRequestException(ITHit.Phrases.Exceptions.BadRequest, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.Forbidden.Code:
				oExceptionToThrow = new oNsExcept.ForbiddenException(ITHit.Phrases.Exceptions.Forbidden, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.MethodNotAllowed.Code:
				oExceptionToThrow = new oNsExcept.MethodNotAllowedException(ITHit.Phrases.Exceptions.MethodNotAllowed, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.NotImplemented.Code:
				oExceptionToThrow = new oNsExcept.NotImplementedException(ITHit.Phrases.Exceptions.MethodNotAllowed, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.NotFound.Code:
				oExceptionToThrow = new oNsExcept.NotFoundException(ITHit.Phrases.Exceptions.NotFound, oResponseData.Href, oException);
				break;

			case oNsHttpStatus.PreconditionFailed.Code:
				oExceptionToThrow = new oNsExcept.PreconditionFailedException(ITHit.Phrases.Exceptions.PreconditionFailed, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.DependencyFailed.Code:
				oExceptionToThrow = new oNsExcept.DependencyFailedException(ITHit.Phrases.Exceptions.DependencyFailed, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;

			case oNsHttpStatus.InsufficientStorage.Code:
				oExceptionToThrow = oNsExcept.Parsers.InsufficientStorage(ITHit.Phrases.Exceptions.InsufficientStorage, oResponseData.Href, oInfo, oErrorInfo, oException);
				break;
				
			default:
				if (sResponseData) {
					sResponseData = '\n'+ ITHit.Phrases.ServerReturned +'\n----\n'+ sResponseData +'\n----\n';
				}
				
				oExceptionToThrow = new oNsExcept.WebDavHttpException(
					ITHit.Phrases.Exceptions.Http + sResponseData,
					oResponseData.Href,
					oInfo,
					new oNsCl.HttpStatus(oResponseData.Status, oResponseData.StatusDescription),
					oException,
					oErrorInfo
				);
				break;
		}
		
		ITHit.Logger.FinishLogging();

		return oExceptionToThrow;
	}
	
	WebDavRequest.prototype.LogRequestInfo = function() {
		
		if (ITHit.Logger.LogLevel <= ITHit.LogLevel.Info) {
			ITHit.Logger.WriteMessage(oRequest._Method +' '+ oRequest._Href);
			var oHeaders = oRequest._Headers;
			for (var sHeaderName in oHeaders) {
				ITHit.Logger.WriteMessage(sHeaderName +' : '+ oHeaders[sHeaderName]);
			}
		}
	}
	
	WebDavRequest.prototype.toString = function() {
		return this._ClassId;
	}
	
	return this;
})();


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client');

/**
* Session for accessing WebDAV servers.
* @class ITHit.WebDAV.Client.WebDavSession
*/
/**
 * Constructor for WebDAV session.
 * @constructor WebDavSession
 */
ITHit.oNS.WebDavSession = function() {

	this.sServerEngine = null;
	this.bIisDetected = null;
	
	this._User    = '';
	this._Pass    = '';
	
	this._ClassId = 'ITHit.WebDAV.Client.WebDavSession_'+ ITHit.WebDAV.Client.WebDavSession._Counter++;
}

ITHit.oNS.WebDavSession.Version = '2.0.1.1235';

ITHit.oNS.WebDavSession._Counter = 0;

/**
 * Returns Resource object corresponding to path.
 * @function {ITHit.WebDAV.Client.Resource} ITHit.WebDAV.Client.WebDavSession.OpenResource
 *
 * @param {String} sPath Path to the resource.
 *
 * @returns Resource corresponding to requested path.
 *
 * @throws ITHit.WebDAV.Client.Exceptions.UnauthorizedException &nbsp;Incorrect credentials provided or insufficient permissions to access the requested item.
 * @throws ITHit.WebDAV.Client.Exceptions.NotFoundException &nbsp;The requested resource doesn't exist on the server.
 * @throws ITHit.WebDAV.Client.Exceptions.ForbiddenException &nbsp;The server refused to fulfill the request.
 * @throws ITHit.WebDAV.Client.Exceptions.WebDavException &nbsp;Unexpected error occurred.
 */
ITHit.oNS.WebDavSession.prototype.OpenResource = function(sPath) {

    // Get reference for namespace.
    var oNsCl = ITHit.WebDAV.Client;

    // Start logging.
    ITHit.Logger.StartLogging();
    ITHit.Logger.IgnoreNextStartLogging();

    return oNsCl.Resource.Open(this, sPath);
}

