/*
* Create request.
* @function {ITHit.WebDAV.Client.WebDavRequest} ITHit.WebDAV.Client.WebDavSession.CreateRequest
* 
* @paramset Syntax 1
* @param {String} sPath Item path.
* @param {optional String} Lock token for item.
* @paramset Syntax 2
* @param {String} sPath Item path.
* @param {optional ITHit.WebDAV.Client.LockUriTokenPair} Lock token for item.
* 
* @returns Request object.
*/
ITHit.oNS.WebDavSession.prototype.CreateRequest = function(sHost, sPath, mLockTokens){

	// Get reference for namespace.
	var oNsCl = ITHit.WebDAV.Client;
	
	if ('undefined' == typeof mLockTokens) {
		mLockTokens = [];
	}
	
	// Return new WebDavRequest object.
	var oRequest = oNsCl.WebDavRequest.Create(sPath, mLockTokens, this._User, this._Pass, sHost);
	
	// Attach event listener.
	ITHit.Events.AddListener(oRequest, 'OnBeforeRequestSend', 'OnBeforeRequestSendHandler', this);
	ITHit.Events.AddListener(oRequest, 'OnResponse', 'OnResponseHandler', this);
	
	return oRequest;
}

ITHit.oNS.WebDavSession.prototype.OnBeforeRequestSendHandler = function(oRequestData, oWebDavRequest) {
	
	ITHit.Events.RemoveListener(oWebDavRequest, 'OnBeforeRequestSend', 'OnBeforeRequestSendHandler', this);
	return ITHit.Events.DispatchEvent(this, 'OnBeforeRequestSend', oRequestData);
}

ITHit.oNS.WebDavSession.prototype.OnResponseHandler = function(oResponseData, oWebDavRequest) {
	
	var oWebDavRequest = arguments[arguments.length-1];

	// set version
	if (this.sServerEngine === null) {
		// Get webdav server version
		this.sServerEngine = oResponseData.GetResponseHeader('x-engine', true);
	}
	if (this.bIisDetected === null) {
	    // check Server header to match the IIS server
	    var sServerHeader = oResponseData.GetResponseHeader('server', true);
	    this.bIisDetected = (/*/^Microsoft-HTTPAPI\//i.test(sServerHeader) ||*/ /^Microsoft-IIS\//i.test(sServerHeader));
	}

	ITHit.Events.RemoveListener(oWebDavRequest, 'OnResponse', 'OnResponseHandler', this);
	return ITHit.Events.DispatchEvent(this, 'OnResponse', oResponseData);
}

/*
* Get file upload progress. Works only with ITHit WebDAV DeltaV ReumableUpload Server.
* @function {Object} ITHit.WebDAV.Client.WebDavSession.GetUploadProgress
*
* @param {String} Item path.
* @returns Array of upload progress info objects.
*/
ITHit.oNS.WebDavSession.prototype.GetUploadProgress = function(sPath) {
	
	// Get reference for namespace.
	var oNsCl = ITHit.WebDAV.Client;
	
	// Start logging.
	ITHit.Logger.StartLogging();
	ITHit.Logger.IgnoreNextStartLogging();
	
	var sPath = oNsCl.Encoder.EncodeURI(sPath);
	
	var oReport = oNsCl.Methods.Report.Go(this, sPath, oNsCl.HierarchyItem.GetHost(sPath));
	
	// Finish logging.
	ITHit.Logger.FinishLogging();
	
	return oReport;
}

ITHit.oNS.WebDavSession.prototype.GetUploadProgressAsync = function (sPath, fCallback) {

    // Get reference for namespace.
    var oNsCl = ITHit.WebDAV.Client;

    // Start logging.
    ITHit.Logger.StartLogging();
    ITHit.Logger.IgnoreNextStartLogging();

    var sPath = oNsCl.Encoder.EncodeURI(sPath);
    var oWebDavRequest = oNsCl.Methods.Report.GoAsync(this, sPath, oNsCl.HierarchyItem.GetHost(sPath), null, null, fCallback);

    // Finish logging.
    ITHit.Logger.FinishLogging();

	return oWebDavRequest;
}

