ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.UrlUtils = function(sUrl) {
	
	// Get references for namespaces.
	var oNsCl       = ITHit.WebDAV.Client;
	var oNsUrlUtils = oNsCl.AjaxFileBrowser.UrlUtils;
	
	if (!sUrl) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongBaseUrl.Paste(String(sUrl)));
	}
	oNsUrlUtils.CheckUrlSchema(sUrl);
	
	var sUrl       = ITHit.WebDAV.Client.Encoder.Decode(sUrl.replace(/\/?$/, '/'));
	
	this.BasePath  = oNsUrlUtils.GetRelativePath(sUrl);
	this.Host      = oNsUrlUtils.GetHost(sUrl);
}

ITHit.oNS.UrlUtils.CheckUrlSchema = function(sUrl) {
	if (!/^http[s]?:\/\/(?:[^\/]+[\/]?)*$/.test(sUrl)) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongBaseUrl.Paste(String(sUrl)));
	}
}

ITHit.oNS.UrlUtils.GetHost = function(sUrl) {
	
	var aResults = sUrl.match(/^(http[s]?:\/\/[^\/]+)/);
	if (!aResults) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongBaseUrl.Paste(String(sUrl)));
	}
	
	return aResults[0] +'/';
}

ITHit.oNS.UrlUtils.prototype.CheckUrlAgainstBase = function(sUrl, bSuppressException) {
    return true;
	if (0 !== sUrl.indexOf(this.BasePath)) {
		if (!bSuppressException) {
			throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongUrl.Paste(sUrl));
		} else {
			return false;
		}
	}
	
	return true;
}

ITHit.oNS.UrlUtils.GetRelativePath = function(sUrl, sCurrentPath) {
	
	// Check URL.
	if (/^http[s]?\:/.test(sUrl)) {
		sUrl = sUrl.replace(/^http[s]?\:\/\/[^\/]+\/?/, '\/');
	}
	
	if (ITHit.Utils.IsUndefined(sCurrentPath)) {
		return sUrl;
	}
	else {
		return ITHit.WebDAV.ClientAjaxFileBrowser.UrlUtils.GetRelativePath(sUrl) + sCurrentPath;
	}
}

ITHit.oNS.UrlUtils.prototype.GetRelativePath = ITHit.oNS.UrlUtils.GetRelativePath;

ITHit.oNS.UrlUtils.prototype.GetAbsolutePath = function(sUrl) {
	
	if (/https?\:\/\//.test(sUrl)) {
		return sUrl;
	}
	
	var oNsBrowser = ITHit.WebDAV.Client.AjaxFileBrowser;
	
	if (!/^\//.test(sUrl)) {
		throw new oNsBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongUrl.Paste(sUrl));
	}

	return this.Host + oNsBrowser.UrlUtils.GetRelativePath(sUrl).substr(1);
}

/**
 *
 * @param {string} sUrl
 * @returns {string}
 */
ITHit.oNS.UrlUtils.GetFileName = function(sUrl) {

	var iLastSlash     = sUrl.lastIndexOf('/'),
		iLastBackslash = sUrl.lastIndexOf('\\'),
		sFileName      = sUrl;

	if (-1 != iLastSlash) {
		sFileName = sFileName.substr(iLastSlash + 1);
	} else if (-1 != iLastBackslash) {
		sFileName = sFileName.substr(iLastBackslash + 1);
	}

	return sFileName;
}

/**
 *
 * @param {string} sUrl
 * @returns {string}
 */
ITHit.oNS.UrlUtils.GetDirName = function(sUrl) {
	var iPos = sUrl.lastIndexOf('/') + 1 || sUrl.lastIndexOf('\\') + 1;
	if (iPos) {
		return sUrl.substr(0, iPos);
	}

	return sUrl;
}

ITHit.oNS.UrlUtils.IsAbsolutePath = function (sUrl) {

    if (/https?\:\/\//.test(sUrl)) {
        return true;
    }
    return false;
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.Utils = {

    /**
     *
     * @param {string} path
     * @returns {string}
     */
    GetFileName: function(path) {
        var index = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
        return index !== -1 ? path.substr(index + 1) : '';
    },

    /**
     *
     * @param {string} path
     * @returns {string}
     */
    GetFileExtension: function(path) {
        var name = this.GetFileName(path);
        var index = name.lastIndexOf('.');
        return index !== -1 ? name.substr(index + 1).toLowerCase() : '';
    },

	FixPNG: function (element){
			
		var src, onload;
		
		// For IE version 5.5-6.
		if (/MSIE (5\.5|6).+Win/.test(navigator.userAgent)) {
			
			// If current element is picture (IMG tag).
			if (element.tagName == 'IMG') {
				
				if (/\.png$/.test(element.src)) {
					if (element.onload) {
						onload = element.onload;
						element.onload = null;
					}
					
					src = element.src;
					element.src = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetBlankGifPath(); // replace image with transparent gif.
				}
			
			// Else whether picture is background.
			} else {
				
				src = element.currentStyle.backgroundImage.match(/url\("(.+\.png)"\)/i);
				if (src) {
					src = src[1];
					element.runtimeStyle.backgroundImage = "none";
				}
			}
			
			// Whether src is not empty, then load image with AlphaImageLoader filter.
			if (src) {
				if (onload) {
					var timer = setTimeout(function() {ITHit.WebDAV.Client.AjaxFileBrowser.Controller.IconNotFound(element);}, 300);
					element.onfilterchange = function(event) {clearTimeout(timer); onload(event);};
				}
				element.runtimeStyle.filter = "progid:DXImageTransform.Microsoft.AlphaImageLoader(src='" + src + "',sizingMethod='scale')";
			}
		}
	},
	
	GetBlankGifPath: function() {
		return 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==';
	}
};

