ITHit.WebDAV.Client.AjaxFileBrowser.HierarchyItem = function(oHierItem) {
	
	this.DisplayName  = oHierItem.DisplayName;
	this.Href         = ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils.GetRelativePath(ITHit.WebDAV.Client.Encoder.Decode(oHierItem.Href));
	this.ResourceType = oHierItem.ResourceType;
	this.CreationDate = oHierItem.CreationDate;
	this.LastModified = oHierItem.LastModified;
	this.Item         = oHierItem;
	
	if (oHierItem instanceof ITHit.WebDAV.Client.Folder) {
		this.Href = this.Href.replace(/\/?$/, '/');
	}
}


