ITHit.oNS.Folder = function(oFolder) {
	
	var oNsBrowser = ITHit.WebDAV.Client.AjaxFileBrowser;
	
	if ( !(oFolder instanceof ITHit.WebDAV.Client.Folder) ) {
		throw new oNsBrowser.Exception('ITHit.WebDAV.Client.Folder class instance expected.');
	}
	
	oNsBrowser.Folder.baseConstructor.call(this, oFolder);
}

