ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.Filter = function(oController, sCollection, bShowFolders) {
	
	this._Controller     = oController;
	this._Collection     = sCollection;
	this.ShowFolders     = bShowFolders || false;
	this._FileExtensions = {
		only:   {},
		except: {}
	};
	this._FileFilterFlag = 0;
	
	this._ClassId        = 'ITHit.WebDAV.Client.AjaxFileBrowser.Filter_'+ ITHit.WebDAV.Client.AjaxFileBrowser.Filter._Counter++;
}

ITHit.oNS.Filter._Counter = 0;

ITHit.oNS.Filter.prototype.ShowFolders = function(bShowFolders) {
	this.ShowFolders = bShowFolders || false;
}

ITHit.oNS.Filter.prototype.SetShowOnlyFileExtensions = function(mFileExt) {
	
	this._FileExtensions.only = {};
	
	if (!mFileExt) {
		this._FileFilterFlag = 0;
		return;
	}
	
	this.SetShowExceptFileExtensions();
	
	var aFileExt = ITHit.Utils.IsArray(mFileExt) ? mFileExt : [mFileExt];
	
	for (var i = 0, l = aFileExt.length; i < l; i++) {
		
		if (!ITHit.Utils.IsUndefined(this._FileExtensions.only[aFileExt[i]])) {
			continue;
		}
		
		this._FileExtensions.only[aFileExt[i]] = true;
	}
	
	this._FileFilterFlag = 1;
}

ITHit.oNS.Filter.prototype.GetShowOnlyFileExtensions = function(){
	
	var aOut = [];
	
	for (var sExt in this._FileExtensions.only) {
		aOut.push(sExt);
	}
	
	return aOut;
}

ITHit.oNS.Filter.prototype.SetShowExceptFileExtensions = function(mFileExt) {
	
	this._FileExtensions.except = {};
	
	if (!mFileExt) {
		this._FileFilterFlag = 0;
		return;
	}
	
	this.SetShowOnlyFileExtensions();
	
	var aFileExt = ITHit.Utils.IsArray(mFileExt) ? mFileExt : [mFileExt];
	
	for (var i = 0, l = aFileExt.length; i < l; i++) {
			
		if (!ITHit.Utils.IsUndefined(this._FileExtensions.except[aFileExt[i]])) {
			continue;
		}
		
		this._FileExtensions.except[aFileExt[i]] = true;
	}
	
	this._FileFilterFlag = 2;
}

ITHit.oNS.Filter.prototype.GetShowExceptFileExtensions = function(){
	
	var aOut = [];
	
	for (var sExt in this._FileExtensions.except) {
		aOut.push(sExt);
	}
	
	return aOut;
}

ITHit.oNS.Filter.prototype.Run = function(aItems) {
	
	var oFilteredItems = {
		'Folders':   [],
		'Resources': [],
		ShowFolders: this.ShowFolders
	};
	
	if (aItems) {
	    for (var i = 0; i < aItems.length; i++) {

	        if (aItems[i].ResourceType != this._Collection) {
	            if (this.FileCheck(aItems[i].Href)) {
					if (!(aItems[i] instanceof ITHit.WebDAV.Client.AjaxFileBrowser.Resource)) {
						aItems[i] = new ITHit.WebDAV.Client.AjaxFileBrowser.Resource(aItems[i]);
					}
	                oFilteredItems['Resources'].push(aItems[i]);
	            }
	        } else {
				if (!(aItems[i] instanceof ITHit.WebDAV.Client.AjaxFileBrowser.Folder)) {
					aItems[i] = new ITHit.WebDAV.Client.AjaxFileBrowser.Folder(aItems[i]);
				}
				oFilteredItems['Folders'].push(aItems[i]);
	        }
	    }
	}
	
	var func = function(a, b) {return a.DisplayName.localeCompare(b.DisplayName);}
	
	oFilteredItems.Folders.sort(func);
	oFilteredItems.Resources.sort(func);
	
	return oFilteredItems;
}

ITHit.oNS.Filter.prototype.FileCheck = function(sFileName) {
	
	switch (this._FileFilterFlag) {
		
		// Without check.
		case 0:
			return true;
		
		// Check for show only files.
		case 1:
			var sExt = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(sFileName);
			return this._FileExtensions.only[sExt] || false;
		
		// Check for show except files.
		case 2:
			var sExt = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(sFileName)
			return !this._FileExtensions.except[sExt];
	}
}

ITHit.oNS.Filter.prototype.toString = function() {
	return this._ClassId;
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.CodeConstructor = function() {}

ITHit.oNS.CodeConstructor._ElementsBinderCounter = 0;
ITHit.oNS.CodeConstructor._FunctionsBinderList   = {};

ITHit.oNS.CodeConstructor.RestoreBindedFunctions = function() {
	
	var oBinders = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor._FunctionsBinderList;
	var oNsDojo  = ITHit.Components.dojo;
	
	for (var sElementId in oBinders) {
		if (!oBinders.hasOwnProperty(sElementId)) continue;
		
		for (var sProp in oBinders[sElementId]) {
			oNsDojo.connect(
				oNsDojo.byId(sElementId),
				sProp.toLowerCase(),
				oBinders[sElementId][sProp]
			);
		}
	}
	
	oBinders = {};
}

ITHit.oNS.CodeConstructor.CreateHTML = function(oLinks, mStruct, oToIgnore, sTab, oReplaceChildProps) {
	
	sTab      = sTab || '';
	oToIgnore = oToIgnore || {};
	
	var html  = [];
	
	if (!ITHit.Utils.IsArray(mStruct)) {
		mStruct = [mStruct];
	}
	
	for (var i = 0, l = mStruct.length; i < l; i++) {
		
		var oJS = mStruct[i];
		
		for (var sElem in oJS) {
			if (!ITHit.Utils.IsUndefined(Object[sElem])) continue;
			
			var bClose = true;
			switch(sElem) {
				case 'img':
				case 'hr':
				case 'br':
				case 'frame':
				case 'input':
					bClose = false;
			}
			
			var sTagName  = sElem.toLowerCase();
			var aNodeData = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor._ParseParams(oLinks, oJS[sElem], oToIgnore, sTab, oReplaceChildProps);
			
			if ('emptyElement' != sElem) {
				if (bClose) {
					html.push([sTab, '<', sTagName, ' ', aNodeData.props.join(' '), '>\n', aNodeData.childNodes.join('\n'), '\n', sTab, '</', sTagName, '>'].join(''));
				}
				else {
					html.push([sTab, '<', sTagName, ' ', aNodeData.props.join(' '), ' />'].join(''));
				}
			} else {
				html.push(aNodeData.childNodes.join(' '));
			}
		}
		
	}
	
	return html.join('\n');
}

ITHit.oNS.CodeConstructor._ParseParams = function(oLinks, oParams, oToIgnore, sTab, oReplaceProps) {
	
	sTab          = sTab +'\t';
	oReplaceProps = oReplaceProps || {};
	
	var oNsCodeConstructor = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor;
	var oNsIsFunction      = ITHit.Utils.IsFunction;
	var oNsUndefined       = ITHit.Utils.IsUndefined;
	
	
	var aNodeData = {
		props: [],
		childNodes: []
	};
	
	for (var sProp in oParams) {
		if (!oParams.hasOwnProperty(sProp)) continue;
		
		var mParamValue = oParams[sProp];
		
		if (!oNsUndefined(oReplaceProps[sProp])) {
			mParamValue = oReplaceProps[sProp];
		}
		
		switch(sProp) {
			
			case 'linkId':
				break;
			
			case 'className':
				aNodeData.props.push('class="'+ mParamValue +'"');
				break;
				
			case 'style':
				if (!oNsUndefined(oParams.show) && !oParams.show) {
					mParamValue.display = 'none';
				}
				aNodeData.props.push(sProp +'="'+ oNsCodeConstructor.PrepareStyle(mParamValue).join(' ') +'"');
				break;
				
			case 'show':
				if (oParams.style) {
					break;
				}
				if (!oParams.show) {
					aNodeData.props.push('style="'+ oNsCodeConstructor.PrepareStyle({display: 'none'}).join(' ') +'"');
				}
				break;
			
			case 'label':
	 			if (oParams.ihDojoType && ('dijit.MenuItem' == oParams.ihDojoType) && !oNsUndefined(oParams.text)) {
					break;
				}
				aNodeData.props.push(sProp +'="'+ String(mParamValue) +'"');
				break;
				
			case 'text':
	 			if (oParams.ihDojoType && ('dijit.MenuItem' == oParams.ihDojoType)) {
					aNodeData.props.push('label="'+ String(mParamValue) +'"');
					break;
				}
				var sText = String(mParamValue).replace(/\|>/gm, '\n'+ sTab);
				if (sText) {
					aNodeData.childNodes.push(sTab + sText);
				}
				break;
				
			// Alias for title.
			case 'tooltip':
				aNodeData.props.push('title="'+ mParamValue +'"');
				break;
				
			case 'title':
				aNodeData.props.push(sProp +'="'+ mParamValue +'"');
				break;
			
			case 'expression':
				aNodeData.props.push(mParamValue);
				break;
				
			case 'childNodes':
				for (var i = 0, l = mParamValue.length; i < l; i++) {
					
					var mChild = mParamValue[i];
					
					if (ITHit.Utils.IsObjectStrict(mChild)) {
						var oReplaceChildProps = {};
						if ( (0 == i) && !oNsUndefined(oParams.text) && mChild['span']) {
							oReplaceChildProps.text = oParams.text;
						}
						
						aNodeData.childNodes.push(oNsCodeConstructor.CreateHTML(oLinks, mChild, oToIgnore, sTab, oReplaceChildProps));
					} else {
						aNodeData.childNodes.push(sTab + mChild);
					}
				}
				break;
			
			case 'innerHTML':
				aNodeData.childNodes.push(mParamValue);
				break;
			
			case 'contextHelp':
				if (!oLinks['ContextHelp'] || !oParams[sProp]) {
					continue;
				}
				
				if (ITHit.Utils.IsUndefined(sElementId)) {
						var sElementId = oParams.id;
						if (!sElementId) {
							sElementId = 'ITHit_Element_' + oNsCodeConstructor._ElementsBinderCounter++;
						}
					}
					
					if (!oNsCodeConstructor._FunctionsBinderList[sElementId]) {
						oNsCodeConstructor._FunctionsBinderList[sElementId] = {};
					}
                    
					oNsCodeConstructor._FunctionsBinderList[sElementId]['onMouseOver'] = ITHit.Utils.MakeScopeClosure(oLinks['ContextHelp'], 'Show', [oParams[sProp], oParams["contextHelpIconClass"]]);
					oNsCodeConstructor._FunctionsBinderList[sElementId]['onMouseOut']  = ITHit.Utils.MakeScopeClosure(oLinks['ContextHelp'], 'Hide');
				
				break;

			case 'dojoProps':
				var mProps = [];
				for (var key in mParamValue) {
					if (mParamValue.hasOwnProperty(key)) {
						mProps.push(key + ":'" + mParamValue[key] + "'")
					}
				}
				aNodeData.props.push('data-dojo-props="' + mProps.join(', ') + '"')
				break;

			case 'dojoMixins':
				aNodeData.props.push('data-dojo-mixins="' + mParamValue.replace(/\./g, '\/') + '"');
				break;
			
			default:
				
				if (!oNsIsFunction(mParamValue)) {
					aNodeData.props.push(sProp + '="' + mParamValue + '"');
				} else {
					
					if (ITHit.Utils.IsUndefined(sElementId)) {
						var sElementId = oParams.id;
						if (!sElementId) {
							sElementId = 'ITHit_Element_' + oNsCodeConstructor._ElementsBinderCounter++;
						}
					}
					
					if (!oNsCodeConstructor._FunctionsBinderList[sElementId]) {
						oNsCodeConstructor._FunctionsBinderList[sElementId] = {};
					}
					oNsCodeConstructor._FunctionsBinderList[sElementId][sProp] = mParamValue;
				}
		}
	}
	
	return aNodeData;
}

ITHit.oNS.CodeConstructor.PrepareStyle = function(mStyle) {
	if (ITHit.Utils.IsString(mStyle)) {
		return [mStyle];
	}

	if (ITHit.Utils.IsObjectStrict(mStyle)) {
		var aStyles = [];
		for (var sProp in mStyle) {
			if (mStyle.hasOwnProperty(sProp)) {
				aStyles.push(sProp.replace(/([A-Z])/g, '-$1').toLowerCase() +': '+ mStyle[sProp] +';');
			}
		}
		return aStyles;
	}

	return [];
}

ITHit.oNS.CodeConstructor.Clone = function(oObject, oContext, bFirstCharToLowerCase) {
	
	var oNsUtils = ITHit.Utils;
	var oNsClone = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.Clone;

	if (ITHit.Utils.IsArray(oObject)) {
		var aNewArray = [];
		for (var i = 0, l = oObject.length; i < l; i++) {
			aNewArray.push(oNsClone(oObject[i]));
		}
		return aNewArray;
	}

	if (!oNsUtils.IsObject(oObject) || oNsUtils.IsNull(oObject)) {
		return oObject;
	}
	var oCloned = oContext || {};
	
	for (var prop in oObject) {
		if (!oObject.hasOwnProperty(prop)) continue;
		
		var sNewProp = prop;
		if (bFirstCharToLowerCase) {
			sNewProp = sNewProp.substr(0, 1).toLowerCase() + sNewProp.substr(1);
		}
		
		// Clone as string.
		switch (sNewProp) {
			
			case 'text':
			case 'title':
			case 'label':
			case 'name':
		    case 'contextHelp':
				oCloned[sNewProp] = String(oObject[prop]);
				continue;
			
			case 'tooltip':
				oCloned.title = oObject[prop];
				continue;
		}
		
		if (!oNsUtils.IsObjectStrict(oObject[prop]) || oNsUtils.IsDOMObject(oObject[prop])) {
			oCloned[sNewProp] = oObject[prop];
		} else {
			oCloned[sNewProp] = oNsClone(oObject[prop], null, bFirstCharToLowerCase);
		}
	}
	
	return oCloned;
}

ITHit.oNS.CodeConstructor.CloneGridColumnsModified = function(aColumns, oModify, userHandlerFormatter) {
	
	var oNsCodeConstructor = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor;
	var oNsCloneModified   = oNsCodeConstructor._CloneGridColumnsModified;
	var aUnorderedColumns  = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.Clone(aColumns);//aColumns.concat();
	var aOrderedColumns    = [];
	var bFormatterIsSet    = userHandlerFormatter && ITHit.Utils.IsFunction(userHandlerFormatter);

	// Create nodes.
	if (oModify && ITHit.Utils.IsArray(oModify.Columns) && oModify.Columns.length) {
		var oCreateOrModifyColumns = oModify.Columns.concat();
		
		for (var i = 0, l = oCreateOrModifyColumns.length; i < l; i++) {
			
			var bFound = false;
			
			if (oCreateOrModifyColumns[i].Id) {
				for (var j = 0, jl = aUnorderedColumns.length; j < jl; j++) {
					if (aUnorderedColumns[j].linkId == oCreateOrModifyColumns[i].Id) {
						aUnorderedColumns[j] = oNsCloneModified(aUnorderedColumns[j], oCreateOrModifyColumns[i], userHandlerFormatter);
						bFound = true;
						break;
					}
				}
			}

			if (!bFound) {
				if ( ITHit.Utils.IsUndefined(oCreateOrModifyColumns[i].Formatter) || !ITHit.Utils.IsFunction(oCreateOrModifyColumns[i].Formatter) || !bFormatterIsSet ) {
                    if (!oCreateOrModifyColumns[i].CustomProperty) {
					    oCreateOrModifyColumns[i].Formatter = function() {return '';}
                    }
				} else {
					oCreateOrModifyColumns[i].Formatter = userHandlerFormatter(oCreateOrModifyColumns[i].Formatter);
				}
				aUnorderedColumns.push(oNsCloneModified({}, oCreateOrModifyColumns[i], userHandlerFormatter));
			}
		}
	}
	
	if (oModify && oModify.Order) {
		for (var i = 0, l = oModify.Order.length; i < l; i++) {
			for (var j = 0, jl = aUnorderedColumns.length; j < jl; j++) {
				if (aUnorderedColumns[j].linkId && (aUnorderedColumns[j].linkId == oModify.Order[i])) {
					aOrderedColumns.push(aUnorderedColumns[j]);
					aUnorderedColumns.splice(j, 1);
					break;
				}
			}
		}
	}

	aOrderedColumns = aOrderedColumns.concat(aUnorderedColumns);
	
	// Convert style objects to string.
	for (var i = 0, l = aOrderedColumns.length; i < l; i++) {
	
		if (aOrderedColumns[i].cellStyles)
			 aOrderedColumns[i].cellStyles   = oNsCodeConstructor.PrepareStyle(aOrderedColumns[i].cellStyles).join(' ');
			 
		if (aOrderedColumns[i].headerStyles)
			 aOrderedColumns[i].headerStyles = oNsCodeConstructor.PrepareStyle(aOrderedColumns[i].headerStyles).join(' ');
			 
		if (aOrderedColumns[i].styles)
			 aOrderedColumns[i].styles       = oNsCodeConstructor.PrepareStyle(aOrderedColumns[i].styles).join(' ');
	}
	
	return aOrderedColumns;
}

ITHit.oNS.CodeConstructor._CloneGridColumnsModified = function(oColumn, oModify, userHandlerFormatter) {
	
	var oNsUtils           = ITHit.Utils;
	var oNsUndefined       = oNsUtils.IsUndefined;
	var oNsCodeConstructor = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor;
	var oNsClone           = oNsCodeConstructor.Clone;
	var oClonedColumn      = {};
	
	for (var prop in oColumn) {
		if (!oColumn.hasOwnProperty(prop)) continue;

		var sFCUProp = prop.substr(0, 1).toUpperCase() + prop.substr(1);
		
		if (oNsUndefined(oModify[sFCUProp])) {
			oClonedColumn[prop] = oColumn[prop];
		} else {
			if (!oNsUtils.IsObjectStrict(oModify[sFCUProp]) || oNsUtils.IsDOMObject(oModify[sFCUProp])) {

				if (('formatter' === prop) && oNsUtils.IsFunction(oModify[sFCUProp])) {
					oClonedColumn[prop] = userHandlerFormatter(oModify[sFCUProp], oColumn[prop]);
					
				} else {
					oClonedColumn[prop] = oModify[sFCUProp];
				}
			} else {
				oClonedColumn[prop] = oNsClone(oColumn[prop], oModify[sFCUProp]);
			}
		}
	}

	for (var prop in oModify) {
		if (!oModify.hasOwnProperty(prop)) continue;
		
		switch (prop) {
			case 'Columns':
			case 'Order':
				continue;
			
			case 'Id':
				oClonedColumn.linkId = oModify.Id;
				continue;
			
			// Hide grid column.
			case 'Show':
			
				if (oNsUndefined(oClonedColumn.styles)) {
					if (!oModify.Show) {
						oClonedColumn.styles = {
							display: "none"
						}
					}
				} else {
					if (oModify.Show) {
						if (oNsUndefined(oClonedColumn.styles.display)) {
							delete oClonedColumn.styles.display;
						}
					} else {
						oClonedColumn.styles.display = "none";
					}
				}
				continue;
			
			case 'Text':
				oClonedColumn.name = String(oModify.Text);
				continue;
			
			case 'Tooltip':
				oClonedColumn.title = oModify[prop];
				continue;

            case 'Formatter':
                oClonedColumn.formatter = userHandlerFormatter(oModify.Formatter);
                continue;

            case 'CellFormatter':
                oClonedColumn.cellFormatter = oModify.CellFormatter;
                continue;
		}
		
		var sFCLProp = prop.substr(0, 1).toLowerCase() + prop.substr(1);

		if (!oNsUtils.IsObjectStrict(oModify[prop]) || oNsUtils.IsDOMObject(oModify[prop])) {
			oClonedColumn[sFCLProp] = oModify[prop];
		} else {
			oClonedColumn[sFCLProp] = oNsClone(oModify[prop], oModify[prop]);
		}
	}
	
	return oClonedColumn;
}

ITHit.oNS.CodeConstructor.CloneCodeModified = function(mObject, oModify) {
	
	if (!oModify) {
		return ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.Clone(mObject);
	}
	
	var oNsCodeConstructor   = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor;
	var oNsCloneCodeModified = oNsCodeConstructor.CloneCodeModified;
	var oNsUtils             = ITHit.Utils;
	var oNsUndefined         = oNsUtils.IsUndefined;
	var bChk                 = false;
	
	var oNew                 = oNsUtils.IsArray(mObject) ? [] : {};
	
	// Check linkId whether modification object passed.
	if (!oNsUndefined(mObject.linkId)) {
		
		// Array passed.
		if (oNsUtils.IsArray(oModify)) {
			for (var i = 0, l = oModify.length; i < l; i++) {
				if (!oNsUndefined(oModify[i].Id) && (oModify[i].Id == mObject.linkId) ) {
					oModify = oModify[i];
					bChk    = true;
					break;
				}
			}
		
		// Object passed.
		} else if (oNsUtils.IsObjectStrict(oModify)) {
			
			if (!oNsUndefined(oModify[mObject.linkId])) {
				oModify = oModify[mObject.linkId];
				bChk    = true;
			}
		}
	}
	
	// Loop through object properties.
	for (var prop in mObject) {
		if (!mObject.hasOwnProperty(prop)) continue;
		
		switch (prop) {
			
			// Skip linkId property.
			case 'linkId': continue;
			
			case 'name':
			case 'text':
			case 'title':
			case 'label':
			case 'tooltip':
		    case 'contextHelp':
				oNew[prop] = String(mObject[prop]);
				continue;
			
			// Handle with child nodes.
			case 'childNodes':
				
				var aChildren = [];
				
				// Unordered nodes.
				if (!bChk || oNsUndefined(oModify['Order'])) {
					aChildren = mObject[prop];
				
				// Order nodes.
				} else {
					
					// Clone unordered elements.
					var aUnordered = mObject[prop].concat();
					var bLoop = false;
					
					// Loop through order list.
					for (var i = 0, il = oModify['Order'].length; i < il; i++) {
						var bFound = false;
						
						// Check for existent structure elements.
						unorderedSearch:
						for (var j = 0, jl = aUnordered.length; j < jl; j++) {
							
							// Search first element node.
							for (var sElemProp in aUnordered[j]) {
								if (!aUnordered[j].hasOwnProperty(sElemProp)) continue;
								
								if (aUnordered[j][sElemProp].linkId == oModify['Order'][i]) {
									aChildren.push(aUnordered[j]);
									aUnordered.splice(j, 1);
									bFound = true;
									break unorderedSearch;
								}
							}
						}
						
						// Whether name not found check for new element label.
						if (!bFound && bChk && oNsUtils.IsArray(oModify['Items'])) {
							for (var k = 0, kl = oModify['Items'].length; k < kl; k++) {
								if ( !oNsUndefined(oModify['Items'][k].Id) && oModify['Order'][i] && (oModify['Items'][k].Id == oModify['Order'][i]) ) {
									var aNewElements = oNsCodeConstructor.CreateElement(oModify['Items'][k]);
									for (var j = 0, jl = aNewElements.length; j < jl; j++) {
										aChildren.push(aNewElements[j]);
									}
									oModify['Items'].splice(k, 1);
									break;
								}
							}
						}
					}
					
					// Concat remained elements.
					aChildren = aChildren.concat(aUnordered);
				}
				
				oNew[prop] = [];
				
				// Pass Modification object itself or modifications for child nodes.
				var mToChildren = oModify;
				if (bChk && oNsUtils.IsArray(oModify['Items'])) {
					mToChildren = oModify['Items'];
				}
				
				// Loop through child nodes.
				for (var i = 0, l = aChildren.length; i < l; i++) {
					oNew[prop].push(oNsCloneCodeModified(aChildren[i], mToChildren));
				}
				
				// Add new child nodes.
				if (bChk && oNsUtils.IsArray(oModify['Items'])) {
					for (var i = 0, l = oModify['Items'].length; i < l; i++) {
						
						if (oModify['Items'][i].Type || oModify['Items'][i].InnerHTML) {
							var aNewElements = oNsCodeConstructor.CreateElement(oModify['Items'][i]);
							for (var j = 0, jl = aNewElements.length; j < jl; j++) {
								oNew[prop].push(aNewElements[j]);
							}
						}
					}
				}
				
				continue;
		}
		
		if (!oNsUtils.IsObjectStrict(mObject[prop]) || oNsUtils.IsDOMObject(mObject)) {
			oNew[prop] = mObject[prop];
		} else {
			oNew[prop] = oNsCloneCodeModified(mObject[prop], oModify);
		}
		
	}
	
	if (bChk) {
		
		var bButtonElement         = !oNsUtils.IsUndefined(mObject.ihDojoType) && (-1 != mObject.ihDojoType.indexOf('.Button'));
		var bIsModifyTextUndefined = oNsUtils.IsUndefined(oModify.Text);
		
		if ( bButtonElement && (
				( bIsModifyTextUndefined && (oNsUtils.IsUndefined(oNew.text) || ('' === oNew.text)) )
				|| ( !bIsModifyTextUndefined && ('' === oModify.Text) )
			)
		) {
			oNew.showLabel = false;
		}
		
		for (var prop in oModify) {
			if (!oModify.hasOwnProperty(prop)) continue;
			
			var sFCLProp = prop.substr(0, 1).toLowerCase() + prop.substr(1);
			
			switch (prop) {
				case 'Items':
				case 'Order':
				case 'InnerHTML':
					continue;
				
				case 'Id':
					if (oNew.linkId) {
						continue;
					}
				
				case 'Tooltip':
					oNew.title = oModify[prop];
					continue;
			}
			
			if (!oNsUtils.IsObjectStrict(oModify[prop] || oNsUtils.IsDOMObject(oModify[prop]))) {
				oNew[sFCLProp] = oModify[prop];
			} else {
				oNew[sFCLProp] = oNsClone(oModify[prop]);
			}
		}
	} else {
		
		if ( !oNsUtils.IsUndefined(oNew.ihDojoType) && (-1 != oNew.ihDojoType.indexOf('.Button')) && (oNsUtils.IsUndefined(oNew.text) || ('' === oNew.text)) ) {
			oNew.showLabel = false;
		}
	}
	
	return oNew;
}

ITHit.oNS.CodeConstructor.CreateElement = function(oCode) {
	
	var oNsClone = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.Clone;
	oCode = oNsClone(oCode);
	
	var aNewElements = [];
	
	if (!oCode.Type && !oCode.InnerHTML) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('New element type is not passed.');	
	}
	
	if (oCode.InnerHTML) {
		
		aNewElements.push({
			emptyElement: {
				innerHTML: oCode.InnerHTML
			}
		});
		
		return aNewElements;
	}
	
	switch (oCode.Type) {
		
		// Create button.
		case 'Button':
			
			aNewElements.push({});
			var iNewElementIndex = aNewElements.length -1;
			
			var oElement = aNewElements[iNewElementIndex].button = {};
			oElement.ihDojoType = 'dijit.form.Button';
	
			if (ITHit.Utils.IsUndefined(oCode.Text) || ('' === oCode.Text)) {
				oElement.showLabel = false;
			}
			// Create tooltip for button.
//			if (oCode.Tooltip && ('' != oCode.Tooltip)) {
//
//				aNewElements.push({});
//				var iNewElementIndex = aNewElements.length -1;
//				
//				var oTooltip = aNewElements[iNewElementIndex].div = {};
//				oTooltip.ihDojoType = 'dijit.Tooltip';
//				
//				if (!oCode.Id) {
//					oCode.Id = 'ithit_element_autoid_' + new Date().getTime();
//				}
//				oTooltip.connectId = oCode.Id;
//				oTooltip.label     = oCode.Tooltip;
//			}
			
			break;

        // Create toggle button.
        case 'ToggleButton':

            aNewElements.push({});
            var iNewElementIndex = aNewElements.length -1;

            var oElement = aNewElements[iNewElementIndex].button = {};
            oElement.ihDojoType = 'dijit.form.ToggleButton';

            if (ITHit.Utils.IsUndefined(oCode.Text) || ('' === oCode.Text)) {
                oElement.showLabel = false;
            }

            break;
		
		default:
			throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Passed unsupported element type: "'+ oCode.Type +'".');
	}
	delete oCode.Type;
	
	oNsClone(oCode, oElement, true);
	
	return aNewElements;
}


