;(function() {

	/**
	 *
	 * @class ITHit.WebDAV.Client.AjaxFileBrowser.CopyMoveManager
	 * @extends Function
	 */
	var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.CopyMoveManager', function () {}, {

		/**
		 * @type {ITHit.WebDAV.Client.AjaxFileBrowserMobile.Controller}
		 */
		_Controller: null,

        /**
         * @type {string}
         */
        _Action: null,

        /**
         * @type {string[]}
         */
        _ItemUrls: null,

        /**
         * @type {ITHit.WebDAV.Client.AjaxFileBrowser.Commands.CopyQueueCommand}
         */
        _CurrentCommand: null,

		constructor: function (oController) {
			this._Controller = oController;
			this._ItemUrls = [];
		},

		/**
		 * Set items to copy
		 * @param {string[]} mItems
		 */
		CopyItems: function (mItems) {
			this.Clear();
			this._Action = self.ACTION_COPY;
			this._ItemUrls = [].concat(mItems);

			ITHit.Events.DispatchEvent(this, 'OnUpdateItems');
		},

		/**
		 * Set items to cut
		 * @param {string[]} mItems
		 */
		CutItems: function (mItems) {
			this.Clear();
			this._Action = self.ACTION_MOVE;
			this._ItemUrls = [].concat(mItems);

			ITHit.Events.DispatchEvent(this, 'OnUpdateItems');
		},

		/**
		 * Clear state
		 */
		Clear: function () {
			this._ItemUrls = [];
            this._CurrentCommand = null;

			ITHit.Events.DispatchEvent(this, 'OnUpdateItems');
		},

		/**
		 *
		 * @returns {number}
		 */
		GetItemsLength: function () {
			return this._ItemUrls.length;
		},

		/**
		 *
		 * @returns {string}
		 */
		GetAction: function () {
			return this._Action;
		},

		/**
		 * Paste copy/cut items to destination dir
		 * @param {string} sDestinationUrl
		 */
		PasteTo: function (sDestinationUrl) {
			// Check required param
			if (!sDestinationUrl) {
				throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.DestinationLocationNotPassed);
			}

			// Check empty items
			if (this._ItemUrls.length === 0) {
				return;
			}

			// Get parent folder to copy/paste same folder.
			if (this._Action === self.ACTION_COPY && this._ItemUrls.length === 1 && this._ItemUrls[0] === sDestinationUrl) {
				sDestinationUrl = sDestinationUrl.replace(/[^\/]+\/?$/, '');
			}

            var sCommandName = this._Action === self.ACTION_MOVE ? 'MoveQueueCommand' : 'CopyQueueCommand';
            this._CurrentCommand = this._Controller.Commands.Create(sCommandName, {
                HrefList: this._ItemUrls,
                ToFolderHref: sDestinationUrl,
                OnOverwrite: ITHit.Utils.MakeScopeClosure(this, '_OnOverwrite'),
                OnSuccess: ITHit.Utils.MakeScopeClosure(this, '_OnFinish')
            });
            this._CurrentCommand.Execute();
		},

        /**
         *
         * @param {string} sAction
         */
        SetOverwriteAction: function(sAction) {
            if (this._CurrentCommand === null) {
                return;
            }

            var oCommand = this._CurrentCommand;

            if (sAction === self.OVERWRITE_CANCEL) {
				if (this._Action === self.ACTION_MOVE) {
                	this.Clear();
				}
                ITHit.Events.DispatchEvent(this, 'OnCancel', [this._ItemUrls, oCommand.ToFolderHref, this._Action]);
            }

            oCommand.SetOverwriteAction(sAction);
        },

        _OnOverwrite: function(sAbsoluteUrl) {
            ITHit.Events.DispatchEvent(this, 'OnOverwrite', [sAbsoluteUrl]);
        },

		_OnFinish: function () {
			if (this._Action === self.ACTION_MOVE) {
				ITHit.Events.DispatchEvent(this, 'OnMoveComplete', [this._ItemUrls, this._CurrentCommand.ToFolderHref, this._Action]);
				this.Clear();
			} else {
				ITHit.Events.DispatchEvent(this, 'OnCopyComplete', [this._ItemUrls, this._CurrentCommand.ToFolderHref, this._Action]);
			}
		}

	}, {

		ACTION_COPY: 'copy',
		ACTION_MOVE: 'move',

        OVERWRITE_CANCEL: 'cancel',
        OVERWRITE_ASK: 'ask',
        OVERWRITE_YES: 'yes',
        OVERWRITE_NO: 'no',
        OVERWRITE_YES_ALL: 'yes_all',
        OVERWRITE_NO_ALL :'no_all'

	});

})();

