ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions');

/**
 * Thrown when upload progress request failed.
 * @class ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.UploadProgressException
 * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException
 */
/**
 * Initializes a new instance of the UploadProgressException class with a specified error message, a reference to the inner exception that is the cause of this exception.
 * @constructor UploadProgressException
 * 
 * @param {String} sUrl Item's URL.
 * @param {String} sMessage The error message string.
 * @param {optional ITHit.Exception} oInnerException The ITHit.Exception instance that caused the current exception.
 */
ITHit.oNS.UploadProgressException = function(sUrl, sMessage, oInnerException) {
	
	this.Url = sUrl;
	
	// Inheritance definition.
	ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.UploadProgressException.baseConstructor.call(this, sMessage, oInnerException);
}

// Extend class.
ITHit.Extend(ITHit.oNS.UploadProgressException, ITHit.oNS.AjaxFileBrowserException);

// Exception name
ITHit.oNS.UploadProgressException.prototype.Name = 'UploadProgressException';



ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.UploadProgressManager = function(iRepeatTime) {
	
	this.Pool        = {};
	this.Counter     = 0;
	this.RepeatTime  = 0;
	this.TimerId     = null;
	
	this.UploadInfoLibraryClass = ITHit.WebDAV.Client.UploadProgressInfo;
	
	this.ChangeProgressRefreshTime(iRepeatTime);
	
	this._ClassId    = 'ITHit.WebDAV.Client.AjaxFileBrowser.UploadProgressManager_'+ ITHit.WebDAV.Client.AjaxFileBrowser.UploadProgressManager._Counter++;
}

ITHit.oNS.UploadProgressManager._Counter = 0;

ITHit.oNS.UploadProgressManager.prototype.ChangeProgressRefreshTime = function(iRepeatTime) {
	
	if (isNaN(iRepeatTime) || (iRepeatTime < 0)) {
		return;
	}
	
	iRepeatTime = Math.ceil(iRepeatTime);
	
	if (0 == iRepeatTime) {
		this.RepeatTime = 0;
		this._CancelSendReport();
		return;
	}
	
	this.RepeatTime = iRepeatTime * 1000;
	this._StartSendReport();
}

ITHit.oNS.UploadProgressManager.prototype.AddResource = function(sUrl) {
	
	this.Pool[sUrl] = true;
	this.Counter++;
	
	this._StartSendReport();
}

ITHit.oNS.UploadProgressManager.prototype.RemoveResource = function(sUrl) {
	
	if (this.Pool[sUrl]) {
		delete this.Pool[sUrl];
		this.Counter--;
		
		if (!this.Counter) {
			this._CancelSendReport();
		}
	}
	
	return true;
}

ITHit.oNS.UploadProgressManager.prototype._StartSendReport = function() {
	
	if (this.Counter && this.RepeatTime && !this.TimerId) {
		this.TimerId = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_CheckUploadProgress'), this.RepeatTime);
	}
}

ITHit.oNS.UploadProgressManager.prototype._CancelSendReport = function() {
	
	if (this.TimerId) {
		clearTimeout(this.TimerId);
		this.TimerId = null;
	}
}

ITHit.oNS.UploadProgressManager.prototype._CheckUploadProgress = function() {
	
	var oOut         = {};
	this.TimerId     = null;
	var oUploadInfo;
	
	for (var sUrl in this.Pool) {
		
		try {
			oUploadInfo = ITHit.Events.DispatchEvent(this, 'OnGetProgress', ['OnGetProgress', sUrl]);
			
			if (!(oUploadInfo instanceof this.UploadInfoLibraryClass)) {
				throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.UploadProgressException(ITHit.Phrases.AjaxFileBrowser.Exceptions.UploadProgressInfoInstanceExpected);
			}
			
			oOut[sUrl] = oUploadInfo;
			
		} catch(e) {
			
			var oResult;
			if (e instanceof ITHit.Exception) {
				oResult = new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.UploadProgressException(sUrl, e.Message, e);
			}
			else {
				oResult = new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.UploadProgressException(sUrl, ITHit.Phrases.AjaxFileBrowser.Exceptions.UploadProgressInfoInstanceExpected, ITHit.Exception(String(e)));
			}
			
			ITHit.Events.DispatchEvent(this, 'OnError', ['OnError', oResult]);
		}
	}
	this._StartSendReport();
	
	ITHit.Events.DispatchEvent(this, 'OnProgress', ['OnProgress', oOut]);
}

ITHit.oNS.UploadProgressManager.prototype.toString = function() {
	return this._ClassId;
}

ITHit.oNS.UploadProgressManager.prototype.OnReportReceive;

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.UploadResult = function(sUrl, bSuccess, sErrorMessage, oStatus) {
	
	if (!ITHit.Utils.IsString(sUrl) || ('' == sUrl) || !ITHit.Utils.IsBoolean(bSuccess)) {
		throw 'URL and Success status must be specified for upload result.';
	}
	
	this.Url          = sUrl;
	this.Success      = bSuccess;
	this.ErrorMessage = sErrorMessage;
	this.Status       = oStatus || null;
}

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.UploadIframe = function(oContainer, sName) {
	
	this.Url                = '';
	this.UploadUrl          = '';
	this.Name               = sName ? sName : 'ITHit_Upload_Iframe_'+ ITHit.WebDAV.Client.AjaxFileBrowser.UploadIframe._Counter;
	
	this._Iframe;
	this._Container         = oContainer;
	this._FFLoadCheckRepeat = 10000;
	this._IframeIETimer     = null;
	this._IframeFFTimer     = null;
	this._IframeLoaded      = false;
	
	var createIframeByStandard = true;
	
	if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 10)) {
		try {
			this._Iframe = document.createElement('<IFRAME name="' + this.Name + '">');
			createIframeByStandard = false;
		} catch (e) {
			// It seems IE9 in compatability mode.
		}
	}
	
	if (createIframeByStandard) {
		this._Iframe = document.createElement('IFRAME');
		this._Iframe.name = this.Name;
	}
	
	this._Iframe.src = 'javascript:{};';
	this._Iframe.className = 'upload_iframe';
	
	this._Container.appendChild(this._Iframe);
	
	this._Iframe.onload             = ITHit.Utils.MakeScopeClosure(this, '_LoadHandler');
	this._Iframe.onreadystatechange = ITHit.Utils.MakeScopeClosure(this, '_ReadyStateChangeHandler');
	
	this._ClassId = 'ITHit.WebDAV.Client.AjaxFileBrowser.UploadIframe_' + ITHit.WebDAV.Client.AjaxFileBrowser.UploadIframe._Counter++;
}

ITHit.oNS.UploadIframe._Counter = 0;

ITHit.oNS.UploadIframe.prototype.BeginUpload = function(oForm) {
	
	if (!(oForm instanceof ITHit.WebDAV.Client.AjaxFileBrowser.UploadFormObject)
		&& !(oForm instanceof ITHit.WebDAV.Client.AjaxFileBrowser.UploadDropObjectAdapter)
	) {
		throw ITHit.Exception('Parameter expected to be UploadFormObject or UploadDropObjectAdapter instance.');
	}
	
	this.Url = oForm.Url;
	this.UploadUrl = oForm.UploadUrl;
	oForm.SetFormTarget(this.Name);
	
	// Check Firefox for connection error.
	if (ITHit.DetectBrowser.FF) {
		this._IframeFFTimer = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_FirefoxLoadCheck'), this._FFLoadCheckRepeat);
	}

    oForm.onsubmit = null;
	oForm.Submit();
	
	ITHit.Events.DispatchEvent(this, 'OnLoadStart', ['OnLoadStart', this.Url]);
}

ITHit.oNS.UploadIframe.prototype._LoadHandler = function(oEvent) {
	
	if (this._IframeIETimer) {
		clearTimeout(this._IframeIETimer);
		this._IframeIETimer             = null;
		this._Iframe.onreadystatechange = null;
	}
	
	if (this._IframeFFTimer) {
		clearTimeout(this._IframeFFTimer);
		this._IframeFFTimer = null;
	}
	
	if (this._IframeLoaded) {
		return;
	}
	this._IframeLoaded = true;
	
	var oResult = this._GetUploadSuccess();
	
	this._FinishHandler(oResult);
	
	if (oResult.Success) {
		this._SuccessHandler('OnLoad', oResult);
	} else {
		this._ErrorHandler('OnError', oResult);
	}
}

ITHit.oNS.UploadIframe.prototype._FinishHandler = function(oResult) {
	
	var oResponse = new ITHit.HttpResponse(oResult.Url, oResult.Status.Code, oResult.Status.Description);
	oResponse.SetBodyText(oResult.ErrorMessage || '');
	
	ITHit.Events.DispatchEvent(this, 'OnFinish', [oResponse]);
}

ITHit.oNS.UploadIframe.prototype._SuccessHandler = function(sEvent, oResult){
	
	if (!ITHit.Events.DispatchEvent(this, 'OnLoad', ['OnLoad', oResult.Url])) {
		this._RemoveIframeTimer();
		return false;
	}
}

ITHit.oNS.UploadIframe.prototype._ErrorHandler = function(sEvent, oResult){
	
	if (!ITHit.Events.DispatchEvent(this, 'OnError', ['OnError', oResult.Url, oResult.Status, String(oResult.ErrorBody || '')])) {
		this._RemoveIframeTimer();
		return false;
	}
}

// IE load check.
ITHit.oNS.UploadIframe.prototype._ReadyStateChangeHandler = function(oEvent) {
	
	if (this._IframeIETimer) {
		clearTimeout(this._IframeIETimer);
		this._IframeIETimer = null;
	}
	
	if ('interactive' == this._Iframe.readyState) {
		this._IframeIETimer = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_CompliteStateCheckNew', oEvent), 500);
	}
	if ('complete' == this._Iframe.readyState) {
		this._IframeIETimer = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_CompliteStateCheckNew', oEvent), 500);
	}
}

ITHit.oNS.UploadIframe.prototype._CompliteStateCheckNew = function(oEvent) {
	
	if (this._IframeIETimer) {
		clearTimeout(this._IframeIETimer);
		this._IframeIETimer = null;
	}
	
	try {
		this._Iframe.contentWindow.document.body;
		this._LoadHandler(oEvent);
	} catch(e) {
		this._IframeIETimer = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_CompliteStateCheck', oEvent), 1000);
	}
}

// FF load check.
ITHit.oNS.UploadIframe.prototype._FirefoxLoadCheck = function() {
	
	// Check for Firefox browser only.
	if (!ITHit.DetectBrowser.FF) {
		return;
	}
	
	try {
		this._Iframe.contentWindow.document;
		this._IframeFFTimer = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_FirefoxLoadCheck'), this._FFLoadCheckRepeat);
	} catch (e) {
		// Load failed with error (connection problems).
		this._LoadHandler(null);
	}
}

ITHit.oNS.UploadIframe.prototype._GetUploadSuccess = function(){
	
	var oXml       = new ITHit.XMLDoc(),
	    oStatus    = new ITHit.WebDAV.Client.AjaxFileBrowser.UploadResult(this.Url, true),
	    bPassCheck = false,
	    bGetTitle  = true,
	    isIE       = ITHit.DetectBrowser.IE,
	    document,
	    body;
	
	// Catch iframe load error in Firefox.
	try {
		document = this._Iframe.contentWindow.document;
		body     = document.body;
	} 
	catch (e) {
		if (-1 == e.message.indexOf('denied')) {
			oStatus.Success = false;
			bGetTitle       = false;
		} else {
			oStatus.Success = true;
			bPassCheck      = true;
		}
	}
	
	if (oStatus.Success && !bPassCheck) {
		
		if (document) {
			// IE < 9
			if (document.XMLDocument) {
				oXml.load(document.XMLDocument.xml);
			
			// Body is not accessible.
			} else if (!body){
				
				// IE 9 XML.
				if (isIE && document.documentElement) {
					var xmlStr = ITHit.XMLDoc.toString(document.documentElement);
					oXml.load(xmlStr);
					
				// W3C browsers.
				} else if (document.firstChild) {
					oXml.appendChild(new ITHit.XMLDoc(document.firstChild.cloneNode(true)));
				
				// IE Success (cannot check success status for large files because of timeout).
				} else if (isIE < 9) {
					bPassCheck = true;
				
				// For W3C browsers not empty body means that there was an error.
				} else {
					oStatus.Success = false;
				}
			}
			else if (isIE && isIE < 9)
			{
				if ((navigator.userAgent.indexOf('Trident/') !== -1 && (/HTTP\/1.1\s+2\d{2}/i).test(body.innerHTML)) || oStatus.Url.indexOf('%') !== -1)
				{
					bPassCheck = true;
				}
				else
				{
					oStatus.Success = false;
				}

			} else {
				// Old implementation.
				// if (isIE && (isIE <9)) {
					// if (-1 == oStatus.Url.indexOf('%')) {
						// oStatus.Success = false;
					// } else {
						// bPassCheck      = true;
					// }
				// } else {
					// oStatus.Success = false;
				// }
				oStatus.Success = false;
			}
		} else {
			oStatus.Success = false;
		}
	}
	
	if (oStatus.Success) {
		if (!bPassCheck) {
			var oRequest = new ITHit.WebDAV.Client.Methods.MultiResponse(oXml, oStatus.Url);
			if (oRequest.Responses.length) {
				oStatus.Status  = oRequest.Responses[0].Status;
				oStatus.Success = oStatus.Status.IsSuccess();
			} else {
				oStatus.Success = false;
			}
		}
	}
	
	// Get error message whether upload failed.
	if (!oStatus.Success) {
		if (oStatus.Status) {
			oStatus.ErrorMessage = oStatus.Status.Description;
		} else if (bGetTitle) {
			var oTitle = this._Iframe.contentWindow.document.getElementsByTagName('TITLE');
			if (oTitle.length) {
				oStatus.ErrorMessage = oTitle[0].text;
			}
		}
		
		if (!oStatus.ErrorMessage) {
			oStatus.ErrorMessage = ITHit.Phrases.AjaxFileBrowser.Interface.FileUploadFailed;
		}
		
		if (body) {
			oStatus.ErrorBody = body.innerHTML;
		}
	}
	
	// Create status whether not set.
	if (!oStatus.Status) {
		
		// Successful status.
		if (oStatus.Success) {
			oStatus.Status = new ITHit.WebDAV.Client.HttpStatus(201, 'Created');
		
		// Non sucessful status.
		} else {
			oStatus.Status = new ITHit.WebDAV.Client.HttpStatus(400, 'Bad Request');
		}
	}
	
	return oStatus;
}

ITHit.oNS.UploadIframe.prototype.Destruct = function() {
	
	ITHit.Events.RemoveAllListeners(this);
	this._RemoveIframeTimer();
}

ITHit.oNS.UploadIframe.prototype._RemoveIframeTimer = function() {
	
	if (this._DelareRemoveIframe) {
		return;
	}
	
	this._DelareRemoveIframe = true;
	
	setTimeout(ITHit.Utils.MakeScopeClosure(this, '_RemoveIframe'), 0);
}

ITHit.oNS.UploadIframe.prototype._RemoveIframe = function() {
	
	if (this._IframeIETimer) {
		clearTimeout(this._IframeIETimer);
		this._IframeIETimer = null;
	}
	
	if (this._IframeFFTimer) {
		clearTimeout(this._IframeFFTimer);
		this._IframeFFTimer = null;
	}
	
	this._Iframe.onload = this._Iframe.onreadystatechange = null;
	ITHit.Components.YAHOO.util.Event.removeListener(this._Iframe, 'readystatechange', this._ReadyStateChangeHandler);
	ITHit.Components.YAHOO.util.Event.removeListener(this._Iframe, 'load',             this._LoadHandler);
	
	if (this._Iframe) {
		this._Container.removeChild(this._Iframe);
		delete this._Iframe;
	}
}

