ITHit.oNS.UploadFirefox = function() {
	
	this._ClassId        = 'ITHit.WebDAV.Client.AjaxFileBrowser.UploadFirefox_'+ ITHit.WebDAV.Client.AjaxFileBrowser.UploadFirefox._Counter++;
	this._LastReportTime = new Date(0).getTime();

	ITHit.WebDAV.Client.AjaxFileBrowser.UploadFirefox.baseConstructor.call(this);
}

// Extend class.
ITHit.Extend(ITHit.oNS.UploadFirefox, ITHit.WebDAV.Client.AjaxFileBrowser.Uploader);

ITHit.oNS.UploadFirefox._Counter = 0;

ITHit.oNS.UploadFirefox.prototype.BeginUpload = function(oUploadFile) {

    this._UploadFile = oUploadFile;
	this.Method = oUploadFile.Method;
	this.Url    = oUploadFile.Url;
	this.UploadUrl = oUploadFile.UploadUrl;
	var oFile   = oUploadFile.Form._GetInputFile().files[oUploadFile.FileIndex];
	
	this._XHR   = new XMLHttpRequest();
	
	var oXhr    = this._XHR;
	
	// onloadstart
	// onprogress
	// onload
	// onerror
	
	oXhr.upload.addEventListener("progress", ITHit.Utils.MakeScopeClosure(this, '_ProgressHandler', oXhr), false);
	// oXhr.upload.addEventListener("load",     ITHit.Utils.MakeScopeClosure(this, '_LoadHandler', oXhr), false); // Don't need to, because onreadystatechange listener is set.
	// oXhr.upload.addEventListener("error",    ITHit.Utils.MakeScopeClosure(this, '_ErrorHandler', oXhr), false); // oXhr.responseBody is empty at this point.
	oXhr.onreadystatechange = ITHit.Utils.MakeScopeClosure(this, '_ReadyStateChange', oXhr);
	
	oXhr.open(this.Method, this.UploadUrl, true);
	
	try {
		oXhr.withCredentials = true;
	} catch(e) {}
	
	if (!this._SkipLoadStartHandling) {
	    ITHit.Events.DispatchEvent(this, 'OnLoadStart', ['OnLoadStart', this.Url]);
	}
	
    try {
        if (ITHit.DetectBrowser.FF >= 7) {
            var iisDetected = oUploadFile.Form.GetIisDetected();
            var iUploadPartSize = oUploadFile.Form.GetMaxUploadSegmentBytes();

            var iFileSize = oFile.fileSize || oFile.size;
            var bPartialUpload = iisDetected || (iUploadPartSize > 0 && iUploadPartSize < iFileSize);
            if (iisDetected && (iUploadPartSize <= 0 || iUploadPartSize > this._IisMaxUploadPartSize)) {
                iUploadPartSize = this._IisMaxUploadPartSize;
            }

            var iBytesUploaded = oUploadFile.Form.GetBytesUploaded(oUploadFile.FileIndex);
            this._BytesUploadedEnd = null;

            if (iBytesUploaded && iBytesUploaded >= iFileSize) {
                ITHit.Events.DispatchEvent(this, 'OnLoad', ['OnLoad', this.Url]);
            }
            else if (iBytesUploaded && ITHit.Utils.IsInteger(iBytesUploaded) || bPartialUpload) {

                if (bPartialUpload && !ITHit.Utils.IsInteger(iBytesUploaded)) {
                    iBytesUploaded = 0;
                }
                
	            var iBytesEnd = iFileSize;
	            if (bPartialUpload) {
	                iBytesEnd = iBytesUploaded + iUploadPartSize;
	                if (iBytesEnd > iFileSize) {
	                    iBytesEnd = iFileSize;
	                }
	            }
	            
	            ITHit.Events.DispatchEvent(this, 'OnUploadPart', [this.Url, iBytesUploaded, iFileSize]);

				if (iBytesUploaded !== 0 || iBytesEnd !== iFileSize) {
	            	oXhr.setRequestHeader("Content-Range", "bytes " + iBytesUploaded + "-" + (iBytesEnd - 1) + "/" + iFileSize);
				}
	            if (bPartialUpload && iBytesEnd < iFileSize) {
	                this._BytesUploadedEnd = iBytesEnd;
	                oXhr.send(oFile.slice(iBytesUploaded, iBytesEnd));
	            }
	            else {
	                oXhr.send(oFile.slice(iBytesUploaded));
	            }
	        }
	        else {
	            oXhr.send(oFile);
	        }
		} else {
			oXhr.sendAsBinary(oFile.getAsBinary());
		}
	} catch(e) {
		this._ErrorHandler('Error', oXhr);
	}
	
	return false;
}

ITHit.oNS.UploadFirefox.prototype._ProgressHandler = function(oXmlObj, oEvent) {
	
	var iNow = new Date().getTime();
	if (iNow - this._LastReportTime < 1000) {
		return;
	}
	this._LastReportTime = iNow;
	
	var oReport = {};
	oReport[this.Url] = new ITHit.WebDAV.Client.AjaxFileBrowser.InternalUploadProgressInfo(this.Url, oEvent.loaded, oEvent.total);
	ITHit.Events.DispatchEvent(this, 'OnProgress', ['OnProgress', oReport]);
}

ITHit.oNS.UploadFirefox.prototype._LoadHandler = function(oXmlObj, oEvent) {
	
	var oStatus = new ITHit.WebDAV.Client.HttpStatus(oXmlObj.status, oXmlObj.statusText);
	if (oStatus.IsSuccess()) {

	    if (this._UploadFile) {

	        var oUploadFile = this._UploadFile;
	        var bPartialUpload = oUploadFile.Form.GetIisDetected() || oUploadFile.Form.GetMaxUploadSegmentBytes() > 0;
	        if (bPartialUpload && ITHit.Utils.IsInteger(this._BytesUploadedEnd)) {

	            this._SkipLoadStartHandling = true;
	            oUploadFile.Form.SetBytesUploaded(oUploadFile.FileIndex, this._BytesUploadedEnd);
	            this.BeginUpload(this._UploadFile);
	            return;
	        }
	    }

	    ITHit.Events.DispatchEvent(this, 'OnLoad', ['OnLoad', this.Url]);
	} else {
		this._ErrorHandler(oXmlObj, oEvent, oStatus);
	}
}

ITHit.oNS.UploadFirefox.prototype._ErrorHandler = function(oXmlObj, oEvent, oStatus) {
	
	ITHit.Events.DispatchEvent(this, 'OnError', ['OnError', this.Url, oStatus, oXmlObj.responseText]);
}

ITHit.oNS.UploadFirefox.prototype._FinishHandler = function(oXmlObj, oStatus) {
	
	var oResponse = new ITHit.HttpResponse(this.Url, oStatus.Code, oStatus.Description);
	oResponse._SetBody(oXmlObj.responseXML, oXmlObj.responseText);
	
	ITHit.Events.DispatchEvent(this, 'OnFinish', [oResponse]);
}

ITHit.oNS.UploadFirefox.prototype._ReadyStateChange = function(oXmlObj, oEvent) {
	
	if (4 != oXmlObj.readyState) {
		return;
	}
	
	var oStatus = new ITHit.WebDAV.Client.HttpStatus(oXmlObj.status, oXmlObj.statusText);
	
	this._FinishHandler(oXmlObj, oStatus);
	
	if (oStatus.IsSuccess()) {
		this._LoadHandler(oXmlObj, oEvent);
	} else {
		this._ErrorHandler(oXmlObj, oEvent, oStatus);
	}
}

ITHit.oNS.UploadFirefox.prototype.Destruct = function() {
	this._XHR.abort();
}

ITHit.oNS.UploadFirefox.prototype.toString = function() {
	return this._ClassId;
}


