/**
 * Information about file upload progress.
 * @function {Object} ITHit.WebDAV.Client.AjaxFileBrowser.UploadProgressInfo
 * 
 * @param {Integer} iBytesUploaded        Uploaded bytes.
 * @param {Integer} iContentLength        Total file size.
 */
ITHit.oNS.UploadProgressInfo = function(iBytesUploaded, iContentLength) {
	
	if (!ITHit.Utils.IsInteger(iBytesUploaded)) {
		throw new ITHit.Exceptions.ArgumentException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongUploadedBytesType, iBytesUploaded);
	}
	
	if (!ITHit.Utils.IsInteger(iContentLength)) {
		throw new ITHit.Exceptions.ArgumentException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongContentLengthType, iContentLength);
	}
	
	if (iBytesUploaded > iContentLength) {
		throw new ITHit.Exceptions.ExpressionException(ITHit.Phrases.AjaxFileBrowser.Exceptions.BytesUploadedIsMoreThanTotalFileContentLength);
	}
	
	/**
	 * Amount of bytes successfully uploaded to server.
	 * @property {Integer} ITHit.WebDAV.Client.UploadProgressInfo.BytesUploaded
	 */
	this.BytesUploaded      = iBytesUploaded;
	
	/**
	 * Total file size.
	 * @property {Integer} ITHit.WebDAV.Client.UploadProgressInfo.TotalContentLength
	 */
	this.TotalContentLength = iContentLength;
}


