ITHit.oNS = ITHit.Declare("ITHit.WebDAV.Client.AjaxFileBrowser.Render");

ITHit.oNS.UploadForm = function(oRoot, sUrl, bDisabled, bDoNotCheckFileExistence, bExternalCreated, oSubmitButton, bDoNotCreateFileNameField) {

	var iNum    = ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadForm._Counter,
	    utilsNs = ITHit.Utils;
	
	// Additional parameters required by server.
	this.UrlAddParams       = 'AjaxFileBrowser=True';
	this.CheckFileExistence = !bDoNotCheckFileExistence;
	this.ExternalCreated    = bExternalCreated;
	this.IsFolderMode = false;
	this.IsResumeAfterCrash = false;
	this._ResumeDestinations = null;
	
	this.inProcess        = false;
	this.root             = oRoot;
	this.url              = sUrl;
	this.disabled         = bDisabled;
	this.name             = 'ithit_upload_iframe_'+ iNum;
	this.ExternalCreated  = false;
	this.iframe;
	this.iframeIETimer    = null;
	this.iframeFFTimer    = null;
	this.iframeLoaded     = false;
	this.iisDetected      = null;
	this.maxUploadSegmentBytes = -1;
    this._SourceNames = {};
    
	this.form             = utilsNs.CreateDOMElement({
		nodeName:      'FORM',
		method:        'POST',
		encoding:      'multipart/form-data',
		acceptCharset: 'UTF-8',
		characterSet:  'UTF-8',
		charset:       'UTF-8',
        onsubmit: function() { return false; } // Fix submit form on `butt` element
	});
	
	if (!bDoNotCreateFileNameField) {
		this.txt = utilsNs.CreateDOMElement({
			nodeName:  'INPUT',
			type: 'text',
			readOnly:  true,
			className: 'dijit dijitReset dijitLeft dijitTextBox uploadFileName',
			style: {
				width:  '100%'
			},
			onkeypress: function() {return false;}
		});
	}

	var self = this;
	this.butt = utilsNs.CreateDOMElement({
	    nodeName: 'BUTTON',
	    className: 'dijitReset dijitStretch dijitButtonNode dijitButtonContents uploadButtons',
	    childNodes: [String(ITHit.Phrases.AjaxFileBrowser.Interface.BrowseFiles)],
	    onclick: function () { return false; }
	});
	
	this.file             = this._CreateFileField();
	this.file.onchange    = ITHit.Utils.MakeScopeClosure(this, 'OnFileFieldChanged');
	this.file.onkeypress  = function () { return false; }
	this.file.onclick = function () {
	    this.webkitdirectory = (self.IsFolderMode ? 'true' : '');
	    if (!self.IsResumeAfterCrash) {
	        this._ResumeDestinations = null;
	    }
	    self.IsFolderMode = false;
	    self.IsResumeAfterCrash = false;
	}

	
	/*
	 * _submFlag :
	 *    0 - without submit button
	 *    1 - create button
	 *    2 - use passed button object
	 */
	this._submFlag = oSubmitButton ? ((utilsNs.IsDOMObject(oSubmitButton)) ? 2 : 1) : 0;
	this.subm      = null;
	
	switch (this._submFlag) {
		
		// Create button.
		case 1:
			this.subm = utilsNs.CreateDOMElement({
					nodeName:  'INPUT',
					type:      'button',
					value:     ITHit.Phrases.AjaxFileBrowser.Interface.Upload,
					className: 'dijitReset dijitStretch dijitButtonNode dijitButtonContents uploadButtons',
					onclick: ITHit.Utils.MakeScopeClosure(this, '_SubmitHandler')
				});
			break;
		
		// Use passed button object.
		case 2:
			this.subm         = oSubmitButton;
			this.subm.onclick = ITHit.Utils.MakeScopeClosure(this, '_SubmitHandler');
			break;
	}
	
	var table = utilsNs.CreateDOMElement({
		nodeName: 'TABLE',
		width: '100%',
		height: '22px',
		margin: 'auto',
		padding: '0px',
		childNodes: [{
			nodeName: 'TBODY',
			childNodes: [{
				nodeName: 'TR',
				childNodes: [{
					nodeName: 'TD',
					childNodes: [
						{
							nodeName: 'TABLE',
							style: {
								width: '100%',
								height: '20px',
								margin: 'auto',
								padding: '0px',
								tableLayout: 'fixed'
							},
							cellSpacing: 0,
							cellPadding: 0,
							childNodes: [{
								nodeName: 'TBODY',
								childNodes: [{
									nodeName: 'TR',
									childNodes: [
										{
											nodeName: 'TD',
											childNodes: [
												this.txt
											]
										},
										{
											nodeName: 'TD',
											style: {
												height:   '20px',
												width:    '80px',
												overflow: 'hidden'
											},
											childNodes: [{
												nodeName: 'DIV',
												className: 'uploadContainer',
												childNodes: [
													this.file,
													{
														nodeName: 'SPAN',
														childNodes: [
															this.butt
														]
													}
												]
											}]
										}]
									}]
								}]
						},
						// Insert button only for create button flag.
						(1 == this._submFlag)
							? {
								nodeName: 'TD',
								style: {
									width: '50px'
								},
								childNodes: [
									this.subm
								]
							}
							: null
						]
					}]
				}]
			}]
		});
	
	this.form.appendChild(table);
	
	if (this.disabled) {
		this.DisableForm();
	} else {
		this.DisableSubmitButton();
	}
	
	this.root.appendChild(this.form);
	
	this._ClassId = 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadForm_' + ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadForm._Counter++;
}

ITHit.oNS.UploadForm._Counter = 0;

ITHit.oNS.UploadForm.prototype._CreateFileField = function() {
	
	var oFile         = document.createElement('INPUT');
	oFile.className   = 'hiddenFileField';
	oFile.type        = 'file';
	oFile.name        = 'file';
	if (this.CheckFileExistence) {
		oFile.multiple = true;
	}
	// IE8 file field transparency fix.
	if (ITHit.DetectBrowser.IE) {
		var _fileStyle = oFile.style;
		_fileStyle.visibility = 'hidden';
		setTimeout(function(){
			_fileStyle.visibility = 'visible';
		}, 0);
	}
	
	return oFile;
}

ITHit.oNS.UploadForm.prototype.DisableForm = function() {
	this.file.disabled = true;
	this.butt.disabled = true;
	if (this.txt) {
		this.txt.disabled  = true;
	}
	this.disabled      = true;
	this.DisableSubmitButton();
}

ITHit.oNS.UploadForm.prototype.EnableForm = function(bEnableSubm) {
	this.file.disabled = false;
	this.butt.disabled = false;
	
	// Update content (webkit browsers bug).
	if ((ITHit.DetectBrowser.Chrome || ITHit.DetectBrowser.Safari) && this.butt.parentNode) {
		this.butt.parentNode.innerHTML += '';
	}
	if (this.txt) {
		this.txt.disabled  = false;
	}
	this.disabled      = false;
	if (bEnableSubm) {
		this.EnableSubmitButton();
	}
}

ITHit.oNS.UploadForm.prototype.ClearFileField = function() {
	
	if (this.txt) {
		this.txt.value = '';
	}
	
	var oFile = this._CreateFileField();
	
	oFile.onchange   = this.file.onchange;
	oFile.onkeypress = this.file.onkeypress;
	oFile.disabled   = this.file.disabled;
	
	this.file.onchange   = null;
	this.file.onkeypress = null;
	
	this.file.parentNode.replaceChild(oFile, this.file);
	this.file = oFile;

	this._bytesUploaded = [];
    this._SourceNames = {};

  if (ITHit.DetectBrowser.Safari || ITHit.DetectBrowser.Chrome)
  {
    this.file.form.style.overflow = 'visible';
  }
}

ITHit.oNS.UploadForm.prototype.ResetForm = function(sUrl, bDoNotCheckFileExistence) {
	
	this.url                = sUrl;
	this.CheckFileExistence = !bDoNotCheckFileExistence;
	
	this.form.reset();
	this.file.multiple = this.CheckFileExistence;
}

ITHit.oNS.UploadForm.prototype.DisableSubmitButton = function() {
	if (this._submFlag) {
		this.subm.disabled = true;
	}
}

ITHit.oNS.UploadForm.prototype.EnableSubmitButton = function() {
	if (this._submFlag) {
		this.subm.disabled = false;
	}
}

ITHit.oNS.UploadForm.prototype.SetUploadUrl = function(sUrl) {
	this.url = sUrl.replace(/\/?$/, '/');
}

ITHit.oNS.UploadForm.prototype.OnFileFieldChanged = function(oEvent) {
	oEvent = oEvent || window.event;
	
	var el       = this.file,
	    urlUtils = ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils;

	if (el.files && el.files.length > 1) {
	    if (ITHit.DetectBrowser.Safari && ITHit.DetectBrowser.Safari == 5.1 && !ITHit.DetectBrowser.Mac) {
	        ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.Safari51WindowsMultiUploadNotSupported);
	        return;
	    }
	}
	
	if (this.txt) {
		// For multiple files.
		if (el.files && el.files.length > 1) {
			
			var aFileNames = [];
			for (var i = 0, l = el.files.length; i < l; i++) {
				aFileNames.push(urlUtils.GetFileName(el.files[i].fileName || el.files[i].name));
			}
			this.txt.value = aFileNames.join(', ');
		
		// For single file.
		} else {
			this.txt.value = urlUtils.GetFileName(el.value);
		}
	}

	this._bytesUploaded = [];
    this._SourceNames = {};
	
	if (this._submFlag) {
		this.EnableSubmitButton();
	} else {
		this._SubmitHandler(oEvent);
	}
};

ITHit.oNS.UploadForm.prototype._AddRequiredParams = function(url) {
	return url + ((-1 == url.indexOf('?')) ? '?' : '&') + this.UrlAddParams;
}

ITHit.oNS.UploadForm.prototype.SetFormTarget = function(sName) {
	
	if (!sName || !ITHit.Utils.IsString(sName)) {
		throw 'String name must be specified as upload form target.';
	}
	
	this.form.target = sName;
}

ITHit.oNS.UploadForm.prototype._GetInputFile = function(){
	return this.file;
}  

ITHit.oNS.UploadForm.prototype.DoClickBrowse = function () {
    var evt = document.createEvent("MouseEvents");
    evt.initEvent("click", true, false);
    this.file.dispatchEvent(evt);
}

ITHit.oNS.UploadForm.prototype._SubmitHandler = function(oEvent) {

    if ('' === this.file.value) {
		return false;
	}
	
	this.form.action  = this._AddRequiredParams(this.GetDestination());

	if (false === ITHit.Events.DispatchEvent(this, 'OnSubmit', [oEvent, new ITHit.WebDAV.Client.AjaxFileBrowser.UploadFormObject(this)])) {
		return false;
	}
	
	this.Hide();
	
	return true;
}

ITHit.oNS.UploadForm.prototype.SetBytesUploaded = function(iIndex, iBytesUploaded) {
    if (this._bytesUploaded) {
        this._bytesUploaded[iIndex] = iBytesUploaded;
    }
}

ITHit.oNS.UploadForm.prototype.GetBytesUploaded = function(iIndex) {
    if (this._bytesUploaded && iIndex >= 0 && iIndex < this._bytesUploaded.length) {
        return this._bytesUploaded[iIndex];
    }

    return null;
}

ITHit.oNS.UploadForm.prototype.Hide = function() {
	this.form.style.display = 'none';
}

ITHit.oNS.UploadForm.prototype.Destruct = function() {
	
	this.file.onchange   = null;
	this.file.onkeypress = null;
	if (this.txt) {
		this.txt.onkeypress  = null;
	}
	this.butt.onclick   = null;
	if (this.subm) {
		this.subm.onclick = null;
	}
	
	this.root.removeChild(this.form);
	
	ITHit.Events.RemoveAllListeners(this);
	
	for (var p in this) {
		this[p] = null;
	}
}

ITHit.oNS.UploadForm.prototype.GetFileSize = function (iIndex) {

    var iFileSize;
    iIndex = iIndex || 0;
    if (this.file.files) {
        var oFile = this.file.files[iIndex];
        if (oFile) {
            iFileSize = oFile.fileSize || oFile.size;
        }
    }
    return iFileSize;
}

ITHit.oNS.UploadForm.prototype.GetSourceName = function(iIndex) {
    if (!this._SourceNames[iIndex]) {
        var sVal;

        iIndex = iIndex || 0;
        if (this.file.files && iIndex !== undefined) {
            var file = this.file.files[iIndex];
            sVal = file.fileName || file.name;

        } else {
            sVal = this.file.value;
        }

        var iPos = sVal.lastIndexOf('/') + 1;
        if (!iPos) {
            iPos =  sVal.lastIndexOf('\\') + 1;
        }

        if (iPos) {
            sVal = sVal.substr(iPos);
        }

        //Fix for the image filename in Safari on iPad and iPhone
        if ((sVal.indexOf("image.jpg", sVal.length - "image.jpg".length) !== -1) && (ITHit.DetectBrowser.iPad || ITHit.DetectBrowser.iPhone)) {
            sVal = sVal.replace("image.jpg", "image" + (new Date()).getTime() + ".jpg");
        }

        this._SourceNames[iIndex] = sVal;
    }

    return this._SourceNames[iIndex];
}

ITHit.oNS.UploadForm.prototype.GetRelativePath = function (iIndex) {
    
    var sVal;
    iIndex = iIndex || 0;
    if (ITHit.DetectBrowser.Chrome) {
        var oFile = this.file.files[iIndex];
        if (oFile && !ITHit.Utils.IsStringNullOrEmpty(oFile.webkitRelativePath)) {
            sVal = oFile.webkitRelativePath;

            var iPos = sVal.indexOf('/') + 1;
            if (!iPos) {
                iPos = sVal.indexOf('\\') + 1;
            }

            if (iPos) {
                sVal = sVal.substr(iPos);
            }

            return sVal;
        }
    }
}

ITHit.oNS.UploadForm.prototype.SetDestination = function(sUrl) {
	this.url = sUrl;
}

ITHit.oNS.UploadForm.prototype.GetDestination = function (iIndex) {

    if (this._ResumeDestinations) {
        var sSource = ITHit.WebDAV.Client.Encoder.Encode(this.GetSourceName(iIndex));
        if (sSource && this._ResumeDestinations[sSource]) {
            return this._ResumeDestinations[sSource];
        }
    }

    var sRet = this.url;
    if (/\/$/.test(sRet)) {
        var sRel = this.GetRelativePath(iIndex);
        if (!ITHit.Utils.IsStringNullOrEmpty(sRel)) {
            if (/\/\.$/.test(sRel)) {
                sRel = sRel.substr(0, sRel.length - 1);
            }
        }
        else {
            sRel = this.GetSourceName(iIndex);
        }
        sRet += ITHit.WebDAV.Client.Encoder.Encode(sRel);
	}

	return sRet;
}

ITHit.oNS.UploadForm.prototype.GetResumeDestinations = function () {
    return this._ResumeDestinations;
}

ITHit.oNS.UploadForm.prototype.GetResumeDestination = function (iIndex) {

    if (this._ResumeDestinations) {
        var sSource = ITHit.WebDAV.Client.Encoder.Encode(this.GetSourceName(iIndex));
        if (sSource && this._ResumeDestinations[sSource]) {
            return this._ResumeDestinations[sSource];
        }
    }
}

ITHit.oNS.UploadForm.prototype.SetResumeDestinations = function (aDestinations) {
    this._ResumeDestinations = aDestinations;
}

ITHit.oNS.UploadForm.prototype.GetFileInfo = function(iIndex) {
	
	if (this.file.files) {
		iIndex = iIndex || 0;
		return this.file.files[iIndex];
	}
	
	return null;
}

ITHit.oNS.UploadForm.prototype.GetUploadFilesLength = function() {
	
	if (this.file.files) {
		return this.file.files.length;
	} else {
		return this.file.value ? 1 : 0;
	}
}

ITHit.oNS.UploadForm.prototype.Submit = function(sUrl) {
	if (sUrl) {
		this.form.action = this._AddRequiredParams(sUrl);
	}
	this.form.submit();
}

ITHit.oNS.UploadForm.prototype.SetInProcess = function() {
	this.inProcess = true;
	ITHit.Events.DispatchEvent(this, 'OnProcessForm', ['OnProcessForm', new ITHit.WebDAV.Client.AjaxFileBrowser.UploadFormObject(this)]);
}

ITHit.oNS.UploadForm.prototype.CheckProcess = function() {
	return this.inProcess;
}

ITHit.oNS.UploadForm.prototype.SetIisDetected = function (bIisDetected) {
    this.iisDetected = bIisDetected;
}

ITHit.oNS.UploadForm.prototype.GetIisDetected = function () {
    return this.iisDetected === true;
}

ITHit.oNS.UploadForm.prototype.SetResumeAfterCrash = function (bIsResumeAfterCrash) {
    this.IsResumeAfterCrash = bIsResumeAfterCrash;
}

ITHit.oNS.UploadForm.prototype.GetResumeAfterCrash = function () {
    return this.IsResumeAfterCrash === true;
}

ITHit.oNS.UploadForm.prototype.SetMaxUploadSegmentBytes = function (iMaxUploadSegmentBytes) {
    this.maxUploadSegmentBytes = iMaxUploadSegmentBytes;
}

ITHit.oNS.UploadForm.prototype.GetMaxUploadSegmentBytes = function () {
    return this.maxUploadSegmentBytes;
}

ITHit.oNS.UploadForm.prototype.toString = function() {
	return this._ClassId;
}

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions');

/**
 * Thrown when upload progress request failed.
 * @class ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.GridException
 * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException
 */
/**
 * Initializes a new instance of the GridException class with a specified error message, a reference to the inner exception that is the cause of this exception.
 * @constructor GridException
 * 
 * @param {String} sMessage The error message string.
 * @param {optional ITHit.Exception} oInnerException The ITHit.Exception instance that caused the current exception.
 */
ITHit.oNS.GridException = function(sMessage, oInnerException) {
	
	// Inheritance definition.
	ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.GridException.baseConstructor.call(this, sMessage, oInnerException);
}

// Extend class.
ITHit.Extend(ITHit.oNS.GridException, ITHit.oNS.AjaxFileBrowserException);

// Exception name
ITHit.oNS.GridException.prototype.Name = 'GridException';



ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView');

ITHit.oNS.Grid = function(element, layout, mapNames) {
	
	// Element id was passed.
	if ( ('string' === typeof element) || (element instanceof String)) {
		this._elementId = element;
		this._grid      = ITHit.Components.dijit.byId(element);
	
	// Element passed as object.
	} else {
		this._elementId = element.id;
		this._grid      = element;
	}

	this._grid.scrollTo = this._GridScrollTo;
	this._grid.onKeyDownOriginal = this._grid.onKeyDown;
	this._grid.onKeyDown = this._GridOnKeyDown;

	// Set custom rows formatter
	var that = this;
	this._grid.renderRow = function(inRowIndex, inNodes) {
		that._RenderRow(this, inRowIndex, inNodes);
	};
    // Fix reset styles in dojo. And fix reset custom class names
    this._grid.rows.applyStyles = function(inRow) {
        var sCustomClassNames = inRow.node.className.replace(/\b(dojo[^ ]+|dnd_target|selection_target)\b/g, '').replace(/  +|^ | $/g, '');
        inRow.node.className = inRow.customClasses + ' ' + sCustomClassNames;
    };
	// Disable focus after tender items - it's fix auto blur in search bar
	this._grid.focus.isNavHeader = function() { return false; };

	if (mapNames && !ITHit.Utils.IsObjectStrict(mapNames)) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.GridException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongParametrType);
	}
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.Grid.baseConstructor.call(this);
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.Grid.base;
	
	this._Layout   = layout;
	this._MapNames = mapNames || {};
	
	this._grid.set('escapeHTMLInData', false);
}

ITHit.Extend(ITHit.oNS.Grid, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.Grid.prototype._GridScrollTo = function(inTop) {
	// summary:
	//		Vertically scroll the grid to a given pixel position
	// inTop: Integer
	//		vertical position of the grid in pixels
	if(!this.fastScroll){
		this.setScrollTop(inTop);
		return;
	}
	this.lastScrollTop = inTop;
	this.delayScroll = true;
	this.scrollTop = inTop;
	if(this._pendingScroll){
		window.clearTimeout(this._pendingScroll);
	}
	var _this = this;
	this._pendingScroll = window.setTimeout(function(){
		delete _this._pendingScroll;
		_this.finishScrollJob();
	}, 100);
}

ITHit.oNS.Grid.prototype._GridOnKeyDown = function(e) {
	// Overwrite dokeydown method in dojox.Grid._Events. Dojo listening keydown
	// event and stop other events. Disable dojo listener.
	switch(e.keyCode) {
		case ITHit.Components.dojo.keys.PAGE_UP:
		case ITHit.Components.dojo.keys.PAGE_DOWN:
		case ITHit.Components.dojo.keys.UP_ARROW:
		case ITHit.Components.dojo.keys.DOWN_ARROW:
		case ITHit.Components.dojo.keys.ENTER:
			return true;
	}

	this.onKeyDownOriginal(e);
}

ITHit.oNS.Grid.prototype._RenderRow = function(grid, inRowIndex, inNodes) {
    // summary: private, used internally to render rows
    grid.views.renderRow(inRowIndex, inNodes, this._skipRowRenormalize);

    if (ITHit.Utils.IsFunction(this._RowFormatter) || ITHit.Utils.IsFunction(this._CellFormatter)) {
        var inRowNode = inNodes[0].childNodes[inRowIndex];
        var sUrl = grid.store.getItem(inRowIndex)[this._MapNames.Url][0];
        var iControllerIndex = this._grid.domNode.parentNode.getAttribute('controllerIndex') || 0;
        var oController = ITHit.WebDAV.Client.AjaxFileBrowser.Controller.GetByIndex(iControllerIndex);
        var oItem = oController._GetItem(sUrl);

        // Set custom row formatter
        if (ITHit.Utils.IsFunction(this._RowFormatter)) {
            this._RowFormatter(inRowNode, oItem.Item, inRowIndex);
        }

        // Set custom cells formatter
        if (ITHit.Utils.IsFunction(this._CellFormatter)) {
            ITHit.Components.dojo.query('td.dojoxGridCell', inRowNode).forEach(function(cellElement, iCellIndex) {
                var oCellOptions = this.Layout.cells[0][iCellIndex];
                if (oCellOptions) {
                    var result = this._CellFormatter(cellElement, oItem.Item, inRowIndex, iCellIndex, oCellOptions);
                    if (!ITHit.Utils.IsUndefined(result) && result !== null) {
                        cellElement.innerHTML = result;
                    }

                    if (oCellOptions.cellFormatter) {
                        var result = oCellOptions.cellFormatter(cellElement, oItem.Item, inRowIndex, iCellIndex, oCellOptions);
                        if (!ITHit.Utils.IsUndefined(result) && result !== null) {
                            cellElement.innerHTML = result;
                        }
                    }
                }
            }, this);
        }
    }
}

ITHit.oNS.Grid.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.Grid';
}

ITHit.oNS.Grid.prototype.GetElementId = function() {
	return this._elementId;
}

ITHit.oNS.Grid.prototype.RenderItems = function(dataRows) {

	this._grid.selection.clear();
	var obj = {
		data: {items: dataRows}
	};

	var store = new ITHit.Components.dojo.data.ItemFileWriteStore(obj);
	var bIsStructureInit = !!this._grid.get('structure');
	if (!bIsStructureInit) {
		this._grid.set('structure', this._Layout);
	}

	this._grid.setStore(store);
}

ITHit.oNS.Grid.prototype.GetSelectedCount = function() {
	return this._grid.selection.getSelectedCount();
}

ITHit.oNS.Grid.prototype.GetSelectedItems = function() {
    var aItems = [];
    var aItemIndexes = this._grid.selection.getSelectedIndexes();
    for (var i = 0, l = aItemIndexes.length; i < l; i++) {
		var oItem = this._grid.getItem(aItemIndexes[i]) || this.GetItemByRowIndex(aItemIndexes[i]);
        aItems.push(oItem);
    }

	return aItems;
}

ITHit.oNS.Grid.prototype.GetItemByRowIndex = function(index) {
	return this._grid.getItem(index) || this._grid.store.getItem(index);
}

ITHit.oNS.Grid.prototype.SearchDataByIndex = function(attribute, index) {
	
	attribute = this._MapNames[String(attribute)] || attribute;

	var row = this._grid.getItem(index) || this.GetItemByRowIndex(index);
	if (!row) {
		return null;
	}

	var data = row[attribute];
	if (data.length) {
		return data[0];
	}
	return null;
}

ITHit.oNS.Grid.prototype.SearchItemByData = function(attribute, toSearch, caseInsensitive) {
	var index = this.SearchIndexByData(attribute, toSearch, caseInsensitive);
	return (null !== index) ? this.Grid._by_idx[index].item : null;
}

ITHit.oNS.Grid.prototype.SearchIndexByData = function(attribute, toSearch, caseInsensitive) {
	var indexes = this.SearchIndexesByData(attribute, toSearch, caseInsensitive, true);
	return indexes.length ? indexes[0] : null;
}

/**
 *
 * @param {string} attribute
 * @param {*} toSearch
 * @param {boolean} [caseInsensitive]
 * @param {boolean} [onlyFirst]
 * @returns {object|null}
 */
ITHit.oNS.Grid.prototype.SearchIndexesByData = function (attribute, toSearch, caseInsensitive, onlyFirst) {
	var items = this.Grid._by_idx,
		indexes = [];

	if (!items || !items.length) {
		return [];
	}

	if (!(toSearch instanceof Array)) {
		toSearch = [toSearch];
	}

	var attributeIndex = this._MapNames[String(attribute)] || attribute;

	for (var i = 0, l = toSearch.length, search; i < l; i++) {
		search = caseInsensitive ? String(toSearch[i]).toLowerCase() : toSearch[i];

		for (var j = 0, lj = items.length, attrValue; j < lj; j++) {
			if (!items[j]) {
				continue;
			}

			attrValue = items[j].item[attributeIndex][0];
			if (caseInsensitive) {
				attrValue = String(attrValue).toLowerCase();
			}
			if (attrValue === search) {
				if (onlyFirst) {
					return [j];
				}

				indexes.push(j);
			}
		}
	}

	return indexes;
},

ITHit.oNS.Grid.prototype.IsSelected = function(index) {
	return this._grid.selection.isSelected(index) || false;
}

ITHit.oNS.Grid.prototype.DeselectAll = function() {
	this._grid.selection.deselectAll();
}

ITHit.oNS.Grid.prototype.SetSelected = function(index, isSet) {
	
	isSet = isSet || false;
	
	if (!ITHit.Utils.IsArray(index)) {
		index = [index];
	}
	
	for (var i = 0, l = index.length; i < l; i++) {
		this._grid.selection.setSelected(index[i], isSet);
	}

	// Scroll to first item, if it no visible
	if (index[0] < this._grid.scroller.firstVisibleRow || this._grid.scroller.lastVisibleRow < index[0]) {
		this._grid.setScrollTop(this._grid.scroller.findScrollTop(index[0]));
		this._grid.focus.setFocusIndex(index[0], 0);
	}
}

ITHit.oNS.Grid.prototype.SelectAll = function() {
	this._grid.selection.selectAll();
}

ITHit.oNS.Grid.prototype.SetSelectedByBoxArea = function(beginX, beginY, endX, endY) {
	
	// Find indexes.
	var indexes = this._grid.findIndexesInBoxCoords(beginX, beginY, endX, endY);
	this.SetSelected(indexes, true);
}

ITHit.oNS.Grid.prototype.SetValue = function(dataRow, attribute, data) {
	attribute = this._MapNames[String(attribute)] || attribute;
	this._grid.store.setValue(dataRow, attribute, data);
}

ITHit.oNS.Grid.prototype.GetValue = function(dataRow, attribute) {
	attribute = this._MapNames[String(attribute)] || attribute;
	return this._grid.store.getValue(dataRow, attribute);
}

ITHit.oNS.Grid.prototype.AddItem = function(dataArray) {
	return this._grid.store.newItem(dataArray);
}

ITHit.oNS.Grid.prototype.DeleteItem = function(dataRow) {
    // Manually delete selection (dojo fix)
    var index = ITHit.Components.dojo.indexOf(this._grid.store._arrayOfTopLevelItems, dataRow);
    this._grid.selection.deselect(index);
    this._grid.selection.remove(index);

	return this._grid.store.deleteItem(dataRow);
}

ITHit.oNS.Grid.prototype.Update = function() {
	this._grid.store.save();
}

ITHit.oNS.Grid.prototype.GetScrollerNode = function() {
	
	if (this._grid.views.views.length) {
		return this._grid.views.views[0].scrollboxNode;
	}
	
	return null;
}

ITHit.oNS.Grid.prototype.SetScrollTop = function(top){
	return this._grid.setScrollTop(top);
}

ITHit.oNS.Grid.prototype.SetScrollLeft = function(left){
	return this._grid.setScrollLeft(left);
}

ITHit.oNS.Grid.prototype.KeyUp = function(aItems, oEvent) {
	var indexes = this._grid.selection.getSelectedIndexes();
	var index = indexes[0] || 0;
	if (this._grid.selection.selectedIndex !== index) {
		this.SetSelected(this._grid.selection.selectedIndex, false);
		index = indexes[indexes.length - 1];
	}

	var newIndex = index > 0 ? index - 1: index;
	this._KeyPress(index, newIndex, oEvent.shiftKey);
}

ITHit.oNS.Grid.prototype.KeyDown = function(aItems, oEvent) {
	var indexes = this._grid.selection.getSelectedIndexes();
	var index = indexes[indexes.length - 1];
	if (this._grid.selection.selectedIndex !== index) {
		this.SetSelected(this._grid.selection.selectedIndex, false);
		index = indexes[0] || 0;
	}

	var newIndex = index < (this._grid.rowCount - 1) ? index + 1 : index;
	this._KeyPress(index, newIndex, oEvent.shiftKey);
}

ITHit.oNS.Grid.prototype.KeyHome = function(aItems, oEvent) {
	var indexes = this._grid.selection.getSelectedIndexes();
	this._KeyHomeEnd(oEvent, indexes[0] || 0, 0);
}
ITHit.oNS.Grid.prototype.KeyEnd = function(aItems, oEvent) {
	var indexes = this._grid.selection.getSelectedIndexes();
	this._KeyHomeEnd(oEvent, indexes[indexes.length - 1], this._grid.rowCount - 1);
}
ITHit.oNS.Grid.prototype.KeyPageUp = function(aItems, oEvent) {
	var indexes = this._grid.selection.getSelectedIndexes();
	var newIndex = (this._grid.scroller.firstVisibleRow * 2 - this._grid.scroller.lastVisibleRow) + 2;
	this._KeyHomeEnd(oEvent, indexes[indexes.length - 1], newIndex);
}
ITHit.oNS.Grid.prototype.KeyPageDown = function(aItems, oEvent) {
	var indexes = this._grid.selection.getSelectedIndexes();
	var newIndex = (this._grid.scroller.lastVisibleRow * 2 - this._grid.scroller.firstVisibleRow) - 2;
	this._KeyHomeEnd(oEvent, indexes[0] || 0, newIndex, this._grid.scroller.lastVisibleRow);
}

ITHit.oNS.Grid.prototype._KeyHomeEnd = function(oEvent, index, newIndex, scrollIndex) {
	if (!this._grid.rowCount) {
		return false;
	}

	newIndex = Math.max(0, newIndex);
	newIndex = Math.min(this._grid.rowCount - 1, newIndex);

    scrollIndex = ITHit.Utils.IsUndefined(scrollIndex) ? newIndex : scrollIndex;

	this._grid.setScrollTop(this._grid.scroller.findScrollTop(scrollIndex));
	this._grid.focus.setFocusIndex(newIndex, 0);

	this.DeselectAll();
	if (oEvent.shiftKey) {
		for (var i = Math.min(index, newIndex); i <= Math.max(index, newIndex); i++) {
			this.SetSelected(i, true);
		}
	} else {
		this.SetSelected(newIndex, true);
	}
}

ITHit.oNS.Grid.prototype._KeyPress = function(index, newIndex, withShift) {
	if (!this._grid.rowCount) {
		return false;
	}

	var selectedLength = this.GetSelectedCount();
	if (!selectedLength) {
		this.SetSelected(0, true);
		this._grid.focus.setFocusIndex(0, 0);
		return;
	}

	if (!withShift) {
		if (1 == selectedLength) {
			this.SetSelected(index, false);
		} else {
			this.DeselectAll();
		}
	}

	this.SetSelected(newIndex, true);
	this._grid.focus.setFocusIndex(newIndex, 0);
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render');

ITHit.oNS.Timer = function(mIndex, iTime, iIncrement, fHandler, bDisabled) {
	
	this.index         = mIndex;
	this.time          = parseInt(iTime) || 0;
	this.increment     = iIncrement      || 1;
	this.type          = (this.increment > 0) ? 'up' : 'down';
	this.active        = !bDisabled;
	this.OnTimerUpdate = fHandler;
	
	this._ReturnTime();
	
	this._ClassId  = 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.Timer_'+ ITHit.WebDAV.Client.AjaxFileBrowser.Render.Timer._Counter++;
}

ITHit.oNS.Timer._Counter = 0;

ITHit.oNS.Timer.prototype._Tick = function() {
	
	if ( !this.active || ('down' === this.type) && (this.time <= 0) ) {
		return;
	}
	
	if (isFinite(this.time)) {
		this.time += this.increment;
		if (this.time < 0) {
			this.time = 0;
		}
	}
	
	this._ReturnTime();
}

ITHit.oNS.Timer.prototype._ReturnTime = function() {
	if (this.OnTimerUpdate instanceof Function) {
		this.OnTimerUpdate(this.index, this.time);
	}
}

ITHit.oNS.Timer.prototype.SetTime = function(mTime) {
	this.time   = mTime;
	this.active = true;
}

ITHit.oNS.Timer.prototype.StopTimer = function() {
	this.active = false;
}

ITHit.oNS.Timer.prototype.SetUpdateHandler = function(fHandler) {
	this.OnTimerUpdate = fHandler;
}

ITHit.oNS.Timer.prototype.IsSetTimerUpdateHandler = function(mTime) {
	return !!this.OnTimerUpdate;
}

ITHit.oNS.Timer.prototype.toString = function() {
	return this._ClassId;
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render');

ITHit.oNS.TimerManager = function(){
	
	this.timers       = [];
	this.timersLength = 0;
	this.interval;
	
	this._ClassId = 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.TimerManager_'+ ITHit.WebDAV.Client.AjaxFileBrowser.Render.TimerManager._Counter++;
}

ITHit.oNS.TimerManager._Counter = 0;

ITHit.oNS.TimerManager.prototype.AddTimer  = function(mIndex, iTime, iIncrement, fHandler, bDisabled) {
	
	if (this.timers[mIndex]) {
		return false;
	}
	
	this.timers[mIndex] = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.Timer(mIndex, iTime, iIncrement, fHandler, bDisabled);
	this.timersLength++;
	
	if (!this.interval) {
		this.interval = setInterval(ITHit.Utils.MakeScopeClosure(this, '_Tick'), 1000);
	}
}

ITHit.oNS.TimerManager.prototype._Tick = function() {
	
	for (var mIndex in this.timers) {
		if (!this.timers.hasOwnProperty(mIndex)) continue;
		
		this.timers[mIndex]._Tick();
	}
}

ITHit.oNS.TimerManager.prototype.SetTime = function(mIndex, iTime) {
	
	if(!this.timers[mIndex]) {
		return false;
	}
	
	this.timers[mIndex].SetTime(iTime);
}

ITHit.oNS.TimerManager.prototype.DeleteTimer = function(mIndex) {
	
	if (!this.timers[mIndex]) {
		return false;
	}
	
	delete this.timers[mIndex];
	this.timersLength--;
	
	if (!this.timersLength && this.interval) {
		clearInterval(this.interval);
		this.interval = null;
	}
}

ITHit.oNS.TimerManager.prototype.StopTimer = function(mIndex) {
	
	if (!this.timers[mIndex]) {
		return false;
	}
	
	this.timers[mIndex].StopTimer();
}

ITHit.oNS.TimerManager.prototype.TimerExists = function(mIndex) {
	return this.timers[mIndex] ? true : false;
}

ITHit.oNS.TimerManager.prototype.SetTimerUpdateHandler = function(mIndex, fHandler) {
	
	if (!this.timers[mIndex]) {
		return;
	}
	
	this.timers[mIndex].SetUpdateHandler(fHandler);
}

ITHit.oNS.TimerManager.prototype.IsSetTimerUpdateHandler = function(mIndex) {
	return (this.timers[mIndex] && this.timers[mIndex].IsSetUpdateHandler());
}

ITHit.oNS.TimerManager.prototype.toString = function() {
	return this._ClassId;
}


ITHit.oNS = ITHit.Declare("ITHit.WebDAV.Client.AjaxFileBrowser.Render");

ITHit.oNS.UploadInfoManager = function(sElementId, oController) {
	
	this._ClassId = 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadInfoManager_'+ ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadInfoManager._Counter++;
	
	var oNsPhrases = ITHit.Phrases.AjaxFileBrowser.Upload;
	
	this._PreloadImg(oController);
	
	var aTableFieldsStructure = [
			{linkId: 'Icon',        name: '&nbsp;',                   field: '1',  width: '22px',  formatter: this.StatusImage,    noresize: 'true'},
			{linkId: 'Source',      name: oNsPhrases.Source,          field: '2',  width: '115px', formatter: this.CreateSourceContainer},
			{linkId: 'Destination', name: oNsPhrases.Destination,     field: '3',  width: '100px', formatter: this.RightPosition,  styles: {textAlign: 'right'}, escapeHTMLInData: 'false'},
			{linkId: 'ProgressBar', name: oNsPhrases.Progress,        field: '4',  width: '78px',  formatter: this.UploadProgress, headerStyle: {textAlign: 'center'}},
			{linkId: 'Progress',    name: oNsPhrases.ProgressPercent, field: '5',  width: '65px',  styles: {textAlign: 'right'}},
			{linkId: 'Uploaded',    name: oNsPhrases.Uploaded,        field: '6',  width: '60px',  formatter: this.FileSize,       styles: {textAlign: 'right'}},
			{linkId: 'FileSize',    name: oNsPhrases.FileSize,        field: '7',  width: '60px',  formatter: this.FileSize,       styles: {textAlign: 'right'}},
			{linkId: 'Speed',       name: oNsPhrases.Speed,           field: '8',  width: '64px',  formatter: this.UploadSpeed,    styles: {textAlign: 'right'}},
			{linkId: 'TimeLeft',    name: oNsPhrases.Left,            field: '9',  width: '54px',  formatter: this.FormatTime,     styles: {textAlign: 'center'}},
			{linkId: 'TimeElapsed', name: oNsPhrases.Elapsed,         field: '10', width: '54px',  formatter: this.FormatTime,     styles: {textAlign: 'center'}}
		];
	
	var oMapNames = {
		'Url':               '0',
		'Status':            '1',
		'Source':            '2',
		'Destination':       '3',
		'ProgressBar':       '4',
		'UploadProgress':    '5',
		'UploadedBytes':     '6',
		'FileSize':          '7',
		'UploadSpeed':       '8',
		'TimeLeft':          '9',
		'TimeElapsed':       '10',
		'UploadStartTime':   '11',
		'LastReportTime':    '12',
		'LastUploadedBytes': '13',
		'StartPosition':     '14',
        'TotalFileSize':     '15'
	};
	
	var aModified = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.CloneGridColumnsModified(aTableFieldsStructure, oController._MofifyInstructions.UploadProgressPanel);
	
	this._Layout = [{
			cells: [
				aModified
			],
			tableLayout: true
		}];
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadInfoManager.baseConstructor.call(this, sElementId, this._Layout, oMapNames);
	this._grid.formatterScope = this;
	
	this.base        = ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadInfoManager.base;
	this._Controller = oController;
	this.Timers      = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.TimerManager();
	
	this.UploadInfoLibraryClass   = ITHit.WebDAV.Client.UploadProgressInfo;
	this.ReportProgressErrorCount = 3;
	this.Pool        = [];
	this.Hash        = {};
	this.IdHash      = {};
	this.TimerHash   = {};
	this.DiffInfo    = {};
	this.IdCounter   = 0;
	this.ErrorLog    = {};
	this.UniqueIndex = oController._index;
	// this.RenderItems(this.Pool);
	
	
	ITHit.Components.dojo.connect(this._grid, 'onRowContextMenu',   ITHit.Utils.MakeScopeClosure(this,        '_OnRowContextMenuHandler'));
	ITHit.Components.dojo.connect(this._grid, 'onRowDblClick',      ITHit.Utils.MakeScopeClosure(this,        '_OnRowDblClickHandler'));

	// Handlers for disable text selection in IE
	ITHit.Components.dojo.connect(this._grid, 'onRowMouseDown',     ITHit.Utils.MakeScopeClosure(this,        '_OnGridMouseDownHandler'));
	ITHit.Components.dojo.connect(this._grid, 'onRowMouseOut',      ITHit.Utils.MakeScopeClosure(this,        '_OnGridMouseOutHandler'));

	this.RenderItems([]);
}

ITHit.Extend(ITHit.oNS.UploadInfoManager, ITHit.oNS.DataView.GridView.Grid);

ITHit.oNS.UploadInfoManager._Counter = 0;

ITHit.oNS.UploadInfoManager.prototype._OnGridMouseDownHandler = function(oEvent) {
	window.document.body.onselectstart = new Function('', 'return false;');
}

ITHit.oNS.UploadInfoManager.prototype._OnGridMouseOutHandler = function(oEvent) {
	window.document.body.onselectstart = null;
}

ITHit.oNS.UploadInfoManager.prototype.StatusImage = function(sValue, iIndex) {
	
	var sOut = '';
	switch (sValue) {
		
		case 'queue':
			sOut = '<div class="queue_status"></div>';
			break;
			
		case 'upload':
			sOut = '<div class="upload_status"></div>';
			break;
			
		case 'paused':
			sOut = '<div class="pause_status"></div>';
			break;
		
		case 'error':
			sOut = '<div class="error_status"></div>';
			break;
	}
	
	return sOut;
}

ITHit.oNS.UploadInfoManager.prototype._PreloadImg = function(oController) {
	
	var s = document.createElement('DIV');
	s.className      = 'ih_style';
	s.style.position = 'absolute';
	s.style.left     = '-10000px';
	s.style.top      = '-10000px';
	s.style.disable  = 'hidden';
	
	var t = document.createElement('DIV');
	t.className = 'table';
	
	var d = document.createElement('DIV');
	d.className = 'error_status';
	
	s.appendChild(t);
	t.appendChild(d);
	
	document.body.appendChild(s);
	document.body.removeChild(s);
}

ITHit.oNS.UploadInfoManager.prototype.RightPosition = function(sValue, iIndex) {
	return ITHit.DetectBrowser.IE < 10
			? sValue
			: '<div class="dijitGrid-rightAlignContainer"><span class="dijitGrid-rightAlignText">'+ sValue +'</span></div>';
}

ITHit.oNS.UploadInfoManager.prototype.CreateSourceContainer = function(sValue, iIndex) {
	
	var sUrl   = this.GetValue(this.GetItemByRowIndex(iIndex), 'Url');
	sUrl = ITHit.Utils.HtmlEscape(sUrl);
	var sIndex = this.IdHash[sUrl] +'_2';
	return this.RightPosition('<div id="'+ sIndex +'">'+ sValue +'</div>', sIndex);
}

ITHit.oNS.UploadInfoManager.prototype.UploadProgress = function(sValue, iIndex) {
	
	var iPerc = parseInt(sValue);
	
	var sAddClass   = '';
	if (sValue.indexOf && (-1 !== sValue.indexOf('error'))) {
		sAddClass = 'error';
	}
	else if (100 <= iPerc) {
		//sAddClass = 'complite';
	}
	
	return '<div class="progress_bar"><div class="progress '+ sAddClass +'" style="width:'+ iPerc +'%"></div></div>';
}

ITHit.oNS.UploadInfoManager.prototype.FileSize = function(sValue, iIndex) {
	
	if (isNaN(sValue)) {
		return sValue;
	}
	
	if ('' === sValue) {
		return sValue;
	}
	
	var fSize = parseFloat(sValue);
	var sOutSize, sSizeType;
	
	if (fSize >= 1048576000) {
		sOutSize = String(Math.round(fSize / 1073741824 * 100) / 100);
		sSizeType = ' GB';
	}
	else if (fSize >= 1048576) {
		sOutSize = String(Math.round(fSize / 1048576 * 100) / 100);
		sSizeType = ' MB';
	}
	else if (fSize >= 1024) {
		sOutSize = String(Math.round(fSize / 1024 * 100) / 100);
		sSizeType = ' KB';
	}
	else {
		sOutSize  = fSize;
		sSizeType = ' B';
	}
	
	if (' B' !== sSizeType) {
		iPos = sOutSize.indexOf('.') + 1;
		if (iPos) {
			if (1 == (sOutSize.length - iPos)) {
				sOutSize += '0';
			}
		} else {
			sOutSize += '.00';
		}
	}
	
	return sOutSize + sSizeType;
}

ITHit.oNS.UploadInfoManager.prototype.UploadSpeed = function(sValue, iIndex) {
	var sSpeed = this.FileSize(sValue, iIndex);
	return ('' !== sSpeed) ? sSpeed +'/s' : sSpeed;
}

ITHit.oNS.UploadInfoManager.prototype.FormatTime = function(mValue, iIndex) {
	
	if (!isFinite(mValue)
		|| ('' === mValue)
	) {
		return mValue;
	}
	
	if (!mValue) {
		return '00:00:00';
	}
	
	var hours   = Math.floor(mValue / 3600);
	var minutes = Math.floor((mValue - (hours * 3600)) / 60);
	var seconds = mValue - (hours * 3600) - (minutes * 60);
	
	return this._LeadingZero(hours) +':'+ this._LeadingZero(minutes) +':'+ this._LeadingZero(seconds);
}

ITHit.oNS.UploadInfoManager.prototype._LeadingZero = function(iInt) {
	return (iInt < 10) ? '0'+ iInt : iInt;
}

ITHit.oNS.UploadInfoManager.prototype._Grid = function() {
	return this._grid;
}

ITHit.oNS.UploadInfoManager.prototype.Add = function(sUrl, sSourceName, iFileSize) {
	
	if (this.CheckUploadItem(sUrl)) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.FilePrecentInUploadList);
		return false;
	}
	
	this.IdHash[sUrl] = 'ithit_interface_upload_cell_'+ this.UniqueIndex +'_'+ this.IdCounter;
	this.IdCounter++;
	this.TimerHash[this.IdHash[sUrl]] = sUrl;
	
	var aItem = [
		sUrl,
		'queue',     // Status
		ITHit.Utils.HtmlEscape(sSourceName), // Source
		'<span style="float:right;">'+ ITHit.Utils.HtmlEscape(ITHit.Decode(sUrl)) +'</span>', // Destination
		0,           // Upload file progress object (?)
		ITHit.Phrases.AjaxFileBrowser.Upload.Queued,       // Uploaded %
		0,           // Uploaded b
		('' !== iFileSize) ? iFileSize : '', // FileSize b
		0,           // Average Upload Speed
		'',          // Time left
		'',          // Time Elapsed
		'',          // Upload start time
		'',          // Last report time
		0,           // Last uploaded bytes
        0,           // Start position
        0            // Total file size
	];
	
	this.Hash[sUrl] = this.AddItem(aItem);
	this.ErrorLog[sUrl] = [];
}

ITHit.oNS.UploadInfoManager.prototype.ResetInfo = function(sUrl) {
	
	var oItem = this.Hash[sUrl];
	if (!oItem) {
		return;
	}
	
	this.SetValue(oItem, 'Status',            'queue'); // Status
	this.SetValue(oItem, 'ProgressBar',       0);       // Upload file progress object (?)
	this.SetValue(oItem, 'UploadProgress',    '0%');    // Uploaded %
	this.SetValue(oItem, 'UploadedBytes',     0);       // Uploaded b
	this.SetValue(oItem, 'UploadSpeed',       0);       // Average Upload Speed
	this.SetValue(oItem, 'TimeLeft',          '');      // Time left
	this.SetValue(oItem, 'TimeElapsed',       '');      // Time Elapsed
	this.SetValue(oItem, 'LastUploadedBytes', 0);       // Last uploaded bytes
	this.SetValue(oItem, 'StartPosition',     0);       // Last uploaded bytes
	this.SetValue(oItem, 'TotalFileSize',     0);       // Last uploaded bytes

	this.ErrorLog[sUrl] = [];
}

ITHit.oNS.UploadInfoManager.prototype.GetStartPosition = function (sUrl) {

    var oItem = this.Hash[sUrl];
    if (!oItem) {
        return 0;
    }

    return this.GetValue(oItem, 'StartPosition');
}

ITHit.oNS.UploadInfoManager.prototype.UploadPartBegin = function (sUrl, iStartPosition, iFileSize) {
    
    var oItem = this.Hash[sUrl];
    if (!oItem) {
        return 0;
    }

    this.SetValue(oItem, 'StartPosition', iStartPosition ? iStartPosition : 0);
    this.SetValue(oItem, 'TotalFileSize', iFileSize ? iFileSize : 0);
}

ITHit.oNS.UploadInfoManager.prototype.BeginUpload = function(sUrl, iStartPosition) {
	
	var oItem = this.Hash[sUrl];
	if (!oItem) {
		return;
	}
	
	var oNow = new Date(),
	    sId  = this.IdHash[sUrl];
	
	this.SetValue(oItem, 'Status',          'upload');
//	this.SetValue(oItem, 'TimeElapsed',     '00:00:00'); // Updated by timer.
	this.SetValue(oItem, 'UploadStartTime', oNow);
	this.SetValue(oItem, 'LastReportTime',  oNow);
	
	if (iStartPosition) {
	    this.SetValue(oItem, 'StartPosition', iStartPosition);
	}

	this.ErrorLog[sUrl] = [];
	
	var sTimeLeftTimerId = sId +'_9';
	if (!this.Timers.TimerExists(sTimeLeftTimerId)) {
		var handler = ITHit.Utils.MakeScopeClosure(this, 'UpdateCellValue', [sUrl, 'TimeLeft']);
		this.Timers.AddTimer(sTimeLeftTimerId,   0, -1, handler, true);
	}
	
	var sTimeElapsedTimerId = sId +'_10';
	if (!this.Timers.TimerExists(sTimeElapsedTimerId)) {
		var handler = ITHit.Utils.MakeScopeClosure(this, 'UpdateCellValue', [sUrl, 'TimeElapsed']);
		this.Timers.AddTimer(sTimeElapsedTimerId, 0, 1, handler);
		
	} else {
		this.Timers.SetTime(sTimeElapsedTimerId, 0);
	}
}

ITHit.oNS.UploadInfoManager.prototype.CheckUploadItem = function(sUrl) {
	return this.Hash[sUrl] ? true : false;
}

ITHit.oNS.UploadInfoManager.prototype.UpdateInfo = function(oReports) {
	
	for (var sUrl in oReports) {
		
		if (this.Hash[sUrl]) {
			
		    var oProgress          = oReports[sUrl],
			    sId                = this.IdHash[sUrl],
			    oItem              = this.Hash[sUrl],
			    oLastReportTime    = this.GetValue(oItem, 'LastReportTime'),
			    oLastBytesUploaded = this.GetValue(oItem, 'LastUploadedBytes'),
                iStartPosition     = this.GetValue(oItem, 'StartPosition'),
		        iFileSize          = this.GetValue(oItem, 'TotalFileSize');

			// update
			if (oProgress instanceof this.UploadInfoLibraryClass) {
				
			    var iTotalFileSize = iFileSize ? iFileSize : oProgress.TotalContentLength + iStartPosition;
				var iUploaded, fUploadSpeed, oNow;
				oNow = new Date();
				
				if (0 !== oProgress.TotalContentLength) {
                    if (!this.DiffInfo[sUrl]) {
                        this.DiffInfo[sUrl] = [];
                    }

                    // Stored diff values
                    this.DiffInfo[sUrl].push({
                        BytesUploaded: oProgress.BytesUploaded - oLastBytesUploaded,
                        TimeUpload: (oNow - oLastReportTime) / 1000
                    });

                    // Get 5 last diff values
                    var iSliceCount = 5;
                    var aLastDiffSlice = this.DiffInfo[sUrl].slice(-1 * iSliceCount);

                    // Calculate average upload speed
                    var iSummaryBytesUploaded = 0;
                    var iSummaryTimeUpload = 0;
                    for (var i = 0, l = aLastDiffSlice.length; i < l; i++) {
                        iSummaryBytesUploaded += aLastDiffSlice[i].BytesUploaded;
                        iSummaryTimeUpload += aLastDiffSlice[i].TimeUpload;
                    }

				    iUploaded    = Math.floor((oProgress.BytesUploaded + iStartPosition) / (iTotalFileSize) * 100);
					fUploadSpeed = iSummaryBytesUploaded / iSummaryTimeUpload;
					fUploadSpeed = (fUploadSpeed > 0) ? fUploadSpeed : 0;
				} else {
					// Zero byte content length fix.
					iUploaded    = 100;
					fUploadSpeed = 0;
				}
				
				this.SetValue(oItem, 'ProgressBar',       iUploaded);                              // File upload progress.
				this.SetValue(oItem, 'UploadProgress',    iUploaded +' %');                        // Uploaded (%).
				this.SetValue(oItem, 'UploadedBytes',     oProgress.BytesUploaded + iStartPosition);                // Uploaded (b).
				this.SetValue(oItem, 'FileSize',          iTotalFileSize);           // File size.
				this.SetValue(oItem, 'UploadSpeed',       (Math.round( fUploadSpeed * 10 ) / 10)); // Average upload speed.
				this.SetValue(oItem, 'LastReportTime',    oNow);                                   // Last report time.
				this.SetValue(oItem, 'LastUploadedBytes', oProgress.BytesUploaded);                // Last bytes uploaded.
				
				// Time left.
				if (fUploadSpeed) {
				    var iTimeLeft = Math.ceil((iTotalFileSize - iStartPosition - oProgress.BytesUploaded) / fUploadSpeed);
					this.Timers.SetTime(sId +'_9', iTimeLeft);
				} else {
					this.Timers.StopTimer(sId +'_9');
					this.SetValue(oItem, 'TimeLeft', '-');
				}
				
				if (100 == iUploaded) {
					// Time left.
					this.Timers.DeleteTimer(sId +'_9');
					this.SetValue(oItem, 'TimeLeft', '00:00:00');
				}
			} else {
				
				this.Timers.StopTimer(sId +'_9');
				
				this.SetValue(oItem, 'ProgressBar',    this.GetValue(oItem, 'ProgressBar') +' error');                                      // File upload progress.
				this.SetValue(oItem, 'UploadProgress', '<span style="color: red">'+ ITHit.Phrases.AjaxFileBrowser.Upload.Error +'</span>'); // Uploaded (%).
				this.SetValue(oItem, 'UploadSpeed',    '');   // Average upload speed.
				this.SetValue(oItem, 'TimeLeft',       '');   // Time left.
				this.SetValue(oItem, 'LastReportTime', oNow); // Last report time.
				
				// Log first 3 errors.
				if (this.ErrorLog[sUrl].length < this.ReportProgressErrorCount) {
					this.ErrorLog[sUrl].push([sUrl, oProgress]);
				}
			}
		}
	}
}

ITHit.oNS.UploadInfoManager.prototype.UpdateCellValue = function(sUrl, mIndex, sElementId, iValue) {
	var oItem = this.Hash[sUrl];
	this.SetValue(oItem, String(this._MapNames[mIndex]), iValue);
}

ITHit.oNS.UploadInfoManager.prototype.UploadError = function(sUrl, sError, sErrorBody) {
    
	var oItem = this.Hash[sUrl];
	
	if (oItem) {
		this.Timers.StopTimer(this.IdHash[sUrl] +'_9');
		this.Timers.StopTimer(this.IdHash[sUrl] +'_10');

        // Remove additional upload info
		delete this.DiffInfo[sUrl];

		if (!this.ErrorLog[sUrl]) this.ErrorLog[sUrl] = [];
		this.ErrorLog[sUrl].splice(0, 0, [sUrl, sError, sErrorBody]);
		
		this.SetValue(oItem, 'Status',         'error');                             // Set error status.
		this.SetValue(oItem, 'ProgressBar',    this.GetValue(oItem, '4') +' error'); // File upload progress.
		this.SetValue(oItem, 'UploadProgress', '<span class="error_percent">'+ ITHit.Phrases.AjaxFileBrowser.Upload.Error +'</span>'); // Uploaded (%).
		this.SetValue(oItem, 'UploadSpeed',    '');                                  // Average upload speed.
		this.SetValue(oItem, 'TimeLeft',       '');                                  // Time left.
		this.SetValue(oItem, 'LastReportTime', new Date());                          // Last report time.
		
		this.Update();
	}
}

ITHit.oNS.UploadInfoManager.prototype.UploadPause = function (sUrl) {

    var oItem = this.Hash[sUrl];

    if (oItem) {
        this.Timers.StopTimer(this.IdHash[sUrl] + '_9');
        this.Timers.StopTimer(this.IdHash[sUrl] + '_10');

        // Remove additional upload info
        delete this.DiffInfo[sUrl];

        this.SetValue(oItem, 'Status', 'paused');                             // Set error status.
        //this.SetValue(oItem, 'ProgressBar', this.GetValue(oItem, '4') + ' error'); // File upload progress.
        this.SetValue(oItem, 'UploadProgress', ITHit.Phrases.AjaxFileBrowser.Upload.Paused); // Uploaded (%).
        this.SetValue(oItem, 'UploadSpeed', '');                                  // Average upload speed.
        this.SetValue(oItem, 'TimeLeft', '');                                  // Time left.
        this.SetValue(oItem, 'LastReportTime', new Date());                          // Last report time.

        this.Update();
    }
}

ITHit.oNS.UploadInfoManager.prototype.UploadResume = function (sUrl) {

    var oItem = this.Hash[sUrl];

    if (oItem) {

        this.SetValue(oItem, 'Status', 'queue');                             // Set error status.
        this.SetValue(oItem, 'UploadProgress', ITHit.Phrases.AjaxFileBrowser.Upload.Queued); // Uploaded (%).
        this.SetValue(oItem, 'UploadSpeed', '');                                  // Average upload speed.
        this.SetValue(oItem, 'TimeLeft', '');                                  // Time left.
        this.Update();
    }
}

ITHit.oNS.UploadInfoManager.prototype.UploadRetry = function (sUrl, iCount) {
    
    var oItem = this.Hash[sUrl];

    if (oItem) {
        this.SetValue(oItem, 'UploadProgress', ITHit.Phrases.AjaxFileBrowser.Upload.RetryIn.Paste(iCount)); 
        this.Update();
    }
}

ITHit.oNS.UploadInfoManager.prototype.Remove = function(sUrl) {
	
	var sId = this.IdHash[sUrl];
	if (sId) {
		this.Timers.DeleteTimer(sId + '_9');
		this.Timers.DeleteTimer(sId + '_10');
	}
	
	if (this.Hash[sUrl]) {
	    this.DeleteItem(this.Hash[sUrl]);
	}
	
	delete this.Hash[sUrl];
	delete this.TimerHash[sId];
	delete this.IdHash[sUrl];
	delete this.ErrorLog[sUrl];
	delete this.DiffInfo[sUrl];
}

ITHit.oNS.UploadInfoManager.prototype.GetStatus = function(sUrl) {
	
	var oItem = this.Hash[sUrl];
	if (!oItem) {
		return null;
	}
	
	return this.GetValue(oItem, 'Status');
}

ITHit.oNS.UploadInfoManager.prototype.GetErrors = function(sUrl) {
	return this.ErrorLog[sUrl];
}

ITHit.oNS.UploadInfoManager.prototype.GetErrorsLength = function(sUrl) {
	var aErrors = this.ErrorLog[sUrl];
	return aErrors ? aErrors.length : 0;
}

ITHit.oNS.UploadInfoManager.prototype.toString = function() {
	return this._ClassId;
}

ITHit.oNS.UploadInfoManager.prototype.GetSelectedItemsList = function() {
	
	var selected = [],
	    items = this.GetSelectedItems();
	
	for (var i = 0, l = items.length; i < l; i++) {
		selected.push(this.GetValue(items[i], 'Url'));
	}
	
	return selected;
}

ITHit.oNS.UploadInfoManager.prototype._OnRowContextMenuHandler = function(event) {
	if (!this.IsSelected(event.rowIndex)) {
		this.DeselectAll();
		this.SetSelected(event.rowIndex, true);
	}
	
	var urls = this.GetSelectedItemsList();
	
	this.DispatchEvent('OnRowContextMenu', [event, urls]);
}

ITHit.oNS.UploadInfoManager.prototype._OnRowDblClickHandler = function(event) {
	
	var data = this.GetItemByRowIndex(event.rowIndex),
	    url  = this.GetValue(data, 'Url');
	    
	this.DispatchEvent('OnRowDoubleClick', [event, url]);
}

