ITHit.oNS.LocalStorage = function () { }

ITHit.oNS.LocalStorage.GetObject = function(sKey) {

    var oResult = {};
    try {
        if (localStorage && localStorage.getItem && JSON && JSON.parse) {
            oResult = JSON.parse(localStorage.getItem(sKey)) || oResult;
        }
    }
    catch (e) {

    }
    return oResult;
}

ITHit.oNS.LocalStorage.SetObject = function (sKey, oValue) {
    
    try {
        if (localStorage && localStorage.setItem && JSON && JSON.stringify) {
            localStorage.setItem(sKey, JSON.stringify(oValue));
        }
    }
    catch (e) {

    }
}

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.ResumableUploadsManager = function (oUploadInfoManager, oUploadManager, oController) {

    this._ClassId = 'ITHit.WebDAV.Client.AjaxFileBrowser.ResumableUploadsManager_' + ITHit.WebDAV.Client.AjaxFileBrowser.ResumableUploadsManager._Counter++;

    this._UploadInfoManager = oUploadInfoManager;
    this._UploadManager = oUploadManager;
    this._Controller = oController;

    this._sLocalStorageKey = 'ITHit_ResumeUploads';
	this._IsRunCheckResumeSupported = false;
    this._ResumableUploadsSupported = (ITHit.DetectBrowser.FF >= 7 || ITHit.DetectBrowser.Safari || ITHit.DetectBrowser.Chrome || ITHit.DetectBrowser.IE >= 10 || ITHit.DetectBrowser.Edge);
}

ITHit.oNS.ResumableUploadsManager._Counter = 0;

ITHit.oNS.ResumableUploadsManager.prototype.LoadResumableUploads = function () {
    
    var oNsDefaultActions = ITHit.WebDAV.Client.AjaxFileBrowser.UploadController.DefaultActions;
    if (!this._ResumableUploadsSupported) return;

    var resumableUploads = ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.GetObject(this._sLocalStorageKey);
    var resumableUploadsNew = [];

    var sBaseUrl = this._Controller.defaultParams.Url;
    if (resumableUploads && resumableUploads.length) {
        for (var i = 0; i < resumableUploads.length; i++) {

            var _uploadInfo = resumableUploads[i];
            if (_uploadInfo) {
                var sUrl = _uploadInfo.Url;

                if (sUrl) {
                    if (sUrl.substr(0, sBaseUrl.length) == sBaseUrl) {
                        var sName = _uploadInfo.SourceName;
                        if (!sName && sUrl) {
                            var iPos = sUrl.lastIndexOf('/') + 1;
                            if (!iPos) {
                                iPos = sUrl.lastIndexOf('\\') + 1;
                            }

                            var sName = (iPos ? sUrl.substr(iPos) : sUrl);
                        }
                        
                        if (_uploadInfo.IsFolder) {
                            var oUploadFile = {
                                Url: sUrl,
                                Method: '',
                                Form: null,
                                RewriteAction: oNsDefaultActions.Rewrite,
                                FileIndex: i,
                                FileExists: false,
                                IsFolder: true,
                                BaseUrl: null
                            };
                            this._UploadManager.AddFilesToPool([oUploadFile]);

                            /*var oUploadFile = new ITHit.WebDAV.Client.AjaxFileBrowser.Upload.UploadFile();
                            oUploadFile.Url = sUrl;
                            oUploadFile.RewriteAction = oNsDefaultActions.Rewrite;
                            oUploadFile.FileIndex = i;
                            oUploadFile.FileExists = false;
                            oUploadFile.IsFolder = true;
                            this._UploadManager.AddFilesToPool([oUploadFile]);*/
                        }
                        else {
                            var oProgress = null;
                            try {
                                oProgress = this._Controller.GetUploadProgress(sUrl);
                            }
                            catch (e) { }
                            _uploadInfo.BytesUploaded = (oProgress && oProgress[0] && oProgress[0].BytesUploaded ? oProgress[0].BytesUploaded : 0);

							this.CheckResumeSupported(sUrl);
                            this._UploadInfoManager.Add(sUrl, sName, _uploadInfo.Size);
                            try {
                                this._UploadInfoManager.BeginUpload(sUrl);

                                if (oProgress && oProgress[0]) {
                                    var oReport = {};
                                    oReport[sUrl] = oProgress[0];
                                    this._UploadInfoManager.UpdateInfo(oReport);
                                }
                            }
                            catch (e) { }
                            this._UploadInfoManager.UploadPause(sUrl);//, 'broken', 'Upload was broken');
                        }
                    }
                    resumableUploadsNew.push(_uploadInfo);
                }
            }
        }
    }

    ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.SetObject(this._sLocalStorageKey, resumableUploadsNew);
    return resumableUploadsNew;
}

ITHit.oNS.ResumableUploadsManager.prototype.IsResumeSupported = function () {
	return this._ResumableUploadsSupported;
}

ITHit.oNS.ResumableUploadsManager.prototype.SetResumeSupported = function (bIsSupported) {
	this._ResumableUploadsSupported = bIsSupported;
	this._IsRunCheckResumeSupported = true;
}

ITHit.oNS.ResumableUploadsManager.prototype.CheckResumeSupported = function (sUrl) {
	/*if (this._IsRunCheckResumeSupported || !this._ResumableUploadsSupported) {
		return;
	}
	this._IsRunCheckResumeSupported = true;

	var that = this;
	this._Controller.GetSupportedFeaturesAsync(sUrl, function (oResult) {
		if (oResult.IsSuccess) {
			that._ResumableUploadsSupported = oResult.Result.ItemOptions.Features & ITHit.WebDAV.Client.Features.ResumableUpload !== 0;
		}
	});*/
}

ITHit.oNS.ResumableUploadsManager.prototype.AddUpload = function (sUrl, sSourceName, iFileSize, bIsFolder) {

    if (!this._ResumableUploadsSupported) return;
    
    var resumableUploads = ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.GetObject(this._sLocalStorageKey);

    var _uploadInfo = null;
    if (resumableUploads && resumableUploads.length) {
        for (var i = 0; i < resumableUploads.length; i++) {
            if (resumableUploads[i].Url == sUrl) {
                _uploadInfo = resumableUploads[i];
                _uploadInfo.SourceName = sSourceName;
                _uploadInfo.Size = iFileSize;
                _uploadInfo.IsFolder = bIsFolder;
                resumableUploads[i] = _uploadInfo;
                break;
            }
        }
    }
    if (!resumableUploads) {
        resumableUploads = [];
    }
    if (_uploadInfo == null) {
        _uploadInfo = { Url: sUrl, SourceName: sSourceName, Size: iFileSize, IsFolder: bIsFolder };
        resumableUploads.push(_uploadInfo);
    }

    ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.SetObject(this._sLocalStorageKey, resumableUploads);
}

ITHit.oNS.ResumableUploadsManager.prototype.RefreshBytesUploaded = function (sUrl) {
    this.RefreshBytesUploadedAsync(sUrl);
}

ITHit.oNS.ResumableUploadsManager.prototype.RefreshBytesUploadedAsync = function (sUrl, fCallback) {
    if (!this._ResumableUploadsSupported) return;
    
    var resumableUploads = ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.GetObject(this._sLocalStorageKey);

    var _uploadInfo = null;
    if (resumableUploads && resumableUploads.length) {
        for (var i = 0; i < resumableUploads.length; i++) {
            if (resumableUploads[i].Url == sUrl) {
                _uploadInfo = resumableUploads[i];

                if (typeof fCallback === 'function') {
                    var self = this;
                    var fOnResponse = function (oReport) {
                        self._RefreshBytesUploadedCallback(resumableUploads, i, _uploadInfo, oReport, fCallback)
                    };

                    this._Controller.GetUploadProgressAsync(sUrl, fOnResponse);
                }
                else {
                    var oProgress = this._Controller.GetUploadProgress(sUrl);

                    _uploadInfo.BytesUploaded = (oProgress && oProgress[0] && oProgress[0].BytesUploaded ? oProgress[0].BytesUploaded : 0);
                    resumableUploads[i] = _uploadInfo;
                }
                break;
            }
        }
    }

    if (typeof fCallback !== 'function') {
        ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.SetObject(this._sLocalStorageKey, resumableUploads);
    }

    return _uploadInfo;
}

ITHit.oNS.ResumableUploadsManager.prototype._RefreshBytesUploadedCallback = function (resumableUploads, i, _uploadInfo, oProgress, fCallback) {

    var bSuccess = true;
    var oError = null;
    if (oProgress instanceof ITHit.WebDAV.Client.AsyncResult) {
        var oResult = oProgress;
        bSuccess = oResult.IsSuccess;
        oError = oResult.Error;
        if (bSuccess) {
            oProgress = oResult.Result;
        }
    }

    if (bSuccess) {
        _uploadInfo.BytesUploaded = (oProgress && oProgress[0] && oProgress[0].BytesUploaded ? oProgress[0].BytesUploaded : 0);
        resumableUploads[i] = _uploadInfo;
        ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.SetObject(this._sLocalStorageKey, resumableUploads);
    }

    if (typeof fCallback === 'function') {
        var oUploadInfoResult = new ITHit.WebDAV.Client.AsyncResult(_uploadInfo, bSuccess, oError);
        fCallback.call(this, oUploadInfoResult, _uploadInfo.Url);
    }
}

ITHit.oNS.ResumableUploadsManager.prototype.RemoveUpload = function (sUrl) {
    
    if (!this._ResumableUploadsSupported) return;

    var resumableUploads = ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.GetObject(this._sLocalStorageKey);

    var resumableUploadsNew = [];
    if (resumableUploads && resumableUploads.length) {
        for (var i = 0; i < resumableUploads.length; i++) {
            if (resumableUploads[i].Url != sUrl) {
                resumableUploadsNew.push(resumableUploads[i]);
            }
        }
    }

    ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.SetObject(this._sLocalStorageKey, resumableUploadsNew);
}

ITHit.oNS.ResumableUploadsManager.prototype.GetUploadInfo = function (sUrl) {

    if (!this._ResumableUploadsSupported) return;

    var resumableUploads = ITHit.WebDAV.Client.AjaxFileBrowser.LocalStorage.GetObject(this._sLocalStorageKey);

    var _uploadInfo;
    if (resumableUploads && resumableUploads.length) {
        for (var i = 0; i < resumableUploads.length; i++) {
            if (resumableUploads[i].Url == sUrl) {
                _uploadInfo = resumableUploads[i];
                break;
            }
        }
    }

    return _uploadInfo;
}

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.UploadCancelManager = function(oController) {
	
    this._Controller = oController;
	this.Pool        = {};
	this.Counter     = 0;
	this.RepeatTime  = 0;
	this.RepeatCount = 1;
	this.TimerId     = null;

	this._FilesToCancel = [];
	this._NextFileIndex = 0;

	this.ChangeCancelSettings(this._Controller.CancelUploadRetryIntervalSeconds, this._Controller.CancelUploadRetryCount);
	
	this._ClassId    = 'ITHit.WebDAV.Client.AjaxFileBrowser.UploadCancelManager_'+ ITHit.WebDAV.Client.AjaxFileBrowser.UploadCancelManager._Counter++;
}

ITHit.oNS.UploadCancelManager._Counter = 0;

ITHit.oNS.UploadCancelManager.prototype.ChangeCancelSettings = function (iRepeatTime, iRepeatCount) {
	
    if ((isNaN(iRepeatTime) || (iRepeatTime < 0)) && (isNaN(iRepeatCount) || (iRepeatCount < 1))) {
		return;
	}
	
	iRepeatTime = Math.ceil(iRepeatTime);
	
	if (0 == iRepeatTime) {
		this.RepeatTime = 0;
		this._CancelTryToCancel();
		return;
	}

	if (!isNaN(iRepeatCount) && iRepeatCount > 0) {
	    this.RepeatCount = iRepeatCount;
	}

	this.RepeatTime = iRepeatTime * 1000;
	this._StartTryToCancel(10);
}

ITHit.oNS.UploadCancelManager.prototype.AddResource = function(sUrl, bFileExists) {
    
    if (this.Pool[sUrl]) return;

    this.Pool[sUrl] = { RepeatCount: this.RepeatCount, FileExists: bFileExists };
	this.Counter++;
	
	this._StartTryToCancel(10);
}

ITHit.oNS.UploadCancelManager.prototype.RemoveResource = function(sUrl) {
    
    if (typeof this.Pool[sUrl] != 'undefined') {
		delete this.Pool[sUrl];
		this.Counter--;
		
		if (!this.Counter) {
			this._CancelTryToCancel();
		}
		
		this._Controller.RefreshOnUpdate(ITHit.Utils.GetParentUrl(sUrl));
	}
	
	return true;
}

ITHit.oNS.UploadCancelManager.prototype._StartTryToCancel = function(iInitialDelay) {
    
    if (this.Counter && this.RepeatTime && !this.TimerId) {
        this.TimerId = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_CheckTryToCancel'), iInitialDelay ? iInitialDelay : this.RepeatTime);
	}
}

ITHit.oNS.UploadCancelManager.prototype._CancelTryToCancel = function() {
	
	if (this.TimerId) {
		clearTimeout(this.TimerId);
		this.TimerId = null;
	}
}

ITHit.oNS.UploadCancelManager.prototype._CheckTryToCancel = function () {
    
    this.TimerId = null;

	this._FilesToCancel = [];
	for (var sUrl in this.Pool) {

	    if (typeof this.Pool[sUrl] == 'undefined') continue;

	    this._FilesToCancel.push({ Url: sUrl, RepeatCount: this.Pool[sUrl].RepeatCount, FileExists: this.Pool[sUrl].FileExists });
	}
    
	this._NextFileIndex = 0;
	this._TryToCancelNextFile();
}

ITHit.oNS.UploadCancelManager.prototype._TryToCancelNextFile = function() {
    
    if (this._NextFileIndex >= this._FilesToCancel.length) {
        this._StartTryToCancel();
        return;
    }

    var oCancel = this._FilesToCancel[this._NextFileIndex];
    var sUrl = oCancel.Url;
    var iRepeatCount = oCancel.RepeatCount;
    var bFileExists = oCancel.FileExists;

    if (typeof this.Pool[sUrl] == 'undefined') {
        this._GotoNextFile();
    }
    else {
        var iCounter = this.Pool[sUrl].RepeatCount - 1;
        this.Pool[sUrl].RepeatCount = iCounter;

        if (iCounter < 0) {
            this.RemoveResource(sUrl);
        }
        else {
            try {
                
                var self = this;
                if (bFileExists) {
                    this._Controller.GetSupportedFeaturesAsync(sUrl, function (oResult) {
                        
                        if (oResult.IsSuccess) {
                            var oOptions = oResult.Result;
                            if ((oOptions.ItemOptions.Features & ITHit.WebDAV.Client.Features.ResumableUpload) > 0) {

                                self._Controller.CancelUploadAsync(sUrl, null, function (oResult) { self._CancelCallback(oResult, sUrl); });
                            }
                            else {
                                self._Controller.DeleteAsync(sUrl, null, function (oResult) { self._CancelCallback(oResult, sUrl); });
                            }
                        }
                    });
                }
                else {
                    this._Controller.DeleteAsync(sUrl, null, function (oResult) { self._CancelCallback(oResult, sUrl); });
                }

                this._GotoNextFile();
            }
            catch (e) { }
        }
    }
}

ITHit.oNS.UploadCancelManager.prototype._CancelCallback = function (oResult, sUrl) {
    
    if (oResult.IsSuccess || oResult.Error instanceof ITHit.WebDAV.Client.Exceptions.NotFoundException) {
        this.RemoveResource(sUrl);
    }
}

ITHit.oNS.UploadCancelManager.prototype._GotoNextFile = function() {

    this._NextFileIndex++;
    setTimeout(ITHit.Utils.MakeScopeClosure(this, '_TryToCancelNextFile'), 10);
}

ITHit.oNS.UploadCancelManager.prototype.toString = function() {
	return this._ClassId;
}

ITHit.oNS = ITHit.Declare("ITHit.WebDAV.Client.AjaxFileBrowser");

ITHit.oNS.UploadController = function(sParentFormElementId, sParentInfoElementId, sUrl, oController, iRepeatTime) {
	
	var oNsBrowser = ITHit.WebDAV.Client.AjaxFileBrowser;
	
	oNsBrowser.UploadController.baseConstructor.call(this);
	this.base = oNsBrowser.UploadController.base;
	
	this._Controller = oController;
	this._Url        = sUrl;
	this._Form;
	
	this._UploadFormToProcess;
	this._UploadRewriteFlag = oNsBrowser.UploadController.DefaultActions.Ask;
	this._NextFileIndex     = 0;
	this._PrepareFilesToUpload     = [];
	this._FilesToUpload     = [];
	this._DnDFiles          = this._Controller._DnDFilesSupported;
	this._LastUploadList    = {};
	
	this._IframeContainer = ITHit.Components.dojo.byId('ithit_interface_iframe_upload_container_'+ this._Controller.GetIndex());
	this.DefaultRoot      = ITHit.Components.dojo.byId(sParentFormElementId);
	this.MaximumUploads   = 3;
	this.IsFormDisabled   = true;
	
	// Set for IE 1 maximum upload.
	if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 10)) {
		this.MaximumUploads = 1;
	}
	
	// Create upload manager instance.
	this.UploadManager = new oNsBrowser.UploadManager(this, this._Controller, this._IframeContainer, this.MaximumUploads, iRepeatTime);
	
	// Set up event handlers.
	ITHit.Events.AddListener(this.UploadManager, 'OnCheckFileExistence', '_CheckFileExistenceHandler', this);
	ITHit.Events.AddListener(this.UploadManager, 'OnAddToPool',          '_AddToPoolHandler',          this);
	ITHit.Events.AddListener(this.UploadManager, 'OnLoadStart',          '_LoadStartHandler',          this);
	ITHit.Events.AddListener(this.UploadManager, 'OnLoad',               '_LoadHandler',               this);
	ITHit.Events.AddListener(this.UploadManager, 'OnError',              '_ErrorHandler',              this);
	ITHit.Events.AddListener(this.UploadManager, 'OnProgress',           '_ProgressHandler',           this);
	ITHit.Events.AddListener(this.UploadManager, 'OnFinish',             '_FinishHandler',             this);
	ITHit.Events.AddListener(this.UploadManager, 'OnGetProgress',        '_GetProgressHandler',        this);
	ITHit.Events.AddListener(this.UploadManager, 'OnUploadPart',         '_UploadPartHandler', this);

	ITHit.Events.AddListener(this.UploadManager, 'OnItemExists',         '_CheckFileExistenceHandler', this);
	ITHit.Events.AddListener(this.UploadManager, 'OnCancelUpload',       '_CancelUploadHandler', this);
	ITHit.Events.AddListener(this.UploadManager, 'OnAutoResumeRetryIn',  '_AutoResumeRetryInHandler', this);
	ITHit.Events.AddListener(this.UploadManager, 'OnTryToResumeError',   '_ErrorHandler', this);
	ITHit.Events.AddListener(this.UploadManager, 'OnTryToResume',        '_TryToResumeHandler', this);

	// Create upload info instance.
	this.UploadInfo = new oNsBrowser.Render.UploadInfoManager(sParentInfoElementId, oController);
	this.UploadInfo.AddListener('OnRowContextMenu', '_OnUploadInfoContextMenuHandler',        this);
	this.UploadInfo.AddListener('OnRowDoubleClick', '_OnUploadInfoRowDoubleClickMenuHandler', this);
	
	this._ResumableUploadsManager = new oNsBrowser.ResumableUploadsManager(this.UploadInfo, this.UploadManager, this._Controller);
	this._ResumableUploadsManager.LoadResumableUploads();

	this._UploadCancelManager = new ITHit.WebDAV.Client.AjaxFileBrowser.UploadCancelManager(this._Controller);

	this.CreateForm(sUrl);
}

ITHit.Extend(ITHit.oNS.UploadController, ITHit.oNS.AjaxFileBrowserBase);

ITHit.oNS.UploadController.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.UploadController';
}

ITHit.oNS.UploadController.DefaultActions = {
	'Ask':        0,
	'Rewrite':    1,
	'RewriteAll': 2,
	'Skip':       3,
	'SkipAll':    4
};

ITHit.oNS.UploadController.prototype.ChangeProgressRefreshTime = function(iRepeatTime) {
	return this.UploadManager.ChangeProgressRefreshTime(iRepeatTime);
}

ITHit.oNS.UploadController.prototype.SetResumeSupported = function (bIsSupported) {
	this._ResumableUploadsManager.SetResumeSupported(bIsSupported);
}

ITHit.oNS.UploadController.prototype.IsResumeSupported = function () {
	return this._ResumableUploadsManager.IsResumeSupported();
}

ITHit.oNS.UploadController.prototype.CreateForm = function(sUrl, oRoot, bDoNotCheckFileExistence, oSubmitButton) {
	
	var bFormDisabled    = this.IsFormDisabled,
		bExternalCreated = oRoot && (oRoot !== this.DefaultRoot);
	
	if (oRoot) {
		bFormDisabled = false;
	}
	
	if (sUrl) {
		sUrl = ITHit.DecodeHost(ITHit.WebDAV.Client.Encoder.Encode(this._Controller._Utils.GetAbsolutePath(sUrl)));
	}
	
	// Create new upload form.
    var bDoNotCreateFileNameField = (!bExternalCreated && this._DnDFiles) || ITHit.DetectBrowser.iPad || ITHit.DetectBrowser.iPhone;
	var oForm = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.UploadForm(oRoot || this.DefaultRoot, sUrl, bFormDisabled, bDoNotCheckFileExistence, (oRoot && (oRoot !== this.DefaultRoot)),  oSubmitButton, bDoNotCreateFileNameField);
	
	if (bExternalCreated) {
		oForm.ExternalCreated = true;
	}

	// Set up event handler.
	ITHit.Events.AddListener(oForm, 'OnSubmit', '_SubmitHandler', this);
	
	if (!oRoot) {
		this._Form = oForm;
	}
	
	return oForm;
}

ITHit.oNS.UploadController.prototype.DisableForm = function() {
	this.IsFormDisabled = true;
	this._Form.DisableForm();
}

ITHit.oNS.UploadController.prototype.EnableForm = function() {
	this.IsFormDisabled = false;
	this._Form.EnableForm();
}

ITHit.oNS.UploadController.prototype.SetUploadUrl = function(sUrl) {
	
	this._Url = sUrl;
	
	if (sUrl) {
		sUrl = ITHit.DecodeHost(ITHit.WebDAV.Client.Encoder.Encode(this._Controller._Utils.GetAbsolutePath(sUrl)));
	}

	this._Form.SetUploadUrl(sUrl);
}

ITHit.oNS.UploadController.prototype._SubmitHandler = function(oEvent, oForm) {
	
	if (!(oForm instanceof ITHit.WebDAV.Client.AjaxFileBrowser.UploadFormObject)
		&& !(oForm instanceof ITHit.WebDAV.Client.AjaxFileBrowser.UploadDropObjectAdapter)
	) {
		throw ITHit.Exception('Parameter expected to be UploadFormObject or UploadDropObjectAdapter instance.');
	}
	
	if (this._FilesToUpload.length) {
		return false;
	}
	
	if (false === ITHit.Events.DispatchEvent(this, 'OnSubmit', [oEvent, oForm])) {
		return false;
	}

	setTimeout(ITHit.Utils.MakeScopeClosure(this, '_AddFiles', oForm), 0);
	
	return false;
}

ITHit.oNS.UploadController.prototype._AddFiles = function(oForm){
    this._UploadFormToProcess = oForm;
    this._AddFilesToQueue();
}

ITHit.oNS.UploadController.prototype._AddFilesToQueue = function () {
    
    var iFilesLength = this._UploadFormToProcess.GetUploadFilesLength();
    // ntgr start: artf46159 : [NTGR][MR1100][WebUI] Uploading SD card/Flash drive status always gets stuck on Queued
    var totalSize = 0;

    for (var i = 0; i < iFilesLength; i++) {
        var oFileInfo = this._UploadFormToProcess.GetFileInfo(i);
        var iFileSize = oFileInfo ? (oFileInfo.size || oFileInfo.fileSize || '') : '';
        totalSize += iFileSize;
    }

    var usbDevicesInfo = window["getUsbDevicesInfo"]();
    //Free Space in Bytes
    var ideviceSpace = (usbDevicesInfo[0].freeSpace) * 1024;

    if (totalSize >= ideviceSpace) {
        ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.FileToUploadTooBig);
        return;
    }
    // ntgr end
    for (var i = 0; i < iFilesLength; i++) {
        
        var sUrl = this._UploadFormToProcess.GetDestination(i);
        var bIsFolder = false;

        var sSourceName = this._UploadFormToProcess.GetRelativePath(i);
        if (!ITHit.Utils.IsStringNullOrEmpty(sSourceName)) {
            if (sSourceName == ".") continue;

            if (/\/\.$/.test(sSourceName)) {
                sSourceName = sSourceName.substr(0, sSourceName.length - 1);
                bIsFolder = true;
            }
        }
        else {
            sSourceName = this._UploadFormToProcess.GetSourceName(i);
        }
        var oFileInfo = this._UploadFormToProcess.GetFileInfo(i);
        var iFileSize = oFileInfo ? (oFileInfo.size || oFileInfo.fileSize || '') : '';
        
        if (!bIsFolder && !this.UploadInfo.CheckUploadItem(sUrl)) {
            this.UploadInfo.Add(sUrl, sSourceName, iFileSize);
            this._PrepareFilesToUpload.push({
                Url:           sUrl,
                RelativePath:  this._UploadFormToProcess.GetRelativePath(i) || '',
                SourceName:    this._UploadFormToProcess.GetSourceName(i),
                FileSize:      this._UploadFormToProcess.GetFileSize(i),
                Method:        this._UploadFormToProcess.Method,
                Form:          this._UploadFormToProcess,
                IsFolder:      bIsFolder
            });
        }
    }

    this._UploadFilesPresent = [];
    this._FilesNotInResumeList = {};
    this._FilesResumeSizeChanged = {};
    this._UploadFileExists = false;
    this._UploadFolders = {};
    this._ProcessUploadFiles();
}

ITHit.oNS.UploadController.prototype._ClearFilesFromQueue = function () {
    
    var iFilesLength = this._UploadFormToProcess.GetUploadFilesLength();

    for (var i = 0; i < iFilesLength; i++) {

        var sUrl = this._UploadFormToProcess.GetDestination(i);
        if (!/\/\.$/.test(sUrl)) {
            this.UploadInfo.Remove(sUrl);
        }
    }
}

ITHit.oNS.UploadController.prototype.SetRewriteUploadFileAction = function(sAction) {
	
	var oNsDefaultActions = ITHit.WebDAV.Client.AjaxFileBrowser.UploadController.DefaultActions;
	
	switch(sAction) {
		
	    case 'cancel':
	        this._ClearFilesFromQueue();
			this._UploadFormToProcess.ClearFileField();
			this.Clear();
			return;
			
		case 'yes':
			this._UploadRewriteFlag = oNsDefaultActions.Rewrite;
			break;
			
		case 'no':
			this._UploadRewriteFlag = oNsDefaultActions.Skip;
			break;
			
		case 'yes_all':
			this._UploadRewriteFlag = oNsDefaultActions.RewriteAll;
			break;
			
		case 'no_all':
			this._UploadRewriteFlag = oNsDefaultActions.SkipAll;
			break;
	}
	
	setTimeout(ITHit.Utils.MakeScopeClosure(this, '_ProcessUploadFiles'), 300);
}

ITHit.oNS.UploadController.prototype.Clear = function() {
    this._UploadFormToProcess = null;
	this._UploadRewriteFlag   = ITHit.WebDAV.Client.AjaxFileBrowser.UploadController.DefaultActions.Ask;
	this._NextFileIndex       = 0;
	this._PrepareFilesToUpload       = [];
	this._FilesToUpload       = [];
	this._UploadFilesPresent  = [];
	this._FilesNotInResumeList = {};
	this._FilesResumeSizeChanged = {};
}

ITHit.oNS.UploadController.prototype._ProcessUploadFiles = function() {

	var oNsDefaultActions = ITHit.WebDAV.Client.AjaxFileBrowser.UploadController.DefaultActions,
		iAskRewriteFlag   = oNsDefaultActions.Ask,
		iFilesLength      = this._UploadFormToProcess.GetUploadFilesLength(),
		aLargeFiles       = [];
	
	if (ITHit.DetectBrowser.FF
		&& (ITHit.DetectBrowser.FF < 7)
		&& ((iFilesLength > 1)
			|| (this._UploadFormToProcess instanceof ITHit.WebDAV.Client.AjaxFileBrowser.UploadDropObjectAdapter)
		)
		&& this._UploadFormToProcess.GetFileInfo(this._NextFileIndex)
	) {
		for (var i = this._NextFileIndex; i < iFilesLength; i++) {
			
			var oFileData = this._UploadFormToProcess.GetFileInfo(i);
			if ( oFileData && ((oFileData.fileSize || oFileData.size) > 104857600) ) {
				aLargeFiles.push(oFileData.name);
			}
		}
		
		if (aLargeFiles.length) {
			ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.FirefoxLargeFilesToUpload.Paste(aLargeFiles.join('\n')));
			this.Clear();
			return false;
		}
	}
	
	for (var i = this._NextFileIndex; i < iFilesLength; i++) {

		this._NextFileIndex = i;

        var sUrl = this._PrepareFilesToUpload[0] ? this._PrepareFilesToUpload[0].Url : this._UploadFormToProcess.GetDestination(i)
        var sRelativePath = this._PrepareFilesToUpload[0] ? this._PrepareFilesToUpload[0].RelativePath : this._UploadFormToProcess.GetRelativePath(i) || '';

		if (sRelativePath == ".") continue;
		
		var sBasePath;
		var bIsFolder = /\/\.$/.test(sRelativePath);
		if (!ITHit.Utils.IsStringNullOrEmpty(sRelativePath)) {
		    sBasePath = sUrl.substr(0, sUrl.length - ITHit.WebDAV.Client.Encoder.Encode(sRelativePath).length + (bIsFolder ? 1 : 0));
		}

		// Ignore duplicate items from last upload session. Possible reason of this is browser implementation for links.
		if (this._LastUploadList[sUrl]) {
			continue;
		}
		
		var bResumableUpload = this._CheckForResumableUpload(sUrl, i);
		
		if (this.UploadManager.CheckFileExistenceInUploadPool(sUrl) && !bResumableUpload) {
		    this._UploadFilesPresent.push(ITHit.WebDAV.Client.Encoder.Decode(sUrl));
		    continue;
		    //if (!alert(ITHit.Phrases.AjaxFileBrowser.Interface.FilePrecentInUploadList)) {
			//	this.Clear();
			//	return false;
			//}
		}
		
		if (this._UploadFormToProcess.CheckFileExistence && (this._UploadRewriteFlag !== oNsDefaultActions.RewriteAll)) {
			
		    switch(this._UploadRewriteFlag) {
					
		        case oNsDefaultActions.Skip:
		            this.UploadInfo.Remove(sUrl);
		            if (1 == iFilesLength) {
		                this._UploadFormToProcess.ClearFileField();
		                this.Clear();
		                return false;
		            }
		            this._UploadRewriteFlag = iAskRewriteFlag;
		            continue;
						
		        case oNsDefaultActions.SkipAll:
		            this._ClearFilesFromQueue();
		            this._UploadFormToProcess.ClearFileField();
		            this.Clear();
		            return false;
		            continue;
					
		        case oNsDefaultActions.Ask:
		            if (!bIsFolder) {
		                var self = this;
		                this.CheckFileExistenceAsync(sUrl, function (oResult) { self._CheckFileExistenceCallback(sUrl, oResult); });
		                return;
		            }
		    }
		}


        /*var oUploadFile = new ITHit.WebDAV.Client.AjaxFileBrowser.Upload.UploadFile();
        oUploadFile.Url = sUrl;
        oUploadFile.Method = this._UploadFormToProcess.Method;
        oUploadFile.Form = this._UploadFormToProcess;
        oUploadFile.RewriteAction = this._UploadFormToProcess.CheckFileExistence ? this._UploadRewriteFlag : oNsDefaultActions.Rewrite;
        oUploadFile.FileIndex = i;
        oUploadFile.FileExists = this._UploadFileExists;
        oUploadFile.IsFolder = bIsFolder;
        oUploadFile.BaseUrl = sBasePath;
        this._FilesToUpload.push(oUploadFile);*/

		if (!bIsFolder) {
		    var parts = sRelativePath.split('/');
		    if (parts.length > 1) {
		        var path = '';
		        for (var i2 = 0; i2 < parts.length - 1; i2++) {
		            if (path !== '') path += '/';
		            path += parts[i2];

		            if (this._UploadFolders[path] == null) {
		                this._UploadFolders[path] = {};

		                this._FilesToUpload.push({
		                    Url:           sBasePath + path,
		                    Method:        this._UploadFormToProcess.Method,
		                    Form:          this._UploadFormToProcess,
		                    RewriteAction: oNsDefaultActions.Rewrite,
		                    FileIndex:     i2,
		                    FileExists:    false,
		                    IsFolder:      true,
		                    BaseUrl:       sBasePath
		                });
		            }
		        }
		    }
		}

		this._FilesToUpload.push({
			Url:           sUrl,
			Method:        this._PrepareFilesToUpload[0] ? this._PrepareFilesToUpload[0].Method : this._UploadFormToProcess.Method,
            Form:          this._PrepareFilesToUpload[0] ? this._PrepareFilesToUpload[0].Form : this._UploadFormToProcess,
			RewriteAction: this._UploadFormToProcess.CheckFileExistence ? this._UploadRewriteFlag : oNsDefaultActions.Rewrite,
			FileIndex:     i,
			FileExists:    this._UploadFileExists,
			IsFolder:      bIsFolder,
            BaseUrl:       sBasePath
		});
		this._UploadFileExists = false;
		
		this._LastUploadList[sUrl] = true;
		
		if (iAskRewriteFlag != this._UploadRewriteFlag) {
			
			switch (this._UploadRewriteFlag) {
				
				case oNsDefaultActions.Rewrite:
				case oNsDefaultActions.Skip:
				    this._UploadRewriteFlag = iAskRewriteFlag;
			}
		}

		var sSourceName = this._PrepareFilesToUpload[0] ? this._PrepareFilesToUpload[0].SourceName : this._UploadFormToProcess.GetSourceName(i);
		var iFileSize = this._PrepareFilesToUpload[0] ? this._PrepareFilesToUpload[0].FileSize : this._UploadFormToProcess.GetFileSize(i);
		this._ResumableUploadsManager.AddUpload(sUrl, sSourceName, iFileSize, bIsFolder);

        this._PrepareFilesToUpload.splice(0, 1);
	}

	if (this._UploadFilesPresent && this._UploadFilesPresent.length > 0) {
	    ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.FilesPresentInUploadList.Paste(this._UploadFilesPresent.join('\n')));
	}
	
	var aFilesNotInResumeList = [];
	for (var _url in this._FilesNotInResumeList) {
	    aFilesNotInResumeList.push(_url);
	}
	var aFilesResumeSizeChanged = [];
	for (var _url in this._FilesResumeSizeChanged) {
	    aFilesResumeSizeChanged.push(_url);
	}
	if (aFilesNotInResumeList.length > 0 || aFilesResumeSizeChanged.length > 0) {
	    ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.FilesResumeNotInListOrChanged.Paste(
            aFilesResumeSizeChanged.join('\n'), aFilesNotInResumeList.join('\n')));
	}
	
	this._LastUploadList = {};
	
	if (!this._FilesToUpload.length) {
		this.Clear();
		return false;
	}

	if (!this._UploadFormToProcess.ExternalCreated) {
		this.CreateForm(this._Url);
	}
	this._UploadFormToProcess.SetInProcess();
	this._UploadFormToProcess.Hide();
	this.UploadManager.AddFilesToPool(this._FilesToUpload);
	this.Clear();
}

ITHit.oNS.UploadController.prototype._CheckForResumableUpload = function (sUrl, iIndex) {
    
    var oNsDefaultActions = ITHit.WebDAV.Client.AjaxFileBrowser.UploadController.DefaultActions;

    var oInfo = this.GetInfo(sUrl);
    if (oInfo) {
        return false;
    }
    
    var bIsInResumeList = (this._UploadFormToProcess.GetResumeDestination(iIndex) != null);
    var bIsResumeAfterCrash = (this._UploadFormToProcess.GetResumeDestinations() != null);
    if (bIsResumeAfterCrash && !bIsInResumeList) {
        this._FilesNotInResumeList[ITHit.WebDAV.Client.Encoder.Decode(sUrl)] = 1;
    }

    var oResumableUpload = this._ResumableUploadsManager.GetUploadInfo(sUrl);
    if (oResumableUpload) {
        if (this.UploadInfo.CheckUploadItem(sUrl)) {
            this.UploadInfo.Remove(sUrl);
        }
        this._UploadFormToProcess.SetBytesUploaded(iIndex, oResumableUpload.BytesUploaded);
        this._UploadRewriteFlag = oNsDefaultActions.Rewrite;
        this._UploadFileExists = true;

        var oFile = this._UploadFormToProcess.GetFileInfo(iIndex);
        var iFileSize = oFile.fileSize || oFile.size;
        if (iFileSize != oResumableUpload.Size) {
            this._FilesResumeSizeChanged[ITHit.WebDAV.Client.Encoder.Decode(sUrl)] = 1;
            this._UploadFormToProcess.SetBytesUploaded(iIndex, 0);
        }
    }
    return (oResumableUpload != null);
}

ITHit.oNS.UploadController.prototype._CheckFileExistenceCallback = function(sUrl, oResult) {
    
    var oNsDefaultActions = ITHit.WebDAV.Client.AjaxFileBrowser.UploadController.DefaultActions;

    if (oResult.IsSuccess) {
        this._UploadFileExists = true;
        this._Controller.OpenRewriteUploadFileDialog(ITHit.WebDAV.Client.Encoder.Decode(sUrl));
    }
    else {
        this._UploadFileExists = false;
        this._UploadRewriteFlag = oNsDefaultActions.Rewrite;
        this._ProcessUploadFiles();
    }
}

ITHit.oNS.UploadController.prototype.CheckFileExistence = function(sUrl) {
	sUrl = ITHit.Decode(sUrl);
	return this._Controller.ItemExists(sUrl);
}

ITHit.oNS.UploadController.prototype.CheckFileExistenceAsync = function (sUrl, fCallback) {
    sUrl = ITHit.Decode(sUrl);
    return this._Controller.ItemExistsAsync(sUrl, fCallback);
}

ITHit.oNS.UploadController.prototype._AddToPoolHandler = function(sEvent, oUploadFile) {

    var oEventData = {
        method: oUploadFile.Method,
        action: oUploadFile.Url
    };
    this.DispatchEvent('OnBeforeUpload', oEventData);

    oUploadFile.Method = oEventData.method.toUpperCase();
    oUploadFile.Url = oEventData.action;

	// Do not insert already exists file and do not insert duplicate file with updated url
    /*if (oUploadFile.Form) {
        var oFileInfo = oUploadFile.Form.GetFileInfo(oUploadFile.FileIndex);
        var sSourceName = oUploadFile.Form.GetSourceName(oUploadFile.FileIndex);
        var iFileSize = oFileInfo ? (oFileInfo.size || oFileInfo.fileSize || '') : '';

        if (!oUploadFile.IsFolder && !this.UploadInfo.CheckUploadItem(oUploadFile.Url)) {
            this.UploadInfo.Add(sUrl, sSourceName, iFileSize);
        }
    }*/
}

ITHit.oNS.UploadController.prototype.GetSelectedItems = function() {
	return this.UploadInfo.GetSelectedItems();
}

ITHit.oNS.UploadController.prototype.GetErrors = function(sUrl) {
	return this.UploadInfo.GetErrors(sUrl);
}

ITHit.oNS.UploadController.prototype.GetErrorsLength = function(sUrl) {
	return this.UploadInfo.GetErrorsLength(sUrl);
}

ITHit.oNS.UploadController.prototype.GetStatus = function (sUrl) {
    return this.UploadInfo.GetStatus(sUrl);
}

ITHit.oNS.UploadController.prototype.GetInfo = function(sUrl) {
	return this.UploadManager.GetInfo(sUrl);
}

ITHit.oNS.UploadController.prototype._LoadStartHandler = function(sEvent, sUrl) {
    
    var uploadInfo = this._ResumableUploadsManager.GetUploadInfo(sUrl);
    this.UploadInfo.BeginUpload(sUrl, uploadInfo ? uploadInfo.BytesUploaded : 0);

	this._ResumableUploadsManager.CheckResumeSupported(sUrl);
}

ITHit.oNS.UploadController.prototype._LoadHandler = function (sEvent, sUrl, sBaseUrl) {
    if (this.UploadInfo.CheckUploadItem(sUrl)) {
        this.UploadInfo.Remove(sUrl);
    }
    this._ResumableUploadsManager.RemoveUpload(sUrl);
    
	this.DispatchEvent('OnLoad', ['OnLoad', sUrl, sBaseUrl]);
}

ITHit.oNS.UploadController.prototype._ErrorHandler = function(sEvent, sUrl, oStatus, sErrorBody) {
    
	var sErrorMessage;
	if (oStatus && oStatus.Code) {
		sErrorMessage = ITHit.Phrases.AjaxFileBrowser.StatusDescriptions[oStatus.Code] || oStatus.Description;
	}
	
	if (!sErrorMessage) {
		sErrorMessage = ITHit.Phrases.AjaxFileBrowser.Interface.FileUploadFailed;
	}
	sErrorMessage = String(sErrorMessage);
	
	this.UploadInfo.UploadError(sUrl, sErrorMessage, sErrorBody);
	this.DispatchEvent('OnError', [sUrl, sErrorMessage, sErrorBody]);
}

ITHit.oNS.UploadController.prototype._GetProgressHandler = function (sEvent, sUrl, fCallback) {
    
    var uploadInfo = this._ResumableUploadsManager.RefreshBytesUploadedAsync(sUrl, fCallback);
    if (!uploadInfo) {
        return false;
    }
    var oProgress = new ITHit.WebDAV.Client.AjaxFileBrowser.UploadProgressInfo(uploadInfo.BytesUploaded, uploadInfo.Size);
    return oProgress;
}

ITHit.oNS.UploadController.prototype._TryToResumeHandler = function (sEvent, aUploads) {

    if (!ITHit.Utils.IsArray(aUploads)) {
        aUploads = [aUploads];
    }

    for (var i = 0; i < aUploads.length; i++) {
        var uploadInfo = aUploads[i];
        var sUrl = uploadInfo.Url;

        this.UploadInfo.UploadResume(sUrl);
    }
}

ITHit.oNS.UploadController.prototype._ProgressHandler = function(sEvent, oReports) {
	this.UploadInfo.UpdateInfo(oReports);
}

ITHit.oNS.UploadController.prototype._FinishHandler = function (oResponse) {
	this.DispatchEvent('OnFinish', [oResponse]);
}

ITHit.oNS.UploadController.prototype._UploadPartHandler = function (sUrl, iBytesUploaded, iFileSize) {
    this.UploadInfo.UploadPartBegin(sUrl, iBytesUploaded, iFileSize);
}

ITHit.oNS.UploadController.prototype._CheckFileExistenceHandler = function(sEvent, sUrl) {
	return this.CheckFileExistence(sUrl);
}

ITHit.oNS.UploadController.prototype._CancelUploadHandler = function (sEvent, sUrl) {
	return this.CancelUpload(sUrl);
}

ITHit.oNS.UploadController.prototype._AutoResumeRetryInHandler = function (sEvent, sUrl, iCount) {
    this.UploadInfo.UploadRetry(sUrl, iCount);
}

// Upload info manager handlers.
ITHit.oNS.UploadController.prototype.CancelUpload = function(aUrl) {
    
	if (!ITHit.Utils.IsArray(aUrl)) {
		aUrl = [aUrl];
	}
	
	for (var i = 0, l = aUrl.length; i < l; i++) {
	    
	    var sUrl = aUrl[i];
		var sStatus = this.UploadInfo.GetStatus(sUrl);
		
		var oFile = this.UploadManager.GetInfo(sUrl);
		this.UploadManager.DeleteForm(sUrl);
		this.UploadInfo.Remove(sUrl);
		this._ResumableUploadsManager.RemoveUpload(sUrl);
		
		if (sStatus && ('queue' != sStatus)) {
		    this._UploadCancelManager.AddResource(sUrl, oFile.FileExists);
		}
	}
}

ITHit.oNS.UploadController.prototype.PauseUpload = function (aUrl) {
    
    if (!ITHit.Utils.IsArray(aUrl)) {
        aUrl = [aUrl];
    }
    
    var self = this;
    for (var i = 0, l = aUrl.length; i < l; i++) {
        var sUrl = aUrl[i];
        var sStatus = this.UploadInfo.GetStatus(sUrl);
        
        this.UploadManager.PauseUpload(sUrl);
        this.UploadInfo.UploadPause(sUrl);
        
        this._ResumableUploadsManager.RefreshBytesUploadedAsync(sUrl,
            function (uploadInfo, sUrl) {
                
                var bSuccess = true;
                if (uploadInfo instanceof ITHit.WebDAV.Client.AsyncResult) {
                    var oResult = uploadInfo;
                    bSuccess = oResult.IsSuccess;
                    if (bSuccess) {
                        uploadInfo = oResult.Result;
                    }
                }
                
                if (bSuccess) {
                    try {
                        var iStartPosition = self.UploadInfo.GetStartPosition(sUrl);
                        if (iStartPosition && uploadInfo.BytesUploaded > iStartPosition) {
                            uploadInfo.BytesUploaded -= iStartPosition;
                            uploadInfo.Size -= iStartPosition;
                        }
                        var oProgress = new ITHit.WebDAV.Client.UploadProgressInfo(sUrl, uploadInfo.BytesUploaded, uploadInfo.Size, 0);
                        var oReports = {};
                        oReports[sUrl] = oProgress;
                        self.UploadInfo.UpdateInfo(oReports);
                    }
                    catch (e) { }
                }

                self.UploadInfo.UploadPause(sUrl);
            });
    }
}

ITHit.oNS.UploadController.prototype.ResumeUpload = function (aUrl) {
    
    if (!ITHit.Utils.IsArray(aUrl)) {
        aUrl = [aUrl];
    }
    
    var noFile = false;
    var formDestinations = {};
    for (var i = 0; i < aUrl.length; i++) {
        var sUrl = aUrl[i];
        var iPos = sUrl.lastIndexOf('/') + 1;
        if (!iPos) {
            iPos = sUrl.lastIndexOf('\\') + 1;
        }	
        if (iPos) {
            sUrl = sUrl.substr(iPos);
        }
        formDestinations[sUrl] = aUrl[i];
        if (!this.GetInfo(aUrl[i])) {
            noFile = true;
        }
    }
    if (noFile) {
        this._Form.SetResumeAfterCrash(true);
        this._Form.SetResumeDestinations(formDestinations);
        this._Form.ClearFileField();
        this._Form.DoClickBrowse();
        return;
    }
    
    var self = this;
    for (var i = 0; i < aUrl.length; i++) {
        var sUrl = aUrl[i];
        
        this.UploadInfo.UploadResume(sUrl);
        this._ResumableUploadsManager.RefreshBytesUploadedAsync(sUrl,
            function (oUploadInfo, sUrl) {
                
                var bSuccess = true;
                var oError = null;
                if (oUploadInfo instanceof ITHit.WebDAV.Client.AsyncResult) {
                    var oResult = oUploadInfo;
                    if (!oResult.IsSuccess) {
                        bSuccess = oResult.IsSuccess;
                        oError = oResult.Error;
                    }
                    oUploadInfo = oResult.Result;
                    if (oError instanceof ITHit.WebDAV.Client.Exceptions.NotFoundException) {
                        bSuccess = true;
                        oUploadInfo = { Url: sUrl, BytesUploaded: 0 };
                    }
                }

                if (bSuccess) {
                    self.UploadManager.ResumeUpload([oUploadInfo]);
                }
                else {
                    self.UploadManager.ResumeUploadError(oUploadInfo.Url, oError);
                }
            });
    }
}

ITHit.oNS.UploadController.prototype.UploadFile = function (sUrl) {
	if (sUrl.indexOf('://') === -1) {
		sUrl = this._Controller.Commands.GetAbsolutePath(sUrl, true);
	}

	this._Form.IsFolderMode = false;
	this._Form.SetDestination(sUrl);
	this._Form.DoClickBrowse();
}

ITHit.oNS.UploadController.prototype.UploadFolder = function (sUrl) {
	if (sUrl.indexOf('://') === -1) {
		sUrl = this._Controller.Commands.GetAbsolutePath(sUrl, true);
	}

	if (ITHit.DetectBrowser.Chrome >= 11) {
        this._Form.IsFolderMode = true;
        this._Form.SetDestination(sUrl);
        this._Form.DoClickBrowse();
    }
    else {
        ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.FolderUploadNotAvailedInYourBrowser);
    }
}

ITHit.oNS.UploadController.prototype.Restart = function(aUrl) {
	
	if (!ITHit.Utils.IsArray(aUrl)) {
		aUrl = [aUrl];
	}
	
	for (var i = 0, l = aUrl.length; i < l; i++) {
		this.UploadInfo.ResetInfo(aUrl[i]);
		this.UploadManager.Restart(aUrl[i]);
	}
}

ITHit.oNS.UploadController.prototype._OnUploadInfoContextMenuHandler = function(event, urls) {
	this.DispatchEvent('OnContextMenu', [event, urls]);
}

ITHit.oNS.UploadController.prototype._OnUploadInfoRowDoubleClickMenuHandler = function(event, url) {
	this.DispatchEvent('OnRowDoubleClick', [event, url]);
}



ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render');

ITHit.oNS.TreeController = function(sElementId, oController) {
	
	this._ClassId    = 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.TreeController_'+ ITHit.WebDAV.Client.AjaxFileBrowser.Render.TreeController._Counter++;
	
	this._elementId  = sElementId;
	this._tree       = new ITHit.Components.YAHOO.widget.TreeView(sElementId, oController._index);
	this._controller = oController;
	this._isActive   = false;
	this._IsFetched = false;
	this._BeforeFetchTreeData = {
		SelectedNode: null,
		OpenToFolder: null
	};

	this._tree.setDynamicLoad(function(o){return function(node, onComplite){o.Load(node, onComplite);}}(this), 1);
	
	// Add root node.
	var root         = this._tree.getRoot();
	var sAbsoluteBaseUrl = ITHit.Utils.HtmlEscape(this._controller._Utils.GetAbsolutePath(this._controller._baseUrl));
	var rootNode     = new ITHit.Components.YAHOO.widget.TextNode(sAbsoluteBaseUrl, root, false);

	rootNode.data    = {
		url: ITHit.Utils.HtmlEscape(this._controller._baseUrl),
		sourceUrl: this._controller._baseUrl
	};

	this._tree.draw();

	ITHit.Events.AddListener(this._controller.Commands.FoldersCollection, 'OnRemove', function(sUrl) {
		this.RemoveNode(sUrl);
	}, this);
	ITHit.Events.AddListener(this._controller.Commands.FoldersCollection, 'OnSet', function(sUrl, aChildren) {
		var oNode = this.GetNodeByUrl(sUrl);
		if (!oNode) {
			return;
		}

		var oFiltered = this._controller._filter.Run(aChildren);
		this.AddNodes(oNode, oFiltered.Folders);
	}, this);
}

ITHit.oNS.TreeController._Counter = 0;

ITHit.oNS.TreeController.prototype.FetchTree = function(sUrl) {
	if (this._IsFetched) {
		return;
	}
	this._IsFetched = true;

	// To array util function
	var fGetValues = function(oItems) {
		var aItems = [];
		for (var key in oItems) {
			if (oItems.hasOwnProperty(key)) {
				aItems.push(oItems[key]);
			}
		}
		return aItems;
	};

	var that = this;
	this._controller.Commands.Create('LoadTreeFoldersCommand', {
		Href: sUrl,
		OnSuccess: function(oItems, oFolderItems) {
			for (var sFolderUrl in oFolderItems) {
				if (!oFolderItems.hasOwnProperty(sFolderUrl)) {
					continue;
				}

				var oFiltered = that._controller._filter.Run(fGetValues(oFolderItems[sFolderUrl]));
				that.RenderItems(oItems[sFolderUrl], oFiltered.Folders);
			}

			if (that._BeforeFetchTreeData.SelectedNode) {
				that.SetSelectedNode(that._BeforeFetchTreeData.SelectedNode);
			}

			if (that._BeforeFetchTreeData.OpenToFolder) {
				that.OpenToFolder(that._BeforeFetchTreeData.OpenToFolder);
			}
		}
	}).Execute();
}

ITHit.oNS.TreeController.prototype.GetTreeId = function() {
	return this._tree.id;
}

ITHit.oNS.TreeController.prototype.Load = function(oNode, onComplite) {
    // FIX Yahoo Tree - Do not lock tree, when click on expand icon (plus).
    // Fix for parallel loading many children
    this._tree.locked = false;

	this._controller.Commands.Create('LoadFolderCommand', {
		Href: oNode.data.sourceUrl,
		OnSuccess: function(oItem, aChildren) {
			if (oItem) {
				onComplite(oItem);
			} else {
				oNode.isLoading = false;
				oNode.updateIcon();
			}

			// Also tree will be rendered by OnSet event
		}
	}).Execute();
}

ITHit.oNS.TreeController.prototype.RenderItems = function(oItem, aItems) {
	
	var sUrl  = oItem.Href,
	    oNode = this.GetNodeByUrl(sUrl);

	if (!oNode) {
		return false;
	}
	
	// oNode.data.item = oItem;
	this.AddNodes(oNode, aItems);
	
	return true;
}

ITHit.oNS.TreeController.prototype.RenameNode = function(sUrl, sNewName) {
	
	var oNode;
	if ('' !== sUrl) {
		oNode = this.GetNodeByUrl(sUrl);
	}
	else {
		oNode = this._tree.root.children[0];
	}
	
	oNode.setUpLabel({label: sNewName});
}

ITHit.oNS.TreeController.prototype.IsOpenedItem = function(sUrl) {
	var oNode = this.GetNodeByUrl(sUrl);
	if (!oNode) {
		return false;
	}

	return oNode.dynamicLoadComplete;
}

ITHit.oNS.TreeController.prototype.GetNodeUrl = function(oNode) {
	return (oNode && oNode.data && oNode.data.sourceUrl) ? oNode.data.sourceUrl : '';
}

ITHit.oNS.TreeController.prototype.GetNodeByUrl = function(sUrl) {
	// LOOK: decodeURI(sUrl)
	return this._tree.getNodeByProperty('sourceUrl', sUrl);
}

ITHit.oNS.TreeController.prototype.NodeExists = function(sUrl) {
	return !!this.GetNodeByUrl(sUrl);
}

ITHit.oNS.TreeController.prototype.GetNodesByProperty = function(sPropName, sValue) {
	return this._tree.getNodesByProperty(sPropName, sValue);
}

ITHit.oNS.TreeController.prototype.AddNodes = function(oNode, aItems) {
	
	// Add node children elements.
	if (!oNode.dynamicLoadComplete && !oNode.children.length) {
		
		for (var i = 0, l = aItems.length; i < l; i++) {
			this.AddNode(oNode, aItems[i]);
		}
		oNode.dynamicLoadComplete = true;
		
	// Update node elements.
	} else {
		
		// Get hash
		var oHash = {};
		for (var i = 0, l = aItems.length; i < l; i++) {
			// LOOK: "decodeURI(aItems[i].Href)"
			oHash[aItems[i].Href] = true;
		}
		
		// Delete elements.
		var aChildren = oNode.children;
		for (var i = 0; i < aChildren.length; i++) {
			if (!oHash[aChildren[i].data.sourceUrl]) {
				this.RemoveNode(aChildren[i].data.sourceUrl);
				aChildren.splice(i, 1);
				i--;
			}
		}
		
		// Add new elements.
		var iIndex = 0;
		for (var i = 0, l = aItems.length; i < l; i++) {
			// LOOK: "decodeURI(aItems[i].Href)"
			if (!oNode.children[iIndex] || oNode.children[iIndex].data.sourceUrl != aItems[i].Href) {
				
				var iLen = oNode.children.length;
				var oNewNode = this.AddNode(oNode, aItems[i]);
				
				// Place node to the right place.
				if (iIndex < iLen) {
					oNewNode.insertBefore(oNode.children[iIndex]);
				}
			}
			iIndex++;
		}
	}
	
	this._tree.draw();
}

ITHit.oNS.TreeController.prototype.AddNode = function(oNode, aNode) {
	// LOOK: ", href: decodeURI(aNode.Href)"
	var node = new ITHit.Components.YAHOO.widget.TextNode({label: ITHit.Utils.HtmlEscape(aNode.DisplayName), href: aNode.Href}, oNode, false);
	// LOOK: "url: decodeURI(aNode.Href)"
	node.data = {
		url: ITHit.Utils.HtmlEscape(aNode.Href),
		sourceUrl: aNode.Href
	};
	
	return node;
}

ITHit.oNS.TreeController.prototype.RemoveChildrenByUrl = function(sUrl) {
	var oNode = this.GetNodeByUrl(sUrl);
	if (oNode) {
		this.RemoveChildren(oNode);
	}
}

ITHit.oNS.TreeController.prototype.RemoveChildren = function(oNode) {
	// Delete elements.
	var aChildren = oNode.children;
	for (var i = 0; i < aChildren.length; i++) {
		this._tree.removeNode(aChildren[i]);
		aChildren.splice(i, 1);
		i--;
	}

	oNode.collapse();

	oNode._dynLoad = true;
	oNode.dynamicLoadComplete = false;
	oNode.isLoading = false;
	oNode.updateIcon();

	this._tree.draw();
}

ITHit.oNS.TreeController.prototype.RemoveNode = function(sUrl) {
	
	var oNode = this.GetNodeByUrl(sUrl);
	if (oNode) {
		this._tree.removeNode(oNode, true);
	}
}

ITHit.oNS.TreeController.prototype.RemoveNodes = function(aUrl) {
	
	var bRefresh = aUrl.length <= 5 ? true : false;
	
	for (var i = 0, l = aUrl.length; i < l; i++) {
		var oNode = this.GetNodeByUrl(aUrl[i]);
		if (oNode) {
			this._tree.removeNode(oNode, bRefresh);
		}
	}
	
	if (!bRefresh) {
		this._tree.draw();
	}
}

ITHit.oNS.TreeController.prototype.UpdateNode = function(sUrl, sNewUrl, sNewLabel) {
	
	var oNode = this.GetNodeByUrl(sUrl);
	if (oNode) {
		oNode.setUpLabel(sNewLabel);
		oNode.data.url = ITHit.Utils.HtmlEscape(sNewUrl);
		oNode.data.sourceUrl = sNewUrl;
		try {
			oNode.getLabelEl().innerHTML = ITHit.Utils.HtmlEscape(sNewLabel);
		}
		catch (e) {}
	}
}

ITHit.oNS.TreeController.prototype.GetNodeByElement = function(oElement) {
	return this._tree.getNodeByElement(oElement);
}

ITHit.oNS.TreeController.prototype.RefreshNode = function(oNode) {

	var oEl = oNode.getToggleEl();
	oEl.className = "";
	oEl.className = /*'ygtvtn'; 'ygtvln';*/ "ygtvloading";


    var prev = this.FlushCacheOnOpenFolder; // @todo
    this._controller.FlushCacheOnOpenFolder = true;
    this._controller.OpenFolderAsync(oNode.data.sourceUrl, true, false, false, function() {
        oNode.isLoading = false;
        oNode.updateIcon();
    });
    this._controller.FlushCacheOnOpenFolder = prev;
}

ITHit.oNS.TreeController.prototype.OpenToFolder = function(sUrl) {
	if (!this._IsFetched) {
		this._BeforeFetchTreeData.OpenToFolder = sUrl;
		return;
	}

	var oNode = this.GetNodeByUrl(sUrl);
    if (oNode) {
        this.OpenToNode(oNode);
    }
}

ITHit.oNS.TreeController.prototype.OpenToNode = function(oNode) {
	if (oNode.parent) {
		this.OpenToNode(oNode.parent);
	}

	oNode.expand();
}

ITHit.oNS.TreeController.prototype.SetSelectedNode = function(sUrl) {
	if (!this._IsFetched) {
		this._BeforeFetchTreeData.SelectedNode = sUrl;
		return;
	}

	this._tree.selectNode('sourceUrl', sUrl);
}

ITHit.oNS.TreeController.prototype.DeselectNode = function() {
	var oNode = this._tree.getSelectedNode();
	if (oNode) {
		oNode.deselectNode();
	}
}

ITHit.oNS.TreeController.prototype.SetNodeOverStyle = function(oElement, bSet) {
	
	var oNode = this.GetNodeByElement(oElement),
	    oEl   = oNode.getLabelEl();
	
	oEl.className = oEl.className.replace(' hover', '');
	if (bSet) {
		oEl.className += ' hover';
	}
}

ITHit.oNS.TreeController.prototype.IsActive = function(sUrl) {
	return this._isActive;
}

ITHit.oNS.TreeController.prototype.SetActive = function(sUrl) {
	
	if (!this._isActive) {
		var oNode       = this._tree.getEl();
		oNode.className = oNode.className +' active';
		this._isActive  = true;
	}
}

ITHit.oNS.TreeController.prototype.SetInactive = function(sUrl) {
	
	if (this._isActive) {
		var oNode       = this._tree.getEl();
		oNode.className = oNode.className.replace(' active', '');
		this._isActive  = false;
	}
}

ITHit.oNS.TreeController.prototype.GetSelectedNodeUrl = function() {
	var oNode = this._tree.getSelectedNode();
	return oNode ? oNode.data.sourceUrl : null;
}

ITHit.oNS.TreeController.prototype.SetRootNode = function (sUrl) {
    var root = this._tree.getRoot();
	var sAbsoluteUrl = ITHit.Utils.HtmlEscape(this._controller._Utils.GetAbsolutePath(sUrl));
    var rootNode = new ITHit.Components.YAHOO.widget.TextNode(sAbsoluteUrl, root, false);

    rootNode.data = {
        url: ITHit.Utils.HtmlEscape(sUrl),
		sourceUrl: sUrl
    };

    this._tree.draw();

}


ITHit.oNS.TreeController.prototype.toString = function() {
	return this._ClassId;
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render');

ITHit.oNS.ViewModes = {
	Details:    'details',
	Medium:     'medium',
	Large:      'large',
	ExtraLarge: 'extralarge'
};


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView');

ITHit.oNS.GridController = function(container, tableViewModifier, imageTypes, preventImageCaching) {
	this.Grid = null;
	this.MapNames = null;
	this._RowFormatter = null;
	this._CellFormatter = null;
	this._CustomColumns = [];

	var phrasesNs            = ITHit.Phrases.AjaxFileBrowser.Grid,
		utilsNs              = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils;

	this._TableFieldsDefautlStructure = [
		{linkId: 'Icon',         name: '&nbsp;',               field: '2', width: '24px', cellStyles: {textAlign: 'center'}, noresize: 'true', formatter: ITHit.Utils.MakeScopeClosure(this, 'FormatIconsByType'), cellClasses: 'image'},
		{linkId: 'Name',         name: phrasesNs.Name,         field: '0', width: '194px', formatter: ITHit.Utils.HtmlEscape},
		{linkId: 'Size',         name: phrasesNs.Size,         field: '1', width: '64px', cellStyles: {textAlign: 'right'}, formatter: utilsNs.FormatSize},
		{linkId: 'Type',         name: phrasesNs.Type,         field: '2', width: '54px'},
		{linkId: 'DateModified', name: phrasesNs.DateModified, field: '3', width: '94px', formatter: utilsNs.FormatDate},
		{linkId: 'Folder',       name: phrasesNs.Folder,       field: '4', width: '150px', hidden: true, formatter: function(sUrl) {
			return ITHit.WebDAV.Client.HierarchyItem.GetFolderParentUri(sUrl);
		}}
	];
	this._TableDefaultMapNames = {
		'Name':         '0',
		'Size':         '1',
		'Type':         '2',
		'LastModified': '3',
		'Url':          '4',
		'Item':         '5',
		'IsLocked':     '6'
	};

	this.Container  = container;
	this.Initiated  = false;
	this.ImageTypes = imageTypes;
	
	// From old code.
	this._ThumbSize       = null;
	this._ViewMode        = ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.Details;
	this._IconSize        = 16;
	this._PreventCache    = preventImageCaching;
	this.ShowImagePreview = true;
	this.ItemsLength      = null;
	
	// Selection changed dispatch setup.
	this.DispatchTimer    = null;
	this.DispatchEventClosure          = ITHit.Utils.MakeScopeClosure(this, '_DispatchSelectionChangedEvent');
	this.SelectionChangedDispatchEvent = true;
	this.LastSelectedItems             = 0;

	this.SetTableStructure(tableViewModifier);
}

ITHit.Extend(ITHit.oNS.GridController, ITHit.oNS.Grid);

ITHit.oNS.GridController.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.GridController';
}

ITHit.oNS.GridController.prototype.SetTableStructure = function(tableViewModifier) {
	tableViewModifier = tableViewModifier || {};

	var tableFieldsStructure = this._TableFieldsDefautlStructure;
	var modifiedCode         = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.CloneGridColumnsModified(
		tableFieldsStructure,
		tableViewModifier,
		ITHit.Utils.MakeScopeClosure(this, '_UserFormatterScopeMaker')
	);

	// Store custom columns
	this._CustomColumns = [];
	if (tableViewModifier.Columns) {
		for (var i = 0, l = tableViewModifier.Columns.length; i < l; i++) {
			if (tableViewModifier.Columns[i].CustomProperty) {
				this._CustomColumns.push(tableViewModifier.Columns[i]);
			}
		}
	}

	// Generate names map
	this.MapNames = {};
	for (var name in this._TableDefaultMapNames) {
		if (this._TableDefaultMapNames.hasOwnProperty(name)) {
			this.MapNames[name] = this._TableDefaultMapNames[name];
		}
	}
	for (var i = 0, l = this._CustomColumns.length; i < l; i++) {
		/** @type {{Id: string, CustomProperty: string, Text: string, Tooltip: string, Formatter: function, Width: string, CellStyles: object, HeaderStyles: object}} */
		var oColumn = this._CustomColumns[i];

		this.MapNames[oColumn.Id] = String(i + 7);
	}

	// Correct modified code
	for (var i = 0, l = modifiedCode.length; i < l; i++) {
		// Set field param, if no exists
		if (!modifiedCode[i].field && this.MapNames[modifiedCode[i].linkId]) {
			modifiedCode[i].field = this.MapNames[modifiedCode[i].linkId];
		}
	}

	this.Layout = {
		cells: [
			modifiedCode
		],
		tableLayout: true
	};

	// Update, if rendered
	if (this.Grid) {
		this.Grid.set('structure', this.Layout);

		// Fix dojo focus manager after update structure. In original code dojo
		// set old focusView then have exceptions on click items
		this.Grid.focus.focusView = this.Grid.views.views[0];

		// Set in base
		this._Layout = this.Layout;
		this._MapNames = this.MapNames;
	}
}

ITHit.oNS.GridController.prototype.SetRowFormatter = function(fFormatter) {
	this._RowFormatter = fFormatter || null;
}

ITHit.oNS.GridController.prototype.SetCellFormatter = function(fFormatter) {
	this._CellFormatter = fFormatter || null;
}

ITHit.oNS.GridController.prototype.ToggleFolderColumn = function(bIsShow) {
	// Find folder column index
	var aCells = this.Grid.layout.cells;
	for (var i = 0, l = aCells.length; i < l; i++) {
		if (aCells[i].linkId === 'Folder') {

			// Set visibility
			this.Grid.layout.setColumnVisibility(aCells[i].index, bIsShow);
			break;
		}
	}
}

ITHit.oNS.GridController.prototype.Initiate = function() {
	
	// Initiate grid.
	if (this.Initiated) {
		return;
	}
	
	this.Grid = new ITHit.Components.dojox.grid.DataGrid({
				id: 'grid' + (new Date()).getTime()
			},
			document.createElement('div')
		);
	
	this.Grid.placeAt(this.Container);
	
	this.Grid.startup();
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.GridController.baseConstructor.call(this, this.Grid, this.Layout, this.MapNames);
	
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.GridController.base;
	
	ITHit.Components.dojo.connect(this._grid, 'onRowContextMenu',   ITHit.Utils.MakeScopeClosure(this,        '_OnRowContextMenuHandler'));
	ITHit.Components.dojo.connect(this._grid, 'onRowClick',         ITHit.Utils.MakeScopeClosure(this,        '_OnRowClickHandler'));
	ITHit.Components.dojo.connect(this._grid, 'onRowDblClick',      ITHit.Utils.MakeScopeClosure(this,        '_OnRowDblClickHandler'));

    //$(this._grid).on('')

   // $('#ihDijit_dijit_layout_ContentPane_3').

	ITHit.Components.dojo.connect(this._grid, 'onSelectionChanged', ITHit.Utils.MakeScopeClosure(this,        '_OnSelectionChangedHandler'));
	ITHit.Components.dojo.connect(this._grid, 'onMouseDown',        ITHit.Utils.MakeScopeClosure(this,        '_OnMouseDownHandler'));
	
	this.Initiated = true;
}

ITHit.oNS.GridController.prototype.IsInitiated = function() {
	return this.Initiated;
}

ITHit.oNS.GridController.prototype.Deactivate = function() {
	
	if (!this.IsInitiated()) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Grid was not initiated.');
	}
	
	this.Container.removeChild(this.Grid.domNode);
	this.RenderItems();
}

ITHit.oNS.GridController.prototype.Activate = function() {
	
	if (!this.IsInitiated()) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Grid was not initiated.');
	}
	
	this.Grid.placeAt(this.Container);
}

ITHit.oNS.GridController.prototype.RenderItems = function(items) {

	var itemsData = [];
	if (items) {
		for (var i = 0, l = items.length; i < l; i++) {
            var oItem = items[i];
		    var isLocked = items[i].Item.ActiveLocks.length > 0;
            var aItem;

			// Folder item.
			if (items[i].ResourceType == 'Folder') {
				var folder = items[i];
                aItem = [folder.DisplayName, '', folder.ResourceType, folder.LastModified, folder.Href, '', isLocked];
				
			// Resource item.
			} else {
				var resource  = items[i],
				    url      = resource.Href,
				    extension = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(url).toUpperCase();
                aItem = [resource.DisplayName, resource.ContentLength, 'File ' + extension, resource.LastModified, resource.Href, '', isLocked];
			}

            // Append custom properties
            for (var i2 = 0, l2 = this._CustomColumns.length; i2 < l2; i2++) {
                /** @type {{Id: string, CustomProperty: string, Text: string, Tooltip: string, Formatter: function, Width: string, CellStyles: object, HeaderStyles: object}} */
                var oColumn = this._CustomColumns[i2];
                aItem.push(oItem.Item.GetProperty(oColumn.CustomProperty));
            }

            itemsData.push(aItem);
		}
	}
	
	this.ItemsLength = itemsData.length;
	this.base.RenderItems.call(this, itemsData);
}

ITHit.oNS.GridController.prototype._UserFormatterScopeMaker = function(userFunction, defaultFunction) {
	return ITHit.Utils.MakeScopeClosure(this, '_UserFormatterCaller', [userFunction, defaultFunction]);
}

ITHit.oNS.GridController.prototype._UserFormatterCaller = function(userFunction, defaultFunction, value, iRowIndex, cell) {
	var url    = this.SearchDataByIndex('Url', iRowIndex);
    var result = this.DispatchEvent('OnCallUserDefinedFunction', [userFunction, url, iRowIndex]);

	// Whether result is not string or number, then call default formatter or set empty string.
	if (!ITHit.Utils.IsString(result) && !ITHit.Utils.IsNumber(result)) {
		if (defaultFunction) {
			result = defaultFunction(value, iRowIndex);
		} else {
			result = '';
		}
	}
	
	return result;
}

ITHit.oNS.GridController.prototype.SetImageTypes = function() {
	
	this.ImageCheck = this.ImageTypes;
	var aTypes      = this.ImageCheck.split('|');
	this.Images     = {};
	
	for (var i = 0, l = aTypes.length; i < l; i++) {
		if ('' === aTypes[i]) {
			continue;
		}
		
		this.Images[aTypes[i].toLowerCase()] = true;
	}
}

ITHit.oNS.GridController.prototype.FormatIconsByType = function(sValue, iIndex) {

	if (this.ImageTypes !== this.ImageCheck) {
		this.SetImageTypes();
	}
	
	var thumbStr,
	    utilsNs = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils;

	var oItem = this.GetItemByRowIndex(iIndex);
	
	// Folder icon.
	if (-1 != String(sValue).indexOf('Folder')) {
		thumbStr = utilsNs.ResourceIcons.CreateImageString(this._IconSize, 'folder');
	
	// Resource icon.
	} else {
		    var sUrl     = this.GetValue(oItem, 'Url'),
		    sExtension   = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(sUrl);
		
		if (sExtension) {
			if (!this.Images[sExtension] || !this.ShowImagePreview || (16 == this._IconSize)) {
				thumbStr = utilsNs.ResourceIcons.CreateImageString(this._IconSize, sExtension);
				
			} else {
				thumbStr = '<img class="image_preview" src="'+ this.GetValue(oItem, 'Item').Item.Href.replace(/#/g, '%23') + (this._PreventCache ? '?lm='+ this.GetValue(oItem, 'LastModified').getTime() +'&' : '?') +'width='+ this._ThumbSize +'&height='+ this._ThumbSize +'" onload="this.onload=null;ITHit.WebDAV.Client.AjaxFileBrowser.Controller.ShowThumb(this,'+ this._ThumbSize +');" />';
			}
		} else {
			thumbStr = utilsNs.ResourceIcons.CreateImageString(this._IconSize, false);
		}
	}
	var isLocked = this.GetValue(oItem, 'IsLocked');

	var lockHtml = isLocked ? '<div class="grid_lock"></div>' : '';
	return '<table class="thumb_block"><tr><td>'+ lockHtml + thumbStr + '</td></tr></table>';
}

ITHit.oNS.GridController.prototype.IsSelected = function(url) {
	var index = this.SearchIndexByData('Url', url);
	return this.base.IsSelected.call(this, index);
}

ITHit.oNS.GridController.prototype.SetSelectedByUrl = function(url) {
	var indexes = this.SearchIndexesByData('Url', url);
	return this.SetSelected(indexes, true);
}

ITHit.oNS.GridController.prototype.GetSelectedItemsList = function() {
	
	if (!this.ItemsLength) {
		return [];
	}
	
	var selected = [],
	    items = this.GetSelectedItems();

	for (var i = 0, l = items.length; i < l; i++) {
		var value = this.GetValue(items[i], 'Url');
		if (value !== null) {
			selected.push(value);
		}
	}

	return selected;
}

ITHit.oNS.GridController.prototype.GetUrlByElement = function(elem) {
	
	if (ITHit.Utils.IsUndefined(elem.gridRowIndex)) {
		return false;
	}
	
	return this.SearchDataByIndex('Url', elem.gridRowIndex);
}

ITHit.oNS.GridController.prototype.UpdateItem = function(url, newUrl, newName, lastModified) {
	
	var item = this.SearchItemByData('Url', url);

	if (item) {
		this.SetValue(item, 'Url',          newUrl);
		this.SetValue(item, 'Name',         newName);
		this.SetValue(item, 'LastModified', lastModified);
		
		this.Update();
	}
}

ITHit.oNS.GridController.prototype.DeleteItems = function(urls) {
	
	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}
	
	for (var i = 0, l = urls.length; i < l; i++) {
		var item = this.SearchItemByData('Url', urls[i]);
		if (item) {
			this.DeleteItem(item);
		}
	}
}

ITHit.oNS.GridController.prototype.SelectRowsByUrl = function(urls) {
	
	if (!this.ItemsLength) {
		return false;
	}
	
	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}
	
	var indexes = this.SearchIndexesByData('Url', urls);
	
	// Disable selection change dispatch event.
	this.SelectionChangedDispatchEvent = false;
	
	// this.DeselectAll();
	
	// Select items.
	this.SetSelected(indexes, true);
	
	// Restore dispatch event.
	this.SelectionChangedDispatchEvent = true;
}


// Event handlers.
ITHit.oNS.GridController.prototype._OnRowContextMenuHandler = function(event) {
	var url = this.SearchDataByIndex('Url', event.rowIndex);
	this.DispatchEvent('OnRowContextMenu', [event, url]);
}

ITHit.oNS.GridController.prototype._OnRowClickHandler = function(event) {
	ITHit.Events.Stop(event);
	
	var url = this.SearchDataByIndex('Url', event.rowIndex);
	this.DispatchEvent('OnRowClick', [event, url]);
}

ITHit.oNS.GridController.prototype._OnRowDblClickHandler = function(event) {
	var url = this.SearchDataByIndex('Url', event.rowIndex);
	this.DispatchEvent('OnRowDoubleClick', [event, url]);
}

ITHit.oNS.GridController.prototype._OnSelectionChangedHandler = function() {
	
	if (!this.SelectionChangedDispatchEvent) {
		return;
	}
	
	if (this.DispatchTimer) {
		clearTimeout(this.DispatchTimer);
	}
	
	this.DispatchTimer = setTimeout(this.DispatchEventClosure, 30);
}

ITHit.oNS.GridController.prototype._DispatchSelectionChangedEvent = function() {
	
	var length = this.GetSelectedCount();
	if (!length && !this.LastSelectedItems) {
		return;
	}
	this.LastSelectedItems = length;
	
	this.DispatchEvent('OnSelectionChanged');
}

ITHit.oNS.GridController.prototype._OnMouseDownHandler = function(event) {
	
	ITHit.Events.Fix(event);
	
	if (1 != event.which) return;
	
	// Check row index.
	if (event.rowIndex < 0) {
		return false;
	}
	
	this.StopEvent(event);
	
	// Get row url data.
	var url = this.SearchDataByIndex('Url', event.rowIndex);
	this.DispatchEvent('OnGridMouseDown', [event, url]);
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView');

ITHit.oNS.ThumbnailItem = function(name, contentLength, type, lastModified, url, creationDate, isLocked) {
	this.Href          = url;
	this.Name          = name;
	this.ContentLength = contentLength;
	this.Type          = type;
	this.LastModified  = lastModified;
	this.CreationDate  = creationDate;
	this.Locked        = isLocked;
	
	this.Item;
	this.Selected      = false;
	this.Rendered      = false;
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItem.baseConstructor.call(this);
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItem.base;
}

ITHit.Extend(ITHit.oNS.ThumbnailItem, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.ThumbnailItem.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItem';
}

ITHit.oNS.ThumbnailItem.prototype.GetName = function() {
	return this.Name;
}

ITHit.oNS.ThumbnailItem.prototype.GetType = function() {
	return this.Type;
}

ITHit.oNS.ThumbnailItem.prototype.GetHref = function() {
	return this.Href;
}

ITHit.oNS.ThumbnailItem.prototype.GetContentLength = function () {
    return this.ContentLength;
}

ITHit.oNS.ThumbnailItem.prototype.GetLastModified = function() {
	return this.LastModified;
}

ITHit.oNS.ThumbnailItem.prototype.GetCreationDate = function () {
    return this.CreationDate;
}

ITHit.oNS.ThumbnailItem.prototype.Render = function(icon) {
	
	if (this.Item) {
		this.Destruct();
	}
	
	var lockedBlock = '';
	if (this.Locked) {
	    lockedBlock = {
	        nodeName: 'DIV',
	        className: 'thumbnailLockContainer',
	        childNodes: [
                {
                    nodeName: 'DIV',
                    className: 'lock'
                }]
	    }
	}

	this.Item = ITHit.Utils.CreateDOMElement({
			nodeName:   'DIV',
			className:  'thumbnailItem dnd_target',
			childNodes: [
				{
					nodeName:   'DIV',
					className:  'iconContainer',
					childNodes: [{
						nodeName: 'TABLE',
						childNodes: [{
							nodeName: 'TBODY',
							childNodes: [{
								nodeName: 'TR',
								childNodes: [{
									nodeName: 'TD',
									childNodes: [
										icon
									]
								}]
							}]
						}]
					},
                    lockedBlock
					]
				},
				{
					nodeName: 'DIV',
					className:  'nameContainer',
					childNodes: [
						this.Name
					]
				}
			]
		});
	
	if (this.Selected) {
		this.SetSelected();
	}
	
	this.Rendered = true;
	
	return this.Item;
}

ITHit.oNS.ThumbnailItem.prototype.Destruct = function() {
	
	if (!this.Item) {
		return;
	}
	
	this.Item.parentNode.removeChild(this.Item);
	this.Item     = null;
	this.Rendered = false;
}

ITHit.oNS.ThumbnailItem.prototype.SetSelected = function() {
	
	if (!this.Item) {
		return false;
	}
	
	if (this.Selected && this.Rendered) {
		return 0;
	}
	
	this.Item.className += ' selected';
	this.Selected        = true;
	
	return true;
}

ITHit.oNS.ThumbnailItem.prototype.Deselect = function() {
	
	if (!this.Item) {
		return false;
	}
	
	if (!this.Selected) {
		return 0;
	}
	
	this.Item.className = this.Item.className.replace(' selected', '');
	this.Selected       = false;
	
	return true;
}

ITHit.oNS.ThumbnailItem.prototype.IsSelected = function() {
	return this.Selected;
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView');

ITHit.oNS.ThumbnailItemsList = function() {
	
	this.ItemsHash = {};
	this.Items     = [];
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItemsList.baseConstructor.call(this);
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItemsList.base;
}

ITHit.Extend(ITHit.oNS.ThumbnailItemsList, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.ThumbnailItemsList.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItemsList';
}

ITHit.oNS.ThumbnailItemsList.prototype._ItemExists = function(url) {
	return !ITHit.Utils.IsUndefined(this.ItemsHash[url]);
}

ITHit.oNS.ThumbnailItemsList.prototype._ReorderHash = function() {
	
	this.ItemsHash = {};
	for (var i = 0, l = this.Items.length; i < l; i++) {
		this.ItemsHash[this.Items[i].Href] = i;
	}
}

ITHit.oNS.ThumbnailItemsList.prototype.Add = function(data) {
	
	var itemClass = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailItem;
	
	this.DispatchEvent('OnBeforeItemsChanged', [this.Items]);
	
	this.ItemsHash = {};
	this.Items     = [];
	
	for (var i = 0, l = data.length; i < l; i++) {
		var item = data[i];
		this.ItemsHash[item.Href] = i;
		this.Items.push(new itemClass(item.DisplayName, item.ContentLength, item.ResourceType, item.LastModified, item.Href, item.CreationDate, item.Item.ActiveLocks.length > 0));
	}
	
	this.DispatchEvent('OnItemsChanged', this.Items);
}

ITHit.oNS.ThumbnailItemsList.prototype.Clear = function() {
	
	this.DispatchEvent('OnClear', [this.Items]);
	
	this.ItemsHash = {};
	this.Items     = [];
}

ITHit.oNS.ThumbnailItemsList.prototype.Delete = function(url) {
	
	if (!this._ItemExists(url)) {
		return false;
	}
	
	this.Items[this.ItemsHash[url]].Destruct();
	this.Items.splice(this.ItemsHash[url], 1);
	delete this.ItemsHash[url];
	
	this._ReorderHash();
	
	// this.DispatchEvent('OnItemDelete', url);
	
	return true;
}

ITHit.oNS.ThumbnailItemsList.prototype.Deselect = function(url) {
	
	if (!this._ItemExists(url)) {
		return false;
	}
	
	return this.Items[this.ItemsHash[url]].Deselect();
}

ITHit.oNS.ThumbnailItemsList.prototype.IsSelected = function(url) {
	
	if (!this._ItemExists(url)) {
		return false;
	}
	
	return this.Items[this.ItemsHash[url]].IsSelected();
}

ITHit.oNS.ThumbnailItemsList.prototype.GetItems = function() {
	return this.Items;
}

ITHit.oNS.ThumbnailItemsList.prototype.GetIndexByUrl = function(url) {
	return this.ItemsHash[url];
}

ITHit.oNS.ThumbnailItemsList.prototype.GetItemByUrl = function (url) {
    var index = this.GetIndexByUrl(url);
    if (index == null)
        return null;
    return this.Items[index];
}

ITHit.oNS.ThumbnailItemsList.prototype.GetItemsCount = function() {
	return this.Items.length;
}

ITHit.oNS.ThumbnailItemsList.prototype.GetUrlByIndex = function(index) {
	return (this.Items[index]) ? this.Items[index].Href : null;
}

ITHit.oNS.ThumbnailItemsList.prototype.GetUrlsRange = function(firstUrl, lastUrl) {
	
	var urls = [];
	if (this.ItemsHash[firstUrl] <= this.ItemsHash[lastUrl]) {
		for (var i = this.ItemsHash[firstUrl], l = this.ItemsHash[lastUrl]; i <= l; i++) {
			urls.push(this.Items[i].Href);
		}
	} else {
		for (var i = this.ItemsHash[firstUrl], l = this.ItemsHash[lastUrl]; i >= l; i--) {
			urls.push(this.Items[i].Href);
		}
	}
	
	return urls;
}

ITHit.oNS.ThumbnailItemsList.prototype.SetSelected = function(url) {
	
	if (!this._ItemExists(url)) {
		return false;
	}
	
	return this.Items[this.ItemsHash[url]].SetSelected();
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView');
ITHit.oNS.ThumbnailSelectionModes = {
	Single: 'Single',
	Shift:  'Shift',
	Ctrl:   'Ctrl'
};

ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView');

ITHit.oNS.ThumbnailSelection = function() {
	
	var thumbViewNs         = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView;
	
	thumbViewNs.ThumbnailSelection.baseConstructor.call(this);
	this.base               = thumbViewNs.ThumbnailSelection.base;
	
	this.DispatchEventsFlag = true;
	this.FirstSelected = null;
	this.ItemsMaxIndex      = 0;
	this.LastSelected = null;
	this.SelectionMode = null;
	this.Selected           = {};
	this.SelectedLength     = 0;
	this.ThumbsInRow        = 1;
	this.ThumbsInColumn     = 1;

	this.SetMode(thumbViewNs.ThumbnailSelectionModes.Single);

	ITHit.Events.AttachEvent(document, 'onkeydown',  ITHit.Utils.MakeScopeClosure(this, '_DetectMode'));
	ITHit.Events.AttachEvent(document, 'onkeyup', ITHit.Utils.MakeScopeClosure(this, 'ClearMode'));
}

ITHit.Extend(ITHit.oNS.ThumbnailSelection, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.ThumbnailSelection.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelection';
}

ITHit.oNS.ThumbnailSelection.prototype.SetMode = function(mode) {
	var modeNs = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelectionModes;
	
	switch(mode) {
		
		case modeNs.Single:
		case modeNs.Shift:
		case modeNs.Ctrl:
			this.SelectionMode = mode;
			break;
		
		default:
			throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Wrong thumblails selection mode has been passed ("'+ mode +'").');
	}
}

ITHit.oNS.ThumbnailSelection.prototype.ClearMode = function() {
	this.SelectionMode = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelectionModes.Single;
}

ITHit.oNS.ThumbnailSelection.prototype.ClearSelection = function() {
	
	this.Selected = {};
	if (this.SelectedLength > 0) {
		this._ClearSelection();
		
		this.DispatchEvent('OnSelectionChanged');
	}
}

ITHit.oNS.ThumbnailSelection.prototype._ClearSelection = function() {
	this.Selected       = {};
	this.SelectedLength = 0;
	this.FirstSelected  = null;
	this.LastSelected   = null;
}

ITHit.oNS.ThumbnailSelection.prototype.SetThumbnailsInRowCount = function(thumbsInRow) {
	
	if (ITHit.Utils.IsNumber(thumbsInRow) && (thumbsInRow > 0)) {
		this.ThumbsInRow = thumbsInRow;
	} else {
		this.ThumbsInRow = 1;
	}
}

ITHit.oNS.ThumbnailSelection.prototype.SetThumbnailsInColumnCount = function(thumbsInColumn) {

	if (ITHit.Utils.IsNumber(thumbsInColumn) && (thumbsInColumn > 0)) {
		this.ThumbsInColumn = thumbsInColumn;
	} else {
		this.ThumbsInColumn = 1;
	}
}

ITHit.oNS.ThumbnailSelection.prototype.IsSelected = function(url) {
	return this.Selected[url];
}

ITHit.oNS.ThumbnailSelection.prototype.InternalSetSelected = function(url) {
	var selectionModesNs = ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelectionModes;

	switch(this.SelectionMode) {
		
		case selectionModesNs.Single:
			
			this.LastSelected  = null;

			if (this.SelectedLength) {
				this.DeselectAll();
			}
			
			if (!this.Selected[url]) {
				this.FirstSelected = url;
				this.SetSelected(url);
				this.ScrollToItem(url);
			}
			break;
			
		case selectionModesNs.Shift:

			// Select first element.
			if (!this.FirstSelected) {
				this.FirstSelected = url;
				
				if (!this.Selected[url]) {
					this.SetSelected(url);
					this.ScrollToItem(url);
				}
			
			// Select all elements between first and last.
			} else if (url != this.LastSelected) {
				this.LastSelected  = url;

				this.SelectionChangedDispatchEvent = false;
				this._SelectByRange(this.FirstSelected, url);
				this.ScrollToItem(url);
				this.SelectionChangedDispatchEvent = true;
				
				this.DispatchEvent('OnSelectionChanged');
			}
			break;
			
		case selectionModesNs.Ctrl:
			this.FirstSelected                 = url;
			this.LastSelected                  = null;
			this.SelectionChangedDispatchEvent = false;

			if (this.Selected[url]) {
				this.Deselect(url);
			} else {
				this.SetSelected(url);
				this.ScrollToItem(url);
			}
			
			this.SelectionChangedDispatchEvent = true;
			this.DispatchEvent('OnSelectionChanged');
			
			if (!this.SelectedLength) {
				this.FirstSelected = null;
			}
			
			break;
	}

}

ITHit.oNS.ThumbnailSelection.prototype._SelectByRange = function(firstUrl, lastUrl) {
	
	var urls    = this.DispatchEvent('GetUrlsRange', [firstUrl, lastUrl]),
	    urlsObj = {};
	
	for (var i = 0, l = urls.length; i < l; i++) {
		urlsObj[urls[i]] = true;
	}
	
	// Deselect previously selected items.
	for (var url in this.Selected) {
		if (!this.Selected.hasOwnProperty(url)) continue;
		
		// Deselect items.
		if (!urlsObj[url]) {
			this.Deselect(url);
		
		// Already selected, then remove it from list for selection.
		} else {
			delete urlsObj[url];
		}
	}
	
	// Select unselected items.
	for (var url in urlsObj) {
		if (!urlsObj.hasOwnProperty(url)) continue;
		
		this.SetSelected(url);
	}
}

ITHit.oNS.ThumbnailSelection.prototype.SetSelected = function(urls) {

	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}

	var selectionChanged = false;
	for (var i = 0, l = urls.length; i < l; i++) {
		var url = urls[i];

		if (!this.Selected[url]) {

			var result = this.DispatchEvent('SelectItemByUrl', url);
			if (result) {
				this.Selected[url] = true;
				this.SelectedLength++;
				selectionChanged   = true;
			}
		}
	}

	if (this.DispatchEventsFlag && selectionChanged) {
		this.DispatchEvent('OnSelectionChanged');
	}
}

ITHit.oNS.ThumbnailSelection.prototype.ScrollToItem = function(sUrl) {
	var iIndex = this.DispatchEvent('OnGetIndexByUrl', sUrl);
	this.DispatchEvent('ScrollToItem', iIndex);
}

ITHit.oNS.ThumbnailSelection.prototype.Deselect = function(urls) {
	
	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}
	
	var selectionChanged = false;
	for (var i = 0, l = urls.length; i < l; i++) {
		var url = urls[i];
		
		if (this.Selected[url]) {
			
			var result = this.DispatchEvent('DeselectItemByUrl', url);
			if (result) {
				delete this.Selected[url];
				this.SelectedLength--;
				selectionChanged = true;
			}
		}
	}
	
	if (this.DispatchEventsFlag && selectionChanged) {
		this.DispatchEvent('OnSelectionChanged');
	}
}

ITHit.oNS.ThumbnailSelection.prototype.SelectAll = function() {
	
	if (this.ItemsMaxIndex && ((this.SelectedLength - 1) != this.ItemsMaxIndex)) {
		
		this.FirstSelected = this.DispatchEvent('OnGetUrlByIndex', 0);
		this.LastSelected  = this.DispatchEvent('OnGetUrlByIndex', this.ItemsMaxIndex);
		
		this.SelectionChangedDispatchEvent = false;
		this._SelectByRange(this.FirstSelected, this.LastSelected);
		this.SelectionChangedDispatchEvent = true;
		
		this.DispatchEvent('OnSelectionChanged');
	}
}

ITHit.oNS.ThumbnailSelection.prototype.DeselectAll = function() {
	
	this.FirstSelected  = null;
	this.LastSelected   = null;
	
	if (!this.SelectedLength) {
		return;
	}
	
	for (var url in this.Selected) {
		if (!this.Selected.hasOwnProperty(url)) continue;
		
		var result = this.DispatchEvent('DeselectItemByUrl', url);
		if (result) {
			
			delete this.Selected[url];
			this.SelectedLength--;
		}
	}
	
	this.Selected       = {};
	this.SelectedLength = 0;
	
	if (this.DispatchEventsFlag) {
		this.DispatchEvent('OnSelectionChanged');
	}
}

ITHit.oNS.ThumbnailSelection.prototype.GetSelectedCount = function() {
	return this.SelectedLength;
}

ITHit.oNS.ThumbnailSelection.prototype.GetSelectedUrlsList = function() {
	
	var urls = [];
	for (var url in this.Selected) {
		if (!this.Selected.hasOwnProperty(url)) continue;
		urls.push(url);
	}
	return urls;
}

ITHit.oNS.ThumbnailSelection.prototype.KeyDown = function(aItems, oEvent) {
	this._DetectMode(oEvent);

	if (!this.SelectedLength) {
		var url = this.DispatchEvent('OnGetUrlByIndex', 0);
		this.InternalSetSelected(url);
	} else {
		var currentIndex = this.DispatchEvent('OnGetIndexByUrl', this.LastSelected || this.FirstSelected),
			index        = currentIndex + this.ThumbsInRow;

		if (index > this.ItemsMaxIndex) {
			return false;
		}
		
		url          = this.DispatchEvent('OnGetUrlByIndex', index);
		this.InternalSetSelected(url);
	}
}

ITHit.oNS.ThumbnailSelection.prototype.KeyUp = function(aItems, oEvent) {
	this._DetectMode(oEvent);
	
	if (!this.SelectedLength) {
		var url = this.DispatchEvent('OnGetUrlByIndex', 0);
		this.InternalSetSelected(url);
	} else {
		
		var currentIndex = this.DispatchEvent('OnGetIndexByUrl', this.LastSelected || this.FirstSelected),
			index        = currentIndex - this.ThumbsInRow;
		
		if (index < 0) {
			// index = 0;
			return false;
		}
		
		var url          = this.DispatchEvent('OnGetUrlByIndex', index);
		this.InternalSetSelected(url);
	}
}

ITHit.oNS.ThumbnailSelection.prototype.KeyLeft = function(aItems, oEvent) {
	this._DetectMode(oEvent);
	
	if (!this.SelectedLength) {
		var url = this.DispatchEvent('OnGetUrlByIndex', 0);
		this.InternalSetSelected(url);
	} else {
		
		var currentIndex = this.DispatchEvent('OnGetIndexByUrl', this.LastSelected || this.FirstSelected),
			index        = currentIndex - 1;
		
		if (index < 0) {
			index = 0;
		}
		
		var url          = this.DispatchEvent('OnGetUrlByIndex', index);
		this.InternalSetSelected(url);
	}
}

ITHit.oNS.ThumbnailSelection.prototype.KeyRight = function(aItems, oEvent) {
	this._DetectMode(oEvent);

	if (!this.SelectedLength) {
		var url = this.DispatchEvent('OnGetUrlByIndex', 0);
		this.InternalSetSelected(url);
	} else {

		var currentIndex = this.DispatchEvent('OnGetIndexByUrl', this.LastSelected || this.FirstSelected),
			index        = currentIndex + 1;

		if (index > this.ItemsMaxIndex) {
			index = this.ItemsMaxIndex
		}

		url = this.DispatchEvent('OnGetUrlByIndex', index);
		this.InternalSetSelected(url);
	}
}

ITHit.oNS.ThumbnailSelection.prototype.KeyHome = function(aItems, oEvent) {
	this._DetectMode(oEvent);
	this.InternalSetSelected(this.DispatchEvent('OnGetUrlByIndex', 0));
}

ITHit.oNS.ThumbnailSelection.prototype.KeyEnd = function(aItems, oEvent) {
	this._DetectMode(oEvent);
	this.InternalSetSelected(this.DispatchEvent('OnGetUrlByIndex', this.ItemsMaxIndex));
}

ITHit.oNS.ThumbnailSelection.prototype.KeyPageUp = function(aItems, oEvent) {
	if (!this.SelectedLength) {
		return;
	}

	this._DetectMode(oEvent);

	var iFirstVisibleIndex = this.DispatchEvent('OnGetFirstVisibleIndex');
	var sSelectedUrl = this.LastSelected || this.FirstSelected;
	var iIndex = this.DispatchEvent('OnGetIndexByUrl', sSelectedUrl);
	var iLeftIndex = iIndex - (Math.floor(iIndex / this.ThumbsInRow) * this.ThumbsInRow);

	var url = this.DispatchEvent('OnGetUrlByIndex', iFirstVisibleIndex + iLeftIndex);
	if (url === sSelectedUrl) {
		var iFirstVisibleIndex2 = Math.max(0, iFirstVisibleIndex - (this.ThumbsInRow * this.ThumbsInColumn));
		var searchIndex = iFirstVisibleIndex !== iFirstVisibleIndex2 ? iFirstVisibleIndex2 + iLeftIndex : 0;
		url = this.DispatchEvent('OnGetUrlByIndex', searchIndex);
	}

	this.InternalSetSelected(url);
}

ITHit.oNS.ThumbnailSelection.prototype.KeyPageDown = function(aItems, oEvent) {
	if (!this.SelectedLength) {
		return;
	}

	this._DetectMode(oEvent);

	var iLastVisibleIndex = this.DispatchEvent('OnGetLastVisibleIndex');
	var sSelectedUrl = this.LastSelected || this.FirstSelected;
	var iIndex = this.DispatchEvent('OnGetIndexByUrl', sSelectedUrl);
	var iLeftIndex = iIndex - (Math.floor(iIndex / this.ThumbsInRow) * this.ThumbsInRow);
	var url = this.DispatchEvent('OnGetUrlByIndex', Math.min(this.ItemsMaxIndex, iLastVisibleIndex + iLeftIndex));

	if (url === sSelectedUrl) {
		iLastVisibleIndex += this.ThumbsInRow * this.ThumbsInColumn;
		url = this.DispatchEvent('OnGetUrlByIndex', Math.min(this.ItemsMaxIndex, iLastVisibleIndex + iLeftIndex));
	}

	this.InternalSetSelected(url);
}

ITHit.oNS.ThumbnailSelection.prototype._DetectMode = function(oEvent) {
	if (oEvent.ctrlKey || oEvent.metaKey) {
		this.SetMode(ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelectionModes.Ctrl);
	} else if (oEvent.shiftKey) {
		this.SetMode(ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelectionModes.Shift);
	} else {
		this.SetMode(ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelectionModes.Single);
	}
}

ITHit.oNS.ThumbnailSelection.prototype.SetItemsQuantity = function(quantity) {
	
	if (ITHit.Utils.IsNumber(quantity) && (quantity > 0)) {
		this.ItemsMaxIndex = quantity - 1;
	} else {
		this.ItemsMaxIndex = 0;
	}
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView');

ITHit.oNS.ThumbnailView = function(container, sizeMode, imageTypes, preventImageCaching, showPreview) {
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailView.baseConstructor.call(this);
	
	this.Container        = container;
	this.IconSize;
	this.Images           = {};
	this.ImageTypes;
	this.ItemsCount;
	this.PreventCaching   = preventImageCaching;
	this.ShowImagePreview = showPreview;
	this.SizeMode;
	this.ThumbSize;
	this.ThumbsInRow;
	this.ThumbsInColumn;
	this.ViewArea         = ITHit.Utils.CreateDOMElement({
			nodeName: 'DIV',
			width: '100%',
			height: '100%',
			margin: '0px',
			padding: '0px',
			className: 'ithitThumbnailViewContainer'
		});
		
	this.SetThumbnailsSize(sizeMode || ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.Medium);
	
	this.ViewArea.onmousedown   = ITHit.Utils.MakeScopeClosure(this, '_OnMouseDownHandler');
	this.ViewArea.onclick       = ITHit.Utils.MakeScopeClosure(this, '_OnClickHandler');
	this.ViewArea.ondblclick    = ITHit.Utils.MakeScopeClosure(this, '_OnDoubleClickHandler');
	this.ViewArea.oncontextmenu = ITHit.Utils.MakeScopeClosure(this, '_OnContextMenuHandler');
	this.ViewArea.onmouseover   = ITHit.Utils.MakeScopeClosure(this, '_OnMouseOverHandler');
	this.ViewArea.onmouseout    = ITHit.Utils.MakeScopeClosure(this, '_OnMouseOutHandler');

    // window.onkeydown            = ITHit.Utils.MakeScopeClosure(this, '_OnKeyDownHandler');
	// window.onkeyup              = ITHit.Utils.MakeScopeClosure(this, '_OnKeyUpHandler');
	this.ViewArea.onselectstart = function () { return false; }

	ITHit.Events.AttachEvent(document, 'onkeydown', ITHit.Utils.MakeScopeClosure(this, '_OnKeyDownHandler'));
	ITHit.Events.AttachEvent(document, 'onkeyup',   ITHit.Utils.MakeScopeClosure(this, '_OnKeyUpHandler'));
	
	this.Container.appendChild(this.ViewArea);
	
	this.SetImageTypes(imageTypes);
	
	this.IsActive = true;
}

ITHit.Extend(ITHit.oNS.ThumbnailView, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.ThumbnailView.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.ThumbnailView.ThumbnailView';
}

ITHit.oNS.ThumbnailView.prototype.GetViewAreaNode = function() {
	return this.ViewArea;
}

ITHit.oNS.ThumbnailView.prototype.GetIndexesByBoxArea = function(beginX, beginY, endX, endY) {
	
	var boxWidth   = this.ThumbSize.Width,
		boxHeight  = this.ThumbSize.Height;
	
	if (!boxWidth || !boxHeight) {
		return false;
	}
	
	var countInRow = this.ThumbsInRow;
	
	var beginRow = Math.ceil(beginY / boxHeight) - (((boxHeight - (beginY % boxHeight)) > this.ThumbSize.MarginBottom) ? 1 : 0),
		endRow   = Math.ceil(endY  / boxHeight)  - (((boxHeight - (endY   % boxHeight)) > this.ThumbSize.MarginTop)    ? 1 : 0),
		beginI   = Math.ceil(beginX / boxWidth)  - (((boxWidth  - (beginX % boxWidth))  > this.ThumbSize.MarginRight)  ? 1 : 0),
		endI     = Math.ceil(endX  / boxWidth)   - (((boxWidth  - (endX   % boxWidth))  > this.ThumbSize.MarginLeft)   ? 1 : 0),
		beginI   = (beginI >= 0) ? beginI : 0,
		endI     = (endI < countInRow) ? endI : (countInRow - 1),
		indexes  = [];
	
	indexIterator:
	for (var i = beginRow; i <= endRow; i++) {
		var rowIndex = i * countInRow;
		for (var j = beginI; j <= endI; j++) {
			
			// Check whether index exists.
			if ((rowIndex + j) >= this.ItemsCount) {
				break indexIterator;
			}
			
			indexes.push(rowIndex + j);
		}
	}
	
	return indexes;
}

ITHit.oNS.ThumbnailView.prototype.Deactivate = function() {
	
	if (!this.IsActive) {
		return;
	}
	
	this.Container.removeChild(this.ViewArea);
	this.IsActive = false;
}

ITHit.oNS.ThumbnailView.prototype.Activate = function(sizeMode) {
	
	if (this.IsActive) {
		return;
	}
	
	if (sizeMode) {
		this.SetThumbnailsSize(sizeMode);
	}
	
	this.Container.appendChild(this.ViewArea);
	this.IsActive = true;
}

ITHit.oNS.ThumbnailView.prototype.SetImageTypes = function(imageTypes) {
	
	var aTypes      = imageTypes.split('|');
	this.Images     = {};
	
	for (var i = 0, l = aTypes.length; i < l; i++) {
		if ('' === aTypes[i]) {
			continue;
		}
		
		this.Images[aTypes[i].toLowerCase()] = true;
	}
}

ITHit.oNS.ThumbnailView.prototype.SetShowImagePreview = function(show) {
	this.ShowImagePreview = show;
	
	var items = this.DispatchEvent('OnGetItems');
	if (items) {
		this.RenderItems(items);
	}
}

ITHit.oNS.ThumbnailView.prototype.RenderItems = function(items) {

	this.ItemsCount = items.length;
	
	if (items.length) {
		
		for (var i = 0, l = items.length; i < l; i++) {
			
			var icon      = this._GetItemIcon(items[i], i),
			    thumbnail = items[i].Render(icon);
			thumbnail.idx = i;
			
			this.ViewArea.appendChild(thumbnail);
		}
		
		if (!this.ThumbSize) {
			var thumbStyle   = ITHit.Utils.GetComputedStyle(thumbnail),
			    marginTop    = parseInt(thumbStyle.marginTop),
			    marginRight  = parseInt(thumbStyle.marginRight),
			    marginBottom = parseInt(thumbStyle.marginBottom),
			    marginLeft   = parseInt(thumbStyle.marginLeft);
			
			this.ThumbSize = {
				MarginTop:    marginTop,
				MarginRight:  marginRight,
				MarginBottom: marginBottom,
				MarginLeft:   marginLeft,
				Width:  thumbnail.offsetWidth  + marginLeft + marginRight,
				Height: thumbnail.offsetHeight + marginTop  + marginBottom
			};
		}
		
		if (!this.ThumbsInRow) {
			this.CalculateThumbsInRowCount();
		}
	}
}

ITHit.oNS.ThumbnailView.prototype._GetItemIcon = function(item, iIndex) {
	
	var utilsNs   = ITHit.Utils,
	    extension = 'folder',
	    icon      = this.DispatchEvent('OnGetIcon', item.GetHref(), iIndex),
	    itemUrl      = item.GetHref();
	
	if (utilsNs.IsString(icon) || utilsNs.IsNumber(icon)) {
		
		var span = utilsNs.CreateDOMElement({
				nodeName:   'SPAN'
			});
		span.innerHTML = ITHit.Utils.HtmlEscape(icon);
		
		return span.firstChild;
	}

	// Create item icon.
	if ('Folder' != item.GetType()) {

        extension = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(itemUrl);
		
		// Icon is image.
		if (this.ShowImagePreview && this.Images[extension.toLowerCase()]) {
			var url = this.DispatchEvent('OnGetAbsolutePath', item.GetHref());
			icon    = utilsNs.CreateDOMElement({
				nodeName:   'IMG',
				className:  'image_preview',
				onload:     new Function('this.onload=this.onerror=null; ITHit.WebDAV.Client.AjaxFileBrowser.Controller.ShowThumb(this, '+ this.ImageSize +');'),
				onerror:    new Function('this.onload=this.onerror=null;'),
				src:        (url.replace(/#/g, '%23') + (this.PreventCaching ? '?lm='+ item.GetLastModified().getTime() +'&' : '?') +'width='+ this.ImageSize +'&height='+ this.ImageSize)
			});
		}
	}
	
	// Get default icon whether was not created already.
	if (!icon) {
		icon = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.ResourceIcons.CreateImage(this.IconSize, extension);
	}

	return icon;
}

ITHit.oNS.ThumbnailView.prototype.SetThumbnailsSize = function(mode) {
	
	if (mode == this.SizeMode) {
		return;
	}
	
	var cls;
	switch (mode) {
		case ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.Medium:
			cls            = 'medium';
			this.IconSize  = 32;
			this.ImageSize = 42;
			break;

		case ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.Large:
			cls            = 'large';
			this.IconSize  = 72;
			this.ImageSize = 85;
			break;

		case ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.ExtraLarge:
			cls            = 'elarge';
			this.IconSize  = 256;
			this.ImageSize = 232;
			break;
		
		default:
			throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Unexpected view mode has been passed "'+ mode +'".');
	}
	
	this.ViewArea.className = this.ViewArea.className.replace(/( medium| large| elarge)/, '') +' '+ cls;
	this.SizeMode           = mode;
	
	// Clear thumbnail size.
	this.ThumbSize          = null;
	this.ThumbsInRow        = null;
	
	var items = this.DispatchEvent('OnGetItems');
	if (items) {
		this.RenderItems(items);
	}
}

ITHit.oNS.ThumbnailView.prototype.DestructItems = function(items) {
	
	for (var i = 0, l = items.length; i < l; i++) {
		items[i].Destruct();
	}
}

ITHit.oNS.ThumbnailView.prototype.CalculateThumbsInRowCount = function() {
	
	this.ThumbsInRow = null;
	this.ThumbsInColumn = null;

	if (this.ThumbSize) {
		this.ThumbsInRow = Math.floor(this.ViewArea.clientWidth / this.ThumbSize.Width);
		this.ThumbsInColumn = Math.floor(this.ViewArea.clientHeight / this.ThumbSize.Height);

		this.DispatchEvent('OnThumbnailsInRowChanged', this.ThumbsInRow);
		this.DispatchEvent('OnThumbnailsInColumnChanged', this.ThumbsInColumn);
	}
}

/**
 * Scroll list container to fully view item
 * @param {number} iIndex
 */
ITHit.oNS.ThumbnailView.prototype.ScrollToItem = function(iIndex) {
	var oListNode = this.Container.lastChild;
	var oItemNode = oListNode.childNodes[iIndex];
	var oContainerPosition = ITHit.Components.dojo.position(this.Container);
	var oItemPosition = ITHit.Components.dojo.position(oItemNode);

	var deltaBottom = (oContainerPosition.y + oContainerPosition.h) - (oItemPosition.y + oItemPosition.h);
	var deltaTop = oItemPosition.y - oContainerPosition.y;

	if (deltaBottom < 0) {
		oListNode.scrollTop += -1 * deltaBottom;
	} else if (deltaTop < 0) {
		oListNode.scrollTop += deltaTop;
	}
}

/**
 *
 * @returns {number}
 */
ITHit.oNS.ThumbnailView.prototype.GetFirstVisibleIndex = function() {
	return this._FindIndexByFilterPosition(function(oItemPosition, oContainerPosition) {
		return oItemPosition.y - oContainerPosition.y >= 0;
	});
}

/**
 *
 * @returns {number}
 */
ITHit.oNS.ThumbnailView.prototype.GetLastVisibleIndex = function() {
	var iIndex = -1;
	this._FindIndexByFilterPosition(function(oItemPosition, oContainerPosition) {
		if ((oContainerPosition.y + oContainerPosition.h) - (oItemPosition.y + oItemPosition.h) < 0) {
			return true;
		}
		iIndex++;
	});

	return this.ThumbsInRow * Math.max(0, iIndex);
}

ITHit.oNS.ThumbnailView.prototype._FindIndexByFilterPosition = function(fFilter) {
	var oListNode = this.Container.lastChild;
	var oContainerPosition = ITHit.Components.dojo.position(this.Container);
	var i = 0;

	while (true) {
		var iIndex = this.ThumbsInRow * i++;
		var oItemNode = oListNode.childNodes[iIndex]
		if (!oItemNode) {
			break;
		}

		var oItemPosition = ITHit.Components.dojo.position(oItemNode);
		if (fFilter.call(this, oItemPosition, oContainerPosition) === true) {
			return iIndex;
		}
	}

	return -1;
}

ITHit.oNS.ThumbnailView.prototype._FindTargetNode = function(targetNode) {
	
	var undefinedFunc = ITHit.Utils.IsUndefined;
	
	while (targetNode && (targetNode != this.Container)) {
		
		// Whether thumbnails index found, then return element. 
		if (!undefinedFunc(targetNode.idx)) {
			return targetNode;
		}
		
		targetNode = targetNode.parentNode;
	}
	
	return null;
}

// Events.
ITHit.oNS.ThumbnailView.prototype._OnMouseDownHandler = function(event) {

	event = ITHit.Events.Fix(event);
	
	if (1 != event.which) return;
	
	var url = this._GetTargetNodeUrl(event, true);
	if (!url) {
		return;
	}
	
	this.DispatchEvent('OnMouseDown', [event, url]);
}

ITHit.oNS.ThumbnailView.prototype._OnClickHandler = function(event) {
	
	event = ITHit.Events.Fix(event);
	
	var url = this._GetTargetNodeUrl(event);
	if (!url) {
		return;
	}
	
	this.DispatchEvent('OnItemClick', [event, url]);
	
	return false;
}

ITHit.oNS.ThumbnailView.prototype._OnDoubleClickHandler = function(event) {
	
	event = ITHit.Events.Fix(event);
	
	var url = this._GetTargetNodeUrl(event);
	if (!url) {
		return;
	}
	
	this.DispatchEvent('OnDoubleClick', [event, url]);
}

ITHit.oNS.ThumbnailView.prototype._OnContextMenuHandler = function(event) {

	event = ITHit.Events.Fix(event);
	
	var url = this._GetTargetNodeUrl(event);
	if (!url) {
		return;
	}
	
	this.DispatchEvent('OnContextMenu', [event, url]);
}

ITHit.oNS.ThumbnailView.prototype._OnMouseOverHandler = function (event) {

    event = ITHit.Events.Fix(event);

    var url = this._GetTargetNodeUrl(event);
    if (!url) {
        return;
    }

    this.DispatchEvent('OnMouseOver', [event, url]);
}

ITHit.oNS.ThumbnailView.prototype._OnMouseOutHandler = function (event) {

    event = ITHit.Events.Fix(event);

    var url = this._GetTargetNodeUrl(event);
    if (!url) {
        return;
    }

    this.DispatchEvent('OnMouseOut', [event, url]);
}

ITHit.oNS.ThumbnailView.prototype._GetTargetNodeUrl = function(event) {
	
	var targetElement = this._FindTargetNode(event.target);
	if (null === targetElement) {
		return;
	}
	
	ITHit.Events.Stop(event);
	
	return this.DispatchEvent('OnGetUrlByIndex', [targetElement.idx]);
}

ITHit.oNS.ThumbnailView.prototype.GetUrlByElement = function(elem) {
	
	var targetElement = this._FindTargetNode(elem);
	if (null === targetElement) {
		return;
	}
	
	return this.DispatchEvent('OnGetUrlByIndex', [targetElement.idx]);
}

ITHit.oNS.ThumbnailView.prototype._OnKeyDownHandler = function(event) {
	event = event || window.event;
	return this.DispatchEvent('OnKeyDown', event);
}

ITHit.oNS.ThumbnailView.prototype._OnKeyUpHandler = function(event) {
	event = event || window.event;
	return this.DispatchEvent('OnKeyUp', event);
}

