ITHit.oNS.ThumbnailController.prototype.Initiate = function(viewMode) {
	
	// Initiate grid.
	if (this.Initiated) {
		return;
	}
	
	this.DispatchTimer;
	this.DispatchEventClosure          = ITHit.Utils.MakeScopeClosure(this, '_DispatchSelectionChangedEvent');
	this.SelectionChangedDispatchEvent = true;
	
	this.Selection = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailSelection();
	this.Selection.AddListener('DeselectItemByUrl',      'Deselect',                   this.Items);
	this.Selection.AddListener('GetUrlsRange',           'GetUrlsRange',               this.Items);
	this.Selection.AddListener('OnGetIndexByUrl',        'GetIndexByUrl',              this.Items);
	this.Selection.AddListener('OnGetUrlByIndex',        'GetUrlByIndex',              this.Items);
	this.Selection.AddListener('OnSelectionChanged',     '_OnSelectionChangedHandler', this);
	this.Selection.AddListener('SelectItemByUrl',        'SetSelected',                this.Items);

	this.View = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailView(this.Container, viewMode, this.InitParams.ImageTypes, this.InitParams.PreventImageCaching, this.InitParams.ShowImagePreview);
	this.View.AddListener('OnContextMenu',               '_OnContextMenuHandler',      this);
	this.View.AddListener('OnMouseOver',                 '_OnMouseOverHandler',        this);
	this.View.AddListener('OnMouseOut',                  '_OnMouseOutHandler',         this);
	this.Selection.AddListener('ScrollToItem',           'ScrollToItem',               this.View);
	this.Selection.AddListener('OnGetFirstVisibleIndex', 'GetFirstVisibleIndex',       this.View);
	this.Selection.AddListener('OnGetLastVisibleIndex',  'GetLastVisibleIndex',        this.View);

	this.View.AddListener('OnDoubleClick',            '_OnDoubleClickHandler',      this);
	this.View.AddListener('OnGetItems',               'GetItems',                   this.Items);
	this.View.AddListener('OnGetAbsolutePath',        '_OnGetAbsolutePathHandler',  this);
	this.View.AddListener('OnGetIcon',                '_OnGetIconHandler',          this);
	this.View.AddListener('OnGetUrlByIndex',          'GetUrlByIndex',              this.Items);
	this.View.AddListener('OnItemClick',              '_OnItemClickHandler',        this);
	this.View.AddListener('OnMouseDown',              '_OnMouseDownHandler',        this);
	this.View.AddListener('OnThumbnailsInRowChanged', 'SetThumbnailsInRowCount',    this.Selection);
	this.View.AddListener('OnThumbnailsInColumnChanged', 'SetThumbnailsInColumnCount',    this.Selection);

	this.Items.AddListener('OnBeforeItemsChanged',    'ClearSelection',             this.Selection);
	this.Items.AddListener('OnBeforeItemsChanged',    'DestructItems',              this.View);
	this.Items.AddListener('OnClear',                 '_ClearSelection',            this.Selection);
	this.Items.AddListener('OnClear',                 'DestructItems',              this.View);
	
	this.Initiated = true;
	
	delete this.InitParams;
}

