ITHit.oNS.ThumbnailController.prototype.DeleteItems = function(urls) {
	
	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}
	
	for (var i = 0, l = urls.length; i < l; i++) {
		var url = urls[i];
		this.Selection.Deselect(url);
		this.Items.Delete(url);
	}
	
	var items = this.Items.GetItems();
	
	this.View.RenderItems(items);
	this.Selection.SetItemsQuantity(items.length);
}

