ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView');

ITHit.oNS.DataViewAdapter = function(gridPlaceholderId, gridViewModification, imageTypes, preventImageCaching, showPreview, contextHelp) {
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.DataViewAdapter.baseConstructor.call(this);
	
	// Get modifiers for thumbnails view.
	var thumbModifier = {};
	if (ITHit.Utils.IsObjectStrict(gridViewModification) && ITHit.Utils.IsArray(gridViewModification.Columns)) {
		var cols = gridViewModification.Columns;
		for (var i = 0, l = cols.length; i < l; i++) {
			if (('Icon' == cols[i].Id) && (cols[i].Formatter)) {
				thumbModifier.IconsHandler = cols[i].Formatter;
			}
		}
	}
	
	this.GridPlaceholder     = document.getElementById(gridPlaceholderId);
	this.Views               = {
		Grid:       new ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.GridController(this.GridPlaceholder, gridViewModification, imageTypes, preventImageCaching),
		Thumbnails: new ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.ThumbnailView.ThumbnailController(this.GridPlaceholder, thumbModifier, imageTypes, preventImageCaching, showPreview, contextHelp)
	};
	
	this._View;
	this._ViewMode;
	this.CurrentView;
	this.Items;
	this.PreventImageCaching = preventImageCaching;

    this.SetViewMode(ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.Details);
}

ITHit.Extend(ITHit.oNS.DataViewAdapter, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.DataViewAdapter.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.DataViewAdapter';
}

ITHit.oNS.DataViewAdapter.prototype.SetViewMode = function(mode) {
	if (this._ViewMode == mode) {
		return;
	}
	
	var viewModesNs = ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes,
	    view;

	switch(mode) {
		
		// Grid view mode.
		case viewModesNs.Details:
			view = 'Grid';
			break;
		
		// Thumbnails view mode.
		case viewModesNs.Medium:
		case viewModesNs.Large:
		case viewModesNs.ExtraLarge:
			view = 'Thumbnails';
			break;
		
		// Wrong view mode.
		default:
			throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.ThumbnailItemsList(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongViewModeIndex);
	}
	
	// Whether view mode was changed.
	if (this._View != view) {
		
		var selectedItems;
		
		// Whether current view exists.
		if (this.CurrentView) {
			
			selectedItems = this.CurrentView.GetSelectedItemsList();
			
			// Remove event listeners for current view.
			this.CurrentView.RemoveListener('OnGetAbsolutePath',         '_OnGetAbsolutePathHandler',         this);
			this.CurrentView.RemoveListener('OnGridMouseDown',           '_OnGridMouseDownHandler',           this);
			this.CurrentView.RemoveListener('OnRowContextMenu',          '_OnRowContextMenuHandler',          this);
			this.CurrentView.RemoveListener('OnRowClick',                '_OnRowClickHandler',                this);
			this.CurrentView.RemoveListener('OnRowDoubleClick',          '_OnRowDoubleClickHandler',          this);
			this.CurrentView.RemoveListener('OnSelectionChanged',        '_OnSelectionChangedHandler',        this);
			this.CurrentView.RemoveListener('OnCallUserDefinedFunction', '_OnCallUserDefinedFunctionHandler', this);
			
			// Deactivate current view.
			this.CurrentView.Deactivate();
		}
		
		// Assign new view mode.
		this._View       = view;
		this._ViewMode   = mode;
		this.CurrentView = this.Views[view];
		
		// Initiate or activate new view mode.
		if (this.CurrentView.IsInitiated()) {
			this.CurrentView.Activate(mode);
		
		} else {
			this.CurrentView.Initiate(mode);
		}
		
		// Attach event listeners.
		this.CurrentView.AddListener('OnGetAbsolutePath',         '_OnGetAbsolutePathHandler',         this);
		this.CurrentView.AddListener('OnGridMouseDown',           '_OnGridMouseDownHandler',           this);
		this.CurrentView.AddListener('OnRowContextMenu',          '_OnRowContextMenuHandler',          this);
		this.CurrentView.AddListener('OnRowClick',                '_OnRowClickHandler',                this);
		this.CurrentView.AddListener('OnRowDoubleClick',          '_OnRowDoubleClickHandler',          this);
		this.CurrentView.AddListener('OnSelectionChanged',        '_OnSelectionChangedHandler',        this);
		this.CurrentView.AddListener('OnCallUserDefinedFunction', '_OnCallUserDefinedFunctionHandler', this);
		
		if (this.Items) {
			this.RenderItems(this.Items);
		}
		
		if (selectedItems && selectedItems.length) {
			this.CurrentView.SelectRowsByUrl(selectedItems);
		}
		
	// View mode was not changed, change thumbnails size.
	} else {
		this.CurrentView.SetThumbnailsSize(mode);
		this._ViewMode = mode;
	}

}

ITHit.oNS.DataViewAdapter.prototype.GetViewMode = function() {
	return this._ViewMode;
}

ITHit.oNS.DataViewAdapter.prototype.SetImageTypes = function(event, imageTypes) {
	
	for (var view in this.Views) {
		if (!this.Views.hasOwnProperty(view)) continue;
		
		if (this.Views[view].SetImageTypes) {
			this.Views[view].SetImageTypes(imageTypes);
		}
	}
}

ITHit.oNS.DataViewAdapter.prototype.SetShowImagePreview = function(event, show) {
	
	for (var view in this.Views) {
		if (!this.Views.hasOwnProperty(view)) continue;
		
		if (this.Views[view].SetShowImagePreview) {
			this.Views[view].SetShowImagePreview(show);
		}
	}
}

