ITHit.oNS.DataViewAdapter.prototype.RenderItems = function(items) {
	
	this.Items = items;
	
	if (this.Items.ShowFolders) {
		return this.CurrentView.RenderItems(this.Items.Folders.concat(this.Items.Resources));
	} else {
		return this.CurrentView.RenderItems(this.Items.Resources);
	}
}

