ITHit.oNS.DataViewAdapter.prototype.KeyPageDown = function(aItems, oEvent) {
	if (this.CurrentView.KeyPageDown) {
		return this.CurrentView.KeyPageDown(aItems, oEvent);
	}
}

ITHit.oNS.DataViewAdapter.prototype.OnResizeViewArea = function() {
	if (this.CurrentView.OnResizeViewArea) {
		this.CurrentView.OnResizeViewArea();
	}
}

ITHit.oNS.DataViewAdapter.prototype.SetSelectedByBoxArea = function(beginX, beginY, endX, endY) {
	return this.CurrentView.SetSelectedByBoxArea(beginX, beginY, endX, endY);
}

ITHit.oNS.DataViewAdapter.prototype.SetScrollTop = function(top) {
	this.CurrentView.SetScrollTop(top);
}

ITHit.oNS.DataViewAdapter.prototype.SetScrollLeft = function(left) {
	this.CurrentView.SetScrollLeft(left);
}

// Event handlers.
ITHit.oNS.DataViewAdapter.prototype._OnRowClickHandler = function(event, url) {
	return this.DispatchEvent('OnRowClick', [event, url]);
}

ITHit.oNS.DataViewAdapter.prototype._OnRowDoubleClickHandler = function(event, url) {
	return this.DispatchEvent('OnRowDoubleClick', [event, url]);
}

ITHit.oNS.DataViewAdapter.prototype._OnSelectionChangedHandler = function() {
	return this.DispatchEvent('OnSelectionChanged');
}

ITHit.oNS.DataViewAdapter.prototype._OnRowContextMenuHandler = function(event, url) {
	return this.DispatchEvent('OnRowContextMenu', [event, url]);
}

ITHit.oNS.DataViewAdapter.prototype._OnGridMouseDownHandler = function(event, url) {
	return this.DispatchEvent('OnGridMouseDown', [event, url]);
}

ITHit.oNS.DataViewAdapter.prototype._OnGetAbsolutePathHandler = function(url) {
	return this.DispatchEvent('OnGetAbsolutePath', url);
}

ITHit.oNS.DataViewAdapter.prototype._OnCallUserDefinedFunctionHandler = function(fHandler, sUrl, iIndex) {
	// Find in current items
	var aItems = this.Items.Folders.concat(this.Items.Resources);
	for (var i = 0, l = aItems.length; i < l; i++) {
		if (aItems[i].Href === sUrl) {
			return fHandler(aItems[i].Item, iIndex);
		}
	}

	throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Not found item in DataViewAdapter.Items by url `' + sUrl + '`');

	//return handler(null, iIndex);
	//return this.DispatchEvent('OnCallUserDefinedFunction', [handler, url, iIndex]);
}


