ITHit.oNS.MenuController._Counter = 0;

ITHit.oNS.MenuController.prototype.ToggleVisible = function(sName, bVisible) {
	this._HiddenMenuItems[sName] = !bVisible;
}

ITHit.oNS.MenuController.prototype._SetActions = function(oMenu, oHandlers) {
	
	var aMenuChildren = oMenu.Children;
	for (var i = 0, l = aMenuChildren.length; i < l; i++) {
		var menuItem = aMenuChildren[i];
		
		if (menuItem.Id) {
			for (var action in oHandlers) {
				if (!oHandlers.hasOwnProperty(action)) continue;
				
				if (menuItem.Id == action) {
					menuItem.OnClick = oHandlers[action];
					break;
				}
			}
		}
		
		if (menuItem.Children && menuItem.Children.length) {
			this._SetActions(menuItem, oHandlers);
		}
	}
}

ITHit.oNS.MenuController.prototype._CloneMenu = function(mInput, aDelete, aDisable) {
	
	aDelete  = aDelete  || [];
	aDisable = aDisable || [];
	
	var oDelete = {};
	// Append global
	for (var sName in this._HiddenMenuItems) {
		if (this._HiddenMenuItems.hasOwnProperty(sName)) {
			oDelete[sName] = this._HiddenMenuItems[sName];
		}
	}

	// Append local
	for (var i = 0, l = aDelete.length; i < l; i++) {
		oDelete[aDelete[i]] = true;
	}
	
	var oDisable = {};
	for (var i = 0, l = aDisable.length; i < l; i++) {
		oDisable[aDisable[i]] = true;
	}
	
	return this._DoCloneMenu(mInput, oDelete, oDisable);
}

ITHit.oNS.MenuController.prototype._DoCloneMenu = function(mInput, oDelete, oDisable) {
	
	oDelete  = oDelete  || {};
	oDisable = oDisable || {};
	
	var clone ;

	// Whether item is array.
	if (ITHit.Utils.IsArray(mInput)) {
		clone = [];
		var bLastIsMenuSeparator = false;
		for (var i = 0, l = mInput.length; i < l; i++) {
			var mVal = this._DoCloneMenu(mInput[i], oDelete, oDisable);
			if (undefined === mVal) {
				continue;
			}

			// Skip duplicate separators
			if (mVal && mVal.Type === 'MenuSeparator') {
				if (bLastIsMenuSeparator) {
					continue;
				}
				bLastIsMenuSeparator = true;
			} else {
				bLastIsMenuSeparator = false;
			}

			clone.push(mVal);
		}
		
	// Whether item is object.
	} else if (ITHit.Utils.IsObjectStrict(mInput)) {
		
		clone = {};
		var bDisable = false;
		if (mInput.Id && oDelete[mInput.Id]) {
			return undefined;
		}
		for (var prop in mInput) {
			if (!mInput.hasOwnProperty(prop)) continue;
			
			switch (prop) {
				
				case 'Id':
					clone['Id'] = mInput[prop];
					
					if (oDisable[mInput[prop]]) {
						bDisable = true;
					}
					continue;
				
				case 'Text':
				case 'ContextHelp':
					clone[prop] = String(mInput[prop]);
					continue;
			}
			
			var mVal = this._DoCloneMenu(mInput[prop], oDelete, oDisable);
			if (undefined !== mVal) {
				clone[prop] = mVal;
			}
		}
		if (bDisable) {
			clone.Disabled = true;
		}
	
	// Item is another type.
	} else {
		clone = mInput;
	}

	return clone;
}

ITHit.oNS.MenuController.prototype.ShowRightPaneContextMenu = function(oEvent, oTarget, oItem) {
	
	var oDelete  = [],
	    oDisable = [],
	    menu;

	if (!this._controller.CopyMoveManager.GetItemsLength()) {
		oDisable.push('Paste');
	}
	if (!this._openOrCreateDocument) {
		oDelete.push('NewDocument');
	}
	
	menu = this._CloneMenu(this._menu.FilesViewPanelGeneralMenu, oDelete, oDisable);
	menu['TargetNodeIds'] = [oTarget];
	menu['TargetItems']   = [oItem];

	this._ShowMenu(menu, oEvent);

    ITHit.oNS.Render.MenuController.RefreshCheckedViewState(this._controller._index);
}

ITHit.oNS.MenuController.prototype.ShowUploadManagerContextMenu = function(oEvent, oTarget, aUrl) {
	
	var aDelete  = [],
	    aDisable = [],
	    oUpload  = this._controller._upload,
	    oDelete = {};
	
	if (!(ITHit.DetectBrowser.FF >= 7 || ITHit.DetectBrowser.Safari || ITHit.DetectBrowser.Chrome || ITHit.DetectBrowser.IE >= 10 || ITHit.DetectBrowser.Edge)) {
	    oDelete['Pause'] = 1;
	    oDelete['Resume'] = 1;
	}
	if (!ITHit.DetectBrowser.IE || ITHit.DetectBrowser.IE > 9) {
	    oDelete['Restart'] = 1;
	}

	if (aUrl.length > 1) {
	    oDelete['Errors'] = 1;
	}
	
	for (var i = 0, l = aUrl.length; i < l; i++) {
		
		var oItemInfo = oUpload.GetInfo(aUrl[i]);
		var sStatus = (oItemInfo ? oItemInfo.Status : oUpload.GetStatus(aUrl[i]));

		if (!oItemInfo && !sStatus) {
			return false;
		}
		
		switch(sStatus) {
			
		    case 'queue':
		    case 'resume':
            case 'retry':
			case 'Restart':
				// Abort
				//oDelete['Pause']   = 1;
				oDelete['Resume']  = 1;
				oDelete['Restart'] = 1;
				oDelete['Errors']  = 1;
				break;
			
			case 'upload':
				// Abort
				// Pause whether resumable
				if (!oItemInfo || !oItemInfo.IsResumable) {
					oDelete['Pause'] = 1;
				}
				oDelete['Resume']  = 1;
				oDelete['Restart'] = 1;
				oDelete['Errors']  = 1;
				break;
			
			case 'paused':
				// Abort
				// Resume
				oDelete['Pause']   = 1;
				oDelete['Restart'] = 1;
				oDelete['Errors']  = 1;
				break;
			
			case 'error':
				// Abort
			    if (!oItemInfo) {
			        oDelete['Restart'] = 1;
			    }
			    if (!oItemInfo || !oItemInfo.IsResumable) {
			        oDelete['Resume'] = 1;
			    }
				oDelete['Pause']  = 1;
				if (!oItemInfo) {
				    oDelete['Errors'] = 1;
				}
				break;
			
			default:
				throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.UnexpectedUploadItemState.Paste(oItemInfo.Status));
		}
	}
	
	for (var prop in oDelete) {
		if (!oDelete.hasOwnProperty(prop)) continue;
		aDelete.push(prop);
	}

	if (!this._controller._Upload().IsResumeSupported()) {
		aDisable.push('Resume');
		aDisable.push('Pause');
	}
	
	var menu = this._CloneMenu(this._menu.UploadProgressPanelMenu, aDelete, aDisable);
	menu['TargetNodeIds'] = [oTarget];
	menu['TargetItems']  = aUrl;
	
	this._ShowMenu(menu, oEvent);
}

ITHit.oNS.MenuController.prototype.ShowTreeContextMenu = function(oEvent, oTarget, oItem, sUrl) {
	
	var oNs           = ITHit.WebDAV.Client.AjaxFileBrowser;
	var oNsController = oNs.Controller;
	var oNsRender     = oNs.Render.RenderController;
	var oController   = this._controller;
	var oDelete       = [];
	var oDisable      = [];

	if (!this._controller.CopyMoveManager.GetItemsLength()) {
		oDisable.push('Paste');
	}
	
	if (!this._openOrCreateDocument) {
		oDelete.push('NewDocument');
	}

	// Disable menu items for root element.
	//if (this._controller._baseUrl == sUrl) {  //vkorotchenko artf44337
	if (sUrl.split("/").length - 1 <= 3){       //vkorotchenko artf44337
		oDisable.push('Copy');
		oDisable.push('Cut');
		oDisable.push('Rename');
		oDisable.push('Delete');
		oDisable.push('UploadFolder'); //vkorotchenko, artf44337
		oDisable.push('UploadFile');   //vkorotchenko, artf44337
	}

	var menu = this._CloneMenu(this._menu.FoldersPanelMenu, oDelete, oDisable);
	menu['TargetNodeIds'] = [oTarget];
	menu['TargetItems']   = [oItem];
	
	this._ShowMenu(menu, oEvent);
}

ITHit.oNS.MenuController.prototype.ShowGridContextMenu = function(oEvent, oTarget, oItems) {

	var oDelete  = [],
	    oDisable = [],
	    sUrl,
	    sFullUrl,
	    oNsFileBrowser = ITHit.WebDAV.Client.AjaxFileBrowser;

	//vkorotchenko artf44337 start
        if (oItems[0].Href.split("/").length - 1 <= 3){
            oDisable.push('UploadFile');
            oDisable.push('UploadFolder');
        }
        //vkorotchenko artf44337 end

	var sourceMenu;
	// Get multiselection menu.
	if (oItems.length > 1) {
		sourceMenu = this._menu.FilesViewPanelMultiselectionMenu;
	
	// Folder or resource menu.
	} else {
		var oItem = oItems[0];
		sUrl      = oItem.Href;
		
		// Get folder menu.
		if (-1 != oItem.ResourceType.indexOf('Folder')) {
			sourceMenu = this._menu.FilesViewPanelFolderMenu;
			
		// Get resource menu.
		} else {
			sourceMenu = this._menu.FilesViewPanelFileMenu;

		    // Check if versioning is enabled fo this item.
			if (!oItem.Item.VersionControlled()) {
				oDisable.push('Versions');
            }

			// Check whether file editing supported.
			var ext = ITHit.Trim(sUrl.substr(sUrl.lastIndexOf(".") + 1));
			if (!ext || (!this._openOrCreateDocument && !this._EditDocumentWithPlugin)) {
				oDelete.push('EditDocument');
			
			// Supported.
			} else {
				
				// Check whether file is potentialy dengerous.
				var edit          = true,
				    fileFormatsNs = oNsFileBrowser.FileFormats;
				
				if (fileFormatsNs.ProtectedExtentions.join('|').indexOf(ext) >= 0) {
					oDelete.push('EditDocument');
					edit = false;
				}
				
				if (edit && !this._EditDocumentWithPlugin && (-1 == fileFormatsNs.MsOfficeEditExtensions.join('|').indexOf(ext))) {
					oDelete.push('EditDocument');
				}
			}
		}
	}

	if (!this._controller.CopyMoveManager.GetItemsLength()) {
		oDisable.push('Paste');
	}
	
	var menu = this._CloneMenu(sourceMenu, oDelete, oDisable);
	menu['TargetNodeIds'] = [oTarget];
	menu['TargetItems']   = oItems;
	
	this._ShowMenu(menu, oEvent);
}

ITHit.oNS.MenuController.prototype._ShowMenu = function(menu, oEvent) {
	// Protect TargetNodeIds property from modification.
	var targetNodeIds = menu.TargetNodeIds,
	    targetItems   = menu.TargetItems;
	delete menu.TargetNodeIds;
	delete menu.TargetItems;
	
	// Check OnShowMenu event listeners length.
	if (ITHit.Events.ListenersLength(this, this._events.onShowMenu)) {
		
		// Get items for OnShowMenu handler.
		var items = [];
		for (var i = 0, l = targetItems.length; i < l; i++) {
			items.push(targetItems[i].Item);
		}
		
		// Dispatch OnShowMenu event.
		if (false === ITHit.Events.DispatchEvent(this, this._events.onShowMenu, [menu, items])) {
			return false;
		}
	}
	
	// Restore TargetNodeIds property.
	menu.TargetNodeIds = targetNodeIds;
	menu.TargetItems   = targetItems;
	
	// Create dojo menu widget.
	var oContextMenu = this._CreateWidgetsTree(menu);
	
	// Events for hover effect on tree when menu is opened.
	if (menu.Id == 'FoldersPanelMenu') {
		ITHit.Events.DispatchEvent(this, 'OnTreeNodeMenuOpen', [oEvent]);
		var _this = this;
		ITHit.Components.ihDojo.connect(oContextMenu, 'onClose', null, function() {ITHit.Events.DispatchEvent(_this, 'OnTreeNodeMenuClose', [oEvent]);});
	}
	
	
	// var bDispatch = ITHit.Events.DispatchEvent(this, this._events.onShowMenu, oContextMenu);
	
	if (oContextMenu && oContextMenu._openMyself) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Controller._SetActive(this._controller._index);
		oContextMenu.startup();
		oContextMenu._openMyself({target: oEvent.target || oEvent.srcElement, coords: {x: oEvent.pageX+2, y: oEvent.pageY}});
	}
}

ITHit.oNS.MenuController.prototype._CreateWidgetsTree = function(oneEntry, menu) {
	
	if (!menu) {
		menu = oneEntry;
	}
	
	var dijit       = ITHit.Components.dijit,
	    widget      = null,
	    popget      = false,
	    div         = document.createElement('div'),
	    params      = {},
	    dojoNs      = ITHit.Components.dojo,
	    utilsNs     = ITHit.Utils,
	    contextHelp = this._controller._ContextHelp;
	
	for (var param in oneEntry) {
		if (!oneEntry.hasOwnProperty(param)) continue;
		
		switch(param) {
				
			// Skip properties.
			//case 'Id':
			case 'Type':
			case 'TargetItems':
			case 'Children':
			case 'Scope':
			case 'ContextHelp':
				continue;

			// Add styles to properties, convert to string whether nedded.
			case 'Style':
				if (ITHit.Utils.IsString(oneEntry[param])) { 
					params['style'] = oneEntry[param];
				} else if (ITHit.Utils.IsObjectStrict(oneEntry[param])) {
					params['style'] = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.PrepareStyle(oneEntry[param]).join(' ');
				}
				continue;
		}
		
		var newParamName = param.substr(0, 1).toLowerCase() + param.substr(1);
		
		params[newParamName] = oneEntry[param];
	}
	
	switch (oneEntry.Type) {
		
		case 'Menu':
			params['first']        = true;
			params['appendToNode'] = this._controller.Settings.GetRootNode();
			widget = new dijit.Menu(params, div);
			if (contextHelp) {
				dojoNs.connect(widget, 'onClose', utilsNs.MakeScopeClosure(contextHelp, 'Hide'));
			}
			break;
		
		case 'MenuItem':
			
			// Attach default handler.
			if (oneEntry.Id && !params.onClick) {
				params.onClick = this._Handlers.GetMenuHandler(menu.Id, oneEntry.Id, menu.TargetItems);
			
			// Attach user defined handler.
			} else if (params.onClick) {
				
				// Get HierarchyItems for user defined handler.
				var items = [];
				for (var i = 0, l = menu.TargetItems.length; i < l; i++) {
					items.push(menu.TargetItems[i].Item);
				}
				
				params.onClick = this._Handlers._MakeClosure(oneEntry.Scope, params.onClick, items);
			}
			
			// Attach stopper whether handler has not beed attached.
			if (!params.onClick) {
				params.onClick = new Function('', '');
			}

            if (params['id']) {
                params['id'] = this._controller._index + params['id'];
            }
			params['label']        = params['text'];
			params['appendToNode'] = this._controller.Settings.GetRootNode();
			widget = new dijit.MenuItem(params, div);
			
			if (contextHelp && oneEntry.ContextHelp) {
			    dojoNs.connect(widget.domNode, 'onmouseover', utilsNs.MakeScopeClosure(contextHelp, 'Show', [oneEntry.ContextHelp, oneEntry.ContextHelpIconClass]));
				dojoNs.connect(widget.domNode, 'onmouseout',  utilsNs.MakeScopeClosure(contextHelp, 'Hide'));
			}
			
			break;
		
		case 'MenuSeparator':
			widget = new dijit.MenuSeparator(params, div);
			break;
		
		case 'PopupMenuItem':
			params['appendToNode'] = this._controller.Settings.GetRootNode();
			widget = new dijit.Menu(params, div);
			popget = true;
			
			if (contextHelp && oneEntry.ContextHelp) {
			    dojoNs.connect(widget.domNode, 'onmouseover', utilsNs.MakeScopeClosure(contextHelp, 'Show', [oneEntry.ContextHelp, oneEntry.ContextHelpIconClass]));
				dojoNs.connect(widget.domNode, 'onmouseout',  utilsNs.MakeScopeClosure(contextHelp, 'Hide'));
			}
			break;
		
		default:
			throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongMenuItemType.Paste(oneEntry.Type));
			return;
	}
	
	if (oneEntry.Children) {
		for (var i = 0, l = oneEntry.Children.length; i < l; i++) {
			var widgetChild = this._CreateWidgetsTree(oneEntry.Children[i], menu);
			widget.addChild(widgetChild);
		}
	}
	
	// Test if we created  a popup menu.
	if (popget) {
	   return new dijit.PopupMenuItem({ label: params['text'] , popup: widget, appendToNode: params['appendToNode'] });
	}
	
	return widget;
}

ITHit.oNS.MenuController.RefreshCheckedViewState = function(index) {
    var oNsViewModes = ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes;
    var viewStateCodeToItemIdRelations = {};
    viewStateCodeToItemIdRelations[oNsViewModes.Details] = 'DetailsView';
    viewStateCodeToItemIdRelations[oNsViewModes.Medium] = 'MediumIcons';
    viewStateCodeToItemIdRelations[oNsViewModes.Large] = 'LargeIcons';
    viewStateCodeToItemIdRelations[oNsViewModes.ExtraLarge] = 'ElargeIcons';
    var iconCssClassMapping = {};
    iconCssClassMapping[oNsViewModes.Details] = 'Details';
    iconCssClassMapping[oNsViewModes.Medium] = 'Medium';
    iconCssClassMapping[oNsViewModes.Large] = 'Large';
    iconCssClassMapping[oNsViewModes.ExtraLarge] = 'ExtraLarge';

    var controller = ITHit.WebDAV.Client.AjaxFileBrowser.Controller.GetByIndex(index);
    var itemToSelect = ITHit.Components.dijit.byId(index + viewStateCodeToItemIdRelations[controller._grid._ViewMode]);
    var menuItemToSelect = ITHit.Components.dijit.byId(index + 'menu' + viewStateCodeToItemIdRelations[controller._grid._ViewMode]);
    var viewButton = ITHit.Components.dijit.byId('ithit_interface_selectView_' + index);
    viewButton.iconNode.className = viewButton.iconNode.className.toString().replace(/(iconView)[^ ]*/, '') + 'iconView' + iconCssClassMapping[controller._grid._ViewMode];

    var setChecked = function(node){
        ITHit.Components.dojo.addClass(node, 'checked_menuitem_icon');
        node.setAttribute('src', ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetBlankGifPath());
        node.style.display = 'block';
    }

    var setUnchecked = function(node){
        node.style.display = 'none';
    }

    //One more dirty hack - for top menu we have to hide check icon on every refresh
    for (var i in viewStateCodeToItemIdRelations) {
        var itemToHide = ITHit.Components.dijit.byId(index + 'menu' + viewStateCodeToItemIdRelations[i]);
        setUnchecked(itemToHide.iconNode);
    }

    if (itemToSelect) setChecked(itemToSelect.iconNode);
    if (menuItemToSelect) setChecked(menuItemToSelect.iconNode);
}

