ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render');

ITHit.oNS.ResourceIcons = function(iconsPath) {
	
	this.IconsPath = iconsPath;
	this.Hash = {
		16: {},
		32: {},
		48: {},
		64: {},
		72: {},
		94: {},
		128: {},
		256: {}
	};
}

ITHit.oNS.ResourceIcons.prototype.Check = function(size, extension) {
	return this.Hash[size][extension.toLowerCase()];
}

ITHit.oNS.ResourceIcons.prototype.Add = function(size, extension, exists) {
	this.Hash[size][extension.toLowerCase()] = exists;
}

// TODO: replace with CreateImage2, items with 'Folder' ext displayed as folders
ITHit.oNS.ResourceIcons.prototype.CreateImage = function (size, extension) {

	extension = extension.toLowerCase();
	
	var thumb;
	
	if ('folder' != extension) {
		
		var exists = extension && this.Check(size, extension);
		if (exists) {
			thumb           = document.createElement('IMG');
			thumb.src       = this.IconsPath + size + '/' + extension + '.png';
			
		} else if (extension && ITHit.Utils.IsUndefined(exists)) {
			thumb           = document.createElement('IMG');
			thumb.onerror   = new Function([], 'this.onerror=this.onload=null;ITHit.WebDAV.Client.AjaxFileBrowser.Controller.IconNotFound(this);');
			thumb.onload    = new Function([], 'this.onerror=this.onload=null;ITHit.WebDAV.Client.AjaxFileBrowser.Controller.IconLoaded(this);');
			thumb.src       = this.IconsPath + size + '/' + extension + '.png?width='+ size +'&height='+ size + '&mode=fit';
		} else {
			thumb           = document.createElement('DIV');
			thumb.className = 'resource';
		}
	} else {
		thumb           = document.createElement('DIV');
		thumb.className = 'folder';
	}
	
	return thumb;
}

ITHit.oNS.ResourceIcons.prototype.CreateImage2 = function (size, url, isFolder) {
    var ns = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.ResourceIcons;
    if (isFolder) {
        return ns.CreateImage(size, 'Folder');
    }
    var ext = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(url);
    return ns.CreateImage(size, ext);
}


ITHit.oNS.ResourceIcons.prototype.CreateImageString = function(size, extension) {

	if (extension) {
		extension = extension.toLowerCase();
	} else {
        extension = false;
    }
	
	if ('folder' != extension) {
		if (false !== extension) {
			var exists = this.Check(size, extension);
			
			if (exists) {
				return '<img src="' + this.IconsPath + size + '/' + extension + '.png" />';
			} else if (ITHit.Utils.IsUndefined(exists)) {
				return '<img onerror="this.onerror=this.onload=null;ITHit.WebDAV.Client.AjaxFileBrowser.Controller.IconNotFound(this);" onload="this.onerror=this.onload=null;ITHit.WebDAV.Client.AjaxFileBrowser.Controller.IconLoaded(this);" src="' + this.IconsPath + size + '/' + extension + '.png" />';
			} else {
				return '<div class="resource" />';
			}
		} else {
			return '<div class="resource" />';
		}
	} else {
		return '<div class="folder" />';
	}
}

ITHit.oNS.ResourceIcons.prototype.SaveIconInfo = function(image, loaded) {
	
	var imageSrc = image.src;
	if (/blank\_\d{2,3}\.gif$/.test(imageSrc)) {
		return;
	}
	
	var imgInfo = imageSrc.match(/\d{2,3}?\/[^\/]+$/)[0].split('/');
	var size    = parseInt(imgInfo[0]);

	var matches = imageSrc.match(/\/([^.\/]+)\.[^.]+(\?.+)?$/);
	var ext     = matches[1];

	this.Add(size, ext, loaded);
	
	if (!loaded) {
		this.ReplaceResourceThumbnail(image);
	}
}

ITHit.oNS.ResourceIcons.prototype.ReplaceResourceThumbnail = function(image) {
	
	var parent = image.parentNode;
	if (!parent) {
	  return;
	}
	
	image.onerror = null;
	image.onload  = null;
	parent.removeChild(image);
	
	var div = document.createElement('DIV');
	div.setAttribute('class',     'resource', true);
	div.setAttribute('className', 'resource', true);
	
	parent.appendChild(div);
}


