// Singletone method, will be created in constructor.
ITHit.oNS.Utils.ResourceIcons;

ITHit.oNS.Utils.FormatSize = function(value) {
	
	if ('number' !== typeof value) {
		return value;
	}
	
	var size = parseFloat(value),
	    formattedSize,
	    phrasesNs = ITHit.Phrases.AjaxFileBrowser.FileSizes;
	
	if (size >= 1048576000) {
		formattedSize = (Math.round(size / 1073741824 * 100) / 100) +' '+ phrasesNs.GB;
	}
	else if (size >= 1048576) {
		formattedSize = (Math.round(size / 1048576 * 100) / 100) +' '+ phrasesNs.MB;
	}
	else if (size >= 1024) {
		formattedSize = (Math.round(size / 1024 * 100) / 100) +' '+ phrasesNs.KB;
	}
	else {
		formattedSize = size +' '+ phrasesNs.B;
	}
	
	return formattedSize;
}

// Adds separator to bytes string.
ITHit.oNS.Utils.FormatSizeBytes = function (iSize) {
    if (!iSize) {
        return '';
    }
    var sSize = iSize.toString(),
        aFormattedSize = [],
        iSeparatorPos = 0;

    for (var i = (sSize.length - 1) ; i >= 0; i--) {
        if (iSeparatorPos && !(iSeparatorPos % 3)) {
            aFormattedSize.push(',');
        }

        aFormattedSize.push(sSize.charAt(i));
        iSeparatorPos++;
    }
    return aFormattedSize.reverse().join('') + ' ' + ITHit.Phrases.AjaxFileBrowser.FileSizes.Bytes;
}

ITHit.oNS.Utils.FormatDate = function(date) {
	return date ? ITHit.Components.dojo.date.locale.format(date) : '';
}


