ITHit.oNS.Dialog.NewFolder = function(sUrl, sName) {
	var oNsController = ITHit.WebDAV.Client.AjaxFileBrowser.Controller;
	var oController = oNsController.GetByIndex(oNsController._GetActive());

	var aFolders = [];
	if (oController._url === sUrl) {
		// Get from current folder (grid)
		aFolders = oController._Grid().Items.Folders;
	} else {
		var aChildren = oController.Commands.FoldersCollection.Get(sUrl) || [];
		aFolders = oController._filter.Run(aChildren).Folders;
	}

	var sNewFolderPhrase = ITHit.Phrases.AjaxFileBrowser.Interface.NewFolderPattern;
	var oPattern = new RegExp('^' + sNewFolderPhrase + '( [0-9]+)?$', 'i');
	var iNewFolderMaxNumber = 0;

	for (var i = 0, l = aFolders.length; i < l; i++) {
		var aMatches = oPattern.exec(aFolders[i].DisplayName);
		if (aMatches !== null) {
			var iNumber = parseInt(aMatches[1]) || 1;
			iNewFolderMaxNumber = Math.max(iNewFolderMaxNumber, iNumber);
		}
	}
	iNewFolderMaxNumber++;

	ITHit.Components.dojo.byId('ithit_interface_new_folder_message').innerHTML = '';
	ITHit.Components.dojo.byId('ithit_interface_new_folder').value             = sName || sNewFolderPhrase + (iNewFolderMaxNumber > 1 ? ' ' + iNewFolderMaxNumber : '');
	ITHit.Components.dojo.byId('ithit_interface_new_folder_url').value         = sUrl;

	ITHit.Components.dijit.byId('ithit_interface_newFolder').show();
}

ITHit.oNS.Dialog.CloseNewFolder = function() {
	ITHit.Components.dijit.byId('ithit_interface_newFolder').hide();
}

