ITHit.oNS.Dialog.Versions = function(sUrl, aProps) {

    var oNsDojo    = ITHit.Components.dojo;
    var oNsRender  = ITHit.WebDAV.Client.AjaxFileBrowser.Render;
    var oGrid      = oNsRender.Dialog.Versions._grid;
    var oNsPhrases = ITHit.Phrases.AjaxFileBrowser.Version;

    oNsDojo.byId('ithit_interface_versions_url').value = sUrl;

    var sizeFormatter = function(sValue) {
        sValue = parseInt(sValue) || 0;
        return ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.FormatSize(sValue);
    }

    oNsRender.Dialog.SwitchVersionUpdateButton(false);
    oNsRender.Dialog.SwitchVersionRemoveButton(false);
    oNsRender.Dialog.SwitchVersionDownloadButton(false);

    var oLayout = [{
        cells: [[
            {name: oNsPhrases.Name, field: '0', width: '90px', formatter: ITHit.Utils.HtmlEscape},
            {name: oNsPhrases.Size, field: '1', width: '70px', formatter: sizeFormatter},
            {name: oNsPhrases.CreationDate, field: '2', width: '120px'},
            {name: oNsPhrases.SavedBy, field: '3', width: 'auto', formatter: ITHit.Utils.HtmlEscape},
            {name: oNsPhrases.Comments, field: '4', width: '120px', hidden: true, formatter: ITHit.Utils.HtmlEscape},
            {field: '5', hidden: true}
        ]],
        tableLayout: true
    }];

    var oMapNames = {
        'Name': '0',
        'Size': '1',
        'CreationDate': '2',
        'SavedBy': '3',
        'Comments': '4',
        'VersionHref': '5'
    };

    if (!oGrid) {
        oGrid = oNsRender.Dialog.Versions._grid = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.DataView.GridView.Grid('ithit_interface_versions_list', oLayout, oMapNames);
        oNsDojo.connect(ITHit.Components.dijit.byId(oGrid.GetElementId()), "onRowClick", ITHit.WebDAV.Client.AjaxFileBrowser.Render.RenderController.EnableVersionControlButtons);
        oNsDojo.connect(ITHit.Components.dijit.byId(oGrid.GetElementId()), "onRowDblClick", function() {
			ITHit.WebDAV.Client.AjaxFileBrowser.Controller.VersionDownload(ITHit.Components.dojo.byId("ithit_interface_versions_url").value);
		});
    }
    ITHit.Components.dijit.byId('ithit_interface_versions').show();

    oGrid.RenderItems(aProps);
	oGrid._grid.setSortIndex(0, true);

	// Get references for controller
	var oNsCl         = ITHit.WebDAV.Client,
		oNsController = oNsCl.AjaxFileBrowser.Controller,
		oController   = oNsController.GetByIndex(oNsController._GetActive()),
		oItem = oController._GetItem(sUrl);

	// Check webdav server version
	if (!oController.SuppressServerWarning) {

		// Get webdav server version
		var sXEngine = oItem.Item.ServerVersion;
		var aXEngineExec = sXEngine && sXEngine.indexOf('IT Hit WebDAV Server') !== -1 ? /v([0-9.]+)/.exec(sXEngine) : null;
		var sWebDavServerVersion = aXEngineExec ? aXEngineExec[1] : '';

		if (sWebDavServerVersion) {
			var sWebDavServerMajorVersion = /^[0-9]+\.[0-9]+/.exec(sWebDavServerVersion)[0];

			var oWarningElement = oNsDojo.byId('ithit_interface_versions_warning_old_version');
			if (parseFloat(sWebDavServerMajorVersion) < 3.5) {
				oWarningElement.innerHTML = ITHit.Utils.HtmlEscape(ITHit.Phrases.AjaxFileBrowser.Interface.WarningOldVersion.Paste(sWebDavServerVersion));
				oWarningElement.style.display = '';
			} else {
				oWarningElement.style.display = 'none';
			}
		}
	}
}
