ITHit.oNS.Dialog.ShowItemInfo = function (sUrl, sItemName, sType, iSize, sCreated, sModified, iAvailableBytes, iUsedBytes) {

	var oNsById = ITHit.Components.dojo.byId,
	    thumb;
	var formatUtils = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils;

	if (ITHit.Utils.IsUndefined(iSize) || iSize === null) {
		oNsById('ithit_interface_item_info_sizeTr').style.display = 'none';
	} else {
		oNsById('ithit_interface_item_info_sizeTr').style.display = '';		
		oNsById('ithit_interface_item_info_size').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSize(iSize) + ' (' + formatUtils.FormatSizeBytes(iSize) + ')');
	}
	
	var extTypePhrase;
	var ext = ITHit.WebDAV.Client.AjaxFileBrowser.Utils.GetFileExtension(sUrl);
	    
	if (sType != 'Folder') {
        if (ext) {
            extTypePhrase = ext;
        } else {
            extTypePhrase = ITHit.Phrases.AjaxFileBrowser.Interface.File;
        }
	} else {
		ext           = sType;
		extTypePhrase = ITHit.Phrases.AjaxFileBrowser.Interface.FileFolderType;
	}

	var thumb = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.ResourceIcons.CreateImage(32, ext);
	
	if (-1 == sUrl.search(/:[0-9]+\//)) {
		iPort = (0 == sUrl.indexOf('https:')) ? 443 : 80;
		sUrl  = sUrl.replace(/([a-zA-Z0-9])\/(?!\/)/, '$1:'+ iPort +'/');
	}

    //Quota info
	var quotaInfoContainer = oNsById('ithit_interface_item_info_quota_container');
	if (( iAvailableBytes >=0 ) && (iUsedBytes >=0)) {
	    quotaInfoContainer.style.display = '';

	    oNsById('ithit_interface_item_info_used_bytes').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSizeBytes(iUsedBytes));
	    oNsById('ithit_interface_item_info_available_bytes').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSizeBytes(iAvailableBytes));
	    oNsById('ithit_interface_item_info_total_bytes').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSizeBytes(iUsedBytes + iAvailableBytes));

	    oNsById('ithit_interface_item_info_used').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSize(iUsedBytes));
	    oNsById('ithit_interface_item_info_available').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSize(iAvailableBytes));
	    oNsById('ithit_interface_item_info_total').innerHTML = ITHit.Utils.HtmlEscape(formatUtils.FormatSize(iUsedBytes + iAvailableBytes));

	    var usedPercent = (iUsedBytes*100/(iUsedBytes + iAvailableBytes)); 
	    oNsById('ithit_interface_item_info_used_percent').innerHTML = ITHit.Utils.HtmlEscape(ITHit.Phrases.AjaxFileBrowser.Interface.UsedPercent.Paste(Math.round(usedPercent)));
	    oNsById('ithit_interface_item_info_used_percent_bar').style.width = usedPercent + "%";
	}
	else {
	    quotaInfoContainer.style.display = 'none';
	}
	
	oNsById('ithit_interface_item_info_icon').innerHTML     = '';
    if (thumb) {
	    oNsById('ithit_interface_item_info_icon').appendChild(thumb);
    }
	oNsById('ithit_interface_item_info_name').value         = sItemName;
	oNsById('ithit_interface_item_info_url').value          = sUrl;
	oNsById('ithit_interface_item_info_type').innerHTML     = ITHit.Utils.HtmlEscape(extTypePhrase);
	oNsById('ithit_interface_item_info_created').innerHTML  = ITHit.Utils.HtmlEscape(sCreated);
	oNsById('ithit_interface_item_info_modified').innerHTML = ITHit.Utils.HtmlEscape(sModified);
	
	ITHit.Components.dijit.byId('ithit_interface_item_info').show();
}

