ITHit.oNS.Dialog.ShowCustomDialog = function(html, newStyle, title) {
	
	var dialog   = ITHit.Components.dijit.byId('ithit_interface_customDialog'),
	    dialogNs = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog;
	
	dialogNs.HideCustomDialog();
	
	if (newStyle) {
		if (!ITHit.Utils.IsObjectStrict(newStyle)) {
			throw new ITHit.Exceptions.ArgumentException(ITHit.Phrases.Exceptions.ObjectExpected, 'newStyle');
		}
		
		var dialogNode = dialog.domNode;
		for (var prop in newStyle) {
			if (!newStyle.hasOwnProperty(prop)) continue;
			dialogNs.CustomStyleChanges[prop] = dialogNode.style[prop];
			dialogNode.style[prop] = newStyle[prop];
		}
	}
	
	var element       = ITHit.Components.dojo.byId('ithit_interface_customDialog_content');
	element.innerHTML = html;
	
	ITHit.Components.dojo.parser.parse({rootNode: element, appendToNode: element});
	
	if (!ITHit.Utils.IsUndefined(title)) {
		dialog.set("title", title);
	}
	dialog.show();
}

ITHit.oNS.Dialog.CustomStyleChanges = {};

ITHit.oNS.Dialog.HideCustomDialog = function() {
	
	var dialog        = ITHit.Components.dijit.byId('ithit_interface_customDialog'),
	    dialogNode    = dialog.domNode,
	    dialogNs      = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog,
	    styleChanges  = dialogNs.CustomStyleChanges,
	    dialogContent = ITHit.Components.dojo.byId('ithit_interface_customDialog_content');
	
	dialog.set("title", '');
	for (var prop in styleChanges) {
		if (!styleChanges.hasOwnProperty(prop)) continue;
		dialogNode.style[prop] = styleChanges[prop];
	}
	
	dialogNs.CustomStyleChanges = {};
	
	ITHit.Components.dojo.query('[widgetid]', dialogContent).forEach(function(node) {
			ITHit.Components.dijit.byNode(node).destroy();
		});
	
	dialogContent.innerHTML = '';
	dialog.hide();
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Render');

ITHit.oNS.ErrorDialog = function(showDetails) {
	
	var phrasesNs = ITHit.Phrases.AjaxFileBrowser.Interface,
	    renderNs  = ITHit.WebDAV.Client.AjaxFileBrowser.Render,
	    oMapNames = {
		'Source':   '0',
		'Message':  '1',
		'Body':     '2'
	};
	this.ShowDetails = showDetails;
	
	this._layout = [{
			cells: [[
				{name: phrasesNs.Source,  field: '0', width: 'auto', cellStyles: 'cursor:pointer;', formatter: ITHit.Utils.HtmlEscape},
				{name: phrasesNs.Message, field: '1', width: 'auto', cellStyles: 'cursor:pointer;', formatter: ITHit.Utils.HtmlEscape}
			]],
			tableLayout: true
		}];
	
	renderNs.ErrorDialog.baseConstructor.call(this, 'ithit_interface_error_details', this._layout, oMapNames);
	
	ITHit.Components.dojo.connect(this._grid, 'onRowDblClick', ITHit.Utils.MakeScopeClosure(this, 'ShowDetailedError'));
	
	this.base = renderNs.ErrorDialog.base;
	
	this.RenderItems([]);
	
	if (!this.ShowDetails) {
		ITHit.Components.dijit.byId('ithit_interface_error_details_button').setAttribute('style', 'display: none;');
	}
}

ITHit.Extend(ITHit.oNS.ErrorDialog, ITHit.oNS.DataView.GridView.Grid);

ITHit.oNS.ErrorDialog.ShowErrorDetails = true;

ITHit.oNS.ErrorDialog.prototype.ShowErrors = function() {
	
	var browserNs  = ITHit.WebDAV.Client.AjaxFileBrowser,
	    aErrorData = [];
	
	switch(arguments.length) {
		
		case 1:
			if (ITHit.Utils.IsArray(arguments[0])) {
				
				var aErrors = arguments[0];
				for (var i = 0, l = aErrors.length; i < l; i++) {
					if (ITHit.Utils.IsArray(aErrors[i])) {
						aErrorData.push(aErrors[i]);
					} else {
						aErrorData.push(['', aErrors[i], '']);
					}
				}
				
			} else {
				throw new browserNs.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongParametrType);
			}
			break;
			
		case 2:
			aErrorData = [[arguments[0], arguments[1], '']];
			break;
			
		case 3:
			aErrorData = [[arguments[0], arguments[1], arguments[2]]];
			break;
			
		default:
			throw new browserNs.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongCountInputParameters);
			return;
	}
	
	browserNs.Render.Dialog.ShowErrors();
	this.RenderItems(aErrorData);
	
	if (this.ShowDetails && aErrorData.length) {
		this.SetSelected(0, true);
		browserNs.Render.Dialog.EnableErrorDetailsButton();
	}
}

ITHit.oNS.ErrorDialog.prototype.ShowDetailedError = function() {
	
	var selectedItems = this.GetSelectedItems();
	if (!this.ShowDetails || !selectedItems.length) {
		return;
	}
	
	var oItem = selectedItems[0];
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowDetailedError(this.GetValue(oItem, 'Source'), this.GetValue(oItem, 'Message'), this.GetValue(oItem, 'Body'));
}


