ITHit.oNS.InterfaceElements = function(sElementId) {
	
	this._Element = ITHit.Components.dijit.byId(sElementId);
	
	if (this._Element) {
		return null;
	}
}

ITHit.oNS.InterfaceElements.prototype.GetDisabled = function() {
	return this._Element.disabled;
}

ITHit.oNS.InterfaceElements.prototype.SetDisabled = function(bDisabled) {
	this._Element.setAttribute('disabled', !!bDisabled);
	return this._Element;
}

ITHit.oNS.InterfaceElements.prototype.SetChecked = function(bChecked) {
    this._Element.setAttribute('checked', !!bChecked);
    return this._Element;
}

ITHit.oNS.InterfaceElements.prototype.GetText = function() {
	return this._Element.label;
}

ITHit.oNS.InterfaceElements.prototype.SetText = function(sLabel) {
	
	if ('' === sLabel) {
		this._Element.showLabel = false;
		
	} else if (!this._Element.showLabel) {
		this._Element.showLabel = true;
	}
	
	return this._Element.setLabel(sLabel);
}

ITHit.oNS.InterfaceElements.prototype.GetIconClass = function() {
	return this._Element.iconClass;
}

ITHit.oNS.InterfaceElements.prototype.SetIconClass = function(sIconClass) {
	
	var oNsDojo = ITHit.Components.dojo;
	
	oNsDojo.removeClass(this._Element.iconNode, this.GetIconClass());
	oNsDojo.addClass(this._Element.iconNode, sIconClass);
	
	this._Element.setAttribute('iconClass', sIconClass);
}

ITHit.oNS.InterfaceElements.prototype.GetTooltip = function() {
	return this._Element.title;
}

ITHit.oNS.InterfaceElements.prototype.SetTooltip = function(sTitle) {
	this._Element.setAttribute('title', sTitle);
	return this._Element;
}

