ITHit.oNS.MenuHandlers.prototype.GetMenuHandler = function(menuId, menuItemId, items) {

	if (!menuId || !menuItemId || !this._HandlerLinks[menuId][menuItemId]) {
		return false;
	}
	
	return this._MakeClosure(this, this._HandlerLinks[menuId][menuItemId], items);
}

ITHit.oNS.MenuHandlers.prototype._MakeClosure = function(scope, func, items) {
	
	if (scope) {
		if (ITHit.Utils.IsString(func)) {
			return function(event) {scope[func](items, event);};
		} else {
			return function(event) {func.call(scope, items, event);};
		}
	} else {
		return function(event) {func(items, event);};
	}
}

