ITHit.oNS.KeyboardShortcutsHandlers.prototype.MakeAction = function(zone, action, event) {

	var urls;

	switch (zone) {

		case 'Actions:TreeNodeSelected':
			// items = this._Controller._Tree().GetSelectedNodeItem();
			urls = this._Controller._Tree().IsActive() ?
				this._Controller._Tree().GetSelectedNodeUrl() :
				null;
			break;

		case 'Actions:FileSelected':
		case 'Actions:FolderSelected':
		case 'Actions:Multiselection':
			urls = this._Controller._Grid().GetSelectedItemsList();
			break;
			
		case 'General:OpenedRoot':
		case 'Actions:BoxSelection':
			urls = this._Controller._url;
			break;

		// case 'Dialog:Errors':
			// break;

		// case 'Dialog:CustomProperties':
			// break;
	}

	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}

	var items = [];
	for (var i = 0, l = urls.length; i < l; i++) {
		var item = this.DispatchEvent('OnGetItem', urls[i]);
		items.push(item);
	}

	var handler = this.ZoneList[zone][action];

	if (!ITHit.Utils.IsArray(items)) {
		items = [items];
	}

	if (ITHit.Utils.IsFunction(this[handler])) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Controller._SetActive(this._Controller._index);
		this[handler](items, event);
	}
}

