ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.KeyboardShortcuts');

ITHit.oNS.ShortcutsController = function(element, controller, activeState) {
	
	var ajaxbrowserNs     = ITHit.WebDAV.Client.AjaxFileBrowser;
	    shortcutsNs       = ajaxbrowserNs.KeyboardShortcuts;
	
	this.ActiveState      = activeState;
	this.Handlers         = new ajaxbrowserNs.Handlers.KeyboardShortcutsHandlers(controller);
	this.CoverageZones    = new shortcutsNs.CoverageZones();
	this.Shortcuts        = new shortcutsNs.ShortcutsParser();
	this.ShortcutHash     = this.Shortcuts.GetParsedHashes();
	this.ZoneActions      = this.CoverageZones.GetCoverageZones();
	this.RepetableEvents  = this.Shortcuts.GetRepeatableEvents();
	this.DisabledEvents   = this.Shortcuts.GetDisabledEvents();
	this.KPWorkaroundFlag = ITHit.DetectBrowser.IE
	this.Cache            = {
			KeyHash: null,
			Zone:    null,
			Disable: false,
			Recheck: true
		};
	
	this.Handlers.AddListener('OnGetItem', '_OnGetItemHandler', this);
	
	ITHit.Events.AttachEvent(document, 'onkeydown',  ITHit.Utils.MakeScopeClosure(this, 'OnKeyDownHandler'));
	// Always stop specified events.
	ITHit.Events.AttachEvent(document, 'onkeypress', ITHit.Utils.MakeScopeClosure(this, 'OnKeyPressHandler'));
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Handlers.KeyboardShortcutsHandlers.baseConstructor.call(this);
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Handlers.KeyboardShortcutsHandlers.base;
}

ITHit.Extend(ITHit.oNS.ShortcutsController, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.ShortcutsController.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.KeyboardShortcuts.ShortcutsController';
}

ITHit.oNS.ShortcutsController.prototype.EnterZone = function(zone) {
	this.CoverageZones.EnterZone(zone);
	this.Cache.Recheck = true;
}

ITHit.oNS.ShortcutsController.prototype.LeaveZone = function(zone) {
	this.CoverageZones.LeaveZone(zone);
	this.Cache.Zone    = null;
	this.Cache.Recheck = true;
}

ITHit.oNS.ShortcutsController.prototype.NewItemSelected = function() {
	this.Cache.Recheck = true;
}

ITHit.oNS.ShortcutsController.prototype.OnKeyPressHandler = function(event) {
	event = event || window.event;
		
	// Ignore keyboard capture whether control is not active.
	if (!this.ActiveState) {
		return;
	}
	
	var keyHash    = this.Shortcuts.GetEventKeyCombinationHash(event),
	    hashAction = this.ShortcutHash[keyHash];
	
	if (hashAction && this.DisabledEvents[hashAction]) {
		ITHit.Events.Stop(event);
	}
}

ITHit.oNS.ShortcutsController.prototype.OnKeyDownHandler = function(event) {
	event = event || window.event;

	// Disable keyboard shortcuts for input/textarea elements
    if (ITHit.WebDAV.Client.AjaxFileBrowser.Render.RenderController.isFormFieldTarget(event)) {
        return true;
    }

	// Ignore keyboard capture whether control is not active.
	if (!this.ActiveState) {
		return;
	}
	
	return this._CallAction(event);
}

ITHit.oNS.ShortcutsController.prototype._CallAction = function(event) {

	if (this.KPWorkaroundFlag) {
		this.OnKeyPressHandler(event);
	}
	
	var keyHash    = this.Shortcuts.GetEventKeyCombinationHash(event),
	    hashAction = this.ShortcutHash[keyHash],
	    curZone    = this.CoverageZones.GetCurrentZone(),
	    cache      = this.Cache;
	
	if (!hashAction || (!this.RepetableEvents[hashAction] && (keyHash == cache.KeyHash) && cache.Zone && !cache.Recheck)) {
		if (hashAction && this.Cache.Disable) {
			ITHit.Events.Stop(event);
			return true;
		}
		
		return;
	}
	
	this.Cache.Zone    = this.CoverageZones.GetCurrentZone();
	this.Cache.KeyHash = keyHash;
	this.Cache.Disable = false;
	
	var actionZone = this.ZoneActions[this.Cache.Zone];

	// Find whether action assiged for current zone and key hash.
	if (actionZone && actionZone[hashAction]) {
		this.Handlers.MakeAction(this.Cache.Zone, hashAction, event);
		this.Cache.Disable = true;
		
		ITHit.Events.Stop(event);
		return true;
	}
}

ITHit.oNS.ShortcutsController.prototype.OnKeyUpHandler = function(event) {
	var event = event || window.event;

	// Disable keyboard shortcuts for input/textarea elements
    if (ITHit.WebDAV.Client.AjaxFileBrowser.Render.RenderController.isFormFieldTarget(event)) {
        return true;
    }
		
	// Ignore keyboard capture whether control is not active.
	if (!this.ActiveState) {
		return;
	}
	
	if (!this._CallAction(event)) {
		this.DispatchEvent('OnKeyUp', event);
	}
}

ITHit.oNS.ShortcutsController.prototype.OnStateChangeHandler = function(activeState) {
	this.ActiveState = activeState;
}

ITHit.oNS.ShortcutsController.prototype._OnGetItemHandler = function(url) {
	return this.DispatchEvent('OnGetItem', url);
}

/**
 *
 * @class ITHit.WebDAV.Client.AjaxFileBrowser.Render.CommandsInfo.ItemView
 * @extends Function
 */
ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Render.CommandsInfo.ItemView', null, {

    _Node: null,

    /**
     * @type {ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseCommand}
     */
    _Command: null,

    /**
     *
     * @param {ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseCommand} oCommand
     * @param {Node} oRootNode
     * @constructor
     */
    constructor: function(oCommand, oRootNode) {
        this._Command = oCommand;

        this._Render(oRootNode);
    },

    /**
     *
     * @returns {Node}
     */
    GetNode: function() {
        return this._Node;
    },

    /**
     *
     * @param {ITHit.WebDAV.Client.AjaxFileBrowser.Commands.ProgressInfo} oProgressInfo
     * @constructor
     */
    UpdateProgress: function(oProgressInfo) {
        ITHit.Components.dojo.query('.progress div', this._Node)[0].style.width = oProgressInfo.GetPercent() + '%';
        ITHit.Components.dojo.query('.status', this._Node)[0].innerHTML = ITHit.Utils.HtmlEscape(oProgressInfo.GetText());

		this._UpdateTitle();
    },

    _Render: function(oRootNode) {
        // Create element
        this._Node = ITHit.Utils.CreateDOMElement({
            nodeName: 'LI',
            childNodes: [
                {
                    nodeName: 'DIV',
                    className: 'status-container',
                    childNodes: [
                        {
                            nodeName: 'DIV',
                            text: 'Loading...',
                            className: 'title'
                        },
                        {
                            nodeName: 'DIV',
                            text: '&nbsp;',
                            className: 'status'
                        },
                        {
                            nodeName: 'DIV',
                            className: 'progress',
                            childNodes: [
                                {
                                    nodeName: 'DIV'
                                }
                            ]
                        }
                    ]
                },
                {
                    nodeName: 'A',
                    href: 'javascript:void(0)',
                    className: 'button-cancel iconCancel'
                }
            ]
        });
        oRootNode.appendChild(this._Node);

        // Set title
		this._UpdateTitle();

        // Subscribe on click cancel button
        ITHit.Components.dojo.query('.button-cancel', this._Node)[0].onclick = ITHit.Utils.MakeScopeClosure(this, '_OnCancel');
    },

	_UpdateTitle: function() {
		var sTitle = this._Command.GetProcessTitle();
		if (this._Command.IsCancelled()) {
			sTitle = ITHit.Phrases.AjaxFileBrowser.Commands.CancelCommand.Paste(sTitle)
		}
		ITHit.Components.dojo.query('.title', this._Node)[0].innerHTML = ITHit.Utils.HtmlEscape(sTitle);
	},

	_OnCancel: function(oEvent) {
        oEvent.preventDefault();

        this._Node.className += 'cancelled';
		this._UpdateTitle();

        this._Command.Abort();
	}

});

;
(function() {

    /**
     *
     * @class ITHit.WebDAV.Client.AjaxFileBrowser.Render.CommandsInfo.ContainerView
     * @extends Function
     */
    var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Render.CommandsInfo.ContainerView', null, {

        _Node: null,
        _UlNode: null,

        _Controller: null,

        _InfoItems: null,

        _LazyCreateTimers: null,

        constructor: function(oController, oRootNode) {
            this._Controller = oController;
            this._InfoItems = {};
            this._LazyCreateTimers = {};

            this._Render(oRootNode);
        },

        _Render: function(oRootNode) {
            // Create element
            this._Node = ITHit.Utils.CreateDOMElement({
                nodeName: 'DIV',
                className: 'commands-info',
                childNodes: [
                    {

                        nodeName: 'UL'
                    }
                ]
            });
            oRootNode.appendChild(this._Node);
            this._UlNode = ITHit.Components.dojo.query('ul', this._Node)[0];

            ITHit.Events.AddListener(this._Controller.Commands, 'OnCommandStart', '_OnCommandStart', this);
            ITHit.Events.AddListener(this._Controller.Commands, 'OnCommandProgress', '_OnCommandProgress', this);
            ITHit.Events.AddListener(this._Controller.Commands, 'OnCommandFinish', '_OnCommandFinish', this);
        },

        _RefreshVisible: function() {
            var hasItems = false;
            for (var sCommandId in this._InfoItems) {
                if (this._InfoItems.hasOwnProperty(sCommandId)) {
                    hasItems = true;
                    break;
                }
            }

            //this._Node.style.display = hasItems ? 'block' : 'none';
        },

        _OnCommandStart: function(oCommand) {
            var that = this;
            var sCommandId = oCommand.GetUniqueId();

			// Skip some commands
			if (oCommand instanceof ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadSupportedFeaturesCommand) {
				return;
			}

            // Lazy create - not show `loading` for quick requests
            this._LazyCreateTimers[sCommandId] = setTimeout(function() {
                // Create info item view
                that._InfoItems[sCommandId] = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.CommandsInfo.ItemView(oCommand, that._UlNode);

                // Check for show container
                that._RefreshVisible();
            }, self.LAZY_CREATE_DELAY);
        },

        /**
         *
         * @param {ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseCommand} oCommand
         * @param {ITHit.WebDAV.Client.AjaxFileBrowser.Commands.ProgressInfo} oProgressInfo
         * @private
         */
        _OnCommandProgress: function(oCommand, oProgressInfo) {
            var oInfoItemView = this._InfoItems[oCommand.GetUniqueId()];
            if (!oInfoItemView) {
                return;
            }

            oInfoItemView.UpdateProgress(oProgressInfo)
        },

        _OnCommandFinish: function(oCommand) {
            var sCommandId = oCommand.GetUniqueId();

            // Clear timer - no create
            if (this._LazyCreateTimers[sCommandId]) {
                clearTimeout(this._LazyCreateTimers[sCommandId]);
            }

            var oItemView = this._InfoItems[sCommandId];
            if (oItemView) {
                this._UlNode.removeChild(oItemView.GetNode());
                delete this._InfoItems[sCommandId];
            }

            // Check for hide container
            this._RefreshVisible();
        }

    }, {

        LAZY_CREATE_DELAY: 10

    });

})();

