	this._showLeftPane        = true;
	this._showQuickUploadPane = true;
	this._leftPaneStyle       = 'tree';
	this._url                 = '';
	this._DragDrop            = new renderNs.DragDrop.DragController(this.FileIconsPath, this.ImageTypes, this.Settings.GetRootNode());
	this._dialog              = new renderNs.Dialog(this);
	this._tree                = new renderNs.TreeController(this._control._GetTreeId(), this);
	this._contextMenu         = new renderNs.MenuController(this, menuHandlers);
	this._upload              = new browserNs.UploadController('ithit_interface_file_upload_'+ this._index, 'ithit_interface_file_uploadInfo_'+ this._index, this._url, this, this.ProgressRefreshTime);
	this._State               = new renderNs.StateController(this.Settings.GetRootNode());
	this._Shortcuts           = new browserNs.KeyboardShortcuts.ShortcutsController(this.Settings.GetRootNode(), this, this._State.GetState());
	this._grid                = new renderNs.DataView.DataViewAdapter('ithit_interface_folderView_'+ this._index, this._MofifyInstructions.FilesView, this.ImageTypes, this.PreventImageCaching, this.ShowImagePreview, this._ContextHelp);
	this._BoxSelection        = new renderNs.BoxSelection.SelectionController(this.Settings.GetRootNode(), 'ithit_interface_folderView_'+ this._index);
	
	ITHit.Events.AddListener(menuHandlers,       'OnGetAbsolutePath',      'OnGetAbsolutePathHandler',       this);
	
	// Context menu events.
	ITHit.Events.AddListener(this._contextMenu,  'OnTreeNodeMenuOpen',     'TreeNodeMenuOpenHandler',        this);
	ITHit.Events.AddListener(this._contextMenu,  'OnTreeNodeMenuClose',    'TreeNodeMenuCloseHandler',       this);
	
	// Upload events.
	this._upload.AddListener('OnLoad',           'UploadCompliteHandler',  this);
	this._upload.AddListener('OnContextMenu',    'OnUploadItemContextMenuHandler',  this);
	this._upload.AddListener('OnRowDoubleClick', 'OnUploadItemDoubleClickHandler',  this);
	
	// Render controller events.
	ITHit.Events.AddListener(this,               'OnSetFileIconsPath',     'OnSetFileIconsPathHandler',      this._DragDrop);
	ITHit.Events.AddListener(this,               'OnSetImageTypes',        'OnSetImageTypesHandler',         this._DragDrop);
	
	// Box selection events.
	ITHit.Events.AddListener(this._BoxSelection, 'OnBoxSelectionStart',    'OnBoxSelectionStartHandler',     this);
	ITHit.Events.AddListener(this._BoxSelection, 'OnBoxSelect',            'OnBoxSelectHandler',             this);
	ITHit.Events.AddListener(this._BoxSelection, 'OnGetSelectionContext',  'OnGetSelectionContextHandler',   this);
	ITHit.Events.AddListener(this._BoxSelection, 'OnBoxSelectionEnd',      'OnBoxSelectionEndHandler',       this);
	ITHit.Events.AddListener(this._BoxSelection, 'OnScrollTop',            'OnScrollTopHandler',             this);
	ITHit.Events.AddListener(this._BoxSelection, 'OnScrollLeft',           'OnScrollLeftHandler',            this);
	ITHit.Events.AddListener(this._BoxSelection, 'OnMouseDown',            'SetActiveState',                 this);
	
	// Drag & Drop events.
	ITHit.Events.AddListener(this._DragDrop,     'OnGetDragDropTargetDataByElement', 'OnGetDragDropTargetDataHandler', this);
	ITHit.Events.AddListener(this._DragDrop,     'OnDragSuccess',          'OnDragSuccessHandler',           this);
	ITHit.Events.AddListener(this._DragDrop,     'OnDragFail',             'OnDragFailHandler',              this);
	ITHit.Events.AddListener(this._DragDrop,     'OnDragStart',            'OnDragStartHandler',             this);
	ITHit.Events.AddListener(this._DragDrop,     'OnDragEnd',              'OnDragEndHandler',               this);
	
	// State events.
	ITHit.Events.AddListener(this._State,        'OnStateChange',          'OnStateChangeHandler',           this._Shortcuts);
	
	// Grid events.
	this._grid.AddListener('OnGetAbsolutePath',  'OnGetAbsolutePathHandler',  this);
	this._grid.AddListener('OnSelectionChanged', 'OnSelectionChangedHandler', this);
	this._grid.AddListener('OnRowContextMenu',   'OnRowContextMenuHandler',   this);
	this._grid.AddListener('OnRowClick',         'OnRowClickHandler',         this);
	this._grid.AddListener('OnGridMouseDown',    '_OnGridMouseDownHandler',   this);
	this._grid.AddListener('OnRowDoubleClick',   'OpenGridItem',              this);
	//this._grid.AddListener('OnCallUserDefinedFunction', '_OnCallUserDefinedFunctionHandler', this);
	ITHit.Events.AddListener(this,               'OnSetImageTypes',           'SetImageTypes',               this._grid);
	ITHit.Events.AddListener(this,               'OnSetShowImagePreview',     'SetShowImagePreview',         this._grid);
	
	// Shortcuts events.
	this._Shortcuts.AddListener('OnGetItem',     'OnGetItemHandler',          this);
	
	this._UploadRefreshTimer          = null;
	this._FilesUploadedWithoutRefresh = 0;
	
	this._hiddenTree;
	this._hiddenFilesView;
