ITHit.oNS.RenderController.NewFolderDialog = function(sUrl) {
	
	// Get references for namespaces.
	var oNs           = ITHit.WebDAV.Client.AjaxFileBrowser;
	var oControllerNs = oNs.Controller;
	
	// Active controller index.
	var iIndex  = oControllerNs._GetActive();
	
	// Get active controller.
	var oController = oControllerNs.GetByIndex(iIndex);
	var sUrl = sUrl || oController._url || '';
	
	if (!sUrl) {
		return false;
	}
	
	oNs.Render.Dialog.NewFolder(sUrl);
}

