ITHit.oNS.RenderController.ShowThumbnail = function(oImg, iSize) {
	
	iSize = parseInt(iSize);
	
	if ((oImg.height > iSize) && (oImg.width > iSize)) {
		
		if (oImg.height >= oImg.width) {
			oImg.style.height = iSize +'px';
			oImg.style.width  = 'auto';
		}
		else {
			oImg.style.width  = iSize +'px';
			oImg.style.height = 'auto';
		}
	}
	else if ( (oImg.height > iSize) || (oImg.width > iSize) ) {
		
		if (oImg.height > iSize) {
			oImg.style.width  = 'auto';
			oImg.style.height = iSize +'px';
		}
		else {
			oImg.style.width  = iSize +'px';
			oImg.style.height = 'auto';
		}
	}
	
	oImg.style.visibility = 'visible';
	oImg.onload = null;
}

ITHit.oNS.RenderController.prototype.GetControl = function(sControlId) {
	
	if (0 === sControlId.indexOf(this._ElementsIdPrefix)) {
		sControlId += '_'+ this.GetIndex();
	}
	
	return new ITHit.WebDAV.Client.AjaxFileBrowser.Render.InterfaceElements(sControlId);
}

ITHit.oNS.RenderController.prototype.SetTreeActive = function() {
	
	if (!this._tree.IsActive()) {
		this._tree.SetActive();
		this.EnterZone('Actions:TreeNodeSelected');
	}
}

ITHit.oNS.RenderController.prototype.SetTreeInactive = function() {
	
	if (this._tree.IsActive()) {
		this._tree.SetInactive();
		this.LeaveZone('Actions:TreeNodeSelected');
	}
}

/**
 * Disable action for keyboard events in forms: input/textarea
 * @see AJAXBR-246
 * @param event
 * @returns {boolean}
 * @private
 */
ITHit.oNS.RenderController.isFormFieldTarget = function(event) {
	event = event || window.event;
	var oElement = event.target || event.srcElement;
	var sTagName = oElement.tagName.toLowerCase();
    return oElement.className.indexOf('dojoxGridHiddenFocus') === -1 && (sTagName === 'input' || sTagName === 'textarea');
}

