ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Handlers');

ITHit.oNS.Button = function(id) {
	this._Button = ITHit.Components.ihDijit.byId(id);
	this._Id     = id;
}

ITHit.oNS.Button.prototype.Disable = function() {
	if (!this._Button) {
		return false;
	}
	this._Button.set('disabled', true);

    var element = document.getElementById(this._Id);
    if (element) {
        element.blur();
    }
}

ITHit.oNS.Button.prototype.Enable = function() {
	if (!this._Button) {
		return false;
	}
	this._Button.set('disabled', false);
}


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser.Handlers');

ITHit.oNS.InterfaceHandlers = function(controller) {
	
	this._Controller = controller;
	this.Url;
	
	this.DeleteButton;
	this.DownloadButton;
	this.CopyButton;
	this.CutButton;
	this.PasteButton;
	this.RedoButton;
	this.InfoButton;
	this.UndoButton;
    this.CopyCutMode;
    this.EditButton;
    this.CustomPropertiesButton;
    this.VersionButton;
    this.EjectButton; // pyao: artf43472
    this.UploadButton; //vkorotchenko: artf44337
    this.PlayButton;	// pyao: artf45174	
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Handlers.InterfaceHandlers.baseConstructor.call(this);
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Handlers.InterfaceHandlers.base;
}

ITHit.Extend(ITHit.oNS.InterfaceHandlers, ITHit.WebDAV.Client.AjaxFileBrowser.AjaxFileBrowserBase);

ITHit.oNS.InterfaceHandlers.prototype._GetClassName = function() {
	return 'ITHit.WebDAV.Client.AjaxFileBrowser.Handlers.InterfaceHandlers';
}


// Add a button to this method if you want to show it on a toolbar
ITHit.oNS.InterfaceHandlers.prototype._Initiate = function() {
	
	var handlers = ITHit.WebDAV.Client.AjaxFileBrowser.Handlers,
	    index = this._Controller._index;
	
	this.DeleteButton   = new handlers.Button('ithit_interface_delete_'+ index);
	this.UploadButton   = new handlers.Button('ithit_interface_upload_'+ index);  //vkorotchenko: artf44337
	this.DownloadButton = new handlers.Button('ithit_interface_download_'+ index);
	this.CopyButton     = new handlers.Button('ithit_interface_copy_'+ index);
	this.CutButton      = new handlers.Button('ithit_interface_cut_'+ index);
	this.PasteButton    = new handlers.Button('ithit_interface_paste_'+ index);
	this.RedoButton     = new handlers.Button('ithit_interface_redo_'+ index);
	this.InfoButton     = new handlers.Button('ithit_interface_info_'+ index);
	this.UndoButton     = new handlers.Button('ithit_interface_undo_'+ index);
    this.EditButton     = new handlers.Button('ithit_interface_edit_'+ index);
    this.CustomPropertiesButton = new handlers.Button('ithit_interface_custom_prop_'+ index);
    this.VersionButton = new handlers.Button('ithit_interface_versions_'+ index);
    this.UpButton = new handlers.Button('ithit_interface_up_'+ index);
    this.EjectButton = new handlers.Button('ithit_interface_eject_' + index);  // pyao: artf43472
    this.PlayButton = new handlers.Button('ithit_interface_play_' + index);		// pyao: artf45174
}

ITHit.oNS.InterfaceHandlers.prototype.GetInterfaceHandler = function(interfaceHandlerId, items) {
	
	if (!this[interfaceHandlerId]) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongInterfaceHandler.Paste(interfaceHandlerId));
	}
	
	return this._MakeClosure(this, interfaceHandlerId, items);
}

ITHit.oNS.InterfaceHandlers.prototype._MakeClosure = function(scope, func, items) {
	
	if (scope) {
		if (ITHit.Utils.IsString(func)) {
			return function(event) {scope[func](items, event);};
		} else {
			return function(event) {func.call(scope, items, event);};
		}
	} else {
		return function(event) {func(items, event);};
	}
}

// Configures toolbar buttons enable/disable state when user selects/deselects some folders/files
ITHit.oNS.InterfaceHandlers.prototype.OnSelectedItemsChangedHandler = function() {
	
	var selectedLength = this.DispatchEvent('OnGetSelectedItemsCount');

	if (selectedLength > 0) {
		this.DeleteButton.Enable();
		this.CopyButton.Enable();
		this.CutButton.Enable();

        if (selectedLength === 1) {
            this.InfoButton.Enable();
            this.CustomPropertiesButton.Enable();

            var oItem = this.DispatchEvent('OnGetSelectedGridItems')[0]; // item is a selected folder/file
            // artf44337 start
            if (oItem.Href.split("/").length -1 > 3){
                this.UploadButton.Enable();
            }
            //artf44337 end
            if (oItem.ResourceType == ITHit.WebDAV.Client.ResourceType.Resource) { // check if it is a file
            	this.DownloadButton.Enable();
            	this.EditButton.Enable();

            	// Check if versioning is enabled fo this item. Do not use Item.SupportedFeatures().VersionControl, this will cause request to server. 
            	// TODO: replace CheckedOut/CheckedIn with VersionControlled property
            	if (oItem.Item.CheckedIn === false && oItem.Item.CheckedOut === false) {
            		this.VersionButton.Disable();
            	} else {
            		this.VersionButton.Enable();
            	}

            	// ntgr start: artf45174
				// Check if it is a media file
                // NETGEAR: DS: play button enabled for all non-folders now
            	//if (this._Controller.isMediaFile(oItem.Href)) {
                if (1) {
	                this.PlayButton.Enable();
				} else {
            		this.PlayButton.Disable();
            	}
            	// ntgr end
            }
            else {
                this.DownloadButton.Disable();
                this.EditButton.Disable();
                this.VersionButton.Disable();
                this.PlayButton.Disable();	// pyao: artf45174
            }
        }
        else {
            this.InfoButton.Disable();
            this.CustomPropertiesButton.Disable();
            this.DownloadButton.Disable();
            this.EditButton.Disable();
            this.VersionButton.Disable();
            this.PlayButton.Disable();	// pyao: artf45174
        }

    }
    else {
        this.UploadButton.Disable();  // artf44337
        this.InfoButton.Disable();
        this.CustomPropertiesButton.Disable();
        this.DownloadButton.Disable();
        this.EditButton.Disable();
        this.DeleteButton.Disable();
        this.CopyButton.Disable();
        this.CutButton.Disable();
        this.VersionButton.Disable();
        this.PlayButton.Disable();	// pyao: artf45174
    }
}


ITHit.oNS.InterfaceHandlers.prototype.OnSelectedFolderChangedHandler = function() {
	this.Url = this._Controller._url;
	//vkorotchenko artf44337 start
	if (this.Url.split("/").length - 1 > 3){
        this.UploadButton.Enable();
        } else {
            this.UploadButton.Disable();
        }
        //vkorotchenko artf44337 end

	if (this._Controller._baseUrl === this.Url) {
		this.UpButton.Disable();
	} else {
		this.UpButton.Enable();
	}
}

ITHit.oNS.InterfaceHandlers.prototype.OnPasteHandler = function() {
	if ('CUT' == this.CopyCutMode) {
		this.PasteButton.Disable();
		this.CopyCutMode = null;
	}
}

ITHit.oNS.InterfaceHandlers.prototype.OnCopyHandler = function() {
	this.CopyCutMode = 'COPY';
	this.PasteButton.Enable();
}

ITHit.oNS.InterfaceHandlers.prototype.OnCutHandler = function() {
	this.CopyCutMode = 'CUT';
	this.PasteButton.Enable();
}

ITHit.oNS.InterfaceHandlers.prototype.OnExecuteCommandHandler = function() {
	this.UndoButton.Enable();
}

ITHit.oNS.InterfaceHandlers.prototype.OnUndoHandler = function() {
	
	var session = this._Controller.Commands;
	
	if (session.IsFirst()) {
		this.UndoButton.Disable();
	}
	
	if (!session.IsLast()) {
		this.RedoButton.Enable();
	}
}

ITHit.oNS.InterfaceHandlers.prototype.OnRedoHandler = function() {
	
	var session = this._Controller.Commands;
	
	if (!session.IsFirst()) {
		this.UndoButton.Enable();
	}
	
	if (session.IsLast()) {
		this.RedoButton.Disable();
	}
}


