ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.Session = function(sHost) {
	
	var oNsBrowser = ITHit.WebDAV.Client.AjaxFileBrowser;
	
	try {
		this._Session = new ITHit.WebDAV.Client.WebDavSession();
	} catch(e) {
		if ('The trial period has expired.' == e) {
			ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.TrialPeriodExpired();
		} else {
			throw e;
		}
	}
	this.Host      = sHost;
	this.Instances = {
		Folder:   oNsBrowser.Folder,
		Resource: oNsBrowser.Resource,
		HierItem: oNsBrowser.HierarchyItem
	}

	this._ClassId  = 'ITHit.WebDAV.Client.AjaxFileBrowser.Session_'+ ITHit.WebDAV.Client.AjaxFileBrowser.Session._Counter++;
}

ITHit.oNS.Session._Counter = 0;

ITHit.oNS.Session.prototype.GetWebDavSession = function() {
	return this._Session;
}

ITHit.oNS.Session.prototype._AlertException = function(e, sMethod) {
	
	switch(sMethod) {
		case 'Session.OpenFolder':
			return;
	}

	var sMessage = this._GetMessageFromException(e, sMethod);
	// @todo
	if (ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(sMessage);
	} else if (typeof window.console !== 'undefined') {
		console.error('TODO', sMessage);
	}
}

ITHit.oNS.Session.prototype._GetMessageFromException = function(e, sMethod) {
	var aMessageLines = [];
	aMessageLines.push(ITHit.Phrases.AjaxFileBrowser.Interface.OperationCannotBePerformed);
	aMessageLines.push(sMethod);

	if (e instanceof ITHit.WebDAV.Client.Exceptions.WebDavHttpException) {
		aMessageLines.push(e.Message + " " + e.Status.Code + " " + e.Status.Description);

		// Find which items failed to copy.
		for (var i = 0, l = e.Multistatus.Responses.length; i < l; i++) {
			var oResponse = e.Multistatus.Responses[i];
			aMessageLines.push(oResponse.Message + " " + oResponse.Status.Code + " " + oResponse.Status.Description);
		}
	} else {
		aMessageLines.push(e.message);
	}

	return aMessageLines.join("\n");
}

ITHit.oNS.Session.prototype.GetAbsolutePath = function(sUrl, bNotEncode) {
						
	if (/^\//.test(sUrl)) {
		sUrl = this.Host + sUrl.substr(1);
	} else {
		sUrl = this.Host + sUrl
	}
	if (bNotEncode) {
		return sUrl;
	}
	
	return ITHit.WebDAV.Client.Encoder.Encode(sUrl);
}

ITHit.oNS.Session.prototype.OpenItem = function(sUrl) {
    try {
        var sAbsoluteUrl = this.GetAbsolutePath(sUrl, true);
        var oItem = this._Session.OpenItem(sAbsoluteUrl);

    } catch(e) {
        this._AlertException(e, 'Session.OpenItem');
        return false;
    }

    if (oItem instanceof ITHit.WebDAV.Client.Folder) {
        return new this.Instances.Folder(oItem);
    }
    else {
        return new this.Instances.Resource(oItem);
    }
}

ITHit.oNS.Session.prototype.CreateFolderAsync = function (sUrl, sLockToken, fCallback) {
    return this._Session.CreateFolderAsync(sUrl, sLockToken, fCallback);
}

ITHit.oNS.Session.prototype.GetUploadProgress = function(sUrl) {
	return this._Session.GetUploadProgress(sUrl);
}

ITHit.oNS.Session.prototype.GetUploadProgressAsync = function (sUrl, fCallback) {
    return this._Session.GetUploadProgressAsync(sUrl, fCallback);
}

ITHit.oNS.Session.prototype.GetSupportedFeaturesAsync = function (sUrl, fCallback) {
    return this._Session.GetSupportedFeaturesAsync(sUrl, fCallback);
}

ITHit.oNS.Session.prototype.DeleteAsync = function (sUrl, oLockTokens, fCallback) {
    return this._Session.DeleteAsync(sUrl, oLockTokens, fCallback);
}

ITHit.oNS.Session.prototype.CancelUploadAsync = function (sUrl, sLockToken, fCallback) {
    return this._Session.CancelUploadAsync(sUrl, sLockToken, fCallback);
}

ITHit.oNS.Session.prototype.ItemExists = function(sUrl) {
	
	try {
		this._Session.OpenItem(ITHit.WebDAV.Client.Encoder.Encode(sUrl));
		return true;
		
	} catch (e) {
		
		if (e instanceof ITHit.WebDAV.Client.Exceptions.NotFoundException) {
			return false;
		}
		
		this._AlertException(e, 'Session.ItemExists');
		return false;
	}
}

ITHit.oNS.Session.prototype.ItemExistsAsync = function (sUrl, fCallback) {

    try {
        return this._Session.OpenItemAsync(ITHit.WebDAV.Client.Encoder.Encode(sUrl),
            function (oResult) {
                if (fCallback) {
                    var oItemExistsResult = new ITHit.WebDAV.Client.AsyncResult(oResult.IsSuccess, oResult.IsSuccess, oResult.Error);
                    fCallback.call(this, oItemExistsResult);
                }
            });

    } catch (e) {
        this._AlertException(e, 'Session.ItemExists');
    }
}


ITHit.oNS.Session.prototype.CancelUpload = function(oResource) {
	
	if (!(oResource instanceof this.Instances.Resource)) {
		throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.Exceptions.ResourceInstanceExpected);
	}
	
	try {
		return oResource.Item.CancelUpload();
		
	}
	catch(e) {
		return false;
	}
}

ITHit.oNS.Session.prototype.SetCredentials = function(user, pass) {
	return this._Session.SetCredentials(user, pass);
}

ITHit.oNS.Session.prototype.GetIisDetected = function () {
    return this._Session.GetIisDetected();
}

ITHit.oNS.Session.prototype.Undelete = function(sUrl) {
	
	try {
		return this._Session.Undelete(sUrl);
	} catch(e) {
		return false;
	}
}

ITHit.oNS.Session.prototype.toString = function() {
	return this._ClassId;
}


