(function () {

	/**
	 *
	 * @class ITHit.WebDAV.Client.AjaxFileBrowser.Commands.RequestsProgressInfo
	 * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Commands.ProgressInfo
	 */
	var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Commands.RequestsProgressInfo', ITHit.WebDAV.Client.AjaxFileBrowser.Commands.ProgressInfo, {

        /**
         * @type {XMLHttpRequestProgressEvent[]}
         */
        _XhrProgresses: null,

		/**
         * @param {XMLHttpRequestProgressEvent[]} aXhrProgresses
		 * @constructor
		 */
		constructor: function (aXhrProgresses) {
            this._XhrProgresses = aXhrProgresses;

            // Calculate complete and total
            for (var i = 0, l = this._XhrProgresses.length; i < l; i++) {
                var oProgress = this._XhrProgresses[i];

                // Skip finished
                if (oProgress.loaded === oProgress.total) {
                    continue;
                }

                this._Complete += oProgress.loaded;
                this._Total += oProgress.total;
            }
		},

        /**
         *
         * @returns {string}
         */
        GetText: function() {
            return this.GetPercent() + '%';
        }

	});

})();


