(function () {

    /**
     *
     * @class ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadFolderCommand
     * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseRequestCommand
     */
    var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadFolderCommand', ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseRequestCommand, {

		/**
		 * @type {string}
		 */
		Href: null,

		/**
		 * @type {boolean}
		 */
		IgnoreCache: false,

        GetTitle: function() {
            return ITHit.Phrases.AjaxFileBrowser.Commands.Names.LoadFolder;
        },

        GetProcessTitle: function() {
			var sFolderName = self.GetNameFromHref(this.Href);
            return ITHit.Phrases.AjaxFileBrowser.Commands.Process.LoadFolder.Paste(sFolderName);
        },

        _Initialize: function() {
            if (this.Href === null) {
                throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Param `Href` is required in LoadFoldersCommand.');
            }

            this.Href = this._CommandsController.NormalizeFolderUrl(this.Href);
        },

		_ExecuteInternal: function () {
			ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadItemCommand.LoadInline(this, this.Href, false, function(oItem) {
				if (!oItem) {
					this._TriggerFinish();
					return;
				}

				// Load folder items
				this._LoadFolderItems(oItem, function (aChildren) {
					this._TriggerFinish(oItem, aChildren);
				});
			});
        },

		/**
		 *
		 * @param {ITHit.WebDAV.Client.AjaxFileBrowser.HierarchyItem} oItem
		 * @param {function} fCallback
		 * @protected
		 */
		_LoadFolderItems: function(oItem, fCallback) {
			// Find in cache
			if (!this.IgnoreCache && this._CommandsController.FoldersCollection.Has(oItem.Href)) {
				fCallback.call(this, this._CommandsController.FoldersCollection.Get(oItem.Href));
				return;
			}

			// Load from server
			var that = this;
			this.AddSessionRequest(oItem.Item.GetChildrenAsync(false, this._CommandsController.ChildrenProperties, function(oAsyncResult) {
                var aItems = [];

                if (!oAsyncResult.IsSuccess) {
					that.AddError(oAsyncResult.Error);
				} else {
                    for (var i = 0, l = oAsyncResult.Result.length; i < l; i++) {
                        aItems.push(oAsyncResult.Result[i] instanceof ITHit.WebDAV.Client.Folder
                            ? new ITHit.WebDAV.Client.AjaxFileBrowser.Folder(oAsyncResult.Result[i])
                            : new ITHit.WebDAV.Client.AjaxFileBrowser.Resource(oAsyncResult.Result[i]));
                    }

					// Save in cache
					that._CommandsController.FoldersCollection.Set(oItem.Href, aItems);
					for (var i = 0, l = aItems.length; i < l; i++) {
						that._CommandsController.ResourcesCollection.Set(aItems[i].Href, aItems[i]);
					}
				}

				fCallback.call(that, aItems);
			}));
		}

    });

})();

