(function () {

    /**
     *
     * @class ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadTreeFoldersCommand
     * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadFolderCommand
     */
    var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadTreeFoldersCommand', ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadFolderCommand, {

		/**
		 * @type {string}
		 */
		Href: null,

        _Items: null,
		_LoadedFolderItems: null,

        constructor: function() {
            this._super.apply(this, arguments);

            this._Items = {};
            this._LoadedFolderItems = {};
        },

        GetTitle: function() {
            return ITHit.Phrases.AjaxFileBrowser.Commands.Names.LoadTree;
        },

        GetProcessTitle: function() {
            var sFolderNameMatches = /([^\/]+)\/?$/.exec(this.Href);
            var sFolderName = sFolderNameMatches !== null ? sFolderNameMatches[1] : this.Href;
            return ITHit.Phrases.AjaxFileBrowser.Commands.Process.LoadTree.Paste(sFolderName);
        },

        _Initialize: function() {
            if (this.Href === null) {
                throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Param `Href` is required in LoadTreeFoldersCommand.');
            }

            this.Href = this._CommandsController.NormalizeFolderUrl(this.Href);
        },

		_ExecuteInternal: function () {
			var sBaseUrl = this._CommandsController.BaseUrl;
            var aPath = this.Href.substr(sBaseUrl.length).replace(/^\/|\/$/g, '').split('/');
			this._LoadRecursive(sBaseUrl, aPath)
        },

		/**
		 *
		 * @param {string} sCurrentPath
		 * @param {string[]} aPath
		 * @private
		 */
        _LoadRecursive: function (sCurrentPath, aPath) {
			ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadItemCommand.LoadInline(this, sCurrentPath, false, function(oItem) {
				if (!oItem) {
					this._TriggerFinish(this._Items, this._LoadedFolderItems);
					return;
				}

                // Store items
                this._Items[oItem.Href] = oItem;

				// Load folder items from server
				this._LoadFolderItems(oItem, function (aItems) {
					// Save in command
					this._LoadedFolderItems[sCurrentPath] = aItems;

					if (aPath.length === 0 || aPath[0] === '') {
						this._TriggerFinish(this._Items, this._LoadedFolderItems);
						return;
					}

					var sDirName = aPath.shift() + '/';
					this._LoadRecursive(sCurrentPath + sDirName, aPath);
				});
			});
        }

    });

})();

