(function () {

    /**
     *
     * @class ITHit.WebDAV.Client.AjaxFileBrowser.Commands.SearchCommand
     * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseRequestCommand
     */
    var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Commands.SearchCommand', ITHit.WebDAV.Client.AjaxFileBrowser.Commands.BaseRequestCommand, {

        /**
         * @type {string}
         */
        Href: null,

		/**
		 * @type {string}
		 */
		Query: null,

		/**
		 * @type {ITHit.WebDAV.Client.SearchQuery}
		 */
		QueryObject: null,

        /**
         * @type {boolean}
         */
		EnableContains: true,

        GetTitle: function() {
            return ITHit.Phrases.AjaxFileBrowser.Commands.Names.Search;
        },

        GetProcessTitle: function() {
            return ITHit.Phrases.AjaxFileBrowser.Commands.Process.Search.Paste(this.Query);
        },

        NormalizeQuery: function(sQuery) {
            // Trim
            sQuery = sQuery.replace(/^\s+|\s+$/g, '');

			// Escape _, %, \
			sQuery = sQuery.replace(/([_%\\])/g, '\\$1');

			// Replace Windows-style *, ? to %, _
			sQuery = sQuery.replace(/\*/g, '%');
			sQuery = sQuery.replace(/\?/g, '_');

			// Append percent in end, if simple query
			if (sQuery && /^".+"$/.test(sQuery) === false) {
				sQuery = sQuery.replace(/%?$/, '%')
			}

			// Trim quotes
			sQuery = sQuery.replace(/^"|"$/g, '');

            return sQuery;
        },

        _Initialize: function() {
            if (this.Href === null || this.Query === null) {
                throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Param `Href`, `Query` is required in SearchCommand.');
            }

            this.Query = this.NormalizeQuery(this.Query);
            this.Href = this._CommandsController.NormalizeFolderUrl(this.Href);
        },

		_ExecuteInternal: function () {
            // Skip empty query
            if (this.Query === '') {
                this._TriggerFinish([]);
                return;
            }

            var that = this;
			ITHit.WebDAV.Client.AjaxFileBrowser.Commands.LoadItemCommand.LoadInline(this, this.Href, false, function(oItem) {
				if (!oItem) {
                    that._TriggerFinish(null, []);
					return;
				}

                if (!(oItem instanceof ITHit.WebDAV.Client.AjaxFileBrowser.Folder)) {
                    that.AddError(new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.TrySearchByResource));
                    that._TriggerFinish(null, []);
                    return;
                }

				this.QueryObject = new ITHit.WebDAV.Client.SearchQuery(that.Query);
				this.QueryObject.SelectProperties = this._CommandsController.ChildrenProperties;
				this.QueryObject.EnableContains = this.EnableContains;

                that.AddSessionRequest(oItem.Item.SearchByQueryAsync(this.QueryObject, function(oAsyncResult) {
                    var aItems = [];

                    if (!oAsyncResult.IsSuccess) {
                        that.AddError(oAsyncResult.Error);
                    } else {
                        for (var i = 0, l = oAsyncResult.Result.length; i < l; i++) {
                            aItems.push(oAsyncResult.Result[i] instanceof ITHit.WebDAV.Client.Folder
                                ? new ITHit.WebDAV.Client.AjaxFileBrowser.Folder(oAsyncResult.Result[i])
                                : new ITHit.WebDAV.Client.AjaxFileBrowser.Resource(oAsyncResult.Result[i]));
                        }

                        // Save in cache
                        for (var i = 0, l = aItems.length; i < l; i++) {
                            that._CommandsController.ResourcesCollection.Set(aItems[i].Href, aItems[i]);
                        }
                    }

                    that._TriggerFinish(oItem, aItems);
                }));
			});
        }

    });

})();

