(function () {

	/**
	 *
	 * @class ITHit.WebDAV.Client.AjaxFileBrowser.Settings.BaseSettings
	 * @extends Function
	 */
	var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Settings.BaseSettings', null, {

		_Id: null,
		_RootNode: null,

		_Settings: null,

		_IsRendered: false,
		_Controller: null,

		constructor: function(oController) {
			this._Controller = oController;
		},

		/**
		 *
		 * @param {object} oSettings
		 */
		SetSettings: function(oSettings) {
			this._Settings = oSettings;

			this._SetInternal(oSettings);
			if (this._IsRendered) {
				this._SetInternalAfterRender(oSettings);
			}
		},

		TriggerRender: function() {
			if (this._IsRendered) {
				return;
			}

			this._IsRendered = true;
			this._SetInternalAfterRender(this._Settings);
		},

		/**
		 * @param {string|HTMLElement} mParam
		 */
		SetId: function(mParam) {
			// Check already set
			if (this._RootNode !== null) {
				return;
			}

			if (ITHit.Utils.IsString(mParam)) {
				this._Id = mParam;
				this._RootNode = document.getElementById(mParam);
			} else if (ITHit.Utils.IsDOMObject(mParam)) {
				// Generate id if no exists
				if (!mParam.id) {
					mParam.id = 'ithit_root_' + (new Date()).getTime();
				}

				this._Id = mParam.id;
				this._RootNode = mParam;
			} else {
				throw new ITHit.WebDAV.Client.Exceptions.InvalidConfigException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongElementIdOrObject);
			}
		},

		/**
		 * @returns {string}
		 */
		GetId: function() {
			return this._Id;
		},

		/**
		 * @param {HTMLElement} oNode
		 */
		SetRootNode: function(oNode) {
			this.SetId(oNode);
		},

		/**
		 * @returns {HTMLElement}
		 */
		GetRootNode: function() {
			return this._RootNode;
		},

		_SetInternal: function(oSettings) {
			this.SetLanguagePack(oSettings.Phrases);
			this.SetId(oSettings.Id);
		},

		/**
		 * Load phrases
		 * @param {object|null} oPhrases
		 */
		SetLanguagePack: function(oPhrases) {
		},

		SetResumeUploadSupported: function(bIsSupported) {
		},

		_SetInternalAfterRender: function(oSettings) {
			if (!ITHit.Utils.IsUndefined(oSettings.ResumeUploadSupported)) {
				this.SetResumeUploadSupported(oSettings.ResumeUploadSupported);
			}
		}

	}, {

		NormalizeObjectSettings: function(oSettings, oArguments) {
			// Old style constructor with three params
			if (!ITHit.Utils.IsObjectStrict(oSettings) || ITHit.Utils.IsDOMObject(oSettings)) {
				if (oArguments.length < 2) {
					throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.InvalidConfigException('To few arguments.');
				}
				if (oArguments.length > 4) {
					throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.InvalidConfigException('To many arguments.');
				}

				oSettings = {
					Id: oSettings,
					Url: oArguments[1],
					Style: oArguments[2],
					ClassName: oArguments[3]
				};
			}

			if (!oSettings.Id) {
				throw new ITHit.WebDAV.Client.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.EmptyElementParameter);
			}

			return oSettings;
		}

	});

})();


;
(function () {

	/**
	 *
	 * @class ITHit.WebDAV.Client.AjaxFileBrowser.Settings.DesktopSettings
	 * @extends ITHit.WebDAV.Client.AjaxFileBrowser.Settings.BaseSettings
	 */
	var self = ITHit.DefineClass('ITHit.WebDAV.Client.AjaxFileBrowser.Settings.DesktopSettings', ITHit.WebDAV.Client.AjaxFileBrowser.Settings.BaseSettings, {

		/**
		 * Load phrases
		 * @param {object|null} oPhrases
		 */
		SetLanguagePack: function(oPhrases) {
			ITHit.Phrases.LoadLocalizedJSON(ITHit.WebDAV.Client.AjaxFileBrowser.Phrases.EN, oPhrases);
		},

		SetPanelsVisible: function(oPanels) {
			// Set panels visible
			var oApiMapping = {
				Folders: 'SetShowFolders',
				FilesView: 'SetShowFilesView',
				Toolbar: 'SetShowToolbar',
				AddressBar: 'SetShowAddressBar',
				UploadPanel: 'SetShowUploadPanel',
				UploadProgressPanel: 'SetShowUploadProgressPanel'
			};
			for (var sPanelName in oApiMapping) {
				if (!oApiMapping.hasOwnProperty(sPanelName)) {
					continue;
				}

				if (oPanels[sPanelName] && !ITHit.Utils.IsUndefined(oPanels[sPanelName].Show)) {
					this._Controller[oApiMapping[sPanelName]](!!oPanels[sPanelName].Show);
				}
			}
		},

		SetMofifyInstructions: function(oPanels) {
			oPanels = ITHit.WebDAV.Client.AjaxFileBrowser.CodeConstructor.Clone(oPanels);
			this._Controller._MofifyInstructions = oPanels;

			if (oPanels.FilesView) {
				this._ProcessCustomColumns(oPanels.FilesView.Columns || []);
			}

			if (this._IsRendered) {
				// @todo re-render

				if (oPanels.FilesView) {
					this._Controller._Grid().Views.Grid.SetRowFormatter(oPanels.FilesView.RowFormatter);
					this._Controller._Grid().Views.Grid.SetCellFormatter(oPanels.FilesView.CellFormatter);
					this._Controller._Grid().Views.Grid.SetTableStructure(oPanels.FilesView);
				}
			}
		},

		SetResumeUploadSupported: function(bIsSupported) {
			this._Controller._upload.SetResumeSupported(bIsSupported);
		},

		_ProcessCustomColumns: function(aColumns) {
			// Custom columns
			for (var i = 0, l = aColumns.length; i < l; i++) {
				/** @type {{Id: string, CustomProperty: string|ITHit.WebDAV.Client.PropertyName, CustomPropertyName: string, CustomPropertyNamespace: string, Text: string, Tooltip: string, Formatter: function, Width: string, CellStyles: object, HeaderStyles: object}} */
				var oColumn = aColumns[i];

				if (typeof oColumn.CustomProperty === 'string') {
					var oNameParams = oColumn.CustomProperty.split(':');
					if (oNameParams.length !== 2) {
						throw new ITHit.Exception('Wrong format custom property `' + oColumn.CustomProperty+ '`. Need format: `myNamespace:myPropertyName`. Or use `CustomPropertyName` and `CustomPropertyNamespace` properties.');
					}

					// Create property instance
					oColumn.CustomProperty = new ITHit.WebDAV.Client.PropertyName(oNameParams[1], oNameParams[0]);
				} else if (oColumn.CustomPropertyName && oColumn.CustomPropertyNamespace) {
					oColumn.CustomProperty = new ITHit.WebDAV.Client.PropertyName(oColumn.CustomPropertyName, oColumn.CustomPropertyNamespace);
				}

				if (oColumn.CustomProperty instanceof ITHit.WebDAV.Client.PropertyName) {
					// @todo Do not push duplicates!
					this._Controller._ChildrenProperties.push(oColumn.CustomProperty);
				}
			}

		},

		/**
		 *
		 * @param {object} oSettings
		 */
		_SetInternal: function(oSettings) {
			this._super(oSettings);

			this.SetMofifyInstructions(oSettings.Panels || {});
		},

		/**
		 *
		 * @param {object} oSettings
		 */
		_SetInternalAfterRender: function(oSettings) {
			this._super(oSettings);

			this.SetPanelsVisible(oSettings.Panels || {});
		}

	});

})();


ITHit.oNS = ITHit.Declare('ITHit.WebDAV.Client.AjaxFileBrowser');

ITHit.oNS.Version = '3.0.0.2480';

ITHit.oNS.Controller = function (mParam/*, sBaseUrl, sStyle, sClass*/) {
	// Get reference for namespace.
	this._ns = ITHit.WebDAV.Client.AjaxFileBrowser;

	this._ChildrenProperties = [];
	this._MofifyInstructions = {};
	this._RefreshOnUpdateTimerId = null;
	this._SearchQuery = null;

	// Convert settings to object
	var oSettings = ITHit.WebDAV.Client.AjaxFileBrowser.Settings.DesktopSettings.NormalizeObjectSettings(mParam, arguments);

	this.Settings = new ITHit.WebDAV.Client.AjaxFileBrowser.Settings.DesktopSettings(this);
	this.Settings.SetSettings(oSettings);

    this.InitWithParams(oSettings);
}

// Extend class.
ITHit.Extend(ITHit.oNS.Controller, ITHit.oNS.Render.RenderController);

ITHit.oNS.Controller._Controllers = [];

ITHit.oNS.Controller._ActiveController = null;

ITHit.oNS.Controller._Counter = 0;

ITHit.oNS.Controller.prototype.GetIndex = function () {
    return this._index;
}

ITHit.oNS.Controller.prototype.InitWithParams = function (oSettings) {

    var oNsUndefined = ITHit.Utils.IsUndefined;
    this.defaultParams = {
		Url: oSettings.Url
	};

    var oConfig = ITHit.Config.AjaxFileBrowser;

    this._ElementsIdPrefix = 'ithit_';

    // Set config properties.
    for (var prop in oConfig) {
        if (
			!oConfig.hasOwnProperty(prop)
			|| (prop == 'ProtectedProperties')
		) {
            continue;
        }

        if (!oConfig.ProtectedProperties[prop]) {

            // Assign passed in constructor properties or from config section whether not defined.
            this[prop] = oNsUndefined(oSettings[prop])
		               ? oConfig[prop]
		               : oSettings[prop]
        } else {
            this[prop] = oConfig[prop];
        }

        // Normalize paths
        switch (prop) {
            case 'FileIconsPath':
            case 'MsOfficeTemplatesPath':
            case 'ThemesPath':
            case 'PluginsPath':
                this[prop] = this[prop].replace(/\/$/, '') + '/';
                break;
        }
    }

    // Additional config properties modifications.
    this.NotAllowedCharacters = this.NotAllowedCharacters.replace(/(\W)/g, '\\$1');

    // detect if editing of MS office documents is available
    this._SharePointOpenOrEditDocs = this.IsSharePointOpenDocumentsCtrlAvailable();

    ITHit.Components.dojo.setBlankGif(this._ns.Utils.GetBlankGifPath());

    // Assign base URL.
    var sServerRoot = location.protocol + '//' + location.host + '/';
    var sBaseServerUrl = ITHit.WebDAV.Client.Encoder.Decode((oSettings.Url || sServerRoot).replace(/^\//, sServerRoot).replace(/\/?$/, '/'));

    // Initiate url class.
    this._Utils = new this._ns.UrlUtils(sBaseServerUrl);

    // Assign base path.
    this._baseUrl = this._Utils.BasePath;

    // First history record for root address.
    this._RootHistoryUrl;

    // Whether root folder was not opened.
    this._RootNotOpened = true;

    this._NowOpenedFolder = null;

    // Add index.
    this._index = this._ns.Controller._Counter++;
    this._ClassId = 'ITHit.WebDAV.Client.AjaxFileBrowser.Controller_' + this._index;
    this._ns.Controller._Controllers[this._index] = this;

    var isBrowser = ITHit.DetectBrowser;
    this._DnDFilesSupported = (isBrowser.FF >= 3.6 || isBrowser.Safari >= 5 || isBrowser.Chrome >= 4 || isBrowser.IE >= 10 || isBrowser.Edge) && !(isBrowser.iPad || isBrowser.iPhone);

    ITHit.Components.dojo._loadInit();

    // Whether history navigation enabled.
	this.History = new ITHit.WebDAV.Client.AjaxFileBrowser.HistoryNavigation.HistoryController(this._Utils.GetRelativePath(sBaseServerUrl));
	this.History.SetEnabled(!!this.EnableHistoryNavigation);
	ITHit.Events.AddListener(this.History, 'OnSetHash', '_OnHistorySetHashHandler', this);
	ITHit.Events.AddListener(this.History, 'OnUrlChange', '_OnHistoryUrlChangeHandler', this);
	ITHit.Events.AddListener(this.History, 'OnSearchQueryChange', '_OnHistorySearchQueryChangeHandler', this);

	// Filter for received items.
	this._filter = new this._ns.Filter(this, ITHit.WebDAV.Client.ResourceType.Folder, this.ShowFolders);

	this._InitializeCommands(oSettings, sBaseServerUrl);
	this._InitializeItemsState(oSettings);

	// Lazy trigger event - wait subscribers
	var that = this;
	setTimeout(function() {
		ITHit.Events.DispatchEvent(that, 'OnInit');
	});
	this._InitializeRenderController(oSettings, sBaseServerUrl);
	this._InitializeInterfaceHandler();
}

ITHit.oNS.Controller.prototype._InitializeCommands = function (oSettings, sBaseServerUrl) {
	// Commands controller (included WebDavSession)
	this.Commands = new ITHit.WebDAV.Client.AjaxFileBrowser.Commands.CommandsController();
	this.Commands.NotAllowedCharacters = this.NotAllowedCharacters;
	this.Commands.ChildrenProperties = this._ChildrenProperties;
	this.Commands.SetRootUrl(sBaseServerUrl);

	// Credentials
	if (!ITHit.Utils.IsUndefined(oSettings.Credentials) && !ITHit.Utils.IsUndefined(oSettings.Credentials.User)) {
		var sPass = !ITHit.Utils.IsUndefined(oSettings.Credentials.Pass) ? oSettings.Credentials.Pass : '';
		this.Commands.SetCredentials(oSettings.Credentials.User, sPass);
	}

	// Commands cache
	if (!ITHit.Utils.IsUndefined(oSettings.FoldersCacheEnable) && oSettings.FoldersCacheSize === 0) {
		oSettings.FoldersCacheEnable = false;
	}
	if (!ITHit.Utils.IsUndefined(oSettings.FoldersCacheEnable)) {
		this.Commands.FoldersCollection.SetEnabled(oSettings.FoldersCacheEnable);
	}
	if (!ITHit.Utils.IsUndefined(oSettings.FoldersCacheSize)) {
		this.Commands.FoldersCollection.SetMaxSize(oSettings.FoldersCacheSize);
		this.Commands.ResourcesCollection.SetMaxSize(oSettings.FoldersCacheSize);
	}

	ITHit.Events.AddListener(this.Commands.FoldersCollection, 'OnDeprecated', function(sUrl) {
		// Skip refresh, if server is unavailable
		var oLastCommand = this.Commands.GetLastExecutedCommand();
		var oLastError = oLastCommand && oLastCommand.HasErrors() ? oLastCommand.GetErrors()[0] : null;
		if (oLastError && oLastError instanceof ITHit.WebDAV.Client.Exceptions.WebDavHttpException && oLastError.Status.Code === 0) {
			return;
		}

		if (this._url === sUrl) {
			this.Refresh();
		} else {
			// Update folders collection for update tree through events OnAdd/OnChange/OnSet
			if (this._Tree().IsOpenedItem(sUrl)) {
				this.Commands.Create('LoadFolderCommand', {
					Href: sUrl
				}).Execute();
			}
		}
	}, this);
	ITHit.Events.AddListener(this.Commands.FoldersCollection, 'OnRemove', function(sUrl) {
		if (this._url === sUrl) {
			// Navigate to parent directory
			var sParentFolderUrl = ITHit.WebDAV.Client.HierarchyItem.GetFolderParentUri(this._url);

			this.OpenFolderAsync(sParentFolderUrl);
		}
	}, this);

	/* pyao: remove search feature as webdev on 9x40 and newer doesn't support this method 
	// Send OPTIONS request for get supported features
	ITHit.Events.AddListener(this.Commands, 'OnFetchFeatures', function(oFeatures) {
		// Show search bar, if supported
		this.SearchBar.Toggle(oFeatures.ItemOptions.Search);
	}, this);
	*/

	// WebDAV session.
	// @todo Deprecated
	this._session = new ITHit.WebDAV.Client.AjaxFileBrowser.Commands.CommandController();
	this._session.Session = this.Commands.Session;
}

ITHit.oNS.Controller.prototype._InitializeRenderController = function (oSettings, sBaseServerUrl) {

	if (this.ShowContextHelp) {
		this._ContextHelp = new ITHit.WebDAV.Client.AjaxFileBrowser.Render.ContextHelp(this.ShowContextHelp);
	}

	var sClass = oSettings.ClassName || this.Settings.GetRootNode().className || ITHit.Config.AjaxFileBrowser.ClassName;
	this._control = new this._ns.Control(this, this.Settings.GetRootNode(), '', oSettings.Style, sClass, this._DnDFilesSupported, this._InterfaceHandler, this._ContextHelp);

	if (this.ShowContextHelp) {
		this._ContextHelp._Initiate();
	}

	// RenderController
	ITHit.WebDAV.Client.AjaxFileBrowser.Controller.baseConstructor.call(this);
	this.base = ITHit.WebDAV.Client.AjaxFileBrowser.Controller.base;

	this.Settings.TriggerRender();

	// Set base server address.
	this._SetAddressBarValue(sBaseServerUrl);

	ITHit.Events.AddListener(this, "OnViewModeChanged", function() {
		ITHit.oNS.Render.MenuController.RefreshCheckedViewState(this._index);
	}, this);

	// ViewMode
	this.SetViewMode(oSettings.ViewMode || oSettings.ViewModeDesktop || ITHit.WebDAV.Client.AjaxFileBrowser.Render.ViewModes.Details);

	ITHit.Events.AttachEvent(window, 'onbeforeunload', ITHit.Utils.MakeScopeClosure(this, '_OnClose'));
}

ITHit.oNS.Controller.prototype._InitializeInterfaceHandler = function () {
	this._InterfaceHandler = new ITHit.WebDAV.Client.AjaxFileBrowser.Handlers.InterfaceHandlers(this);

	ITHit.Events.AddListener(this._InterfaceHandler, 'OnGetAbsolutePath', 'OnGetAbsolutePathHandler', this);
	ITHit.Events.AddListener(this, 'OnMenuPaste', 'OnPasteHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, 'OnMenuCopy', 'OnCopyHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, 'OnMenuCut', 'OnCutHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, 'OnShortcutsPaste', 'OnPasteHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, 'OnShortcutsCopy', 'OnCopyHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, 'OnShortcutsCut', 'OnCutHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, '_OnSelectedItemsChanged', 'OnSelectedItemsChangedHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this, '_OnSelectedFolderChanged', 'OnSelectedFolderChangedHandler', this._InterfaceHandler);

	// Declared InterfaceHandler listener here baseuse grid initiated in base constructor.
	this._InterfaceHandler.AddListener('OnGetSelectedItemsCount', 'GetSelectedCount', this._grid);
	this._InterfaceHandler.AddListener('OnGetSelectedGridItems', 'GetSelectedItems', this);

	// Subscribe to session events here, but WebDav session created above
	ITHit.Events.AddListener(this.Commands, 'OnCommandFinish', 'OnExecuteCommandHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this.Commands, 'OnUndo', 'OnUndoHandler', this._InterfaceHandler);
	ITHit.Events.AddListener(this.Commands, 'OnRedo', 'OnRedoHandler', this._InterfaceHandler);

	this._InterfaceHandler._Initiate();
}

ITHit.oNS.Controller.prototype._InitializeItemsState = function (oSettings) {
	// Search properties
	this.SetSearchAutocompleteEnable(!ITHit.Utils.IsUndefined(oSettings.SearchAutocompleteEnable) ? oSettings.SearchAutocompleteEnable : true);
	this.SetSearchDynamicEnable(!ITHit.Utils.IsUndefined(oSettings.SearchDynamicEnable) ? oSettings.SearchDynamicEnable : true);

	// Open history url (hash part).
	var sHash = document.location.hash.replace('#', '');
	if (this.OpenHistoryLink && sHash) {
		// Lazy set selected folder. Waiting subscribe to browser events (for example - OnBeforeRequestSend)
		// For future, good style is:
		//  1. ITHit.Events.AddListener(ajaxFileBrowser, 'OnBeforeRequestSend', ...);
		//  2. Other events..
		//  3. ajaxFileBrowser.Run(); - manually run ajaxFileBrowser controller
		var self = this;
		setTimeout(function() {
			self.History.SetHash(sHash);
		});
	} else if (!ITHit.Utils.IsUndefined(oSettings.SelectedFolder)) {
		// SelectedFolder
		this.SetSelectedFolderAsync(oSettings.SelectedFolder, false);
	}

	// SelectedItems
	if (!ITHit.Utils.IsUndefined(oSettings.SelectedItems)) {
		this.SetSelectedItemsAsync(oSettings.SelectedItems, false);
	}
}

ITHit.oNS.Controller.prototype.SetSettings = function (oSettings) {
	this.Settings.SetSettings(oSettings || {});
}

// detects if SharePoint.OpenDocuments or FFWinPlugin is supported
ITHit.oNS.Controller.prototype.IsSharePointOpenDocumentsCtrlAvailable = function () {
    if (ITHit.DetectBrowser.IE) {
        try {
            new ActiveXObject("SharePoint.OpenDocuments");
            return true;
        } catch (e) { }
    } else {
        // detect FFWinPlugin Plug-in
        var plugins = navigator.plugins;
        var pluginName = ITHit.DetectBrowser.Mac ? 'SharePoint Browser Plug-in' : 'Microsoft Office'; // MS Office plugin has different name on Mac and Windows
        for (var i = 0; i < plugins.length; i++) {
            if (plugins[i].name.indexOf(pluginName) == 0) {
                return true;
            }
        }
    }
    if (ITHit.DetectBrowser.Chrome) {
        // Google Chrome does not support Microsoft Office and Java (NPAPI plugins) since v42 on Windows and OS X released Apri 14, 2015 and on Linux since v35.
        // We still can open MS Office documents, but can not detect MS Office presence, version and can not run Java
        return true;
    }
    return false;
}

