// @todo
ITHit.oNS.Controller.prototype.OnGetItemHandler = function(sUrl) {
	// Check is current folder
	if (this._CurrentItem && this._CurrentItem.Href === sUrl) {
		return this._CurrentItem;
	}

	// Find in current folder items
	var aItems = this._Grid().Items.Folders.concat(this._Grid().Items.Resources);
	for (var i = 0, l = aItems.length; i < l; i++) {
		if (aItems[i].Href === sUrl) {
			return aItems[i];
		}
	}

	throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException('Not found item in DataViewAdapter.Items by url `' + sUrl + '`');
    //return this.Commands.ResourcesCollection.Get(url);
}

ITHit.oNS.Controller.prototype.UploadCompliteHandler = function(sEvent, sUrl, sBaseUrl) {
    
	if (!this.OnUploadAutoRefresh) {
		return;
	}
	
	var sPath = ITHit.Utils.IsStringNullOrEmpty(sBaseUrl) ? sUrl : sBaseUrl;
	var sDir = ITHit.Decode(this._Utils.GetRelativePath(sPath).replace(/[^\/]+$/, ''));
	if (sDir === this._url) {
		
		if (this._UploadRefreshTimer) {
			clearTimeout(this._UploadRefreshTimer);
			this._UploadRefreshTimer = null;
		}
		
		this._UploadRefreshTimer = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_RefreshOnUpdateTimer', sDir), 500);
	}
}

ITHit.oNS.Controller.prototype.RefreshOnUpdate = function (sDir) {
    
    var sPath = sDir;
    if (/^http\:\/\//i.test(sPath) || /^https\:\/\//i.test(sPath)) {
        sPath = ITHit.WebDAV.Client.Encoder.Decode(this._Utils.GetRelativePath(sPath));
    }
    this._RefreshOnUpdate(sPath);
}

ITHit.oNS.Controller.prototype._RefreshOnUpdate = function (sDir) {

    if (this._RefreshOnUpdateTimerId) {
        clearTimeout(this._RefreshOnUpdateTimerId);
    }

    this._RefreshOnUpdateTimerId = setTimeout(ITHit.Utils.MakeScopeClosure(this, '_RefreshOnUpdateTimer', sDir), 1000);
}

ITHit.oNS.Controller.prototype._RefreshOnUpdateTimer = function (sDir) {
    if (sDir === this._url) {
        this.Refresh();
    }
}

