ITHit.oNS.Controller.prototype._GetItem = function(sPath, silence, ignoreCache) {
    var oLoadedItem = null;
	var that = this;
    this.Commands.Create('LoadItemSyncCommand', {
        Href: sPath,
        IgnoreCache: ignoreCache,
        OnError: function(aErrors) {
            if (!silence) {
				that.Errors.ShowCommandErrors(aErrors);
            }
        },
        OnSuccess: function(oItem) {
            oLoadedItem = oItem;
        }
    }).Execute();
	return oLoadedItem;
}

ITHit.oNS.Controller.prototype.OpenFolder = function(sUrl, bDoNotUpdateGrid, bPreventSaveInHistory, bDoNotNotify) {
	// Check passed URL.
	this._Utils.CheckUrlAgainstBase(sUrl);

    var that = this;
    var oLoadedItem = null;
    this.Commands.Create('LoadFolderSyncCommand', {
        Href: sUrl,
        IgnoreCache: this.FlushCacheOnOpenFolder,
        OnSuccess: function(oItem, aChildren) {
            oLoadedItem = oItem;
            that._OpenFolderAsyncCallback(aChildren, sUrl, oItem, bDoNotUpdateGrid, bPreventSaveInHistory, bDoNotNotify);
        }
    }).Execute();

    return oLoadedItem;
}

ITHit.oNS.Controller.prototype.OpenFolderAsync = function (sUrl, bDoNotUpdateGrid, bPreventSaveInHistory, bDoNotNotify, fCallback) {
    sUrl = ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils.GetRelativePath(sUrl).replace(/\/?$/, '/');

    // @todo Need fCallback proxy to current query
    if (!fCallback && this._NowOpenedFolder === sUrl) {
        return;
    }
    this._NowOpenedFolder = sUrl;

    fCallback = fCallback || function() {};

    // Check passed URL.
    this._Utils.CheckUrlAgainstBase(sUrl);

    var that = this;
    this.Commands.Create('LoadFolderCommand', {
        Href: sUrl,
        IgnoreCache: this.FlushCacheOnOpenFolder,
        OnFinish: function() {
            that._NowOpenedFolder = null;
        },
        OnAbort: function() {
			fCallback.call(that, null);
        },
        OnSuccess: function(oItem, aChildren) {
            that._OpenFolderAsyncCallback(aChildren, sUrl, oItem, bDoNotUpdateGrid, bPreventSaveInHistory, bDoNotNotify);
			fCallback.call(that, oItem);
        }
    }).Execute();
}

ITHit.oNS.Controller.prototype._OpenFolderAsyncCallback = function(aChildren, sUrl, oItem, bDoNotUpdateGrid, bPreventSaveInHistory, bDoNotNotify) {

    // Filter items.
    var oFiltered = this._filter.Run(aChildren);

	// Force update grid after search
	if (this._SearchQuery) {
		bDoNotUpdateGrid = false;
	}

	// Detect current (previous) folder
	var oCurrentFolder = this._url && !this._SearchQuery ? this.Commands.ResourcesCollection.Get(this._url) : null;
	this._SearchQuery = null;

	if (!bDoNotUpdateGrid && !bDoNotNotify) {
		if (ITHit.Events.DispatchEvent(this, 'OnBeforeSelectedFolderChanged', [oCurrentFolder, oItem.Item, null]) === false) {
			return;
		}
	}

    // Render items.
    this.RenderGridItems(oItem, oFiltered, bDoNotUpdateGrid);

    // Update browser history.
    if (this._RootHistoryUrl && !bPreventSaveInHistory) {
        this.History.SetUrl(this.Commands.GetAbsolutePath(oItem.Href, true));
    }

    if (!this._RootHistoryUrl && !bDoNotUpdateGrid) {
        this._RootHistoryUrl = sUrl;
    }

    if (this._RootNotOpened) {
        this.EnterZone('General:OpenedRoot');
        this._RootNotOpened = false;
    }

    ITHit.Events.DispatchEvent(this, '_OnSelectedFolderChanged');
    if (!bDoNotUpdateGrid && !bDoNotNotify) {
        ITHit.Events.DispatchEvent(this, 'OnSelectedFolderChanged', [oCurrentFolder, oItem.Item, null]);
    }
}

ITHit.oNS.Controller.prototype.OpenSearchResultsAsync = function(sQuery, sUrl, bDoNotUpdateSearchBar) {
	sUrl = sUrl || this._url;

	if (!bDoNotUpdateSearchBar) {
		this.SearchBar.SetValue(sQuery);
	}

	// Send search command
	var that = this;
	var oCommand = this.Commands.Create('SearchCommand', {
		Href: sUrl,
		Query: sQuery,
		OnSuccess: function(oItem, aItems) {
			if (ITHit.Events.DispatchEvent(that, 'OnBeforeSelectedFolderChanged', [oItem.Item, null, oCommand.QueryObject]) === false) {
				return;
			}

			that._url = oItem.Href;

			var oFiltered = that._filter.Run(aItems); // @todo Do not skip folders on search!
			that.RenderGridItems(oItem, oFiltered, null, true);

			// Mark in history
			that.History.SetSearchQuery(sQuery, that.Commands.GetAbsolutePath(oItem.Href, true));

			if (!that._RootHistoryUrl) {
				that._RootHistoryUrl = oItem.Href;
			}

			// Deselect node in tree
			that._Tree().DeselectNode();

			ITHit.Events.DispatchEvent(that, '_OnSelectedFolderChanged');
			ITHit.Events.DispatchEvent(that, 'OnSelectedFolderChanged', [oItem.Item, null, oCommand.QueryObject]);
		}
	});
	oCommand.Execute();

	// @todo Move
	this._SearchQuery = oCommand.QueryObject;

	return oCommand;
}

ITHit.oNS.Controller.prototype.GetSelectedItems = function() {
	
	var gridItems = this._Grid().GetSelectedItemsList(),
	    items     = [];
	
	for (var i = 0, l = gridItems.length; i < l; i++) {
		try {
			items.push(this.OnGetItemHandler(gridItems[i]));
		} catch (e) {
			items.push(this._GetItem(gridItems[i], true));
		}
	}

	
	return items;
}

ITHit.oNS.Controller.prototype.GetSelectedTreeItem = function() {
	return this._Tree().GetSelectedItemsList();
}

/**
 * Selects items in file panel. The tree will expand synchronously to show content of the necessary folder if required. All items must be located in the same folder. All items located in the folder other than the first item will be ignored. 
 * @param {array} aSelected this method you must pass either array of URLs or array of HierarchyItem objects.
 * @param {boolean} bDoNotNotify Fire SelectedFolderChanged if this parameter is false. Default is true.
 * @public 
 */
ITHit.oNS.Controller.prototype.SetSelectedItems = function (aSelected, bDoNotNotify) {
	bDoNotNotify = bDoNotNotify !== false;

    return this._SetSelectedItems(aSelected, bDoNotNotify, false);
}

/**
 * Selects items in file panel. The tree will expand asynchronously to show content of the necessary folder if required. All items must be located in the same folder. All items located in the folder other than the first item will be ignored.
 * @param {array} aSelected this method you must pass either array of URLs or array of HierarchyItem objects.
 * @param {boolean} bDoNotNotify Fire SelectedFolderChanged if this parameter is false. Default is true.
 * @param {function} fCallback Function to call when operation is completed.
 * @public
 */
ITHit.oNS.Controller.prototype.SetSelectedItemsAsync = function(aSelected, bDoNotNotify, fCallback) {
	bDoNotNotify = bDoNotNotify !== false;
    fCallback = fCallback || function() {};

    this._SetSelectedItems(aSelected, bDoNotNotify, false, fCallback);
}

ITHit.oNS.Controller.prototype.OpenLocation = function(aSelected) {
	this._SetSelectedItems([aSelected], false, true, function() {});
}

ITHit.oNS.Controller.prototype._SetSelectedItems = function(aSelected, bDoNotNotify, bForceOpenFolder, fCallback) {
    // Convert input data into array.
    if (!(aSelected instanceof Array)) {
        aSelected = [aSelected];
    }

    // Result array to select.
    var aSelectedUrl = [];

    // Get reference for namespace.
    var oNsHierItem  = ITHit.WebDAV.Client.HierarchyItem;

    for (var i = 0, l = aSelected.length; i < l; i++) {

        var mSelectedItem = aSelected[i];

        // Check whether passed item is instance of ITHit.WebDAV.Client.HierarchyItem class or not.
        if (!(mSelectedItem instanceof oNsHierItem)) {

            // Passed url to select.

            // Trim passed string.
            mSelectedItem = ITHit.WebDAV.Client.Encoder.Decode(ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils.GetRelativePath(ITHit.Trim(mSelectedItem)));

            // Whether string is empty, continue loop.
            if (!mSelectedItem && (0 !== mSelectedItem)) {
                continue;
            }

            // Push item url to result array.
            aSelectedUrl.push(mSelectedItem);
            if (!/\/$/.test(mSelectedItem)) {
                aSelectedUrl.push(mSelectedItem +'/');
            }
        }
        else {

            // Passed ITHit.WebDAV.Client.HierarchyItem.

            // Get url and push it to result array.
            aSelectedUrl.push(ITHit.WebDAV.Client.Encoder.Decode(ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils.GetRelativePath(mSelectedItem.Href)));
        }
    }

    // Check whether result array is not empty.
    if (aSelectedUrl.length === 0) {
        if (typeof fCallback === 'function') {
            fCallback.call(this, []);
        } else {
            return [];
        }
    }

    // Get first url parent directory.
    var sPath = aSelectedUrl[0].replace(/[^\/]+?\/?$/, '');
    try {
        this._Utils.CheckUrlAgainstBase(sPath, this._url);
    } catch(e) {
        if (typeof window.console !== 'undefined') {
            console.error(e);
        }
        return;
    }

    this.Flags.DispatchSelectedItemsChanged = !bDoNotNotify;

    // Change current directory to first item's parent if needed.
    if (bForceOpenFolder || this._url !== sPath) {
        var self = this;
        if (typeof fCallback === 'function') {
            this.SetSelectedFolderAsync(ITHit.WebDAV.Client.Encoder.Encode(sPath), bDoNotNotify, function() {
                self._SetSelectedItemsCallback(aSelectedUrl, bDoNotNotify, fCallback);
            });
        } else {
            this.SetSelectedFolder(ITHit.WebDAV.Client.Encoder.Encode(sPath), bDoNotNotify);
            return this._SetSelectedItemsCallback(aSelectedUrl, bDoNotNotify, fCallback);
        }
    } else {
        return this._SetSelectedItemsCallback(aSelectedUrl, bDoNotNotify, fCallback);
    }
}

ITHit.oNS.Controller.prototype._SetSelectedItemsCallback = function(aSelectedUrl, bDoNotNotify, fCallback) {
    this._Grid().DeselectAll();
    this._Grid().SetSelectedByUrl(aSelectedUrl);

	if (!bDoNotNotify) {
		//ITHit.Events.DispatchEvent(this, "OnSelectedItemsChanged", this);
	}

    if (typeof fCallback === 'function') {
        // @todo Return selected aItems instead urls list in first argument
        fCallback.call(this, []); // aItems
    } else {
        return []; // aItems
    }
}

/**
 * Returns selected folder or null if no folder is selected.
 * @return {Item|null}
 * @public
 */
ITHit.oNS.Controller.prototype.GetSelectedFolder = function() {
	var sUrl = this._Tree().GetSelectedNodeUrl();
	if (sUrl === null) {
		return null;
	}

	var item = this._GetItem(sUrl);
	if (!item) {
		return null;
	}
	
	return item.Item;
}

/**
 * Navigates to specified folder synchronously. Opens tree if required.
 * @param {string} mDestination Href of the folder to select.
 * @param {boolean} bDoNotNotify Fire SelectedFolderChanged if this parameter is false. Default is false.
 * @public
 */
ITHit.oNS.Controller.prototype.SetSelectedFolder = function(mDestination, bDoNotNotify) {
	bDoNotNotify = bDoNotNotify !== false;

    var sDestinationPath = mDestination;
    if (mDestination instanceof ITHit.WebDAV.Client.HierarchyItem) {
        sDestinationPath = mDestination.Href;
    }

    sDestinationPath = ITHit.WebDAV.Client.Encoder.Decode(ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils.GetRelativePath(sDestinationPath.replace(/\/?$/, '/')));

    var sCurrentPath = this._baseUrl;
    var aPath = sDestinationPath.replace(sCurrentPath, '').replace(/\/?$/, '').split('/');
    var oTree = this._Tree();

    this._SetSelectedFolderNext(sCurrentPath, aPath, oTree, sDestinationPath);
    return this.OpenFolder(sDestinationPath, false, null, bDoNotNotify);
}

ITHit.oNS.Controller.prototype._SetSelectedFolderNext = function(sCurrentPath, aPath, oTree, sDestinationPath) {
    if (!aPath.length || aPath[0] === '') {
        return;
    }

    var sDirName = aPath.shift() +'/';

    if (!oTree.NodeExists(sCurrentPath + sDirName)) {

        var self = this;
        var oItem = this.OpenFolder(sCurrentPath, true, false, false);

        if (!oItem) {
            return;
        }

        if (!oTree.NodeExists(sCurrentPath + sDirName)) {
            try {
                throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.NonExistentLocation.Paste(self.Commands.GetAbsolutePath(sCurrentPath + sDirName, true)));
            } catch (e) {
                ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(e);
            }
            return;
        }
    }

    this._SetSelectedFolderNext(sCurrentPath + sDirName, aPath, oTree, sDestinationPath);
}

/**
 * Navigates to specified folder asynchronously. Opens tree if required.
 * @param {string} mDestination Href of the folder to select.
 * @param {boolean} bDoNotNotify Fire SelectedFolderChanged if this parameter is false. Default is false.
 * @param {function} fCallback Function to call when operation is completed.
 * @public
 */
ITHit.oNS.Controller.prototype.SetSelectedFolderAsync = function (mDestination, bDoNotNotify, fCallback) {
	bDoNotNotify = bDoNotNotify !== false;

	var sDestinationPath = mDestination;
	if (mDestination instanceof ITHit.WebDAV.Client.HierarchyItem) {
		sDestinationPath = mDestination.Href;
	}

	sDestinationPath     = ITHit.WebDAV.Client.Encoder.Decode(ITHit.WebDAV.Client.AjaxFileBrowser.UrlUtils.GetRelativePath(sDestinationPath.replace(/\/?$/, '/')));

    this.OpenFolderAsync(sDestinationPath, null, null, bDoNotNotify, fCallback);
}

