ITHit.oNS.Controller.prototype._OpenGridItem = function(oItem) {
	
	var sResourceType = oItem.ResourceType,
	    clientNs      = ITHit.WebDAV.Client;
	
	if (false === ITHit.Events.DispatchEvent(this, 'OnOpenItem', oItem)) {
		return false;
	}
	
	if (sResourceType == clientNs.ResourceType.Folder) {
		var sUrl = clientNs.Encoder.Decode(clientNs.AjaxFileBrowser.UrlUtils.GetRelativePath(oItem.Href));
		this._grid.DeselectAll();
		this.OpenFolderAsync(sUrl);
		
		// ITHit.Events.DispatchEvent(this, 'OnSelectedFolderChanged', this);
	}
	else {
		//ntgr start
		var sEncodedUrl = oItem.Item.Href;
		//ntgr end
		this.playMedia(sEncodedUrl);	// pyao: artf45174
	}	
}

