ITHit.oNS.Controller.prototype.UploadFileDialog = function(sUrl, bDoNotCheckFileExistence) {

	if (!ITHit.DetectBrowser.IE || ITHit.DetectBrowser.IE >= 10) {
		this._upload.UploadFile(sUrl);
		return;
	}
	
	if (!this._dialog._uploadForm) {
		this._dialog._uploadForm = this._upload.CreateForm(sUrl, ITHit.Components.dojo.byId('ithit_interface_uploadResourceFile'), bDoNotCheckFileExistence, ITHit.Components.dojo.byId('ithit_interface_uploadResource_subm'));
		var _this = this;
		ITHit.Events.AddListener(this._dialog._uploadForm, 'OnProcessForm', 'CloseUploadFileDialog', this);
	} else {
		this._dialog._uploadForm.ResetForm(sUrl, bDoNotCheckFileExistence);
	}
	
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowUploadResourceDialog(sUrl, (-1 == sUrl.search(/\/$/)), this._Utils.GetAbsolutePath(sUrl));
}

