ITHit.oNS.Controller.prototype.CloseUploadFileDialog = function() {
	if (!this._dialog._uploadForm.CheckProcess()) {
		return false;
	}
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.HideUploadResourceDialog();
	ITHit.Events.RemoveListener(this._dialog._uploadForm, 'OnProcessForm', 'CloseUploadFileDialog', this);
	this._dialog._uploadForm = null;
}

ITHit.oNS.Controller.prototype.DeleteItems = function(aUrls) {
    if (!ITHit.Utils.IsArray(aUrls)) {
        aUrls = [aUrls];
    }

    var that = this;
    this.Commands.BeginQueue({
        OnFinish: function(aFinishCommands, aErrors) {
            var aDeletedUrls = [];
            for (var i = 0, l = aFinishCommands.length; i < l; i++) {
				if (!aFinishCommands[i].HasErrors()) {
                	aDeletedUrls.push(aFinishCommands[i].Href);
				}
            }

			// Skip, if no changes
			if (aDeletedUrls.length === 0) {
				that.Refresh();
				return;
			}

            that._Grid().DeleteItems(aDeletedUrls);
            that._Tree().RemoveNodes(aDeletedUrls);

            if (aDeletedUrls.length !== aUrls.length) {
                var aToSelect = [];
                for (var i = aDeletedUrls.length, l = aUrls.length; i < l; i++) {
                    aToSelect.push(aUrls[i]);
                }

                that._Grid().DeselectAll();
                that._Grid().SetSelectedByUrl(aToSelect);
            }
        }
    });

    for (var i = 0, l = aUrls.length; i < l; i++) {
        this.Commands.Create('DeleteCommand', {
            Href: aUrls[i]
        });
    }
    return this.Commands.EndQueue();
}

