ITHit.oNS.Controller.prototype.OpenDocument = function(sUrl, forceDownload, sFileName) {
    sFileName = sFileName || null;

    //Download via virtual link tag and it`s HTML5 "download" attribute
    if (forceDownload && this.DownloadWithVirtualLink(sUrl, sFileName) === true){
        return;
    }

	// Force file download (whether supported by server).
	if (forceDownload) {
		sUrl += (sUrl.indexOf('?') !== -1 ? '&' : '?') + 'download';
	}
	
	// Prevent document caching.
	if (this.PreventOpenDocumentCaching) {
		sUrl += (sUrl.indexOf('?') !== -1 ? '&' : '?') + new Date().getTime();
	}

	window.open(this._Utils.GetAbsolutePath(sUrl));
}

ITHit.oNS.Controller.prototype.DownloadWithVirtualLink = function(sUrl, sFileName){
    sFileName = sFileName || null;

    if (ITHit.DetectBrowser.IE || ITHit.DetectBrowser.FF) {
        return false;
    }

    var link = document.createElement('a');
    link.href = sUrl.indexOf('://') ? sUrl : this.Commands.GetAbsolutePath(sUrl, true);
    link.download = sFileName || sUrl.substring(sUrl.lastIndexOf('/') + 1, sUrl.length);

    if (link.click) {
        link.click();
        return true;
    }
    else if (document.createEvent)
    {
        var e = document.createEvent('MouseEvents');
        e.initEvent('click' ,true ,true);
        link.dispatchEvent(e);
        return true;
    }
}

ITHit.oNS.Controller.prototype.GetProperties = function(sUrl) {
	var that = this;
	this.Commands.Create('LoadItemProperties', {
		Href: sUrl,
		OnSuccess: function(aItemProps) {
			var aProps = [];

			for (var i = 0, l = aItemProps.length; i < l; i++) {
				aProps.push([aItemProps[i].Name.NamespaceUri, aItemProps[i].Name.Name, aItemProps[i].StringValue()]);
			}

			that._ns.Render.Dialog.ViewProperties(sUrl, aProps, that._Utils.GetAbsolutePath(sUrl));
		}
	}).Execute();
}

ITHit.oNS.Controller.prototype.GetVersions = function(sUrl) {
	var that = this;
	this.Commands.Create('LoadItemVersions', {
		Href: sUrl,
		OnSuccess: function(aVersionList) {
			var aRows = [];

			for (var i = 0, l = aVersionList.length; i < l; i++) {
				var aProps = [];
				for (var i2 = 0, l2 = aVersionList[i].length; i2 < l2; i2++) {
					var oProperty = aVersionList[i][i2];
					var sValue = '';

					if (oProperty instanceof Date) {
						sValue = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.FormatDate(oProperty);
					} else if (oProperty instanceof ITHit.WebDAV.Client.Property) {
						sValue = oProperty.StringValue();
					} else {
						sValue = oProperty.toString();
					}

					aProps.push(sValue);
				}
				aRows.push(aProps);
			}

			that._ns.Render.Dialog.Versions(sUrl, aRows, that._Utils.GetAbsolutePath(sUrl));
		}
	}).Execute();
}

ITHit.oNS.Controller.VersionUpdate = function(sUrl) {
    // Get references for controller
    var oNsCl         = ITHit.WebDAV.Client,
        oNsController = oNsCl.AjaxFileBrowser.Controller,
        oController   = oNsController.GetByIndex(oNsController._GetActive());

    // Get references for grid dialog.
    var oNsDialog = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog;
    var oGrid     =  oNsDialog.Versions._grid;

    if (1 != oGrid.GetSelectedCount()) {
        return false;
    }

    // Get selected item and file version href
    var oGridItem      = oGrid.GetSelectedItems()[0];
    var sToHrefUpdate = oGrid.GetValue(oGridItem, 'VersionHref');

	oController.Commands.Create('VersionUpdate', {
		Href: sUrl,
		ToHref: sToHrefUpdate,
		OnSuccess: function(bIsSuccess) {
			oController.GetVersions(sUrl);
		}
	}).Execute();
}

ITHit.oNS.Controller.VersionDelete = function(sUrl) {
    // Get references for controller
    var oNsCl         = ITHit.WebDAV.Client,
        oNsController = oNsCl.AjaxFileBrowser.Controller,
        oController   = oNsController.GetByIndex(oNsController._GetActive());

    // Get references for grid dialog.
    var oNsDialog = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog;
    var oGrid     =  oNsDialog.Versions._grid;

    // Get selected items
	var aGridItemList = oGrid.GetSelectedItems();

	oController.Commands.BeginQueue({
		OnSuccess: function() {
			oController.GetVersions(sUrl);
		}
	});

	for (var i = 0, l = aGridItemList.length; i < l; i++) {
		var oGridItem      = oGrid.GetSelectedItems()[i];
		var sVersionHref = oGrid.GetValue(oGridItem, 'VersionHref');

		oController.Commands.Create('VersionDelete', {
			Href: sUrl,
			VersionHref: sVersionHref
		});
	}
	return oController.Commands.EndQueue();
}

ITHit.oNS.Controller.VersionDownload = function(sUrl) {
    // Get references for controller
    var oNsCl         = ITHit.WebDAV.Client,
        oNsController = oNsCl.AjaxFileBrowser.Controller,
        oController   = oNsController.GetByIndex(oNsController._GetActive());

    // Get references for grid dialog.
    var oNsDialog = oNsCl.AjaxFileBrowser.Render.Dialog;
    var oGrid     =  oNsDialog.Versions._grid;

    if (1 != oGrid.GetSelectedCount()) {
        return false;
    }

    // Get selected item and file version href
    var oGridItem      = oGrid.GetSelectedItems()[0];
    var sVersionHref = oGrid.GetValue(oGridItem, 'VersionHref');

    var oItem = oController._GetItem(sUrl);
    var sVersionName = oGrid.GetValue(oGridItem, 'Name').toLowerCase();
    var sFileName = oItem.DisplayName.indexOf('.') !== -1 ?
        oItem.DisplayName.replace(/(\.[^.]+)$/, '_' + sVersionName + '$1') :
        oItem.DisplayName + '_' + sVersionName;

    oController.OpenDocument(sVersionHref, true, sFileName);
}

