ITHit.oNS.Controller.Parse = function(mElement) {
	
	var oElement = document.body;
	var oNs      = ITHit.WebDAV.Client.AjaxFileBrowser;
	
	if (mElement) {
		
		if (ITHit.Utils.IsString(mElement)) {
			oElement = document.getElementById(mElement);
			if (!oElement) {
				throw oNs.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongElementIdOrObject);
			}
		}
		else {
			oElement = mElement;
		}
	}
	
	return ITHit.Components.dojo.parser.parse(oElement)[0].GetControl();
}

