ITHit.oNS.Controller.prototype._OnGridMouseDownHandler = function(event, url) {

    var selectedUrls = this._grid.GetSelectedItemsList();
    //NETGEAR: DS: if the row is already selected and is the only item selected, a second mouse down opens it
    //NETGEAR: DS: this avoids issues with needing double click on mobile
    if(selectedUrls.length ===1 && this._grid.IsSelected(url)) {
        this._OpenGridItem(this._GetItem(url));
        return;
    }


	// Return whether event item is not present in selection list.
	if (selectedUrls.length && !this._grid.IsSelected(url)) {
		if (event.ctrlKey === false && event.metaKey === false && event.shiftKey === false) {
			selectedUrls = [url];
			// Do not use method SetSelectedItems, because it changed folder
			this._SetSelectedItemsCallback(selectedUrls);
		} else {
			return false;
		}
	}

	if (!selectedUrls.length) {
		selectedUrls.push(url);
	}

	var dndData = this._GetDragDropDataFromItems_New(selectedUrls),
	    target  = ITHit.WebDAV.Client.AjaxFileBrowser.Controller._GetEventTarget(event);
	
	this._DragDrop.MouseDown(event, target, dndData);
}

ITHit.oNS.Controller.prototype._GetDragDropDataFromItems_New = function(urls) {
	
	if (!ITHit.Utils.IsArray(urls)) {
		urls = [urls];
	}
	
	var item,
	    dndData = [];

	for (var i = 0, l = urls.length; i < l; i++) {
		try {
			item = this.OnGetItemHandler(urls[i]);
		} catch (e) {
			item = this._GetItem(urls[i], true);
		}

		dndData.push({
				Name: item.DisplayName,
				Url: item.Href,
				ResourceType: item.ResourceType
			});
	}
	
	return dndData;
}

