ITHit.oNS.Controller._GetDragDropDataFromItems = function(aItems) {
	
	if (!ITHit.Utils.IsArray(aItems)) {
		aItems = [aItems];
	}
	
	var aSource = [];
	
	for (var i = 0, l = aItems.length; i < l; i++) {
		aSource.push({
				Name: aItems[i].DisplayName,
				Url: aItems[i].Href,
				ResourceType: aItems[i].ResourceType
			});
	}
	
	return aSource;
}

ITHit.oNS.Controller.prototype.OnGetDragDropTargetDataHandler = function(event, elem) {
	
	if (-1 == elem.className.indexOf('dnd_target')) {
		return false;
	}
	
	// Try to search element in tree.
	var treeNode = this._Tree().GetNodeByElement(elem),
		url;
	
	// Search in tree element.
	if (treeNode) {
		url = this._Tree().GetNodeUrl(treeNode);
		
	// Search in grid element.
	} else {
		url = this._grid.GetUrlByElement(elem);
	}
	
	// Whether url not found, then current folder is a target.
	if (!url) {
		url = this._url;
	}
	
	var item = this._GetItem(url);
	
	return ITHit.WebDAV.Client.AjaxFileBrowser.Controller._GetDragDropDataFromItems(item)[0];
}

ITHit.oNS.Controller.OnDragOverHandler = function(event) {
	
    if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 10)) {
		return false;
	}
	
	var dt = event.dataTransfer;
	if (!dt) {
		return;
	}
	
	var dtTypes = dt.types;
	if (dtTypes) {
		// FF
		if (dtTypes.contains && !dtTypes.contains("Files")) return;
		// Chrome
		if (dtTypes.indexOf && (-1 == dtTypes.indexOf("Files"))) return;
	}
	
	dt.dropEffect = 'copy';
	
	return false;
}

ITHit.oNS.Controller.PreviousDragTarget;

ITHit.oNS.Controller.OnDragEnterHandler = function(event) {
	
    if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 10)) {
		return false;
	}
	
	var nsBrowser    = ITHit.WebDAV.Client.AjaxFileBrowser,
		elem         = nsBrowser.Controller._GetEventTarget(event),
		dropTarget   = nsBrowser.Render.DragDrop.DragHelpers.FindTargetNode(elem);
	
	if ( dropTarget &&(nsBrowser.Controller.PreviousDragTarget != dropTarget)) {
		dropTarget.className += ' drag_over';
		nsBrowser.Controller.PreviousDragTarget = dropTarget;
	}
	
	return false;
}

ITHit.oNS.Controller.OnDragLeaveHandler = function(event) {
	
    if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 10)) {
		return false;
	}
	
	var nsBrowser  = ITHit.WebDAV.Client.AjaxFileBrowser,
		elem       = nsBrowser.Controller._GetEventTarget(event),
		dropTarget = nsBrowser.Render.DragDrop.DragHelpers.FindTargetNode(elem);
		
	nsBrowser.Controller.PreviousDragTarget = null;
	
	if (dropTarget) {
		dropTarget.className = dropTarget.className.replace(' drag_over', '');
	}
	
	return false;
}

ITHit.oNS.Controller.OnFilesDropHandler = function(event, index) {
	
	if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 10)) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.DropFilesIEUnsupported);
		return false;
	}

	var nsClient      = ITHit.WebDAV.Client,
		nsBrowser     = nsClient.AjaxFileBrowser,
		nsController  = nsBrowser.Controller,
		controller    = nsController.GetByIndex(index),
		targetElem    = nsBrowser.Render.DragDrop.DragHelpers.FindTargetNode(nsController._GetEventTarget(event)),
		dragTarget    = controller.OnGetDragDropTargetDataHandler(event, targetElem),
		dragTargetUrl = nsBrowser.UrlUtils.GetRelativePath(dragTarget.Url);
	
	if (!dragTarget) {
		return false;
	}
	
	if (dragTarget.ResourceType == ITHit.WebDAV.Client.ResourceType.Folder) {
		dragTargetUrl = dragTargetUrl.replace(/\/?$/, '/');
	} else {
		dragTargetUrl = nsClient.HierarchyItem.GetFolderParentUri(dragTargetUrl);
	}
	dragTargetUrl = ITHit.DecodeHost(ITHit.WebDAV.Client.Encoder.Encode(controller._Utils.GetAbsolutePath(dragTargetUrl)));
	
	var dropObject = new nsBrowser.UploadDropObjectAdapter(dragTargetUrl, event.dataTransfer, function (dropObject) {
	    
	    controller._upload._SubmitHandler(event, dropObject);
	    if (targetElem) {
	        targetElem.className = targetElem.className.replace(' drag_over', '');
	    }
	});
	
}

ITHit.oNS.Controller.prototype.OnDragSuccessHandler = function(event, action, sourceData, targetData) {
	
	var itemsUrlToCutOrCopy = [],
		targetUrl = targetData.Url,
		clientNs  = ITHit.WebDAV.Client,
		moveFlag  = (action == clientNs.AjaxFileBrowser.Render.DragDrop.DragInfo.Actions.Move);
	
	// Get parent folder for resource target.
	if (targetData.ResourceType != clientNs.ResourceType.Folder) {
		targetUrl = clientNs.HierarchyItem.GetFolderParentUri(targetUrl);
	}
	
	// Get target relative path.
	targetUrl = clientNs.Encoder.Decode(clientNs.AjaxFileBrowser.UrlUtils.GetRelativePath(targetUrl));
	
	// Collect items for further action.
	for (var i = 0, l = sourceData.length; i < l; i++) {
		itemsUrlToCutOrCopy.push(sourceData[i].Url);
	}
	
	// Save items for move action.
	if (moveFlag) {
        this.CopyMoveManager.CutItems(itemsUrlToCutOrCopy);
	
	// Save items for copy action.
	} else {
        this.CopyMoveManager.CopyItems(itemsUrlToCutOrCopy);
	}
	
	// Paste items.
	this.CopyMoveManager.PasteTo(targetUrl);
	
	return true;
}

