ITHit.oNS.Controller.prototype._OnHistoryUrlChangeHandler = function(sUrl) {
	var preventSaveInHistory = false;

	if (!sUrl) {
		if (!this._RootHistoryUrl) {
			return;
		}
		
		sUrl                  = this._RootHistoryUrl;
		preventSaveInHistory = true;
	}

	var sAbsoluteUrl = sUrl.indexOf('://') === -1 ? this.Commands.GetAbsolutePath(sUrl, true) : sUrl;
	if (this.CheckNaviagtionToAnotherServer(sAbsoluteUrl)) {
		this.NavigateToAnotherServer(sAbsoluteUrl);
		return;
	}

	this.OpenFolderAsync(sUrl, false, preventSaveInHistory);
}

