ITHit.oNS.Controller.prototype.isMediaFile = function (sUrl) {
	var ext = ITHit.Trim(sUrl.substr(sUrl.lastIndexOf(".") + 1)) || "";

	switch (ext.toLowerCase()) {
		// supported video
		case 'ogv':
		case 'mp4':
		// supported audio
		case 'mp3':
		case 'wav':
		case 'ogg':
		// supported image
		case 'jpeg':
		case 'jpg':
		case 'gif':
		case 'png':
		case 'apng':
		case 'svg':
		case 'bmp':
		// unsupported video
		case 'webm':
		case 'mkv':
		case 'flv':
		case 'vob':
		case 'drc':
		case 'gifv':
		case 'mng':
		case 'avi':
		case 'mov':
		case 'qt':
		case 'wmv':
		case 'yuv':
		case 'rm':
		case 'rmvb':
		case 'asf':
		case 'amv':
		case 'm4v':	// ? does html5 support it? 
		case 'm4p':	// ? does html5 support it?
		case 'mpg':
		case 'mp2':
		case 'mpeg':
		case 'mpe':
		case 'mpv':
		case 'm2v':
		case 'm4v':
		case 'svi':
		case '3gp':
		case '3g2':
		case 'mxf':
		case 'roq':
		case 'nsv':
		case 'f4v':
		case 'f4p':
		case 'f4a':
		case 'f4b':
		// unsupported audio:
		case 'aa':
		case 'aac':
		case 'aax':
		case 'act':
		case 'aiff':
		case 'amr':
		case 'ape':
		case 'au':
		case 'awb':
		case 'dct':
		case 'dss':
		case 'dvf':
		case 'flac':
		case 'gsm':
		case 'iklax':
		case 'ivs':
		case 'm4a':
		case 'm4b':
		case 'm4p':
		case 'mmf':
		case 'mpc':
		case 'msv':
		case 'oga':
		case 'mogg':
		case 'opus':
		case 'ra':
		case 'rm':
		case 'raw':
		case 'sln':
		case 'tta':
		case 'vox':
		case 'wav':
		case 'wma':
		case 'wv':
		case 'webm':
		case '8svx':
		// unsupported image:
		case 'exif':
		case 'tiff':
		case 'ppm':
		case 'pgm':
		case 'pbm':
		case 'pnm':
		case 'webp':
		case 'heif':
		case 'mpg':
			return true;
		default:
			return false;
	}
}

ITHit.oNS.Controller.prototype.playMedia = function (sUrl) {
	//ntgr start
	var decodedsUrl = decodeURI(sUrl);
	var ext = ITHit.Trim(decodedsUrl.substr(decodedsUrl.lastIndexOf(".") + 1));
	//ntgr end
	if (!ext) {
		return false;
	}

	// Get full path.
	if (!/^https?\:\/\//.test(sUrl)) {
		sUrl = this._Utils.Host + sUrl.replace(/^\//, "");
	}

	var html_contents = "";

	ext = ext.toLowerCase();

	//ntgr starts
	if(ITHit.DetectBrowser.IE && ITHit.DetectBrowser.IE < 11){
		ext = "";
	}
	//ntgr ends

	switch (true) {
		case ext == 'ogv':
			ext = 'ogg';
		case ext == 'mp4':
        //case ext == 'mov':
        //case ext == 'avi':
			html_contents = "<video autoplay controls style='width: 100%; height: auto;' src='" + sUrl + "' type='video/" + ext + "'></video>";
			break;
		case ext == 'mp3':
		case ext == 'wav':
		case ext == 'ogg':
			html_contents = "<audio autoplay controls src='" + sUrl + "' type='audio/" + ext + "'></audio>";
			break;
		case ext == 'jpeg':
		case ext == 'jpg':
		case ext == 'gif':
		case ext == 'png':
		case ext == 'apng':
		case ext == 'svg':
		case ext == 'bmp':
			html_contents = "<img autoplay controls src='" + sUrl + "' type='image/" + ext + "'></img>";
			break;
		//case this.isMediaFile(sUrl) == true:
                //window.open(sUrl, '_blank'); // jen: artf45214 comment out to display message
			//// Message to be displayed if format is not supported
			//document.getElementById('ithit_interface_protocol_installation_text').innerHTML = ITHit.Phrases.AjaxFileBrowser.Interface.InstallProtocolDoc.toString();
			//ITHit.Components.dijit.byId('ithit_interface_protocol_installation').show();
			/*setTimeout(function() {
                ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.NonSupportedFileType); // jen: artf45214
            }.bind(this), 10);*/
            //window.open(sUrl, '_blank'); // jen: artf45214 comment out to display message
			//return;
		default:
            window.open(sUrl, '_blank');
			return;
	}

	var new_window = window.open('', '_blank');
	new_window.document.write('<!doctype html><html><head><title>' + sUrl + '</title><meta charset="UTF-8" /></head><body>' + html_contents + '</body></html>');
}
//ntgr end

ITHit.oNS.Controller.prototype.EditDocument = function(sUrl) {
	
	if (!this._SharePointOpenOrEditDocs && !this.EnablePlugins) {
		return false;
	}
	
	var ext = ITHit.Trim(sUrl.substr(sUrl.lastIndexOf(".") + 1));
	if (!ext) {
		return false;
	}
	
	var fileFormatsNs = ITHit.WebDAV.Client.AjaxFileBrowser.FileFormats;
	
	if (fileFormatsNs.ProtectedExtentions.join('|').indexOf(ext) >= 0) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.ProtectedForRunningFileExtension.Paste(ext));
		return false;
	}
	
	// Get full path.
	if (!/^https?\:\/\//.test(sUrl)) {
		sUrl = this._Utils.Host + sUrl.replace(/^\//, "");
	}
	
    // Message to be displayed if protocol is not installed
	var errorCallback = function () {
        document.getElementById('ithit_interface_protocol_installation_text').innerHTML = ITHit.Phrases.AjaxFileBrowser.Interface.InstallProtocolDoc.toString();
        ITHit.Components.dijit.byId('ithit_interface_protocol_installation').show();
	}

    //Edit MS Office document with Microsoft Office, if failed use custom protocol
	var dmNs = ITHit.WebDAV.Client.DocManager;
	if (dmNs.IsMicrosoftOfficeDocument(sUrl) && ((ITHit.DetectOS.OS == 'Windows') || (ITHit.DetectOS.OS == 'MacOS'))) {
	    var mountingUrl = this._baseUrl;
	    var enablePlugins = this.EnablePlugins;
	    dmNs.MicrosoftOfficeEditDocument(sUrl, function () {
	        if (enablePlugins) {
	            ITHit.WebDAV.Client.DocManager.DavProtocolEditDocument(sUrl, mountingUrl, errorCallback);
	        }
	    });
	}
	else {
	    if (this.EnablePlugins) {
	        dmNs.DavProtocolEditDocument(sUrl, this._baseUrl, errorCallback);
	    }
	}
}

ITHit.oNS.Controller.prototype.OpenFolderInFM = function (sUrl) {
    
    // Get full path.
    if (!/^https?\:\/\//.test(sUrl)) {
        sUrl = this._Utils.Host + sUrl.replace(/^\//, "");
    }

    // Open using HttpBehavior component.
    if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 11)) {

        if (this._httpFolder == null) {
            var span = {
                nodeName: 'span',
                style: { display: 'none', behavior: 'url(#default#httpFolder)' }
            };
            this._httpFolder = ITHit.Utils.CreateDOMElement(span);
			this.Settings.GetRootNode().appendChild(this._httpFolder);
        }

        var res = this._httpFolder.navigate(sUrl);
        if (res != "OK") {
            var fr = ITHit.Phrases.AjaxFileBrowser.Interface;
            var html = '<table cellspacing="10" style="width:100%">' +
                '<tr><td colspan="2"><b>' + fr.FailedToOpenWinExplorer + '</b></td></tr>' +
                '<tr><td style="width:60px; vertical-align:top" nowrap="">URL: </td><td nowrap="">' + sUrl + '</td></tr>' +
                '<tr><td nowrap="">' + fr.Error + '</td><td nowrap="">' + res + '</td></tr>' +
                '<tr><td colspan="2">' + fr.WebFoldersUpdate.Paste("http://www.microsoft.com/downloads/details.aspx?familyid=17C36612-632E-4C04-9382-987622ED1D64&displaylang=en") +'</td></tr>' +
                '<tr><td colspan="2" style="padding-top: 15px; text-align: right; ">' +
                '<button type="button" ihDojoType="dijit.form.Button" class="ihDialogButton" iconClass="iconCancel" onclick="ITHit.WebDAV.Client.AjaxFileBrowser.Controller.HideDialog();" >' + fr.Close + '</button>' +
                '</td></tr>' +
                '</table>';

            this.ShowDialog(html, { width: '500px' }, 'Error');
        }

        // Edit with java applet.
    } else if (this.EnablePlugins) {
        // Message to be displayed if protocol is not installed
        var errorCallback = function () {
            document.getElementById('ithit_interface_protocol_installation_text').innerHTML = ITHit.Phrases.AjaxFileBrowser.Interface.InstallProtocolFm.toString();
            ITHit.Components.dijit.byId('ithit_interface_protocol_installation').show();
        }
        ITHit.WebDAV.Client.DocManager.OpenFolderInOsFileManager(sUrl, this._baseUrl, errorCallback);
    }
}

ITHit.oNS.Controller.prototype.OpenContainingFolderInFM = function (sUrl) {
    return this.OpenFolderInFM(sUrl.substring(0, sUrl.lastIndexOf('/')));
}

ITHit.oNS.Controller.prototype.SharePointNewDocument = function (sTemplateIndex, sSaveUrl) {
    if (!this._SharePointOpenOrEditDocs) {
        return false;
    }

    sTemplateIndex += "_13";

    var sTemplate = ITHit.WebDAV.Client.AjaxFileBrowser.DocTemplates[sTemplateIndex];

    if (!sTemplate) {
        throw new ITHit.WebDAV.Client.AjaxFileBrowser.Exceptions.AjaxFileBrowserException(ITHit.Phrases.AjaxFileBrowser.Exceptions.WrongTemplateIndex);
    }

    var sPath = this.MsOfficeTemplatesPath;
    var oRegExp = new RegExp('^https?\:\/\/');

    if (!oRegExp.test(sPath)) {
        sPath = this._Utils.Host + sPath.replace(/^\//, '');
    }
    if (!oRegExp.test(sSaveUrl)) {
        sSaveUrl = this._Utils.Host + sSaveUrl.replace(/^\//, '');
    }

    var sTemplatePath = sPath + sTemplate;

    try {
        // MS Office 2013 frovides protocols instead of ActiveX/plugins
        var ext = ITHit.Trim(sTemplatePath.substr(sTemplatePath.lastIndexOf(".") + 1));
        var schema = ITHit.WebDAV.Client.DocManager.GetMsOfficeSchemaByExtension(ext);
        var url = schema + ':nft|u|' + sTemplatePath + '|s|' + sSaveUrl; //Example for MS Office 2013 and later: ms-word:nft|u|http://server/folder/file.dotx|s|http://server/folder/
        window.location.href = url;
    } catch (e) {
        return false;
    }
}

