ITHit.oNS.Controller.RenameItem = function(sUrl, sNewName) {
    var oNsController = ITHit.WebDAV.Client.AjaxFileBrowser.Controller;
    var oController   = oNsController.GetByIndex(oNsController._GetActive());

    var oCommand = oController.Commands.Create('RenameCommand', {
        Href: sUrl,
        NewName: sNewName,
        ReturnException: true,
        OnError: function(aErrors) {
            ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.Rename(sUrl, oCommand.NewName);
			oController.Errors.ShowCommandErrors(aErrors);

			// Fix hide dojo overlay
			ITHit.Components.dijit._DialogLevelManager.hide(ITHit.Components.dijit.byId('ithit_interface_renameItem'));
        }
    });

    if (oController._url === sUrl) {
        var sFutureUrl = oCommand.GetFutureUrl();
        var isFolder = sFutureUrl.substr(sFutureUrl.length - 1, 1) === '/';
        oController._url = isFolder ? sFutureUrl : ITHit.WebDAV.Client.HierarchyItem.GetFolderParentUri(sFutureUrl);
    }

    oCommand.Execute();

    return !oCommand.HasErrors();
}

ITHit.oNS.Controller.CreateFolder = function(sUrl, sName) {
    var oNsController = ITHit.WebDAV.Client.AjaxFileBrowser.Controller;
    var oController   = oNsController.GetByIndex(oNsController._GetActive());

    var oCommand = oController.Commands.Create('CreateFolderCommand', {
        Href: sUrl,
        Name: sName,
        OnError: function(aErrors) {
			ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.NewFolder(sUrl, oCommand.Name);
			oController.Errors.ShowCommandErrors(aErrors);

			// Fix hide dojo overlay
			ITHit.Components.dijit._DialogLevelManager.hide(ITHit.Components.dijit.byId('ithit_interface_newFolder'));
        },
        OnSuccess: function() {
            ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.CloseNewFolder();
        }
    });
    oCommand.Execute();

    return !oCommand.HasErrors();
}

