ITHit.oNS.Controller.EditPropertyDialog = function() {
	
	var oNsDialog = ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog;
	var oGrid     =  oNsDialog.ViewProperties._grid;
	
	if (1 != oGrid.GetSelectedCount()) {
		return false;
	}
	
	var oItem      = oGrid.GetSelectedItems()[0];
	
	var sNamespace = oGrid.GetValue(oItem, 'Namespace');
	var sName      = oGrid.GetValue(oItem, 'Name');
	var mValue     = oGrid.GetValue(oItem, 'Value');
	
	oNsDialog.UpdateProperty(sNamespace, sName, mValue);
}

ITHit.oNS.Controller.AddOrUpdateProperty = function(sUrl, sNamespace, sName, sValue) {
	
	if (!sName || /([^\w\-\.]|^[0-9\-\.])/.test(sName) || !sNamespace || /([^\w\-\.]|^[0-9\-\.])/.test(sNamespace)) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.PropertyNameRestriction);
		return false;
	}

	var oNs           = ITHit.WebDAV.Client,
	    oNsController = oNs.AjaxFileBrowser.Controller,
	    oController   = oNsController.GetByIndex(oNsController._GetActive()),
	    oProp         = new oNs.Property(new oNs.PropertyName(sName, sNamespace), sValue);

	oController.Commands.Create('PropertiesUpdate', {
		Href: sUrl,
		PropertiesToUpdate: [oProp],
		OnSuccess: function(oItem) {
			ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.CloseAddProperty();
			ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.CloseUpdateProperty();

			oController.GetProperties(sUrl);
		}
	}).Execute();

	return false;
}

ITHit.oNS.Controller.DeleteProperties = function(sUrl) {
	
	var oNs           = ITHit.WebDAV.Client,
	    oNsController = oNs.AjaxFileBrowser.Controller,
	    oNsPropName   = oNs.PropertyName,
	    oController   = oNsController.GetByIndex(oNsController._GetActive()),
	    oGrid         = oNs.AjaxFileBrowser.Render.Dialog.ViewProperties._grid;
	
	if (!oGrid.GetSelectedCount()) {
		return false;
	}
	
	var aItems = oGrid.GetSelectedItems();
	var aProps = [];
	for (var i = 0, l = aItems.length; i < l; i++) {
		aProps.push(new oNsPropName(oGrid.GetValue(aItems[i], 'Name'), oGrid.GetValue(aItems[i], 'Namespace')));
	}

	oController.Commands.Create('PropertiesUpdate', {
		Href: sUrl,
		PropertiesToDelete: aProps,
		OnSuccess: function(oItem) {
			ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.HideDeletePropertiesDialog();
			oController.GetProperties(sUrl);
		}
	}).Execute();

	return true;
}

ITHit.oNS.Controller.OnResizeDataViewArea = function(index) {
	var grid = ITHit.WebDAV.Client.AjaxFileBrowser.Controller.GetByIndex(index)._Grid();
	if (grid) {
		grid.OnResizeViewArea();
	}
}

ITHit.oNS.Controller.prototype.ShowUploadErrors = function(sUrl) {
	this._error.ShowErrors(this._upload.GetErrors(sUrl));
}

ITHit.oNS.Controller.ShowUploadErrors = function(iIndex, sUrl) {
	
	var oNsController = ITHit.WebDAV.Client.AjaxFileBrowser.Controller;
	var oController   = oNsController.GetByIndex(iIndex);
	
	oController.ShowUploadErrors(sUrl);
}

ITHit.oNS.Controller.ShowThumb = function(oImg, iSize) {
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.RenderController.ShowThumbnail(oImg, iSize);
}

ITHit.oNS.Controller.IconLoaded = function(oImage) {
	if (ITHit.DetectBrowser.IE && (ITHit.DetectBrowser.IE < 7)) {
		ITHit.WebDAV.Client.AjaxFileBrowser.Utils.FixPNG(oImage);
	}
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.ResourceIcons.SaveIconInfo(oImage, true);
}

ITHit.oNS.Controller.IconNotFound = function (oImage) {
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Utils.ResourceIcons.SaveIconInfo(oImage, false);
}

ITHit.oNS.Controller.EnterZone = function(index, zone) {
	var controller   = ITHit.WebDAV.Client.AjaxFileBrowser.Controller.GetByIndex(index);
	controller.EnterZone(zone);
}


ITHit.oNS.Controller.prototype.EnterZone = function(zone) {
	this._Shortcuts.EnterZone(zone);
}

ITHit.oNS.Controller.LeaveZone = function(index, zone) {
	var controller   = ITHit.WebDAV.Client.AjaxFileBrowser.Controller.GetByIndex(index);
	controller._Shortcuts.LeaveZone(zone);
}

ITHit.oNS.Controller.prototype.LeaveZone = function(zone) {
	this._Shortcuts.LeaveZone(zone);
}

/**
 *
 * @param sUrl
 * @returns {boolean}
 */
ITHit.oNS.Controller.prototype.CheckNaviagtionToAnotherServer = function (sUrl) {
    var oTmpUtils = new this._ns.UrlUtils(sUrl);

	return oTmpUtils.Host !== this.Commands.Host
		||  oTmpUtils.BasePath.indexOf(this.Commands.BaseUrl) !== 0;
}

ITHit.oNS.Controller.prototype.NavigateToAnotherServer = function (sUrl) {
	// Create session for provided host, checking if it is reachable
	this._NowOpenedFolder = null;

	var that = this;
	this.Commands.SetRootUrl(sUrl);
	this.Commands.LoadRootUrl(function(oItem) {
		if (!oItem) {
			if (ITHit.DetectBrowser.IE >= 7 && ITHit.DetectBrowser.IE <= 9) {
				ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowCustomDialog(ITHit.Phrases.AjaxFileBrowser.Interface.CrossDomainRequestsIssueIE, false, ITHit.Phrases.AjaxFileBrowser.Interface.CrossDomainRequestsIssueTitle);
			} else {
				ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowCustomDialog(ITHit.Phrases.AjaxFileBrowser.Interface.CrossDomainRequestsIssue, false, ITHit.Phrases.AjaxFileBrowser.Interface.CrossDomainRequestsIssueTitle);
			}
		} else {
			that._ChangeRootElementCallback(sUrl, oItem);
		}
	});
}

ITHit.oNS.Controller.prototype.OnAddressBarKeyDown = function (oEvent) {
    if (ITHit.Components.dojo.keys.ENTER == oEvent.keyCode) {
        var oElement = oEvent.target || oEvent.srcElement;
        this.OpenFolderFromInterface(oElement.value);
        ITHit.Components.dojo.stopEvent(oEvent);
    }
}

ITHit.oNS.Controller.prototype.SetUrl = function (sUrl) {
    this.NavigateToAnotherServer(sUrl);
}

ITHit.oNS.Controller.prototype.GetUrl = function () {
    return this.defaultParams.Url;
}


ITHit.oNS.Controller.prototype.HistoryGoBack = function () {
    this.History.Back();
}

ITHit.oNS.Controller.prototype._ChangeRootElementCallback = function (sUrl, oFolder) {
    if (oFolder === false) {
        ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowMessage(ITHit.Phrases.AjaxFileBrowser.Interface.NonExistentLocation);
        return;
    }

    // Removing Old Root Node
    this._Tree().RemoveNodes([this._Utils.BasePath]);

    // Updating variables of current controller
    var oTmpUtils = new this._ns.UrlUtils(sUrl);
    this._baseUrl = oTmpUtils.BasePath;
    this._Utils = oTmpUtils;

    // Adding new Root Node
    this._Tree().SetRootNode(this._baseUrl);

    // Let control to load contents of folder
    this.SetSelectedFolderAsync(sUrl);
}

ITHit.oNS.Controller.prototype.OpenFolderFromInterface = function (sAddress) {
    this.History.SetHash(ITHit.WebDAV.Client.Encoder.Encode(sAddress));
}

ITHit.oNS.Controller.prototype.GetSession = function() {
	return this.Commands.Session.GetWebDavSession();
}

ITHit.oNS.Controller.prototype.GetIisDetected = function () {
    return this.Commands.Session.GetIisDetected();
}

ITHit.oNS.Controller.prototype.GetTransferManager = function() {
	return this._upload;
}

ITHit.oNS.Controller.prototype.GetProgressManager = function() {
	return this._upload.UploadManager;
}

ITHit.oNS.Controller.prototype.GetMenuManager = function() {
	return this._contextMenu;
}

ITHit.oNS.Controller.prototype.ShowDialog = function(html, newStyle, title) {
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.ShowCustomDialog(html, newStyle, title);
	ITHit.WebDAV.Client.AjaxFileBrowser.Controller._SetActive(this._index);
}

ITHit.oNS.Controller.prototype.HideDialog = function() {
	ITHit.WebDAV.Client.AjaxFileBrowser.Render.Dialog.HideCustomDialog();
}

ITHit.oNS.Controller.HideDialog = function(){
	var controllerNs = ITHit.WebDAV.Client.AjaxFileBrowser.Controller;
	controllerNs.GetByIndex(controllerNs._GetActive()).HideDialog();
}

ITHit.oNS.Controller.BuyNow = function() {
	
	var oWin = window.open('http://www.webdavsystem.com/pricing#ajaxbrowser', '_blank');
	oWin.focus();
}

ITHit.oNS.Controller.SetActiveState = function(iIndex) {
	ITHit.WebDAV.Client.AjaxFileBrowser.Controller.GetByIndex(iIndex).SetActiveState();
}

ITHit.oNS.Controller.prototype.SetActiveState = function() {
	this._State.SetActiveState();
}

ITHit.oNS.Controller.prototype.toString = function() {
	return this._ClassId;
}

ITHit.oNS.Controller.prototype._OnClose = function (event) {
    var queueEmpty = this.GetProgressManager().IsQueueEmpty();
    var msg = ITHit.Phrases.AjaxFileBrowser.Interface.UploadInProgressWarning;
    if (!queueEmpty) {
        if (typeof event == 'undefined') {
            event = window.event;
        }
        if (ITHit.DetectBrowser.Chrome || ITHit.DetectBrowser.Safari) {
            return msg;
        }
        else {
            event.returnValue = msg;
        };
    }
}


